/* ---- v112 · Phase 0 online-prep: seedable RNG + single clock (defaults behave exactly like Math.random / Date.now) ---- */
var RNGS={s:null},CLK={off:0};
function rngSeed(n){RNGS.s=(n==null)?null:(n>>>0);}
function rng(){if(RNGS.s===null)return Math.random();let t=RNGS.s=(RNGS.s+0x6D2B79F5)>>>0;t=Math.imul(t^(t>>>15),t|1);t^=t+Math.imul(t^(t>>>7),t|61);return((t^(t>>>14))>>>0)/4294967296;}
function nowMs(){return Date.now()+CLK.off;}
