/* v56 · keyboard works in any input language (Thai, etc.): keys are read by their physical position.
   Registered first, in the capture phase, so every later key handler sees the English key. */
(function(){const SYM={Backquote:'`',Minus:'-',Equal:'=',BracketLeft:'[',BracketRight:']',Backslash:'\\',Semicolon:';',Quote:"'",Comma:',',Period:'.',Slash:'/',Space:' '};
  const fix=e=>{const k=e.key,c=e.code||'';if(!(k==='Process'||k==='Unidentified'||(k&&k.length===1&&k.charCodeAt(0)>127)))return;
    const t=e.target;if(t&&/^(INPUT|TEXTAREA)$/.test(t.tagName)&&t.type!=='range'&&t.type!=='checkbox')return;   // typing Thai in text fields stays Thai
    let m=null;if(/^Key[A-Z]$/.test(c))m=e.shiftKey?c[3]:c[3].toLowerCase();else if(/^Digit\d$/.test(c))m=c[5];else if(/^Numpad\d$/.test(c))m=c[6];else if(SYM[c])m=SYM[c];
    if(m!=null)try{Object.defineProperty(e,'key',{value:m,configurable:true});}catch(_){}};
  addEventListener('keydown',fix,true);addEventListener('keyup',fix,true);addEventListener('keypress',fix,true);})();
