function D(cls,list){
  CLASSES[cls].sk=list.map(([id,n,type,o],i)=>{
    const s=Object.assign({id,name:n,type,cls,idx:i,cd:6,mp:15,m:0,dt:CLASSES[cls].dt||'phys',r:0,range:450},o);
    s.th=s.elem==='holy'?'holy':s.elem==='void'?'void':(s.elem==='fire'||s.elem==='ice')?'elemental':CLASSES[cls].th;
    SK[id]=s;return id;
  });
}
