function scaleZone(Z,k,kr){Z.w=Math.round(Z.w*k);Z.h=Math.round(Z.h*k);if(Z.way)Z.way=Z.way.map(v=>Math.round(v*k));
  if(Z.areas)Z.areas=Z.areas.map(a=>({...a,x:Math.round(a.x*k),y:Math.round(a.y*k),r:Math.round(a.r*kr)}));}
