function genBG(zid){
  const Z=ZONES[zid];const c=document.createElement('canvas');c.width=Math.ceil(Z.w*BGS);c.height=Math.ceil(Z.h*BGS);
  const g=c.getContext('2d');g.scale(BGS,BGS);srand(Z.seed);LIGHTS=[];
  const gr=g.createLinearGradient(0,0,Z.w*.4,Z.h);gr.addColorStop(0,Z.ground[1]);gr.addColorStop(1,Z.ground[3]);g.fillStyle=gr;g.fillRect(0,0,Z.w,Z.h);
  const A=Z.w*Z.h;
  for(let i=0;i<A/9000;i++)softBlob(g,srr(0,Z.w),srr(0,Z.h),srr(70,280),srr(.25,.8),srr(0,TAU),Z.ground[Math.floor(sr()*4)],srr(.08,.24));
  g.lineCap='round';
  for(let i=0;i<A/5000;i++){const x=srr(0,Z.w),y=srr(0,Z.h),l=srr(12,44),a=srr(-.6,.6)+(i%2?0:Math.PI/2);
    g.strokeStyle=rgba(Z.ground[Math.floor(sr()*4)],srr(.08,.22));g.lineWidth=srr(3,9);g.beginPath();g.moveTo(x,y);g.quadraticCurveTo(x+Math.cos(a)*l*.5+srr(-5,5),y+Math.sin(a)*l*.5+srr(-5,5),x+Math.cos(a)*l,y+Math.sin(a)*l);g.stroke();}
  FEAT[Z.pk||Z.base||zid](g,Z);
  for(const a of (Z.areas||[])){g.save();g.globalAlpha=.1;g.fillStyle='#ffffff';g.font=`700 ${Math.round(a.r*.2)}px Cinzel, Georgia, serif`;g.textAlign='center';g.fillText(a.n.toUpperCase(),a.x,a.y+a.r*.55);g.restore();}
  const eg=g.createRadialGradient(Z.w/2,Z.h/2,Math.min(Z.w,Z.h)*.35,Z.w/2,Z.h/2,Math.max(Z.w,Z.h)*.75);eg.addColorStop(0,'rgba(0,0,0,0)');eg.addColorStop(1,'rgba(0,0,0,.55)');g.fillStyle=eg;g.fillRect(0,0,Z.w,Z.h);
  return c;
}

/* ---------- Zone loading & spawning ---------- */
function loadZone_v1(zid,arrive){
  G.zone=zid;const Z=ZONES[zid];
  GATES=gatesFor(zid);
  WAY=Z.way&&!Z.base?{x:Z.way[0],y:Z.way[1]}:null;
  NEXUS=Z.nexus?{x:Z.nexus[0],y:Z.nexus[1]}:null;
  NPCS=zid==='capital'?[{x:Z.nexus[0]+260,y:Z.nexus[1]-190,n:'Spirit Merchant',kind:'merchant'},{x:Z.nexus[0]-280,y:Z.nexus[1]-170,n:'Master Smith Borin',kind:'smith'}]:[];loot=[];
  BG=genBG(zid);
  PROPS=loadPropsFor(zid);buildSolids();ED.sel=null;ED.hover=null;ED.dirty=false;if(ED.on)renderEditor();
  enemies=[];projs=[];gfx=[];orbs=[];timers=[];fx=fx.filter(f=>f.keep);amb=[];
  P.x=arrive.x;P.y=arrive.y;P.cape=[];P.dash=null;P.spin=null;
  for(const s of summons){s.x=P.x+rand(-60,60);s.y=P.y+rand(-60,60);}
  camSync();cam.x=P.x-VW/2;cam.y=P.y-VH/2;clampCam();
  if(!Z.safe){const cap=mobCap();for(let i=0;i<cap&&enemies.length<cap;i++)spawnEnemy(true);}
  if(zid==='throne')spawnBoss();
  showBanner(Z.n,Z.range?`${Z.th} · Lv ${Z.range[0]}–${Z.range[1]}${zid==='dark'?'+':''}`:`${Z.th} · ${Z.sub}`);
  G.area='';updZoneTag();
}
function arrivalFrom(zid,from){
  const g=gatesFor(zid).find(x=>x.to===from);
  if(g){const Z=ZONES[zid],a=Math.atan2(Z.h/2-g.y,Z.w/2-g.x);return {x:g.x+Math.cos(a)*170,y:g.y+Math.sin(a)*170};}
  return {x:ZONES[zid].w/2,y:ZONES[zid].h/2};
}
function travel(to,how){
  if(G.fade)return;
  const from=G.zone;
  G.fade={t:0,fn:()=>{
    let arr;
    if(how==='tele'&&!ZONES[to].way&&to!=='capital')arr=arrivalFrom(to,fieldEntrance(to));
    else if(how==='tele'){arr=to==='capital'?{x:ZONES.capital.nexus[0],y:ZONES.capital.nexus[1]+170}:{x:ZONES[to].way[0],y:ZONES[to].way[1]+80};}
    else arr=arrivalFrom(to,from);
    loadZone(to,arr);
    burst(P.x,P.y,pal(null),40,260);ring(P.x,P.y,10,140,.6,pal(null).main,8);saveGame();
  }};
}
function mobCap(){const Z=ZONES[G.zone];if(Z.safe)return 0;return Math.round(Z.w*Z.h/520000*(G.zone==='dark'?.65:1)*(Z.density||1)*G.density);}
function spawnEnemy_v1(initial){
  const Z=ZONES[G.zone];if(Z.safe)return;
  let x,y,tries=0;
  do{x=rand(140,Z.w-140);y=rand(140,Z.h-140);tries++;}
  while(tries<50&&(d2(x,y,P.x,P.y)<(initial?480:700)||(!initial&&d2(x,y,P.x,P.y)>2200)||!freeSpot(Z,x,y,90)||blocked(x,y,40)||(Z.areas||[]).some(a=>a.safe&&d2(a.x,a.y,x,y)<a.r+80)));
  if(tries>=50)return;
  const back=GATES[0],maxD=Math.hypot(Z.w,Z.h)*.85,prog=clamp(d2(x,y,back.x,back.y)/maxD,0,1);
  const L=Z.mobs.length,idx=clamp(Math.floor(prog*L*1.15+rand(-1.2,1.2)),0,L-1);
  const [type,lv]=Z.mobs[idx],m=MOBS[type];
  const n=m.pack?ri(m.pack,m.pack+2):(rng()<.25?2:1);
  for(let i=0;i<n;i++){const a=rand(0,TAU),r=i?rand(40,110):0,ex=clamp(x+Math.cos(a)*r,60,Z.w-60),ey=clamp(y+Math.sin(a)*r,60,Z.h-60);
    const e=makeEnemy(type,Math.max(1,lv+ri(-1,2)),ex,ey);if(i)e.leader=enemies[enemies.length-i];enemies.push(e);}
}
function makeEnemy(type,L,x,y){
  const m=MOBS[type],mul=m.boss?40:m.elite?5:1;
  const hp=Math.round((30+L*18+Math.pow(L,1.5)*2.2)*mul*Math.sqrt(m.sz/22));
  return {type,m,L,x,y,sx:x,sy:y,vx:0,vy:0,sz:m.sz,maxHp:hp,hp,atk:(6+L*2.4)*(m.boss?2.4:m.elite?1.6:1),def:L*.9,sp:m.sp,
    st:{},atkCd:rand(.5,1.5),wind:0,aggro:false,ph:rand(0,TAU),flash:0,face:rand(0,TAU),dead:false,castCd:rand(1.5,3),wanderT:0,wx:0,wy:0,dotT:0,special:rand(3,6),poly:null,hitT:0,alertT:0,strikeT:0,atkAng:0,calmT:0};
}
function spawnBoss(){
  const a=ZONES.throne.areas[1];
  if(enemies.some(e=>e.m.boss))return;
  const e=makeEnemy('darklord',250,a.x,a.y);enemies.push(e);
}
/* =====================================================================
   Particles & effect spawners
   ===================================================================== */
function part(o){if(parts.length>1700)parts.splice(0,100);parts.push(Object.assign({x:0,y:0,vx:0,vy:0,life:.8,max:.8,size:5,col:'#5ef0e0',type:'glow',rot:0,vr:0,grav:0,drag:.92,sway:0,ph:rng()*TAU,grow:0},o));}
function emitThemed(x,y,pl,n,spd,o={}){
  n=Math.round(n*(G.fxBoost||1));
  for(let i=0;i<n;i++){
    const a=o.ang!==undefined?o.ang+rand(-(o.spread||.6),o.spread||.6):rand(0,TAU),v=rand(.25,1)*spd,vx=Math.cos(a)*v,vy=Math.sin(a)*v;
    const col=rng()<.6?pl.main:pl.accent,life=rand(.45,1)*(o.life||1);
    switch(pl.part){
      case 'feather':if(rng()<.45)part({x,y,vx:vx*.6,vy:vy*.6-30,life:life*1.4,max:life*1.4,size:rand(5,9),col:pl.accent,type:'feather',rot:rand(0,TAU),vr:rand(-3,3),drag:.9,sway:30});else part({x,y,vx,vy,life,max:life,size:rand(4,9),col,type:'glow'});break;
      case 'smoke':if(rng()<.4)part({x,y,vx:vx*.4,vy:vy*.4-20,life:life*1.3,max:life*1.3,size:rand(16,28),col:pl.dark,type:'smoke',drag:.9,grow:20});else part({x,y,vx,vy:vy-40,life,max:life,size:rand(4,9),col,type:'flame',drag:.9});break;
      case 'spark':part({x,y,vx:vx*1.3,vy:vy*1.3,life:life*.8,max:life*.8,size:rand(2,4),col,type:'spark',grav:260,drag:.95});if(rng()<.3)part({x,y,vx:vx*.3,vy:vy*.3-40,life,max:life,size:rand(6,12),col:pl.glow,type:'glow',drag:.9});break;
      case 'shard':if(rng()<.5)part({x,y,vx,vy,life,max:life,size:rand(4,8),col:pl.accent,type:'shard',rot:rand(0,TAU),vr:rand(-6,6),drag:.9});else part({x,y,vx:vx*.4,vy:vy*.4,life:life*1.2,max:life*1.2,size:rand(10,18),col:'#e6f8ff',type:'mist',drag:.9,grow:16});break;
      case 'star':part({x,y,vx,vy,life:life*.6,max:life*.6,size:rand(4,9),col:pl.core,type:'star',rot:rand(0,1),drag:.88});break;
      default:part({x,y,vx,vy:vy-15,life,max:life,size:rand(4,10),col,type:'wisp',drag:.93,sway:rand(20,50)});
    }
  }
}
function burst(x,y,pl,n,spd){emitThemed(x,y,pl,n,spd);}
function ring(x,y,r0,r1,dur,col,w){const b=G.fxBoost||1;r1*=1+(b-1)*.22;w*=1+(b-1)*.6;fx.push({k:'ring',x,y,r0,r1,t:0,dur,col,w});}
function textAt(x,y,txt,col,size=18,o={}){texts.push({x:x+rand(-10,10),y,txt:String(txt),col,size,life:o.life||1.05,max:o.life||1.05,vy:o.vy||-70,vx:rand(-20,20)});}
function shake(v){G.shake=Math.max(G.shake,v);}
function crescent(x,y,a0,a1,r,w,dur,pl,follow,extra={}){const b=G.fxBoost||1;w*=1+(b-1)*.5;fx.push(Object.assign({k:'cres',x,y,a0,a1,r,w,t:0,dur,fade:.18,pl,follow},extra));}
function log(msg,cls=''){const el=document.createElement('div');el.textContent=msg;if(cls)el.className=cls;const L=$('#log');L.appendChild(el);while(L.children.length>6)L.firstChild.remove();setTimeout(()=>el.remove(),6200);}

/* =====================================================================
   Combat core
   ===================================================================== */
function attackStat(dt){return dt==='mag'?P.matk*(1+B('matk')):P.atk*(1+B('atk'));}
function hitEnemy_v2(e,m,o={}){
  if(e.dead)return 0;
  let d=attackStat(o.dt)*m*rand(.92,1.08);
  const crit=o.critAlways||rng()*100<ST6.cc(P.crit+B('crit'));
  if(crit)d*=1.6+B('critDmg');
  d*=lvDmgMul(e);
  if(!o.true)d*=100/(100+e.def*(e.st.armorBreak>0?.5:1));
  d*=1+P.sp*.006;
  if(o.exec&&e.hp/e.maxHp<o.exec){if(!e.m.boss){d=e.hp;textAt(e.x,e.y-e.sz*2.4,'EXECUTE','#ff4fd8',26,{life:1.3});}else d*=3;}
  return applyDamage(e,Math.max(1,Math.round(d)),crit,o);
}
function applyDamage(e,d,crit,o={}){
  e.hp-=d;e.flash=.12;e.hitT=3;if(!e.aggro)provoke(e);
  const col=o.dot?(o.dot==='burn'?'#ff9a4a':'#8dff6a'):o.true?'#ff6bf0':crit?'#ffbe5c':'#e8fbff';
  window.__DN207={d,crit,dot:!!o.dot,e};try{textAt(e.x,e.y-e.sz*1.6,(crit?'✦':'')+fmt(d),col,o.dot?13:crit?26:18);}finally{window.__DN207=null;}
  if(o.st)applySt(e,o.st,o);
  if(o.kb&&!e.m.boss){const a=Math.atan2(e.y-(o.fy??P.y),e.x-(o.fx??P.x));e.vx+=Math.cos(a)*o.kb*(e.m.elite?.3:1);e.vy+=Math.sin(a)*o.kb*(e.m.elite?.3:1);}
  const ls=B('lifesteal')+(o.drain||0);if(ls>0&&!o.dot)healP(C182.lifesteal(e,d,ls,o),true);
  if(!o.dot&&o.pl)emitThemed(e.x,e.y-e.sz*.5,o.pl,crit?10:5,crit?260:160);
  if(e.hp<=0)killEnemy(e);
  return d;
}
function applySt(e,st,o){
  const base=attackStat(o.dt||'phys');const bm=e.m.boss?.3:e.m.elite?.6:1;
  for(const k in st){const v=st[k];
    if(k==='burn'||k==='poison')e.st[k]={t:v,dps:base*(o.dotm||.28)};
    else if(k==='slow')e.st.slow=Math.max(e.st.slow||0,v);
    else e.st[k]=Math.max(e.st[k]||0,v*bm);}
}
function killEnemy_v2(e){
  if(e.dead)return;e.dead=true;
  const m=e.m,diff=P.lvl-e.L;let f=1;if(diff>8)f=Math.max(.1,1-(diff-8)*.06);else if(diff<0)f=1+Math.min(.5,-diff*.02);
  const exp=Math.round((10+Math.pow(e.L,1.85))*(m.boss?30:m.elite?4:1)*f);
  gainExp(exp,e.x,e.y-e.sz*2.4);
  if(rng()<.7||m.elite||m.boss){const g=Math.round((e.L*1.5*rand(.6,1.4)+2)*(m.boss?20:m.elite?4:1));P.gold+=g;}
  const n=m.boss?14:m.elite?5:ri(0,2);
  for(let i=0;i<n;i++)orbs.push({x:e.x+rand(-20,20),y:e.y+rand(-20,20),vx:rand(-120,120),vy:rand(-120,120),kind:pick(['hp','mp','hp','mp','power']),t:0,ph:rand(0,TAU)});
  if(rng()<(m.boss?1:m.elite?.8:.16))orbs.push({x:e.x,y:e.y,vx:rand(-80,80),vy:rand(-80,80),kind:'power',t:0,ph:0});
  const r=rng();
  if(r<.16)addItem({id:'hpPot',q:1});else if(r<.26)addItem({id:'mpPot',q:1});else if(r<.40)addItem({id:'shard',q:ri(1,3)});
  if(rng()<(m.boss?1:m.elite?.4:.05)){const w=makeWeapon(pick(Object.keys(WEAPONS)),e.L,m.boss?3:m.elite?ri(1,2):rng()<.25?1:0);if(addItem(w))log(`ได้รับ ${w.name} (${WEAPONS[w.t].n})`,'g');}
  if(e.L>=40&&rng()<.05)addItem({id:'hpPot2',q:1});
  // spirit dissolves upward
  for(let i=0;i<(m.boss?90:22);i++)part({x:e.x+rand(-e.sz,e.sz),y:e.y-rand(0,e.sz*1.5),vx:rand(-40,40),vy:rand(-160,-40),life:rand(.6,1.4),max:1.4,size:rand(4,10)*(m.boss?2:1),col:rng()<.5?m.c:'#ffffff',type:'wisp',sway:40,drag:.95});
  ring(e.x,e.y-e.sz*.4,e.sz*.5,e.sz*3,.5,m.c,5);
  if(m.boss){G.bossT=90;shake(18);log('Dark Lord ถูกปราบแล้ว! จะคืนชีพใน 90 วินาที','v');showBanner('DARK LORD VANQUISHED','ชัยชนะแห่งวิญญาณ');}
}
function gainExp(x,tx,ty){
  if(P.lvl>=C182cap())return;P.exp+=x;if(tx!==undefined)textAt(tx,ty,`+${fmt(x)} EXP`,'#c9a8ff',13,{life:1.2,vy:-45});
  while(P.lvl<C182cap()&&P.exp>=need(P.lvl)){P.exp-=need(P.lvl);levelUp();}
}
function levelUp(){
  const sp=Math.floor(P.lvl/5)+3;P.lvl++;P.statPts+=sp;
  recalc();P.hp=P.maxHp;P.mp=P.maxMp;
  const pl=pal(null);fx.push({k:'pillar',x:P.x,y:P.y,t:0,dur:1.4,col:'#ffbe5c',w:70,h:420});
  ring(P.x,P.y,10,220,.8,'#ffbe5c',8);emitThemed(P.x,P.y,THEMES.holy,40,240);emitThemed(P.x,P.y,pl,30,200);
  textAt(P.x,P.y-80,'LEVEL UP!','#ffbe5c',30,{life:1.8,vy:-40});
  log(`เลเวลอัป! Lv ${P.lvl} · +${sp} Status Points`,'g');
  if(G.win==='wSkill')renderSkillWin();if(G.win==='wInv')renderInv();
}
function healP(v,silent){if(P.dead)return;const a=Math.min(P.maxHp-P.hp,v);P.hp+=a;if(!silent&&a>0)textAt(P.x,P.y-50,'+'+fmt(a),'#8dffc8',18);else if(silent&&a>=1&&rng()<.3)textAt(P.x,P.y-50,'+'+fmt(a),'#8dffc8',12);}
function hurtPlayer_v2(raw,src){
  if(P.dead||G.state!=='play'||G.edit)return;
  if(G.god||P.dome||P.invT>0||(P.dash&&!P.dash.back)){if(rng()<.15)textAt(P.x,P.y-50,'IMMUNE','#ffd36b',14);return;}
  let d=raw*rand(.9,1.1)*Math.max(ST6.on?.1:0,100/(100+P.def));d*=1-clamp(B('def'),-.5,.85);d=Math.max(1,Math.round(d));
  if(P.shield>0){const a=Math.min(P.shield,d);P.shield-=a;d-=a;if(a>0&&rng()<.4)textAt(P.x,P.y-50,'ABSORB','#9be8ff',13);}
  const rf=B('reflect');if(rf>0&&src&&!src.dead)applyDamage(src,Math.max(1,Math.round(raw*rf)),false,{});
  if(d<=0)return;
  P.hp-=d;P.hurtT=.25;textAt(P.x,P.y-44,fmt(d),'#ff6b8b',17);shake(3);
  if(P.hp<=0)playerDeath();
}
function playerDeath(){
  for(const id in P.buffs){const b=P.buffs[id];if(b.revive){P.hp=Math.round(P.maxHp*b.revive);delete P.buffs[id];P.invT=2.5;
    fx.push({k:'pillar',x:P.x,y:P.y,t:0,dur:1.6,col:'#fff2b8',w:90,h:520});ring(P.x,P.y,10,260,.9,'#ffd36b',10);emitThemed(P.x,P.y,THEMES.holy,60,300);
    textAt(P.x,P.y-90,SK[id]?SK[id].name.toUpperCase()+'!':'REVIVE','#fff2b8',28,{life:1.8});log(`${SK[id]?SK[id].name:'Revive'} ทำงาน — คืนชีพ!`,'g');return;}}
  P.hp=0;P.dead=true;G.state='dead';
  for(let i=0;i<80;i++)part({x:P.x,y:P.y-20,vx:rand(-80,80),vy:rand(-220,-40),life:rand(.8,1.8),max:1.8,size:rand(4,10),col:pick(['#5ef0e0','#b98cff','#ffffff']),type:'wisp',sway:40});
  setTimeout(()=>{$('#overSub').textContent=`วิญญาณของคุณแตกสลายที่ ${ZONES[G.zone].n} · Lv ${P.lvl} ${CLASSES[P.cls].n}`;$('#over').hidden=false;},900);
}

/* ---------- Basic attack: weapon stance movesets ---------- */
function aimPoint(range){
  let tx,ty;
  const t=G.auto&&G.autoT&&!G.autoT.dead?G.autoT:null;
  if(t){tx=t.x;ty=t.y;}
  else if(G.lastInput==='touch'){const n=nearestEnemy(P.x,P.y,700);if(n){tx=n.x;ty=n.y;}else{tx=P.x+Math.cos(P.face)*200;ty=P.y+Math.sin(P.face)*200;}}
  else{tx=mwx(mouse.x,mouse.y);ty=mwy(mouse.x,mouse.y);}
  if(range){const d=d2(tx,ty,P.x,P.y);if(d>range){tx=P.x+(tx-P.x)/d*range;ty=P.y+(ty-P.y)/d*range;}}
  return {x:tx,y:ty};
}
function nearestEnemy(x,y,r,skip){let b=null,bd=r;for(const e of enemies){if(e.dead||(skip&&skip.has(e)))continue;const d=d2(e.x,e.y,x,y);if(d<bd){bd=d;b=e;}}return b;}
function inSector(e,cx,cy,ang,r,arc){const d=d2(e.x,e.y,cx,cy);if(d>r+e.sz)return false;if(arc>=TAU-.01)return true;return Math.abs(angDiff(ang,Math.atan2(e.y-cy,e.x-cx)))<=arc/2+Math.min(.5,e.sz/Math.max(d,1));}
function inLine(e,x,y,ang,len,w){const dx=e.x-x,dy=e.y-y,c=Math.cos(ang),s=Math.sin(ang),along=dx*c+dy*s,perp=Math.abs(-dx*s+dy*c);return along>-e.sz&&along<len+e.sz&&perp<w/2+e.sz;}

function basicAttack_v4(){
  if(P.atkCd>0||P.dead||P.dash||G.edit)return;
  const wt=P.weapon.t,W_=WEAPONS[wt],pl=wpal(),tgt=aimPoint(),ang=Math.atan2(tgt.y-P.y,tgt.x-P.x);
  P.face=ang;P.atkCd=1/Math.min(8,W_.aspd*P.aspdF*(1+B('aspd')));
  const dt=W_.magic?'mag':'phys',m=W_.mult;P.combo=(P.combo+1)%6;
  if(wt==='dagger'||wt==='fist'){
    const side=P.combo%2?1:-1,a=ang+rand(-.18,.18);P.swing={t:0,dur:.13,type:'thrust',ang:a};
    const L=W_.range,x1=P.x+Math.cos(a)*L,y1=P.y-6+Math.sin(a)*L;
    fx.push({k:'thrust',x0:P.x+Math.cos(a)*14+Math.cos(a+Math.PI/2)*side*6,y0:P.y-6+Math.sin(a)*14,x1,y1,t:0,dur:.18,pl});
    fx.push({k:'star',x:x1,y:y1,t:0,dur:.22,pl,s:18});
    for(const e of enemies)if(inSector(e,P.x,P.y,a,L,W_.arc))hitEnemy(e,m,{dt,pl});
  }else if(wt==='sword'){
    const side=P.combo%2?1:-1,a0=ang-side*1.3,a1=ang+side*1.3;
    P.swing={t:0,dur:.2,type:'arc',a0,a1};
    crescent(P.x,P.y,a0,a1,W_.range*.85,26,.2,pl,true);
    emitThemed(P.x+Math.cos(ang)*60,P.y+Math.sin(ang)*60,pl,6,140,{ang,spread:.8});
    for(const e of enemies)if(inSector(e,P.x,P.y,ang,W_.range,W_.arc))hitEnemy(e,m,{dt,pl,kb:40});
  }else if(W_.heavy){
    const wind=.24/Math.min(1.6,P.aspdF*(1+B('aspd')));
    P.swing={t:0,dur:wind+.26,type:'heavy',ang,wind};
    fx.push({k:'charge',t:0,dur:wind,pl});
    timers.push({t:wind,fn:()=>{
      const a0=ang-1.6,a1=ang+.9;crescent(P.x,P.y,a0,a1,W_.range*.85,44,.16,pl,true,{heavy:1});
      const ix=P.x+Math.cos(ang)*W_.range*.6,iy=P.y+Math.sin(ang)*W_.range*.6;
      ring(ix,iy,10,W_.range*.9,.45,pl.main,10);ring(ix,iy,5,W_.range*.6,.35,pl.core,4);
      fx.push({k:'crack',x:ix,y:iy,t:0,dur:1.2,pl,seed:rng()*1000,r:W_.range*.6});
      for(let i=0;i<16;i++)part({x:ix,y:iy,vx:rand(-220,220),vy:rand(-260,60),life:rand(.4,.8),max:.8,size:rand(3,7),col:'#3a2a2a',type:'debris',grav:600,rot:rand(0,6),vr:rand(-8,8),drag:.97});
      emitThemed(ix,iy,pl,14,260);shake(7);
      for(const e of enemies)if(inSector(e,P.x,P.y,ang,W_.range,W_.arc)||d2(e.x,e.y,ix,iy)<W_.range*.5+e.sz)hitEnemy(e,m,{dt,pl,kb:120});
    }});
  }else if(wt==='spear'){
    P.swing={t:0,dur:.22,type:'thrust',ang,long:1};
    fx.push({k:'wave',x:P.x,y:P.y-6,ang,len:W_.range,w:W_.w,t:0,dur:.3,pl});
    for(const e of enemies)if(inLine(e,P.x,P.y,ang,W_.range,W_.w))hitEnemy(e,m,{dt,pl,kb:30});
  }else if(wt==='bow'){
    P.swing={t:0,dur:.18,type:'bow',ang};
    fireProj({ang,spd:1050,m,dt,pl,kind:'arrow',size:6,range:W_.range});
  }else if(wt==='staff'){
    P.swing={t:0,dur:.22,type:'cast',ang};
    fireProj({ang,spd:620,m,dt,pl,kind:'orb',size:11,range:W_.range,aoe:55});
  }
}
function fireProj(o){
  const a=o.ang,sx=o.x??(P.x+Math.cos(a)*18),sy=o.y??(P.y-8+Math.sin(a)*18);
  projs.push({team:'p',x:sx,y:sy,vx:Math.cos(a)*o.spd,vy:Math.sin(a)*o.spd,spd:o.spd,life:(o.range||600)/o.spd,m:o.m,dt:o.dt,pl:o.pl,kind:o.kind||'orb',size:(o.size||10)*(1+((o.fxk||1)-1)*.35),
    pierce:o.pierce,bounce:o.bounce||0,homing:o.homing,aoe:o.aoe,st:o.st,kb:o.kb,true:o.true,critAlways:o.critAlways,dotm:o.dotm,boomer:o.boomer,range:o.range||600,trav:0,ret:false,hit:new Set(),multi:o.multi,elem:o.elem,fxk:o.fxk||1,ctx:o.ctx||C182.cur,mhit:new Map(),trail:[],emitT:0,rot:0});
}

/* ---------- Skill execution engine ---------- */
function mpCost(s,lv){return Math.round(s.mp*(1+(lv-1)*.08)+P.lvl*.05*(s.mp/15));}
function castSkillNow_v1(id){
  if(!id||P.dead||G.state!=='play'||G.edit)return false;
  const s=SK[id],lv=P.skills[id]||0;if(!lv)return false;
  if(s.type==='passive'){textAt(P.x,P.y-60,'Passive','#8fa4cc',13);return false;}
  if((P.cds[id]||0)>0)return false;
  const cost=mpCost(s,lv);if(P.mp<cost){textAt(P.x,P.y-60,'MP ไม่พอ','#7fc8ff',14);return false;}
  P.mp-=cost;P.cds[id]=s.cd*(1-clamp(B('cdr'),0,.7));
  const pl=pal(s),m=(s.m||0)*(1+.12*(lv-1)),tgt=aimPoint(s.range||450),ang=Math.atan2(tgt.y-P.y,tgt.x-P.x);
  const fxk=1+(lv-1)*.13;const o={ctx:C182.cur,dt:s.dt,elem:s.elem,fxk,pl,st:s.st,kb:s.kb,true:s.true,drain:s.drain,dotm:s.dotm,exec:s.exec,critAlways:s.critAlways};
  P.face=ang;G.fxBoost=fxk;
  ring(P.x,P.y,6,50,.35,pl.main,3);emitThemed(P.x,P.y-10,pl,6,90);
  const flash=document.querySelector(`.slot[data-sk="${id}"]`);if(flash){flash.classList.remove('flash');void flash.offsetWidth;flash.classList.add('flash');}
  switch(s.type){
    case 'slash':{
      const a0=ang-s.arc/2,a1=ang+s.arc/2;P.swing={t:0,dur:.24,type:'arc',a0,a1};
      crescent(P.x,P.y,a0,a1,s.r*.85,40,.24,pl,true,{big:1});
      if(s.cross)crescent(P.x,P.y,ang+Math.PI/2-.9,ang+Math.PI/2+.9,s.r*.7,30,.24,pl,true,{big:1});
      emitThemed(P.x+Math.cos(ang)*s.r*.6,P.y+Math.sin(ang)*s.r*.6,pl,20,240,{ang,spread:1});
      for(const e of enemies)if(inSector(e,P.x,P.y,ang,s.r,s.arc))hitEnemy(e,m,o);
      shake(4);break;}
    case 'execute':{
      const a0=ang-s.arc/2,a1=ang+s.arc/2;P.swing={t:0,dur:.3,type:'arc',a0,a1};
      crescent(P.x,P.y,a0,a1,s.r*.9,58,.3,pl,true,{big:1,scythe:1});
      emitThemed(P.x+Math.cos(ang)*s.r*.6,P.y+Math.sin(ang)*s.r*.6,pl,30,280,{ang,spread:1.2});
      for(const e of enemies)if(inSector(e,P.x,P.y,ang,s.r,s.arc))hitEnemy(e,m,o);
      shake(8);break;}
    case 'nova':{
      ring(P.x,P.y,10,s.r,.5,pl.main,14);ring(P.x,P.y,5,s.r*.8,.4,pl.core,4);fx.push({k:'rune',x:P.x,y:P.y,r:s.r*.7,t:0,dur:.8,pl});
      if(s.cross)fx.push({k:'crossbeam',x:P.x,y:P.y,r:s.r,t:0,dur:.6,pl});
      emitThemed(P.x,P.y,pl,40,s.r*2.2);
      for(const e of enemies)if(d2(e.x,e.y,P.x,P.y)<s.r+e.sz)if(m>0)hitEnemy(e,m,o);else applySt(e,s.st||{},o);
      if(s.heal)healP(P.maxHp*s.heal);
      if(s.buff){P.buffs[id]=Object.assign({t:s.dur,max:s.dur,pl},scaleBuff(s.buff,lv));}
      if(s.st&&s.st.fear)textAt(P.x,P.y-80,'FEAR!','#b98cff',20);
      shake(5);break;}
    case 'proj':{
      const n=s.n||1;
      for(let i=0;i<n;i++){
        const spread=s.spread||0,a=n>1&&spread?ang-spread/2+spread*(i/(n-1)):ang;
        const shoot=()=>{const aa=s.burst?Math.atan2(aimPoint().y-P.y,aimPoint().x-P.x)+rand(-.05,.05):a;
          fireProj({ang:aa,spd:s.spd||700,m,dt:s.dt,pl,kind:s.kind||(['archer','sniper','sharpshooter','phantombow','ranger','beastmaster'].includes(s.cls)?'arrow':'orb'),size:s.size||(s.kind==='crescent'?26:10),
            range:s.range||650,pierce:s.pierce,bounce:s.bounce,homing:s.homing,aoe:s.aoe,st:s.st,kb:s.kb,true:s.true,critAlways:s.critAlways,dotm:s.dotm,multi:s.multi,elem:s.elem,fxk});};
        if(s.burst&&i>0)timers.push({t:s.burst*i,fn:shoot});else shoot();
      }
      P.swing={t:0,dur:.2,type:WEAPONS[P.weapon.t].ranged?'bow':'cast',ang};break;}
    case 'boomerang':
      fireProj({ang,spd:720,m,dt:s.dt,pl,kind:s.kind||'shield',size:s.size||18,range:s.range,boomer:1,st:s.st,kb:60,elem:s.elem});P.swing={t:0,dur:.22,type:'cast',ang};break;
    case 'line':{
      fx.push({k:'beam',x:P.x,y:P.y-8,ang,len:s.len,w:s.w,t:0,dur:.55,pl,tru:s.true});
      if(s.quake){for(let i=1;i<6;i++)timers.push({t:i*.05,fn:()=>{const x=P.x+Math.cos(ang)*s.len*i/6,y=P.y+Math.sin(ang)*s.len*i/6;fx.push({k:'crack',x,y,t:0,dur:1,pl,seed:rng()*999,r:60});for(let k=0;k<6;k++)part({x,y,vx:rand(-150,150),vy:rand(-220,0),life:.7,max:.7,size:rand(3,6),col:'#3a2a2a',type:'debris',grav:600,drag:.97});}});}
      if(s.true)fx.push({k:'rift',x:P.x,y:P.y-8,ang,len:s.len,t:0,dur:.9,pl});
      for(let i=0;i<24;i++){const k=rand(0,1);emitThemed(P.x+Math.cos(ang)*s.len*k,P.y+Math.sin(ang)*s.len*k,pl,1,120);}
      for(const e of enemies)if(inLine(e,P.x,P.y,ang,s.len,s.w))hitEnemy(e,m,o);
      P.swing={t:0,dur:.25,type:'thrust',ang,long:1};shake(s.true?10:6);break;}
    case 'ground':{
      const at=s.self?{x:P.x,y:P.y}:tgt;
      gfx.push({id,x:at.x,y:at.y,r:s.r,t:0,dur:s.dur,tick:s.tick,acc:0,m,o,heal:s.heal,pull:s.pull,pl,follow:s.self,bolt:s.bolt,briar:s.briar,arrows:s.arrows,cross:s.cross,elem:s.elem});
      ring(at.x,at.y,10,s.r,.5,pl.main,6);break;}
    case 'burst':{
      fx.push({k:'rune',x:tgt.x,y:tgt.y,r:s.r*.8,t:0,dur:.6,pl});ring(tgt.x,tgt.y,10,s.r,.45,pl.main,16);emitThemed(tgt.x,tgt.y,pl,40,300);
      for(const e of enemies)if(d2(e.x,e.y,tgt.x,tgt.y)<s.r+e.sz)hitEnemy(e,m,o);shake(6);break;}
    case 'meteor':{
      const n=s.n||1;
      for(let i=0;i<n;i++){const a=rand(0,TAU),d=n>1?rand(0,s.spreadR||150):0;
        fx.push({k:'meteor',x:tgt.x+Math.cos(a)*d,y:tgt.y+Math.sin(a)*d,t:-i*(s.arrows?.06:.13),fall:s.arrows?.28:.5,r:s.r,m,o,pl,arrows:s.arrows,pillar:s.pillar,big:n===1});}
      break;}
    case 'chain':{
      let from={x:P.x,y:P.y-10},hit=new Set(),mm=m,pts=[[from.x,from.y]];
      for(let i=0;i<s.n;i++){const e=nearestEnemy(from.x,from.y,i?280:s.range,hit);if(!e)break;hit.add(e);pts.push([e.x,e.y-e.sz*.6]);hitEnemy(e,mm,Object.assign({},o,{st:{stun:.3}}));mm*=.9;from=e;}
      if(pts.length===1)pts.push([tgt.x,tgt.y]);
      fx.push({k:'bolt',pts,t:0,dur:.4,pl:pl.key==='spirit'||G.theme==='auto'?{...pl,main:'#bff4ff',glow:'#6aa8ff'}:pl});break;}
    case 'dash':{
      const a=s.back?ang+Math.PI:ang,dur=.2;P.dash={vx:Math.cos(a)*s.range/dur,vy:Math.sin(a)*s.range/dur,t:dur,m,o,hit:new Set(),back:s.back,pl};
      if(s.back)P.invT=.3;break;}
    case 'leap':{
      P.dash={leap:1,sx:P.x,sy:P.y,tx:tgt.x,ty:tgt.y,t:.35,dur:.35,m,o,hit:new Set(),pl,r:s.r};P.invT=.4;break;}
    case 'blink':{
      fx.push({k:'ghost',x:P.x,y:P.y,t:0,dur:.5,pl});emitThemed(P.x,P.y,pl,20,200);
      P.x=clamp(tgt.x,30,ZONES[G.zone].w-30);P.y=clamp(tgt.y,30,ZONES[G.zone].h-30);
      ring(P.x,P.y,10,90,.4,pl.main,6);emitThemed(P.x,P.y,pl,24,220);
      if(s.buff)P.buffs[id]={t:s.dur,max:s.dur,pl,...scaleBuff(s.buff,lv)};P.invT=.25;break;}
    case 'buff':{
      P.buffs[id]=Object.assign({t:s.dur,max:s.dur,pl},scaleBuff(s.buff,lv));
      if(s.buff.shield)P.shield=Math.max(P.shield,P.maxHp*s.buff.shield*(1+.05*(lv-1)));
      fx.push({k:'rune',x:P.x,y:P.y,r:70,t:0,dur:.9,pl,follow:1});ring(P.x,P.y,70,10,.5,pl.main,6);
      for(let i=0;i<30;i++)emitThemed(P.x+rand(-30,30),P.y+rand(-10,20),pl,1,60);
      textAt(P.x,P.y-80,s.name,pl.main,16);break;}
    case 'heal':{
      healP(P.maxHp*s.heal*(1+.05*(lv-1)));
      if(s.cleanse){P.hurtT=0;}
      if(s.buff)P.buffs[id]=Object.assign({t:s.dur,max:s.dur,pl},scaleBuff(s.buff,lv));
      if(s.dome)P.dome={t:s.dome,max:s.dome,r:140,pl};
      const hp=G.theme==='auto'?THEMES.holy:pl;
      fx.push({k:'pillar',x:P.x,y:P.y,t:0,dur:.9,col:hp.accent,w:60,h:300});ring(P.x,P.y,90,10,.5,'#8dffc8',6);
      for(let i=0;i<24;i++)part({x:P.x+rand(-34,34),y:P.y+rand(-10,20),vx:0,vy:rand(-160,-60),life:rand(.6,1.1),max:1.1,size:rand(4,8),col:pick(['#8dffc8','#ffffff',hp.main]),type:'star',drag:.97});break;}
    case 'summon':{
      const sd=SUMMON[s.sum];fx.push({k:'rune',x:P.x,y:P.y,r:90,t:0,dur:1,pl});
      const mine=summons.filter(u=>u.src===id);for(const u of mine)u.t=0; // replace old ones
      const spawn=(kind,k,cnt)=>{const a=k/cnt*TAU;const u={kind,sd:SUMMON[kind],src:id,x:P.x+Math.cos(a)*50,y:P.y+Math.sin(a)*50,t:s.dur,max:s.dur,cd:rand(0,.5),m:SUMMON[kind].m*(1+.1*(lv-1)),face:0,ph:rand(0,TAU),tgt:null};summons.push(u);emitThemed(u.x,u.y,pl,16,160);ring(u.x,u.y,5,50,.4,sd.col,4);};
      for(let k=0;k<s.n;k++)spawn(s.sum,k,s.n);if(s.extra)spawn(s.extra,0,1);
      while(summons.length>12)summons.shift();break;}
    case 'dome':
      P.dome={t:s.dur*(1+.05*(lv-1)),max:s.dur,r:s.r,pl};ring(P.x,P.y,10,s.r,.5,pl.main,10);emitThemed(P.x,P.y,pl,50,260);textAt(P.x,P.y-90,s.name.toUpperCase(),pl.main,20);break;
    case 'revive':
      P.buffs[id]={t:s.dur,max:s.dur,pl,revive:s.heal};fx.push({k:'pillar',x:P.x,y:P.y,t:0,dur:1,col:pl.accent,w:50,h:320});textAt(P.x,P.y-80,s.name,pl.main,16);break;
    case 'spin':
      P.spin={t:s.dur,max:s.dur,tick:s.tick,acc:0,r:s.r,m,o,pl};break;
    case 'trap':
      gfx.push({id,x:tgt.x,y:tgt.y,r:s.r,t:0,dur:25,trap:1,armed:.6,m,o,pl,elem:s.elem});ring(tgt.x,tgt.y,5,40,.3,pl.main,3);break;
  }
  levelFx(s,lv,tgt,pl);G.fxBoost=1;
  return true;
}
function scaleBuff(b,lv){const o={};for(const k in b)o[k]=b[k]*(b[k]>0?1+.06*(lv-1):1);return o;}

/* =====================================================================
   Update
   ===================================================================== */
function update(dt){
  time+=dt;
  if(G.fade){G.fade.t+=dt;if(G.fade.t>=.35&&!G.fade.done){G.fade.done=1;G.fade.fn();}if(G.fade.t>=.85)G.fade=null;}
  $('#fade').style.opacity=G.fade?(G.fade.t<.35?G.fade.t/.35:1-(G.fade.t-.35)/.5):0;
  if(G.edit){updEditorMove(dt);}
  else{
  if(G.state==='play'&&!P.dead){updPlayer(dt);updCasting(dt);thiefTick(dt);updBeacons();}
  updInvLive(dt);
  updEnemies(dt);updSummons(dt);updProjs(dt);updGround(dt);updOrbs(dt);updLoot(dt);
  for(let i=timers.length-1;i>=0;i--){timers[i].t-=dt;if(timers[i].t<=0){const f=timers[i].fn;timers.splice(i,1);f();}}
  }
  updFx(dt);updParts(dt);updAmbient(dt);
  // spawning
  const Z=ZONES[G.zone];
  if(!Z.safe&&G.state==='play'&&!G.edit){G.spawnT-=dt;if(G.spawnT<=0){G.spawnT=.45;if(enemies.filter(e=>!e.m.boss).length<mobCap())spawnEnemy(false);}
    if(G.zone==='throne'&&G.bossT>0){G.bossT-=dt;if(G.bossT<=0){spawnBoss();log('Dark Lord ฟื้นคืนชีพที่ Throne of the Dark Lord!','v');}}}
  enemies=enemies.filter(e=>!e.dead);
  // camera
  camStep(dt);const tx=P.x-VW/2,ty=P.y-VH/2;cam.x=lerp(cam.x,tx,Math.min(1,dt*6));cam.y=lerp(cam.y,ty,Math.min(1,dt*6));clampCam();
  G.shake=Math.max(0,G.shake-dt*30);
  if(G.banner>0){G.banner-=dt;if(G.banner<=0)$('#banner').classList.remove('show');}
  G.saveT+=dt;if(G.saveT>20&&G.state==='play'){G.saveT=0;saveGame();}
}
function updEditorMove(dt){
  let ix=0,iy=0;if(keys.w||keys.arrowup)iy-=1;if(keys.s||keys.arrowdown)iy+=1;if(keys.a||keys.arrowleft)ix-=1;if(keys.d||keys.arrowright)ix+=1;
  const l=Math.hypot(ix,iy)||1,sp=keys.shift?1600:800,Z=ZONES[G.zone];P.x=clamp(P.x+ix/l*sp*dt,30,Z.w-30);P.y=clamp(P.y+iy/l*sp*dt,30,Z.h-30);P.vx=P.vy=0;P.swing=null;
}
function clampCam(){const Z=ZONES[G.zone];cam.x=Z.w<VW?(Z.w-VW)/2:clamp(cam.x,0,Z.w-VW);cam.y=Z.h<VH?(Z.h-VH)/2:clamp(cam.y,0,Z.h-VH);}

function updPlayer(dt){
  const Z=ZONES[G.zone];
  for(const id in P.cds)if(P.cds[id]>0)P.cds[id]=Math.max(0,P.cds[id]-dt);
  P.atkCd=Math.max(0,P.atkCd-dt);P.invT=Math.max(0,P.invT-dt);P.hurtT=Math.max(0,P.hurtT-dt);G.potCd=Math.max(0,G.potCd-dt);
  for(const id in P.buffs){const b=P.buffs[id];b.t-=dt;if(b.t<=0){delete P.buffs[id];if(SK[id]&&SK[id].buff&&SK[id].buff.shield)P.shield=0;}}
  if(P.dome){P.dome.t-=dt;if(P.dome.t<=0)P.dome=null;}
  // regen
  C182.regenTick(dt);
  P.mp=Math.min(P.maxMp,P.mp+C182.mpRegen()*dt);
  // aura / storm
  const au=B('aura');if(au>0){P.auraT-=dt;if(P.auraT<=0){P.auraT=.5;for(const e of enemies)if(d2(e.x,e.y,P.x,P.y)<170+e.sz)hitEnemy(e,au*.5,{dt:'mag',pl:pal(null)});}}
  const stm=B('storm');if(stm>0){P.stormT-=dt;if(P.stormT<=0){P.stormT=1/stm;const e=nearestEnemy(P.x,P.y,420);if(e){fx.push({k:'bolt',pts:[[e.x+rand(-30,30),e.y-300],[e.x,e.y-e.sz*.5]],t:0,dur:.3,pl:{...THEMES.ice,main:'#dff6ff'}});hitEnemy(e,1.4,{dt:'mag',pl:THEMES.ice,st:{stun:.2}});ring(e.x,e.y,5,50,.3,'#bff4ff',4);}}}
  // input
  let ix=0,iy=0;
  if(keys.w||keys.arrowup)iy-=1;if(keys.s||keys.arrowdown)iy+=1;if(keys.a||keys.arrowleft)ix-=1;if(keys.d||keys.arrowright)ix+=1;
  if(G.touch&&G.touch.move){const tx=mwx(G.touch.x,G.touch.y),ty=mwy(G.touch.x,G.touch.y),dd=d2(tx,ty,P.x,P.y);if(dd>20){ix=(tx-P.x)/dd;iy=(ty-P.y)/dd;}}
  if((ix||iy)&&camY()){const r=scr2wDir(ix,iy/camT());ix=r[0];iy=r[1];}   // WASD is camera-relative when the view is rotated
  let jm=1;if(G.joy&&G.joy.m>0){const r=scr2wDir(G.joy.x,G.joy.y/camT());ix=r[0];iy=r[1];jm=Math.max(.3,G.joy.m);G.lastInput='touch';}
  if(G.auto&&!ix&&!iy){const v=autoPlay(dt);ix=v[0];iy=v[1];}
  else if(G.auto)G.autoT=null;
  const il=Math.hypot(ix,iy);if(il>0){ix/=il;iy/=il;}
  const spd=P.speed*Math.max(0,1+B('speed'))*stealthSpeed()*(P.swing&&P.swing.type==='heavy'?.45:1)*(P.casting?.3:1)*1*jm;
  if(P.dash){
    const d=P.dash;
    if(d.leap){d.t-=dt;const k=1-d.t/d.dur;P.x=lerp(d.sx,d.tx,ease(k));P.y=lerp(d.sy,d.ty,ease(k));P.jump=Math.sin(k*Math.PI)*60;
      if(d.t<=0){P.jump=0;P.dash=null;ring(P.x,P.y,10,d.r,.5,d.pl.main,14);fx.push({k:'crack',x:P.x,y:P.y,t:0,dur:1.2,pl:d.pl,seed:rng()*999,r:d.r*.7});emitThemed(P.x,P.y,d.pl,40,300);shake(10);
        for(const e of enemies)if(d2(e.x,e.y,P.x,P.y)<d.r+e.sz)hitEnemy(e,d.m,Object.assign({},d.o,{kb:150}));}}
    else{P.x+=d.vx*dt;P.y+=d.vy*dt;d.t-=dt;
      if(!d.back&&d.m)for(const e of enemies)if(!d.hit.has(e)&&d2(e.x,e.y,P.x,P.y)<e.sz+40){d.hit.add(e);hitEnemy(e,d.m,Object.assign({},d.o,{kb:180}));}
      if(d.t<=0)P.dash=null;}
    if(rng()<.9)P.ghosts.push({x:P.x,y:P.y,life:.3,pl:d.pl});
  }else{
    P.vx=lerp(P.vx,ix*spd,Math.min(1,dt*14));P.vy=lerp(P.vy,iy*spd,Math.min(1,dt*14));
    P.x+=P.vx*dt;P.y+=P.vy*dt;
  }
  if(!(P.dash&&P.dash.leap))collide(P,P.r*.8);
  P.x=clamp(P.x,30,Z.w-30);P.y=clamp(P.y,30,Z.h-30);
  P.walk+=Math.hypot(P.vx,P.vy)*dt*.05;
  for(const g of P.ghosts)g.life-=dt;P.ghosts=P.ghosts.filter(g=>g.life>0);
  // face mouse when not auto
  // v39: face the way you walk (WASD, joystick, autoplay); attacks still turn you toward the target / mouse
  if(il>0&&!P.swing&&!P.casting&&!P.dash){const ta=Math.atan2(iy,ix);P.face+=angDiff(P.face,ta)*Math.min(1,dt*16);}
  // swing
  if(P.swing){P.swing.t+=dt;if(P.swing.t>=P.swing.dur)P.swing=null;}
  if(P.spin){const sp=P.spin;sp.t-=dt;sp.acc+=dt;
    if(sp.acc>=sp.tick){sp.acc-=sp.tick;const a=time*14;crescent(P.x,P.y,a,a+2.6,sp.r*.8,30,.16,sp.pl,true);for(const e of enemies)if(d2(e.x,e.y,P.x,P.y)<sp.r+e.sz)hitEnemy(e,sp.m,sp.o);emitThemed(P.x,P.y,sp.pl,4,sp.r*1.5);}
    if(sp.t<=0)P.spin=null;}
  // attack input
  if((mouse.down&&!G.assign)||keys[' '])basicAttack();
  // interact detection
  let best=null,bd=120;
  if(WAY&&d2(WAY.x,WAY.y,P.x,P.y)<bd){best={k:'way'};bd=d2(WAY.x,WAY.y,P.x,P.y);}
  if(NEXUS&&d2(NEXUS.x,NEXUS.y,P.x,P.y)<200){best={k:'nexus'};}
  for(const n of NPCS)if(d2(n.x,n.y,P.x,P.y)<110)best={k:'npc',n};
  G.interact=best;
  // gates
  for(const g of GATES)if(d2(g.x,g.y,P.x,P.y)<62&&!G.fade){travel(g.to,'gate');break;}
  // area
  let area='';for(const a of (Z.areas||[]))if(d2(a.x,a.y,P.x,P.y)<a.r)area=a.n;
  if(area!==G.area){G.area=area;if(area)showBanner(area,Z.n,2.4);updZoneTag();}
  // cape
  const ax=P.x,ay=P.y-12-(P.jump||0);if(!P.cape.length)for(let i=0;i<6;i++)P.cape.push({x:ax,y:ay+i*6});
  P.cape[0].x=ax;P.cape[0].y=ay;
  for(let i=1;i<P.cape.length;i++){const c=P.cape[i],p=P.cape[i-1];c.y+=dt*40;c.x+=Math.sin(time*3+i)*dt*8;const dx=c.x-p.x,dy=c.y-p.y,l=Math.hypot(dx,dy)||1;c.x=p.x+dx/l*6.5;c.y=p.y+dy/l*6.5;}
}
function interact(){
  const it=G.interact;if(!it||G.state!=='play')return false;
  if(it.k==='way'){
    if(!G.unlocked.has(G.zone)){G.unlocked.add(G.zone);
      fx.push({k:'pillar',x:WAY.x,y:WAY.y,t:0,dur:2.6,col:'#8dffe8',w:110,h:700});ring(WAY.x,WAY.y,10,300,1,'#5ef0e0',12);ring(WAY.x,WAY.y,10,200,.8,'#ffffff',4);
      emitThemed(WAY.x,WAY.y-40,THEMES.spirit,80,340);shake(6);showBanner('WAYSTONE ATTUNED',`ปลดล็อกจุดวาร์ป ${ZONES[G.zone].n} แล้ว`,3);log(`ปลดล็อก Waystone: ${ZONES[G.zone].n}`,'g');saveGame();
    }else travel('capital','tele');
  }else if(it.k==='nexus')openWin('wTele');
  else if(it.k==='npc')openWin(NPC_WIN[it.n.kind]||'wShop');
  return true;
}
function usePotion(kind){
  if(G.potCd>0||P.dead)return;
  const ids=window.POTFLAT221&&POTFLAT221.on?POTFLAT221.ids(kind):kind==='hp'?(P.hp/P.maxHp<.4?['hpPot2','hpPot']:['hpPot','hpPot2']):['mpPot'];
  for(const id of ids)if(countItem(id)){useItemId(id);G.potCd=.8;return;}
  const now=performance.now();if(now-(G.potMsgT||-1e9)<1000)return;G.potMsgT=now;
  textAt(P.x,P.y-60,kind==='hp'?'ไม่มียา HP':'ไม่มียา MP','#8fa4cc',13);
}
function useItemId(id){
  const it=ITEMS[id];if(!it)return;
  if(it.heal){C182.hsrc='potion';try{healP(window.POTFLAT221&&POTFLAT221.on&&it.healN>0?it.healN:P.maxHp*it.heal);}finally{C182.hsrc=null;}ring(P.x,P.y,50,10,.4,'#ff6b8b',4);}
  if(it.mana){P.mp=Math.min(P.maxMp,P.mp+(window.POTFLAT221&&POTFLAT221.on&&it.manaN>0?it.manaN:P.maxMp*it.mana));textAt(P.x,P.y-50,'+MP','#5ef0e0',16);}
  if(id==='bagScroll'){if(P.invSize>=192){log('กระเป๋าขยายเต็มที่แล้ว (192 ช่อง)','r');return;}P.invSize=Math.min(192,P.invSize+16);log(`ขยายกระเป๋าเป็น ${P.invSize} ช่อง`,'g');}
  if(it.k==='mat')return;
  if(it.k==='dye'){log(`${it.n}: ใช้ที่ Madame Celeste (Stylist) ข้างน้ำพุในเมืองหลวง`,'v');return;}
  takeItem(id,1);if(G.win==='wInv')renderInv();
}

/* ---------- Autoplay (uses only slotted skills) ---------- */
function effRange(s,e){
  switch(s.type){case 'slash':case 'execute':case 'nova':case 'spin':return (s.r||150)*.85;
    case 'line':return s.len*.8;case 'proj':case 'boomerang':return 480;case 'dash':case 'leap':return s.range||300;
    case 'trap':return 220;case 'ground':return s.self?s.r*.8:(s.range||450);default:return s.range||450;}
}
function autoPlay_v2(dt){
  if(ZONES[G.zone].safe){G.autoT=null;return [0,0];}
  const hpP=P.hp/P.maxHp;
  if(hpP<.35&&G.potCd<=0)usePotion('hp');
  if(P.mp/P.maxMp<.12&&G.potCd<=0)usePotion('mp');
  let t=G.autoT&&!G.autoT.dead&&d2(G.autoT.x,G.autoT.y,P.x,P.y)<950?G.autoT:nearestEnemy(P.x,P.y,900);
  G.autoT=t;
  const dT=t?d2(t.x,t.y,P.x,P.y):1e9;
  for(const id of P.slots){
    if(!id||!P.skills[id])continue;const s=SK[id];if((P.cds[id]||0)>0||P.mp<mpCost(s,P.skills[id]))continue;
    let go=false;
    if(s.type==='heal')go=hpP<.6||(!!s.buff&&!P.buffs[id]&&t&&dT<500&&hpP<.85);
    else if(s.type==='dome')go=hpP<.45&&t&&dT<400;
    else if(s.type==='revive')go=!P.buffs[id]&&t&&dT<600;
    else if(s.type==='buff')go=!P.buffs[id]&&t&&dT<520;
    else if(s.type==='summon')go=t&&dT<600&&summons.filter(u=>u.src===id).length<s.n;
    else if(s.type==='blink')go=t&&dT>420&&dT<700;
    else if(s.type==='dash'&&s.back)go=t&&dT<90&&hpP<.5;
    else if(t)go=dT<=effRange(s,t)+t.sz;
    if(go){castSkill(id);break;}
  }
  let orb=null,od=260;for(const o of orbs){const d=d2(o.x,o.y,P.x,P.y);if(d<od){od=d;orb=o;}}
  const W_=WEAPONS[P.weapon.t],pref=W_.ranged?300:W_.range*.6;
  if(t){
    P.face=Math.atan2(t.y-P.y,t.x-P.x);
    if(dT<=(W_.ranged?W_.range*.9:W_.range+t.sz*.5))basicAttack();
    if(dT>pref+t.sz)return [(t.x-P.x)/dT,(t.y-P.y)/dT];
    if(W_.ranged&&dT<160)return [-(t.x-P.x)/dT,-(t.y-P.y)/dT];
    return [0,0];
  }
  if(orb)return [(orb.x-P.x)/od,(orb.y-P.y)/od];
  const Z=ZONES[G.zone];
  if(!G.autoWp||d2(G.autoWp.x,G.autoWp.y,P.x,P.y)<80)G.autoWp={x:rand(250,Z.w-250),y:rand(250,Z.h-250)};
  const d=d2(G.autoWp.x,G.autoWp.y,P.x,P.y);return [(G.autoWp.x-P.x)/d,(G.autoWp.y-P.y)/d];
}

/* ---------- Enemies: ecosystem & aggro rules ----------
   Lv 1-80  : passive  -> only fights back after being hit (green label)
   Lv > 80  : aggressive -> attacks on entering its detection radius (red label)
   Attack range = detection radius x (atkScale / 10), default 3/10, tweakable in GM console */
function isAggressive(e){return e.L>80||e.m.boss;}
function detectR(e){return G.aggroR*(e.m.boss?1.5:e.m.elite?1.2:1);}
function attackR(e){return detectR(e)*G.atkScale/10;}
function provoke(e){if(e.aggro)return;e.aggro=true;e.alertT=.9;e.calmT=0;
  for(const o of enemies)if(o!==e&&!o.aggro&&o.type===e.type&&d2(o.x,o.y,e.x,e.y)<220){o.aggro=true;o.alertT=.9;}}
function updEnemies(dt){
  const Z=ZONES[G.zone];
  for(const e of enemies){
    if(e.dead)continue;
    e.flash=Math.max(0,e.flash-dt);e.hitT=Math.max(0,e.hitT-dt);e.alertT=Math.max(0,e.alertT-dt);
    const st=e.st;for(const k in st){if(typeof st[k]==='number'){st[k]-=dt;if(st[k]<=0)delete st[k];}else{st[k].t-=dt;if(st[k].t<=0)delete st[k];}}
    e.dotT-=dt;if(e.dotT<=0){e.dotT=.5;for(const k of ['burn','poison'])if(st[k]){applyDamage(e,Math.max(1,Math.round(st[k].dps*.5*100/(100+e.def*.5))),false,{dot:k});if(e.dead)break;}}
    if(e.dead)continue;
    const dP=d2(e.x,e.y,P.x,P.y);
    // far-away monsters sleep (cheap)
    if(dP>1900&&!e.aggro){e.wind=0;continue;}
    if(st.burn&&rng()<.4)part({x:e.x+rand(-e.sz*.6,e.sz*.6),y:e.y-rand(0,e.sz),vx:0,vy:rand(-80,-30),life:.5,max:.5,size:rand(4,8),col:'#ff8a3d',type:'flame'});
    if(st.poison&&rng()<.3)part({x:e.x+rand(-e.sz*.6,e.sz*.6),y:e.y-rand(0,e.sz),vx:0,vy:rand(-50,-20),life:.7,max:.7,size:rand(3,6),col:'#8dff6a',type:'bubble'});
    e.x+=e.vx*dt;e.y+=e.vy*dt;e.vx*=Math.pow(.02,dt);e.vy*=Math.pow(.02,dt);
    if(e.strikeT>0){e.strikeT-=dt;const v=e.strikeV;e.x+=Math.cos(e.atkAng)*v*dt;e.y+=Math.sin(e.atkAng)*v*dt;}
    if(st.stun){e.wind=0;collide(e,e.sz*.7);continue;}
    const alive=!P.dead&&G.state==='play'&&!(P.stealth>0&&!e.m.boss);
    const det=detectR(e),atr=attackR(e);
    if(alive&&!e.aggro&&isAggressive(e)&&dP<det){provoke(e);textAt(e.x,e.y-e.sz*2.6,'!','#ff5a6a',26,{life:.8,vy:-30});}
    if(!alive)e.aggro=false;
    // passive monsters calm down when the player leaves
    if(e.aggro&&!isAggressive(e)){if(dP>det*1.8)e.calmT+=dt;else e.calmT=0;if(e.calmT>4){e.aggro=false;e.calmT=0;}}
    let spd=e.sp*(st.slow?.45:1)*(e.crsSlowT>0?.6:1)*(e.jdSlow>0?.7:1)*(st.root?0:1);
    let mx=0,my=0;
    if(st.fear&&alive){mx=(e.x-P.x)/dP;my=(e.y-P.y)/dP;spd*=1.1;}
    else if(e.aggro){
      if(d2(e.x,e.y,e.sx,e.sy)>1600&&dP>600&&!e.m.boss){e.aggro=false;}
      if(!e.wind)e.face=Math.atan2(P.y-e.y,P.x-e.x);
      const reach=atr+e.sz+P.r;
      if(e.m.rng){
        const castR=Math.max(reach,atr*2.4+e.sz);
        if(dP>castR*.95){mx=(P.x-e.x)/dP;my=(P.y-e.y)/dP;}else if(dP<castR*.45){mx=-(P.x-e.x)/dP;my=-(P.y-e.y)/dP;spd*=.6;}
        e.castCd-=dt;if(e.castCd<=0&&dP<castR&&!st.silence&&!e.wind){e.castCd=e.m.boss?1.4:rand(2,3);enemyShoot(e);}
      }
      if(e.wind>0){
        e.wind-=dt;spd=0;
        if(e.wind<=0){ // strike: lunge along the locked angle, up to the attack range
          const lunge=Math.max(0,Math.min(dP-e.sz-P.r+10,atr));e.strikeT=.12;e.strikeV=lunge/.12;
          const toP=Math.atan2(P.y-e.y,P.x-e.x);
          if(dP<=reach+18&&Math.abs(angDiff(e.atkAng,toP))<.75)hurtPlayer(e.atk,e);
          const hx=e.x+Math.cos(e.atkAng)*(lunge+e.sz),hy=e.y+Math.sin(e.atkAng)*(lunge+e.sz);ring(hx,hy,4,e.sz*1.4,.25,e.m.c,4);e.lunge=.15;
        }
      }else{
        if(!e.m.rng&&dP>reach-6){mx=(P.x-e.x)/dP;my=(P.y-e.y)/dP;}
        e.atkCd-=dt;
        if(e.atkCd<=0&&dP<=reach){e.atkCd=e.m.boss?1:rand(1.1,1.6);e.wind=.42;e.atkAng=Math.atan2(P.y-e.y,P.x-e.x);}
      }
      if(e.m.boss||e.m.elite)bossAI(e,dt,dP);
    }else{
      e.wanderT-=dt;if(e.wanderT<=0){e.wanderT=rand(2,6);const lead=e.leader&&!e.leader.dead?e.leader:null;const a=rand(0,TAU),r=rand(0,lead?90:220);e.wx=(lead?lead.x:e.sx)+Math.cos(a)*r;e.wy=(lead?lead.y:e.sy)+Math.sin(a)*r;}
      const d=d2(e.x,e.y,e.wx,e.wy);if(d>10){mx=(e.wx-e.x)/d;my=(e.wy-e.y)/d;spd*=e.m.sh==='fish'?.6:.35;e.face=Math.atan2(my,mx);}
    }
    e.lunge=Math.max(0,(e.lunge||0)-dt);
    e.x+=mx*spd*dt;e.y+=my*spd*dt;
    if(!(e.m.boss||e.m.raid))for(const o of enemies){if(o===e||o.dead)continue;const dx=e.x-o.x,dy=e.y-o.y;if(Math.abs(dx)>80||Math.abs(dy)>80)continue;const d=Math.hypot(dx,dy),mn=(e.sz+o.sz)*.8;if(d>0&&d<mn){const push=(mn-d)*.5;e.x+=dx/d*push;e.y+=dy/d*push;}}
    if(alive&&dP<e.sz+P.r-4){if(e.m.boss||e.m.raid){const ov=e.sz+P.r-4-dP;if(dP<.5){const a0=(P.face||0)+Math.PI;P.x+=Math.cos(a0)*ov;P.y+=Math.sin(a0)*ov;}else{P.x-=(e.x-P.x)/dP*ov;P.y-=(e.y-P.y)/dP*ov;}}else{const push=(e.sz+P.r-4-dP)*.5;if(dP>.5){e.x+=(e.x-P.x)/dP*push;e.y+=(e.y-P.y)/dP*push;}}}   // bosses are immovable: the player is pushed out instead (dash skills can no longer shove a boss)
    if(!e.m.fly)collide(e,e.sz*.7);
    e.x=clamp(e.x,40,Z.w-40);e.y=clamp(e.y,40,Z.h-40);
  }
}
function enemyShoot(e,ang,spd){
  const a=ang??Math.atan2(P.y-e.y,P.x-e.x),v=spd||300;
  projs.push({team:'e',x:e.x,y:e.y-e.sz*.6,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:2.6,dmg:e.atk*.85,size:e.m.boss?12:8,col:e.m.c,src:e,trail:[],kind:'eorb'});
}
function bossAI_v1(e,dt,dP){
  e.special-=dt;
  if(e.tele){e.tele.t-=dt;if(e.tele.t<=0){if(d2(P.x,P.y,e.tele.x,e.tele.y)<e.tele.r){C182.hk='tele';try{hurtPlayer(e.atk*C182.telMul(e),e);}finally{C182.hk=null;}C182.telHit(e);}ring(e.tele.x,e.tele.y,10,e.tele.r,.4,e.m.c,14);emitThemed(e.tele.x,e.tele.y,{...THEMES.void,main:e.m.c},30,260);shake(8);e.tele=null;}}
  if(e.special<=0){
    e.special=e.m.boss?rand(3.5,5):rand(5,7);
    const r=rng();
    if(r<.4){for(let i=0;i<(e.m.boss?18:10);i++)enemyShoot(e,i/(e.m.boss?18:10)*TAU+time,240);}
    else if(r<.75){e.tele={x:P.x,y:P.y,r:e.m.boss?200:150,t:C182.telT(e),max:C182.telT(e)};}
    else if(e.m.boss){for(let i=0,vn=C182.vsN(e);i<vn;i++){const a=rand(0,TAU);const s=makeEnemy('voidspawn',Math.max(1,e.L-50),e.x+Math.cos(a)*120,e.y+Math.sin(a)*120);s.aggro=true;s.mnn=1;s.mnnOwner=e;{const q=C182.vsSpot(e,s.x,s.y);s.x=q.x;s.y=q.y;}C182.addGrace(s,e);enemies.push(s);emitThemed(s.x,s.y,THEMES.void,20,200);}textAt(e.x,e.y-e.sz*2.4,'RISE, MY SPAWN','#ff4fd8',18);}
  }
}

/* ---------- Summons ---------- */
function updSummons(dt){
  for(const u of summons){
    u.t-=dt;u.cd-=dt;const sd=u.sd;
    if(!u.tgt||u.tgt.dead||d2(u.tgt.x,u.tgt.y,P.x,P.y)>600)u.tgt=nearestEnemy(u.x,u.y,420);
    let tx,ty,near=false;
    if(u.tgt){const d=d2(u.tgt.x,u.tgt.y,u.x,u.y);u.face=Math.atan2(u.tgt.y-u.y,u.tgt.x-u.x);
      if(d>sd.range*(sd.ranged?.8:1)+u.tgt.sz){tx=u.tgt.x;ty=u.tgt.y;}else near=true;
      if(d<sd.range+u.tgt.sz+6&&u.cd<=0){u.cd=sd.cd;
        if(sd.ranged){fireProj({x:u.x,y:u.y-(sd.fly?30:10),ang:u.face,spd:sd.fly?800:560,m:u.m,dt:sd.mag?'mag':'phys',pl:u.kind==='imp'?THEMES.fire:{...THEMES.holy,part:'wisp'},kind:sd.fly?'arrow':'orb',size:7,range:400});}
        else{hitEnemy(u.tgt,u.m*(1+B('atk')*.5),{dt:sd.mag?'mag':'phys',pl:u.kind==='wolf'?THEMES.spirit:THEMES.void,kb:30});u.lunge=.15;crescent(u.x,u.y,u.face-.8,u.face+.8,26,10,.14,u.kind==='wolf'?THEMES.spirit:THEMES.void,false);}}}
    else{const i=summons.indexOf(u),a=i/Math.max(1,summons.length)*TAU+time*.4;tx=P.x+Math.cos(a)*70;ty=P.y+Math.sin(a)*55;if(d2(tx,ty,u.x,u.y)<20)near=true;u.face=Math.atan2(ty-u.y,tx-u.x);}
    if(!near&&tx!==undefined){const d=d2(tx,ty,u.x,u.y)||1,sp=sd.sp*(d>500?2:1);u.x+=(tx-u.x)/d*sp*dt;u.y+=(ty-u.y)/d*sp*dt;}
    u.lunge=Math.max(0,(u.lunge||0)-dt);
    if(rng()<.2)part({x:u.x+rand(-8,8),y:u.y-rand(0,20)-(sd.fly?30:0),vx:0,vy:-30,life:.5,max:.5,size:rand(3,6),col:sd.col,type:'wisp'});
  }
  for(const u of summons)if(u.t<=0)emitThemed(u.x,u.y,{...THEMES.spirit,main:u.sd.col},14,120);
  summons=summons.filter(u=>u.t>0);
}

/* ---------- Projectiles ---------- */
function updProjs(dt){
  const Z=ZONES[G.zone];
  for(const p of projs){
    p.life-=dt;p.trail.push([p.x,p.y]);if(p.trail.length>16)p.trail.shift();p.rot+=dt*14;
    if(p.team==='p'){
      if(p.homing){const e=nearestEnemy(p.x,p.y,420,p.hit);if(e){const cur=Math.atan2(p.vy,p.vx),want=Math.atan2(e.y-e.sz*.5-p.y,e.x-p.x),na=cur+clamp(angDiff(cur,want),-7*dt,7*dt);p.vx=Math.cos(na)*p.spd;p.vy=Math.sin(na)*p.spd;}}
      if(p.boomer){p.trav+=p.spd*dt;if(!p.ret&&p.trav>=p.range){p.ret=true;p.hit.clear();}
        if(p.ret){const d=d2(P.x,P.y-8,p.x,p.y)||1;p.vx=(P.x-p.x)/d*p.spd;p.vy=(P.y-8-p.y)/d*p.spd;if(d<24)p.life=0;}else p.life=Math.max(p.life,.1);}
      p.x+=p.vx*dt;p.y+=p.vy*dt;
      p.emitT-=dt;if(p.emitT<=0&&p.kind!=='arrow'){p.emitT=.03;G.fxBoost=p.fxk||1;emitThemed(p.x,p.y,p.pl,1,40,{life:.7});G.fxBoost=1;}
      if(p.kind==='arrow'&&rng()<.5)part({x:p.x,y:p.y,vx:rand(-20,20),vy:rand(-20,20),life:.4,max:.4,size:rand(2,4),col:p.pl.accent,type:'glow'});
      for(const e of enemies){
        if(e.dead)continue;
        if(d2(e.x,e.y-e.sz*.4,p.x,p.y)>e.sz+p.size)continue;
        if(p.multi){const lt=p.mhit.get(e)||0;if(time-lt<p.multi)continue;p.mhit.set(e,time);hitEnemy(e,p.m*.35,p);continue;}
        if(p.hit.has(e))continue;
        if(p.aoe){explode(p);p.life=0;break;}
        p.hit.add(e);hitEnemy(e,p.m,Object.assign({fx:p.x-p.vx,fy:p.y-p.vy},p));
        if(p.bounce>0){p.bounce--;const n=nearestEnemy(p.x,p.y,380,p.hit);if(n){const a=Math.atan2(n.y-p.y,n.x-p.x);p.vx=Math.cos(a)*p.spd;p.vy=Math.sin(a)*p.spd;p.life=Math.max(p.life,.8);}else p.life=0;}
        else if(!p.pierce&&!p.boomer){p.life=0;emitThemed(p.x,p.y,p.pl,6,150);}
        if(p.life<=0)break;
      }
      if(p.life<=0&&p.aoe&&!p.exploded)explode(p);
    }else{
      p.x+=p.vx*dt;p.y+=p.vy*dt;
      if(rng()<.4)part({x:p.x,y:p.y,vx:0,vy:0,life:.35,max:.35,size:p.size,col:p.col,type:'glow'});
      if(P.dome&&d2(P.x,P.y,p.x,p.y)<P.dome.r){p.life=0;emitThemed(p.x,p.y,P.dome.pl,6,140);continue;}
      if(!P.dead&&d2(P.x,P.y-10,p.x,p.y)<P.r+p.size){hurtPlayer(p.dmg,p.src);p.life=0;ring(p.x,p.y,4,30,.25,p.col,3);}
    }
    if(p.x<-50||p.y<-50||p.x>Z.w+50||p.y>Z.h+50)p.life=0;
  }
  projs=projs.filter(p=>p.life>0);
}
function explode(p){
  p.exploded=1;ring(p.x,p.y,8,p.aoe,.4,p.pl.main,12);ring(p.x,p.y,4,p.aoe*.7,.3,p.pl.core,4);emitThemed(p.x,p.y,p.pl,30,p.aoe*2.4);shake(5);
  for(const e of enemies)if(d2(e.x,e.y,p.x,p.y)<p.aoe+e.sz)hitEnemy(e,p.m,Object.assign({fx:p.x,fy:p.y},p));
}

/* ---------- Ground zones & traps ---------- */
function updGround(dt){
  for(const z of gfx){
    z.t+=dt;if(z.follow){z.x=P.x;z.y=P.y;}
    if(z.trap){
      z.armed-=dt;if(z.armed<=0){const e=enemies.find(e=>!e.dead&&d2(e.x,e.y,z.x,z.y)<z.r*.55+e.sz);
        if(e){ring(z.x,z.y,8,z.r,.4,z.pl.main,10);emitThemed(z.x,z.y,z.pl,34,z.r*2.2);fx.push({k:'rune',x:z.x,y:z.y,r:z.r*.8,t:0,dur:.6,pl:z.pl});shake(4);
          for(const o of enemies)if(d2(o.x,o.y,z.x,z.y)<z.r+o.sz)hitEnemy(o,z.m,z.o);
          if(z.o.st&&z.o.st.root)fx.push({k:'vines',x:z.x,y:z.y,r:z.r,t:0,dur:2.5,pl:z.pl});z.t=z.dur;}}
      continue;
    }
    z.acc+=dt;
    if(z.pull)for(const e of enemies){const d=d2(e.x,e.y,z.x,z.y);if(d<z.r*1.3&&d>10&&!e.m.boss){e.x+=(z.x-e.x)/d*z.pull*dt;e.y+=(z.y-e.y)/d*z.pull*dt;}}
    if(z.acc>=z.tick){z.acc-=z.tick;
      for(const e of enemies)if(d2(e.x,e.y,z.x,z.y)<z.r+e.sz&&z.m>0)hitEnemy(e,z.m,z.o);
      if(z.heal&&d2(P.x,P.y,z.x,z.y)<z.r){C182.hsrc='zone';try{healP(P.maxHp*z.heal,true);}finally{C182.hsrc=null;}}
      if(z.bolt){const a=rand(0,TAU),r=rand(0,z.r),x=z.x+Math.cos(a)*r,y=z.y+Math.sin(a)*r;fx.push({k:'bolt',pts:[[x+rand(-40,40),y-320],[x+rand(-15,15),y-150],[x,y]],t:0,dur:.25,pl:G.theme==='auto'?{...THEMES.ice,main:'#e6f8ff'}:z.pl});ring(x,y,4,50,.25,z.pl.main,4);}
    }
  }
  gfx=gfx.filter(z=>z.t<z.dur);
}

/* ---------- Orbs ---------- */
function updOrbs(dt){
  const mag=G.auto?320:160;
  for(const o of orbs){
    o.t+=dt;o.x+=o.vx*dt;o.y+=o.vy*dt;o.vx*=Math.pow(.05,dt);o.vy*=Math.pow(.05,dt);
    const d=d2(o.x,o.y,P.x,P.y);
    if(!P.dead&&d<mag&&o.t>.35){const s=(1-d/mag)*900+120;o.x+=(P.x-o.x)/d*s*dt;o.y+=(P.y-o.y)/d*s*dt;}
    if(!P.dead&&d<26&&o.t>.35){o.dead=1;
      if(o.kind==='hp'){C182.hsrc='pickup';try{healP(P.maxHp*.08);}finally{C182.hsrc=null;}}
      else if(o.kind==='mp'){const a=P.maxMp*.12;P.mp=Math.min(P.maxMp,P.mp+a);textAt(P.x,P.y-50,'+'+fmt(a)+' MP','#5ef0e0',14);}
      else{P.sp=Math.min(250,P.sp+1);recalc();textAt(P.x,P.y-60,'SPIRIT POWER +1','#ffbe5c',15);}
      emitThemed(P.x,P.y-10,o.kind==='power'?THEMES.holy:o.kind==='hp'?{...THEMES.spirit,main:'#8dffc8'}:THEMES.spirit,10,120);}
    if(o.t>40)o.dead=1;
  }
  orbs=orbs.filter(o=>!o.dead);
}

/* ---------- FX & particles update ---------- */
function updFx(dt){
  for(const f of fx){
    f.t+=dt;
    if(f.k==='meteor'&&!f.hit&&f.t>=f.fall){f.hit=1;G.fxBoost=(f.o&&f.o.fxk)||1;if(G.fxBoost>=1.5)ring(f.x,f.y,f.r*.3,f.r*1.3,.6,f.pl.accent,5);
      ring(f.x,f.y,8,f.r,.45,f.pl.main,f.big?20:10);emitThemed(f.x,f.y,f.pl,f.big?60:18,f.r*2.5);
      if(f.pillar)fx.push({k:'pillar',x:f.x,y:f.y,t:0,dur:.8,col:f.pl.accent,w:f.r*.8,h:500});
      if(!f.arrows)fx.push({k:'crack',x:f.x,y:f.y,t:0,dur:1.2,pl:f.pl,seed:rng()*999,r:f.r*.7});
      shake(f.big?14:f.arrows?1:4);
      for(const e of enemies)if(d2(e.x,e.y,f.x,f.y)<f.r+e.sz)hitEnemy(e,f.m,Object.assign({fx:f.x,fy:f.y,kb:f.big?120:30},f.o));G.fxBoost=1;}
    if(f.k==='cres'&&f.t<f.dur&&rng()<.6){const p=f.t/f.dur,a=f.a0+(f.a1-f.a0)*ease(p),cx=f.follow?P.x:f.x,cy=(f.follow?P.y:f.y)-6;emitThemed(cx+Math.cos(a)*f.r,cy+Math.sin(a)*f.r,f.pl,1,60,{life:.6});}
  }
  fx=fx.filter(f=>f.k==='meteor'?f.t<f.fall+.05:f.t<(f.dur+(f.fade||0)));
}
function updParts(dt){
  let j=0;
  for(let i=0;i<parts.length;i++){const p=parts[i];p.life-=dt;if(p.life<=0)continue;
    const dr=Math.pow(p.drag,dt*60);p.vx*=dr;p.vy*=dr;p.vy+=p.grav*dt;p.x+=p.vx*dt+(p.sway?Math.sin(time*4+p.ph)*p.sway*dt:0);p.y+=p.vy*dt;p.rot+=p.vr*dt;p.size+=p.grow*dt;parts[j++]=p;}
  parts.length=j;
  for(const t of texts){t.life-=dt;t.y+=t.vy*dt;t.x+=t.vx*dt;t.vy*=Math.pow(.2,dt);}
  texts=texts.filter(t=>t.life>0);
}
let tumbles=[];
function updAmbient(dt){
  const Z=ZONES[G.zone],n={mote:40,firefly:90,sand:80,ash:80,snow:260,ember:80,bubble:110,void:70}[Z.amb]||40;
  while(amb.length<n)amb.push(newAmb(Z.amb,true));
  if(amb.length>n)amb.length=n;
  const gust=Z.amb==='snow'?1+Math.max(0,Math.sin(time*.35))*1.6:1;
  for(const a of amb){a.x+=a.vx*dt*(a.k==='snow'?gust:1)+Math.sin(time*a.f+a.ph)*a.sw*dt;a.y+=a.vy*dt;a.life-=dt;
    const sx=a.x-cam.x,sy=a.y-cam.y;if(a.life<=0||sx<-80||sy<-80||sx>VW+80||sy>VH+80)Object.assign(a,newAmb(Z.amb,false));}
  // desert tumbleweeds rolling with the wind
  if(ZB()==='desert'){while(tumbles.length<5)tumbles.push({x:cam.x+rand(-200,VW),y:cam.y+rand(0,VH),vx:rand(90,170),r:rand(12,22),rot:0,hop:rand(0,6)});
    for(const t of tumbles){t.x+=t.vx*dt;t.rot+=t.vx*dt/t.r;t.hop+=dt*4;if(t.x-cam.x>VW+100||Math.abs(t.y-cam.y-VH/2)>VH){t.x=cam.x-rand(60,300);t.y=cam.y+rand(0,VH);}}}else tumbles.length=0;
  // deep sea: bubbles rising from the seabed
  if(ZB()==='deepsea'&&rng()<.5)part({x:cam.x+rand(0,VW),y:cam.y+VH+10,vx:rand(-8,8),vy:rand(-90,-40),life:rand(4,7),max:7,size:rand(2,5),col:'#bff6ff',type:'bubble',drag:1,sway:18});
  // lava rivers boil
  if(ZB()==='lava'&&Z.lavaP&&rng()<.5){const p=pick(Z.lavaP);if(inView(p[0],p[1],0)){const x=p[0]+rand(-40,40),y=p[1]+rand(-30,30);ring(x,y,2,rand(12,24),.45,'#ffcf6b',3);for(let i=0;i<4;i++)part({x,y,vx:rand(-50,50),vy:rand(-150,-50),life:.6,max:.6,size:rand(2,3.5),col:pick(['#ffbe5c','#ff6a1a']),type:'spark',grav:260,drag:.97});}}
  // dark continent: rifts leak void motes
  if(ZB()==='dark'&&rng()<.3)part({x:cam.x+rand(0,VW),y:cam.y+rand(0,VH),vx:0,vy:rand(-40,-15),life:2,max:2,size:rand(10,20),col:'#12001f',type:'smoke',grow:10,drag:.99});
}
function newAmb(k,init){
  const x=cam.x+rand(-40,VW+40),y=cam.y+rand(-40,VH+40);
  const b={x,y,vx:0,vy:0,life:rand(4,10),ph:rand(0,TAU),f:rand(1,3),sw:10,size:rand(2,4),col:'#ffffff',k};
  switch(k){
    case 'firefly':Object.assign(b,{vx:rand(-10,10),vy:rand(-10,10),sw:30,col:pick(['#c4ff9e','#7dffc4','#ffe38a']),size:rand(3,6)});break;
    case 'sand':Object.assign(b,{vx:rand(120,220),vy:rand(-10,20),col:'#e8c49a',size:rand(1,3),sw:6});if(!init)b.x=cam.x-30;break;
    case 'ash':Object.assign(b,{vx:rand(20,60),vy:rand(10,40),col:pick(['#9a8a8a','#ff8a3d','#6a6068']),size:rand(1.5,3.5),sw:20});break;
    case 'snow':Object.assign(b,{vx:rand(60,140),vy:rand(70,150),col:'#ffffff',size:rand(1.2,4.5),sw:25,big:rng()<.08});if(b.big)b.size=rand(6,10);if(!init){if(rng()<.5)b.y=cam.y-20;else b.x=cam.x-40;}break;
    case 'ember':Object.assign(b,{vx:rand(-15,15),vy:rand(-70,-30),col:pick(['#ff8a3d','#ffbe5c','#ff5a2a']),size:rand(1.5,3.5),sw:20});if(!init)b.y=cam.y+VH+20;break;
    case 'bubble':Object.assign(b,{vx:rand(-8,8),vy:rand(-60,-20),col:'#9bf4ff',size:rand(1.5,6),sw:15,life:rand(8,14)});if(!init)b.y=cam.y+VH+20;break;
    case 'void':Object.assign(b,{vx:rand(-10,10),vy:rand(-30,-8),col:pick(['#b04cff','#ff4fd8','#6a1bd1']),size:rand(2,5),sw:25});break;
    default:Object.assign(b,{vx:rand(-8,8),vy:rand(-18,-4),col:pick(['#8dffc8','#ffbe5c','#5ef0e0']),size:rand(1.5,3.5),sw:15});
  }
  return b;
}
/* =====================================================================
   Rendering
   ===================================================================== */
const spriteCache={};
function glowSprite(col){
  let c=spriteCache[col];if(c)return c;
  c=document.createElement('canvas');c.width=c.height=64;const g=c.getContext('2d');
  const gr=g.createRadialGradient(32,32,0,32,32,32);gr.addColorStop(0,rgba(col,1));gr.addColorStop(.22,rgba(col,.65));gr.addColorStop(.55,rgba(col,.18));gr.addColorStop(1,rgba(col,0));
  g.fillStyle=gr;g.fillRect(0,0,64,64);spriteCache[col]=c;return c;
}
function glow(x,y,r,col,a=1){if(a<=0||r<=0)return;ctx.globalAlpha=Math.min(1,a);ctx.drawImage(glowSprite(col),x-r,y-r,r*2,r*2);}
const add=()=>{ctx.globalCompositeOperation='lighter';};
const norm=()=>{ctx.globalCompositeOperation='source-over';ctx.globalAlpha=1;};
function ell(x,y,rx,ry,col,a){ctx.globalAlpha=a;ctx.fillStyle=col;ctx.beginPath();ctx.ellipse(x,y,Math.max(.1,rx),Math.max(.1,ry),0,0,TAU);ctx.fill();ctx.globalAlpha=1;}
function inView(x,y,m=120){return x>cam.x-m&&y>cam.y-m&&x<cam.x+VW+m&&y<cam.y+VH+m;}

let fogSprite=null;
function makeFog(){const c=document.createElement('canvas');c.width=c.height=256;const g=c.getContext('2d');srand(5);
  for(let i=0;i<40;i++){const x=srr(40,216),y=srr(40,216),r=srr(30,90);const gr=g.createRadialGradient(x,y,0,x,y,r);gr.addColorStop(0,'rgba(255,255,255,.12)');gr.addColorStop(1,'rgba(255,255,255,0)');g.fillStyle=gr;g.fillRect(0,0,256,256);}
  return c;}

function render(){
  ctx.setTransform(DPR,0,0,DPR,0,0);norm();
  ctx.fillStyle=(window.EDGE_BG||'#03060f');ctx.fillRect(0,0,W,H);
  const Z=ZONES[G.zone];
  const sx=G.shake?rand(-G.shake,G.shake):0,sy=G.shake?rand(-G.shake,G.shake):0;
  camSync();const CZ=camZ(),CT=camT();
  const cx=Math.round(cam.x-sx),cy=Math.round(cam.y-sy);
  ctx.save();ctx.translate(sx*CZ,sy*CZ);camApply(ctx);      // v11: zoom + pitch + yaw rotation (ground foreshortened & rotated)
  // background (painterly bake at half res)
  if(BG){const bx=Math.max(0,cx),by=Math.max(0,cy),w=Math.min(cx+VW+2,Z.w)-bx,h=Math.min(cy+VH+2,Z.h)-by;
    if(w>0&&h>0){if(window.__TILEBG&&window.__TILEBG.zone===G.zone)window.__TILEBG.draw(ctx,bx,by,w,h);else ctx.drawImage(BG,bx*BGS,by*BGS,w*BGS,h*BGS,bx,by,w,h);}}
  // animated surface overlays
  surfaceFx(Z);
  // ground-layer props (pools, rifts, drifts, vines)
  const vis=[];for(const p of PROPS){if(!propVisible(p))continue;if(PROP_DEFS[p.t].layer==='ground')drawProp(p);else vis.push(p);}
  // lights
  add();for(const l of LIGHTS){if(!inView(l.x,l.y,80))continue;const p=.65+.35*Math.sin(time*l.sp+l.ph);glow(l.x,l.y,l.r*(l.lamp?1:1.6)*(.85+.15*p),l.col,.55*p);if(l.lamp)glow(l.x,l.y,5,'#fff4d6',.9);}norm();
  // ground effects
  for(const z of gfx)drawGround(z);
  for(const f of fx)if(f.k==='crack'||f.k==='rune'||f.k==='vines')drawFx(f);
  // world objects
  for(const g of GATES)bb(g.x,g.y,()=>drawGate(g));
  if(WAY)bb(WAY.x,WAY.y,drawWaystone);
  if(NEXUS)bb(NEXUS.x,NEXUS.y,drawNexus);
  drawBeacons();
  // telegraphs
  for(const e of enemies)if(e.tele)drawTele(e);
  drawRaidTele();
  // orbs
  for(const o of orbs)bb(o.x,o.y,()=>drawOrb(o));
  for(const l of loot)if(inView(l.x,l.y,40))bb(l.x,l.y,()=>drawLoot(l));
  // entities sorted by y
  if(G.showRadii)drawRadii();
  const ents=vis;for(const e of enemies)if(inView(e.x,e.y,150))ents.push(e);for(const u of summons)ents.push(u);ents.push(P);for(const n of NPCS)ents.push(n);for(const b of BEACONS)if(b.zone===G.zone&&inView(b.x,b.y,160))ents.push(b);for(const c of RCHESTS)if(c.zone===G.zone&&inView(c.x,c.y,160))ents.push(c);
  ents.sort((a,b)=>depthKey(a)-depthKey(b));
  for(const e of ents)bb(e.x,e.y,()=>{if(e===P){drawPlayer();drawCastBar();}else if(e.sd)drawSummon(e);else if(e.chest)drawChest(e);else if(e.to&&e.zone)drawBeacon(e);else if(e.kind)drawMerchant(e);else if(e.t&&PROP_DEFS[e.t])drawProp(e);else drawEnemy(e);});
  for(const t of tumbles)bb(t.x,t.y,()=>drawTumble(t));
  // projectiles & fx
  for(const p of projs)drawProj(p);
  for(const f of fx)if(!(f.k==='crack'||f.k==='rune'||f.k==='vines'))drawFx(f);
  drawParts();if(window.MNFIX&&MNFIX.flush)MNFIX.flush(bb);
  // ambient
  add();for(const a of amb){const al=Math.min(1,a.life)*.8;if(a.k==='snow'){if(a.big){glow(a.x,a.y,a.size*2,'#ffffff',al*.6);continue;}norm();ctx.globalAlpha=al*.85;ctx.fillStyle='#ffffff';ctx.beginPath();ctx.arc(a.x,a.y,a.size,0,TAU);ctx.fill();add();}
    else if(a.k==='bubble'){ctx.globalAlpha=al*.6;ctx.strokeStyle=a.col;ctx.lineWidth=1;ctx.beginPath();ctx.arc(a.x,a.y,a.size,0,TAU);ctx.stroke();}
    else if(a.k==='sand'){ctx.globalAlpha=al*.35;ctx.strokeStyle=a.col;ctx.lineWidth=a.size;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(a.x-a.vx*.06,a.y);ctx.stroke();}
    else glow(a.x,a.y,a.size*(a.k==='firefly'?4:3),a.col,al*(a.k==='firefly'?.6+.4*Math.sin(time*5+a.ph):.7));}norm();
  // texts
  drawTexts();
  drawEditorOverlay();
  ctx.restore();
  applyLighting(cx,cy);
  if(ZB()==='deepsea')godRays();
  if(ZB()==='snow'){const k=Math.max(0,Math.sin(time*.35));if(k>.2){const g=ctx.createLinearGradient(0,0,W,H);g.addColorStop(0,`rgba(235,245,255,${.18*k})`);g.addColorStop(.5,`rgba(235,245,255,${.05*k})`);g.addColorStop(1,`rgba(235,245,255,${.2*k})`);ctx.fillStyle=g;ctx.fillRect(0,0,W,H);}}
  // fog
  if(!fogSprite)fogSprite=makeFog();
  ctx.globalAlpha=ZB()==='deepsea'?.45:ZB()==='dark'?.4:.28;
  const nFog=Math.min(G.gfx==='low'?0:G.gfx==='med'?2:5,fxv('fog'));if(nFog<5)ctx.globalAlpha*=1.6;
  for(let i=0;i<nFog;i++){const s=620+i*90,x=((i*437+time*(12+i*4)-cam.x*.3)%(W+s*2)+W+s*2)%(W+s*2)-s,y=((i*263-cam.y*.3)%(H+s)+H+s)%(H+s)-s*.5;ctx.drawImage(fogSprite,x,y,s*1.6,s);}
  ctx.globalAlpha=1;
  // color wash per zone
  const wash={capital:'rgba(40,80,160,.08)',jungle:'rgba(20,120,110,.07)',desert:'rgba(160,80,60,.06)',wasteland:'rgba(120,60,40,.07)',snow:'rgba(120,170,255,.06)',lava:'rgba(255,60,20,.07)',deepsea:'rgba(20,120,200,.12)',dark:'rgba(120,20,180,.1)'}[ZB()]||'rgba(0,0,0,0)';
  ctx.fillStyle=wash;ctx.fillRect(0,0,W,H);
  drawAtmos();
  // hurt vignette
  if(!vignette){vignette=ctx.createRadialGradient(W/2,H/2,Math.min(W,H)*.35,W/2,H/2,Math.max(W,H)*.75);vignette.addColorStop(0,'rgba(0,0,0,0)');vignette.addColorStop(1,'rgba(2,3,12,.7)');}
  ctx.fillStyle=vignette;ctx.fillRect(0,0,W,H);
  if(P&&(P.hurtT>0||P.hp/P.maxHp<.25)){const a=P.hurtT>0?P.hurtT*1.6:.2+.1*Math.sin(time*5);const g=ctx.createRadialGradient(W/2,H/2,Math.min(W,H)*.3,W/2,H/2,Math.max(W,H)*.7);g.addColorStop(0,'rgba(255,40,80,0)');g.addColorStop(1,`rgba(255,40,80,${Math.min(.5,a)})`);ctx.fillStyle=g;ctx.fillRect(0,0,W,H);}
  // bloom
  // bloom — v22: cheap downsample bloom (the old canvas blur() filter cost ~20 ms per frame)
  if(G.bloom&&(G.gfx||'high')==='high'&&fxv('bloom')){
    const sw=Math.max(8,Math.round(W/10)),sh=Math.max(6,Math.round(H/10));
    if(!BLM.c){BLM.c=document.createElement('canvas');BLM.g=BLM.c.getContext('2d');}
    if(BLM.c.width!==sw||BLM.c.height!==sh){BLM.c.width=sw;BLM.c.height=sh;}
    BLM.n=(BLM.n+1)%2;if(BLM.n===0||BLM.c.width!==sw){
    const g=BLM.g;g.globalCompositeOperation='source-over';g.globalAlpha=1;g.imageSmoothingEnabled=true;g.drawImage(cv,0,0,sw,sh);
    g.globalCompositeOperation='multiply';g.drawImage(BLM.c,0,0);g.drawImage(BLM.c,0,0);   // keep only the bright parts (≈ contrast)
    bctx.globalCompositeOperation='source-over';bctx.filter='none';bctx.imageSmoothingEnabled=true;bctx.clearRect(0,0,bcv.width,bcv.height);bctx.drawImage(BLM.c,0,0,bcv.width,bcv.height);}
    ctx.setTransform(1,0,0,1,0,0);ctx.globalCompositeOperation='screen';ctx.globalAlpha=.7;ctx.imageSmoothingEnabled=true;
    ctx.drawImage(bcv,0,0,cv.width,cv.height);norm();ctx.setTransform(DPR,0,0,DPR,0,0);
  }
}
const BLM={c:null,g:null,n:0},FOGC={c:null,g:null};

/* ---------- Surfaces ---------- */
function surfaceFx(Z){
  if(ZB()==='jungle'&&Z.river){add();for(let i=0;i<Z.river.length;i+=3){const p=Z.river[i];if(!inView(p[0],p[1]))continue;glow(p[0]+Math.sin(time+i)*30,p[1]+Math.cos(time*.7+i)*20,60,'#2fd6c0',.08+.05*Math.sin(time*2+i));}norm();}
  if(ZB()==='lava'&&Z.lavaP){add();for(let i=0;i<Z.lavaP.length;i+=2){const p=Z.lavaP[i];if(!inView(p[0],p[1]))continue;glow(p[0],p[1],70,'#ff5a1a',.12+.08*Math.sin(time*1.5+i*.7));}norm();}
  if(ZB()==='deepsea'){add();ctx.globalAlpha=.06;ctx.strokeStyle='#9bf4ff';ctx.lineWidth=2;
    for(let i=0;i<14;i++){const y0=Math.floor(cam.y/120)*120+i*120;ctx.beginPath();for(let x=cam.x-40;x<cam.x+VW+40;x+=40)ctx.lineTo(x,y0+Math.sin(x*.01+time+i)*20+Math.sin(x*.023-time*.7)*14);ctx.stroke();}norm();}
}

/* ---------- Player ---------- */
// m33 p219: hero ground shadow + glow + ring (was inline in drawPlayer_v1; p219 draws it in the ground pass so grass can cover it)
function heroGround(x,y0,t,pl){
  ell(x,y0+10,18,6,'#000000',.45);
  add();glow(x,y0+6,48,pl.main,.32+.08*Math.sin(t*3));ctx.globalAlpha=.35;ctx.strokeStyle=pl.main;ctx.lineWidth=1.5;ctx.beginPath();ctx.ellipse(x,y0+8,26+Math.sin(t*3)*2,8,0,0,TAU);ctx.stroke();norm();
}
function drawPlayer_v1(){
  if(!P)return;
  const x=P.x,y0=P.y,j=P.jump||0,y=y0-j,t=time,pl=pal(null),dead=P.dead;
  if(dead)return;
  const bob=Math.sin(P.walk*2)*1.5;
  // ghosts / afterimages
  add();for(const g0 of P.ghosts){const o_=wl(g0.x-x,g0.y-y0),g={x:x+o_[0],y:y0+o_[1],pl:g0.pl,life:g0.life};const a=g.life/.3;glow(g.x,g.y-14,30,g.pl.main,a*.5);ctx.globalAlpha=a*.35;ctx.fillStyle=g.pl.main;ctx.beginPath();ctx.ellipse(g.x,g.y-8,11,14,0,0,TAU);ctx.fill();ctx.beginPath();ctx.arc(g.x,g.y-24,8,0,TAU);ctx.fill();}norm();
  // shadow & aura
  if(window.__P219&&__P219.on&&__P219.drawnAt===time&&__P219.ctx===ctx)__P219.mark();else heroGround(x,y0,t,pl);   // m33 p219: ring / shadow drawn in the ground pass (under grass)
  if(typeof aura10Back==='function')try{aura10Back(x,y0);}catch(e){}norm();
  if(P.invT>0&&Math.floor(t*20)%2)ctx.globalAlpha=.55;
  const fa=P.face+camY(),facingUp=Math.sin(fa)<-.2;
  const wa=weaponAngle()+camY();const hx=x+Math.cos(wa)*13,hy=y-6+bob+Math.sin(wa)*8+(P.swing&&P.swing.type==='thrust'?Math.sin(Math.min(1,P.swing.t/P.swing.dur)*Math.PI)*(P.swing.long?22:10)*Math.sin(wa):0);
  const hx2=hx+(P.swing&&P.swing.type==='thrust'?Math.sin(Math.min(1,P.swing.t/P.swing.dur)*Math.PI)*(P.swing.long?22:10)*Math.cos(wa):0);
  const HERO=useHero()?heroFrame(x,y0-j,fa,wa,t,bob):null;G.lastHero=HERO;let wx=HERO?HERO.hx:hx2,wy=HERO?HERO.hy:hy,wBehind=HERO?HERO.behind:facingUp,WA=HERO&&HERO.wa!=null?HERO.wa:wa;
  if(!HERO&&!P.swing&&!P.casting){ // knight / wizard idle: weapon rests in the hand at the side instead of pointing at the mouse
    const sd=Math.cos(fa)>=0?1:-1,wt=P.weapon.t,mv=Math.hypot(P.vx,P.vy)>25?Math.sin(P.walk*1.15):0;
    wx=x+sd*12+Math.cos(fa)*2;wy=y-3+bob+mv*1.5;
    WA=wt==='staff'||wt==='spear'||wt==='book'?-Math.PI/2+sd*.14+mv*.06:(wt==='bow'||wt==='gun')?(sd>0?0:Math.PI):Math.PI/2-sd*(.55+mv*.12);
    wBehind=facingUp;}
  if(wBehind){drawWeapon(ctx,P.weapon.t,wx,wy,WA,WSCALE[P.weapon.t]||.8,wpal(),true);gripHand(wx,wy);}
  if(SPR_OVR.player)drawPlayerSprite(x,y,bob,fa);else if(HERO)drawHeroFrame(HERO);else{
  // cape
  if(P.cape.length){const c=P.cape;ctx.beginPath();const sw=[10,11,12,13,13.5,14];
    for(let i=0;i<c.length;i++)ctx.lineTo(c[i].x-sw[i]+(i?Math.sin(t*4+i)*1.5:0),c[i].y+bob);
    for(let i=c.length-1;i>=0;i--)ctx.lineTo(c[i].x+sw[i]+(i?Math.sin(t*4+i+1)*1.5:0),c[i].y+bob);
    const cg=ctx.createLinearGradient(x,y-14,x,y+24);cg.addColorStop(0,'#1a2860');cg.addColorStop(1,'#0a4a5a');ctx.fillStyle=cg;ctx.fill();
    add();ctx.strokeStyle=rgba(pl.main,.5);ctx.lineWidth=1.2;ctx.stroke();norm();if(P.invT>0&&Math.floor(t*20)%2)ctx.globalAlpha=.55;}
  // legs
  const lk=Math.sin(P.walk*2)*4;
  ctx.fillStyle='#1c2a4e';ctx.beginPath();ctx.ellipse(x-5,y+8+lk*.3,4,6,0,0,TAU);ctx.ellipse(x+5,y+8-lk*.3,4,6,0,0,TAU);ctx.fill();
  // torso
  const tg=ctx.createRadialGradient(x-4,y-12+bob,2,x,y-4+bob,16);tg.addColorStop(0,'#9ab8e8');tg.addColorStop(.45,'#3e5c96');tg.addColorStop(1,'#18264a');
  ctx.fillStyle=tg;ctx.beginPath();ctx.ellipse(x,y-4+bob,11.5,13,0,0,TAU);ctx.fill();
  ctx.fillStyle='#2c4478';ctx.beginPath();ctx.arc(x-11,y-11+bob,5.5,0,TAU);ctx.arc(x+11,y-11+bob,5.5,0,TAU);ctx.fill();
  add();glow(x,y-6+bob,10,pl.accent,.7+.3*Math.sin(t*4));ctx.fillStyle=pl.core;ctx.beginPath();ctx.moveTo(x,y-10+bob);ctx.lineTo(x+3,y-6+bob);ctx.lineTo(x,y-2+bob);ctx.lineTo(x-3,y-6+bob);ctx.fill();norm();
  if(P.invT>0&&Math.floor(t*20)%2)ctx.globalAlpha=.55;
  // head
  const hg=ctx.createRadialGradient(x-3,y-26+bob,1,x,y-22+bob,11);hg.addColorStop(0,'#c8dcff');hg.addColorStop(.5,'#5a78b8');hg.addColorStop(1,'#1c2c58');
  ctx.fillStyle=hg;ctx.beginPath();ctx.arc(x,y-22+bob,9.5,0,TAU);ctx.fill();
  // plume
  add();for(let i=0;i<6;i++){const k=i/6;glow(x-Math.cos(fa)*k*18+Math.sin(t*5+i)*2,y-31+bob-Math.sin(fa)*k*6+k*8,7-k*4,pl.accent,.6-k*.4);}norm();
  // visor
  if(!facingUp){add();ctx.strokeStyle=pl.core;ctx.lineWidth=2.4;ctx.lineCap='round';const vx=Math.cos(fa)*4,vy=Math.max(0,Math.sin(fa))*2;
    ctx.beginPath();ctx.moveTo(x-5+vx,y-22+bob+vy);ctx.lineTo(x+5+vx,y-22+bob+vy);ctx.stroke();glow(x+vx,y-22+bob+vy,12,pl.main,.8);norm();}
  }
  ctx.globalAlpha=1;
  if(!wBehind){drawWeapon(ctx,P.weapon.t,wx,wy,WA,WSCALE[P.weapon.t]||.8,wpal(),true);gripHand(wx,wy);}
  drawGlowFX(x,y0,wx,wy,WA);   // paperdoll: final Glow FX layer
  // charge glow on heavy windup
  if(P.swing&&P.swing.type==='heavy'&&P.swing.t<P.swing.wind){add();const k=P.swing.t/P.swing.wind;glow(hx+Math.cos(wa)*40,hy+Math.sin(wa)*40,20+k*30,wpal().main,.4+k*.6);norm();}
  // dome / halo / shield
  if(P.dome&&!P.dome.v2){const d=P.dome,a=Math.min(1,d.t/.3);add();const g=ctx.createRadialGradient(x,y0-10,d.r*.2,x,y0-10,d.r);g.addColorStop(0,rgba(d.pl.main,0));g.addColorStop(.8,rgba(d.pl.main,.12*a));g.addColorStop(1,rgba(d.pl.core,.5*a));
    ctx.fillStyle=g;ctx.beginPath();ctx.arc(x,y0-10,d.r,0,TAU);ctx.fill();ctx.globalAlpha=.45*a;ctx.strokeStyle=d.pl.accent;ctx.lineWidth=1;
    for(let i=0;i<12;i++){const aa=i/12*TAU+t*.4;ctx.beginPath();ctx.moveTo(x+Math.cos(aa)*d.r,y0-10+Math.sin(aa)*d.r);ctx.lineTo(x+Math.cos(aa+2.1)*d.r,y0-10+Math.sin(aa+2.1)*d.r);ctx.stroke();}norm();}
  if(Object.values(P.buffs).some(b=>b.revive)){add();ctx.strokeStyle='#fff2b8';ctx.lineWidth=2.5;ctx.globalAlpha=.8;ctx.beginPath();ctx.ellipse(x,y-38+bob+Math.sin(t*3)*2,11,4,0,0,TAU);ctx.stroke();glow(x,y-38+bob,16,'#ffd36b',.6);norm();}
  if(P.shield>0){add();ctx.globalAlpha=.35+.1*Math.sin(t*6);ctx.strokeStyle='#9be8ff';ctx.lineWidth=2;ctx.beginPath();ctx.arc(x,y-10,30,0,TAU);ctx.stroke();norm();}
  // buff swirl
  const nb=Object.keys(P.buffs).length;if(nb){add();let i=0;for(const id in P.buffs){const b=P.buffs[id],a=t*2+i*TAU/nb;glow(x+Math.cos(a)*26,y-2+Math.sin(a)*9,8,b.pl?b.pl.main:pl.main,.8);i++;}norm();}
}
function weaponAngle(){
  const s=P.swing,f=P.face;
  if(!s)return f+.9*(Math.cos(f)>=0?1:-1)*.6;
  const k=Math.min(1,s.t/s.dur);
  switch(s.type){
    case 'arc':return s.a0+(s.a1-s.a0)*ease(k);
    case 'heavy':if(s.t<s.wind)return s.ang-2.4*ease(s.t/s.wind);return s.ang-2.4+3.2*ease(Math.min(1,(s.t-s.wind)/(s.dur-s.wind)));
    case 'cast':return s.ang-.5+k;
    default:return s.ang;
  }
}
function drawWeapon_v1(g,t,x,y,a,sc,pl,live){
  g.save();g.translate(x,y);g.rotate(a);g.scale(sc,sc);g.lineCap='round';
  const blade=(len,wd,guard)=>{
    g.fillStyle='#3a2a1a';g.fillRect(-6,-2,8,4);
    g.fillStyle='#c9b27a';g.fillRect(1,-guard,3,guard*2);
    const bg=g.createLinearGradient(0,-wd,0,wd);bg.addColorStop(0,'#f4fbff');bg.addColorStop(.5,'#9ab4d8');bg.addColorStop(1,'#4a5e88');
    g.fillStyle=bg;g.beginPath();g.moveTo(4,-wd);g.lineTo(4+len-wd*1.4,-wd);g.lineTo(4+len,0);g.lineTo(4+len-wd*1.4,wd);g.lineTo(4,wd);g.closePath();g.fill();
    g.globalCompositeOperation='lighter';g.strokeStyle=rgba(pl.main,.9);g.lineWidth=1.4;g.beginPath();g.moveTo(6,0);g.lineTo(2+len,0);g.stroke();
    if(live){g.globalAlpha=.5;g.drawImage(glowSprite(pl.main),len*.2,-wd*3,len,wd*6);g.globalAlpha=1;}g.globalCompositeOperation='source-over';
  };
  switch(t){
    case 'dagger':blade(18,3,5);break;
    case 'sword':case 'scythe':blade(34,3.6,7);break;
    case 'greatsword':blade(54,6,11);break;
    case 'axe':{g.strokeStyle='#5a3e26';g.lineWidth=4;g.beginPath();g.moveTo(-8,0);g.lineTo(46,0);g.stroke();
      const ag=g.createLinearGradient(30,-20,30,20);ag.addColorStop(0,'#f4fbff');ag.addColorStop(1,'#5a6e98');g.fillStyle=ag;
      g.beginPath();g.moveTo(34,-3);g.quadraticCurveTo(38,-24,54,-20);g.quadraticCurveTo(46,0,54,20);g.quadraticCurveTo(38,24,34,3);g.closePath();g.fill();
      g.globalCompositeOperation='lighter';g.strokeStyle=rgba(pl.main,.9);g.lineWidth=2;g.beginPath();g.moveTo(54,-20);g.quadraticCurveTo(46,0,54,20);g.stroke();if(live){g.globalAlpha=.5;g.drawImage(glowSprite(pl.main),34,-26,30,52);g.globalAlpha=1;}g.globalCompositeOperation='source-over';break;}
    case 'spear':{g.strokeStyle='#5a3e26';g.lineWidth=3.2;g.beginPath();g.moveTo(-18,0);g.lineTo(56,0);g.stroke();
      g.fillStyle='#e8f4ff';g.beginPath();g.moveTo(54,-5);g.lineTo(72,0);g.lineTo(54,5);g.closePath();g.fill();
      g.globalCompositeOperation='lighter';if(live){g.globalAlpha=.7;g.drawImage(glowSprite(pl.main),52,-12,26,24);g.globalAlpha=1;}g.fillStyle=pl.accent;g.fillRect(48,-3,5,6);g.globalCompositeOperation='source-over';break;}
    case 'bow':{g.strokeStyle='#6a4a2a';g.lineWidth=3.5;g.beginPath();g.arc(-6,0,22,-1.2,1.2);g.stroke();
      const pull=P.swing&&P.swing.type==='bow'&&live?Math.sin(Math.min(1,P.swing.t/P.swing.dur)*Math.PI)*8:0;
      g.globalCompositeOperation='lighter';g.strokeStyle=rgba(pl.main,.8);g.lineWidth=1;g.beginPath();g.moveTo(-6+Math.cos(-1.2)*22,Math.sin(-1.2)*22);g.lineTo(-pull-8,0);g.lineTo(-6+Math.cos(1.2)*22,Math.sin(1.2)*22);g.stroke();
      g.strokeStyle=rgba(pl.accent,.6);g.lineWidth=2;g.beginPath();g.arc(-6,0,22,-1.2,1.2);g.stroke();g.globalCompositeOperation='source-over';break;}
    case 'staff':{g.strokeStyle='#4a3a5e';g.lineWidth=3.5;g.beginPath();g.moveTo(-14,0);g.lineTo(46,0);g.stroke();
      g.strokeStyle='#c9b27a';g.lineWidth=2;g.beginPath();g.arc(50,0,7,0,TAU);g.stroke();
      g.globalCompositeOperation='lighter';g.drawImage(glowSprite(pl.main),34,-16,32,32);g.drawImage(glowSprite(pl.core),44,-6,12,12);g.globalCompositeOperation='source-over';break;}
  }
  g.restore();
}

/* ---------- Enemies ---------- */
