    if(e.m.jelly){for(let i=0;i<6;i++){ctx.strokeStyle=rgba(e.m.c,.5);ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x-s*.6+i*s*.24,cy+s*.3);for(let k=1;k<6;k++)ctx.lineTo(x-s*.6+i*s*.24+Math.sin(t*3+k+i)*4,cy+s*.3+k*s*.28);ctx.stroke();}
      ctx.fillStyle=rgba(e.m.c,.35);ctx.beginPath();ctx.ellipse(x,cy,s*(1+fl*.08),s*.75,0,Math.PI,TAU);ctx.fill();}
    else{ctx.fillStyle=rgba(e.m.c,.3);for(const sd of [-1,1]){ctx.save();ctx.translate(x,cy);ctx.rotate(sd*(.5+fl*.45));ctx.beginPath();ctx.ellipse(sd*s*.95,0,s*.95,s*.34,0,0,TAU);ctx.fill();ctx.restore();}}
