function drawEnemy_v1(e){
  const m=e.m,s=e.sz,t=time+e.ph,x=e.x+(e.lunge?Math.cos(e.face)*e.lunge*40:0),y=e.y+Math.sin(t*3)*2.5;
  ell(e.x,e.y+s*.35,s*.95,s*.32,'#000000',.4);
  add();glow(x,y-s*.5,s*3,m.c,.22+.06*Math.sin(t*2));glow(x,y-s*.5,s*1.6,m.c2,.22);norm();
  if(e.wind>0){add();const k=1-e.wind/.38;ctx.globalAlpha=.5*k;ctx.strokeStyle='#ff6b8b';ctx.lineWidth=3;ctx.beginPath();ctx.arc(e.x,e.y,s+P.r+14,e.face-.9,e.face+.9);ctx.stroke();glow(x+Math.cos(e.face)*s,y-s*.5,s*k,'#ff6b8b',.6);norm();}
  if(SPR_OVR['mob:'+e.type])drawMobSprite(e,x,y,s);else (SHAPES[m.sh]||SHAPES.blob)(e,x,y,s,t);
  if(e.flash>0){add();glow(x,y-s*.6,s*2,'#ffffff',e.flash*6);norm();}
  if(e.st.slow){add();ctx.globalAlpha=.4;ctx.strokeStyle='#9be8ff';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(e.x,e.y+s*.3,s,s*.35,0,0,TAU);ctx.stroke();norm();}
  if(e.st.root){ctx.strokeStyle='#4fbf5a';ctx.lineWidth=3;for(let i=0;i<5;i++){const a=i/5*TAU;ctx.beginPath();ctx.moveTo(e.x+Math.cos(a)*s,e.y+s*.3+Math.sin(a)*s*.3);ctx.quadraticCurveTo(e.x+Math.cos(a)*s*.3,e.y-s*.6,e.x+Math.cos(a+1)*s*.4,e.y-s*.2);ctx.stroke();}}
  const top=y-s*(m.sh==='wraith'||m.sh==='lord'?2.2:m.sh==='elemental'?2.4:1.9);
  if(e.st.stun){add();for(let i=0;i<3;i++){const a=time*5+i*TAU/3;glow(x+Math.cos(a)*s*.6,top+Math.sin(a)*4,7,'#ffe38a',1);}norm();}
  if(e.st.fear){add();ctx.strokeStyle='#b98cff';ctx.lineWidth=2;ctx.beginPath();for(let i=0;i<20;i++){const a=i*.5+time*6,r=i*.6;ctx.lineTo(x+Math.cos(a)*r,top-6+Math.sin(a)*r*.5);}ctx.stroke();norm();}
  if(e.st.silence){ctx.fillStyle='#b98cff';ctx.font='700 13px Cinzel, serif';ctx.textAlign='center';ctx.fillText('···',x+s*.8,top);}
  // name & bar: passive (Lv<=80) green, aggressive (Lv>80) red
  if(d2(e.x,e.y,P.x,P.y)<720||e.hitT>0||m.boss){
    const ag=isAggressive(e),bw=m.boss?170:Math.max(46,s*2.4),by=top-12;
    const _bar=yb=>{ctx.fillStyle='rgba(3,6,18,.8)';rrect(x-bw/2-1,yb-1,bw+2,7,4);ctx.fill();
    const k=clamp(e.hp/e.maxHp,0,1);const g=ctx.createLinearGradient(x-bw/2,0,x+bw/2,0);
    if(ag){g.addColorStop(0,'#b0102a');g.addColorStop(1,'#ff6a7a');}else{g.addColorStop(0,'#1f9a4a');g.addColorStop(1,'#8dffa8');}
    ctx.fillStyle=g;rrect(x-bw/2,yb,bw*k,5,3);ctx.fill();};e._bw=bw;e._bar=_bar;if(!(window.NPLATE232&&NPLATE232.on&&window.MNFIX&&MNFIX.on))_bar(by);
    ctx.fillStyle=(window.__MOBNAME&&__MOBNAME.on)?'#ffffff':lvGapCol(e);
    ctx.font=`${m.boss||m.elite?700:600} ${m.boss?14:11}px "Noto Sans Thai", system-ui, sans-serif`;ctx.textAlign='center';ctx.shadowColor='#000';ctx.shadowBlur=4;
    {const _t0=`${(e.L-P.lvl)>=25?'☠ ':''}Lv${e.L}${dgapTag(e)} ${m.n}${m.elite?' ★':''}`;const _M=window.MNFIX&&MNFIX.on?MNFIX.begin(e,_t0,x,by-5,ctx):null;if(_M&&_M.hide){ctx.shadowBlur=0}else{const _t=_M?_M.t:_t0,_ly=_M?_M.y:by-5;const _run=()=>{if(window.NPLATE232&&NPLATE232.on&&window.MNFIX&&MNFIX.on&&e._bar){try{NPLATE232.bar(e,x,by,_ly)}catch(_){}}if(window.__MOBNAME&&__MOBNAME.on){const cmb=!!(e.aggro||e.hitT>0||(typeof time==='number'&&time-(e._rbHit||-99)<3)),sw=' ⚔';const w1=ctx.measureText(_t).width,w2=ctx.measureText(sw).width,xc=x-w2/2,off=e._mnOff||0;ctx.lineWidth=3;ctx.lineJoin='round';ctx.strokeStyle='rgba(0,0,0,.85)';ctx.strokeText(_t,xc+off,_ly);ctx.fillStyle='#ffffff';ctx.fillText(_t,xc,_ly);e._mnOff=(e._elTag&&e._elTag.t===time)?(e._elTag.x-xc):0;const ax=xc+e._mnOff;ctx.textAlign='left';ctx.strokeText(sw,ax+w1/2,_ly);ctx.fillStyle=cmb?'#ff3b3b':'#ffffff';ctx.fillText(sw,ax+w1/2,_ly);ctx.textAlign='center';ctx.lineWidth=1}else ctx.fillText(`${_t}${e.aggro&&!ag?' ⚔':''}`,x,_ly);ctx.shadowBlur=0;};if(_M&&_M.defer!==false&&MNFIX.defer){MNFIX.defer(e,ctx.fillText,_M.f,_M.a,_run)}else _run();ctx.shadowBlur=0;}}
  }
  if(e.alertT>0){add();glow(x,top-30,18,'#ff5a6a',e.alertT);norm();}
}
function drawRadii(){
  ctx.save();ctx.lineWidth=1.5;
  for(const e of enemies){if(!inView(e.x,e.y,500))continue;const ag=isAggressive(e),dr=detectR(e),ar=attackR(e);
    ctx.setLineDash([6,6]);ctx.strokeStyle=ag?'rgba(255,90,106,.45)':'rgba(125,255,154,.35)';ctx.beginPath();ctx.ellipse(e.x,e.y,dr,dr*.62,0,0,TAU);ctx.stroke();
    ctx.setLineDash([]);ctx.strokeStyle=ag?'rgba(255,160,90,.7)':'rgba(141,255,200,.6)';ctx.beginPath();ctx.ellipse(e.x,e.y,ar+e.sz,(ar+e.sz)*.62,0,0,TAU);ctx.stroke();}
  ctx.restore();
}
function godRays(){
  ctx.save();ctx.globalCompositeOperation='lighter';
  for(let i=0;i<5;i++){const x=((i*337-cam.x*.15+time*14)%(W+600)+W+600)%(W+600)-300,w=90+i*30;
    const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'rgba(140,230,255,.12)');g.addColorStop(1,'rgba(140,230,255,0)');ctx.fillStyle=g;
    ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x+w,0);ctx.lineTo(x+w+260,H);ctx.lineTo(x+200,H);ctx.closePath();ctx.globalAlpha=.6+.4*Math.sin(time*.5+i);ctx.fill();}
  ctx.restore();
}
function drawTumble(t){const y=t.y-Math.abs(Math.sin(t.hop))*14;ell(t.x+4,t.y+t.r*.6,t.r,t.r*.3,'#000000',.25);ctx.save();ctx.translate(t.x,y);ctx.rotate(t.rot);ctx.strokeStyle='#b8925a';ctx.lineWidth=1.5;
  for(let i=0;i<12;i++){const a=i*.9;ctx.beginPath();ctx.arc(Math.cos(a)*t.r*.2,Math.sin(a*1.7)*t.r*.2,t.r*(.6+(i%3)*.15),a,a+2.2);ctx.stroke();}ctx.restore();}
function rrect(x,y,w,h,r){ctx.beginPath();ctx.roundRect?ctx.roundRect(x,y,Math.max(0,w),h,r):ctx.rect(x,y,Math.max(0,w),h);}
function drawTele(e){const T=e.tele,k=1-T.t/T.max;add();ctx.globalAlpha=.25+.3*k;ctx.fillStyle=rgba(e.m.c,.25*k);ctx.beginPath();ctx.arc(T.x,T.y,T.r*k,0,TAU);ctx.fill();ctx.strokeStyle=e.m.c;ctx.lineWidth=3;ctx.beginPath();ctx.arc(T.x,T.y,T.r,0,TAU);ctx.stroke();norm();}

/* ---------- Summons ---------- */
function drawSummon(u){
  const sd=u.sd,t=time+u.ph,x=u.x+(u.lunge?Math.cos(u.face)*u.lunge*50:0),a=Math.min(1,u.t/1.5);
  const fly=sd.fly?30+Math.sin(t*3)*4:0,y=u.y-fly;
  ell(u.x,u.y+6,sd.sz*.8,sd.sz*.3,'#000000',.35*a);
  ctx.globalAlpha=a;add();glow(x,y-sd.sz*.4,sd.sz*2.6,sd.col,.35*a);norm();ctx.globalAlpha=a;
  const c=Math.cos(u.face),s=Math.sin(u.face),z=sd.sz;
  if(u.kind==='wolf'){ctx.strokeStyle=rgba(sd.col,.8);ctx.lineWidth=3;ctx.lineCap='round';const st=Math.sin(t*14)*5;for(const [k,ph] of [[-.5,1],[.5,-1]])for(const sd2 of [-1,1]){ctx.beginPath();ctx.moveTo(x+c*z*k,y-z*.3+sd2*3);ctx.lineTo(x+c*z*k+st*ph,y+z*.3);ctx.stroke();}
    add();ctx.fillStyle=rgba(sd.col,.55);ctx.beginPath();ctx.ellipse(x,y-z*.4,z*1.1,z*.5,Math.atan2(s*.5,c)*.6,0,TAU);ctx.fill();
    const hx=x+c*z*1.1,hy=y-z*.6+s*z*.3;ctx.beginPath();ctx.arc(hx,hy,z*.45,0,TAU);ctx.fill();ctx.beginPath();ctx.moveTo(hx-3,hy-4);ctx.lineTo(hx-1,hy-z*.9);ctx.lineTo(hx+3,hy-5);ctx.fill();
    for(let i=0;i<5;i++)glow(x-c*z*(1.1+i*.3),y-z*.5-i*2+Math.sin(t*6+i)*3,z*.5-i,sd.col,.5);glow(hx+c*3,hy,5,'#ffffff',1);norm();}
  else if(u.kind==='falcon'){const fl=Math.sin(t*14);add();ctx.fillStyle=rgba(sd.col,.6);for(const k of [-1,1]){ctx.beginPath();ctx.moveTo(x,y);ctx.quadraticCurveTo(x-s*k*z*1.6,y+c*k*z*1.2-z*fl,x-s*k*z*2.2-c*z*.5,y+c*k*z*1.6-z*fl*1.2);ctx.lineTo(x-c*z*.4,y-s*z*.3);ctx.fill();}
    ctx.beginPath();ctx.ellipse(x,y,z*.9,z*.4,u.face,0,TAU);ctx.fill();glow(x+c*z*.8,y+s*z*.4,6,'#ffffff',1);glow(x,y,z*1.5,sd.col,.5);norm();}
  else if(u.kind==='imp'){const cy=y-z*.9;const g=ctx.createRadialGradient(x-2,cy-3,1,x,cy,z);g.addColorStop(0,'#ffb080');g.addColorStop(1,'#6a0a2a');ctx.fillStyle=g;ctx.beginPath();ctx.arc(x,cy,z*.75,0,TAU);ctx.fill();
    ctx.fillStyle='#3a0a1a';for(const k of [-1,1]){ctx.beginPath();ctx.moveTo(x+k*z*.4,cy-z*.5);ctx.lineTo(x+k*z*.7,cy-z*1.2);ctx.lineTo(x+k*z*.15,cy-z*.7);ctx.fill();
      ctx.fillStyle='rgba(106,10,42,.7)';ctx.beginPath();ctx.moveTo(x+k*z*.5,cy);ctx.lineTo(x+k*z*1.6,cy-z*.6+Math.sin(t*16)*4);ctx.lineTo(x+k*z*1.3,cy+z*.4);ctx.fill();ctx.fillStyle='#3a0a1a';}
    add();glow(x,cy+z,z,'#ff6a3d',.7+.3*Math.sin(t*10));glow(x-4,cy,4,'#ffe38a',1);glow(x+4,cy,4,'#ffe38a',1);norm();}
  else{const cy=y-z*.9;ctx.fillStyle='#d8e2f4';ctx.beginPath();ctx.arc(x,cy,z*.45,0,TAU);ctx.fill();ctx.strokeStyle='#c8d6ee';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x,cy+z*.4);ctx.lineTo(x,y);for(let i=0;i<3;i++){ctx.moveTo(x-z*.35,cy+z*.6+i*4);ctx.lineTo(x+z*.35,cy+z*.6+i*4);}ctx.stroke();
    ctx.strokeStyle='#9fb4ff';ctx.lineWidth=2.5;ctx.beginPath();ctx.moveTo(x+c*z*.5,cy+z*.5);ctx.lineTo(x+c*z*1.4,cy+z*.2+s*z*.6);ctx.stroke();
    add();glow(x-3,cy,5,'#b04cff',1);glow(x+3,cy,5,'#b04cff',1);glow(x,cy+z*.4,z*1.2,'#6a1bd1',.35);norm();}
  ctx.globalAlpha=1;
}

/* ---------- World objects ---------- */
function runeCircle(x,y,r,rot,col,a,ry=.45){
  ctx.save();ctx.translate(x,y);ctx.scale(1,ry);ctx.globalAlpha=a;ctx.strokeStyle=col;ctx.lineWidth=2/ry*.6;
  ctx.beginPath();ctx.arc(0,0,r,0,TAU);ctx.stroke();ctx.beginPath();ctx.arc(0,0,r*.82,0,TAU);ctx.stroke();
  ctx.rotate(rot);ctx.beginPath();for(let i=0;i<7;i++){const a1=i/6*TAU*2;ctx.lineTo(Math.cos(a1)*r*.8,Math.sin(a1)*r*.8);}ctx.stroke();
  for(let i=0;i<12;i++){const a1=i/12*TAU;ctx.save();ctx.rotate(a1);ctx.beginPath();ctx.moveTo(r*.86,-4);ctx.lineTo(r*.94,0);ctx.lineTo(r*.86,4);ctx.moveTo(r*.9,-6);ctx.lineTo(r*.9,6);ctx.stroke();ctx.restore();}
  ctx.restore();ctx.globalAlpha=1;
}
function drawWaystone(){
  const x=WAY.x,y=WAY.y,on=G.unlocked.has(G.zone),t=time;
  add();runeCircle(x,y,90,t*(on?.4:.05),on?'#5ef0e0':'#56688f',on?.8:.35);if(on)glow(x,y,120,'#5ef0e0',.25+.08*Math.sin(t*2));norm();
  ell(x+10,y+6,26,9,'#000000',.5);
  const g=ctx.createLinearGradient(x-16,0,x+16,0);g.addColorStop(0,on?'#2a3c6a':'#262c3a');g.addColorStop(.5,on?'#4a6a9a':'#3a4254');g.addColorStop(1,on?'#141e3a':'#161a24');
  ctx.fillStyle=g;ctx.beginPath();ctx.moveTo(x-16,y);ctx.lineTo(x-11,y-74);ctx.lineTo(x,y-96);ctx.lineTo(x+11,y-74);ctx.lineTo(x+16,y);ctx.closePath();ctx.fill();
  ctx.strokeStyle=on?'rgba(160,240,255,.4)':'rgba(140,150,170,.25)';ctx.lineWidth=1.5;ctx.stroke();
  if(on){add();ctx.strokeStyle='#8dffe8';ctx.lineWidth=2;for(let i=0;i<5;i++){const yy=y-14-i*13;ctx.globalAlpha=.5+.5*Math.sin(t*3-i);ctx.beginPath();ctx.moveTo(x-5,yy);ctx.lineTo(x,yy-5);ctx.lineTo(x+5,yy);ctx.stroke();}
    const cy=y-118+Math.sin(t*2)*5;glow(x,cy,40,'#5ef0e0',.8);ctx.globalAlpha=1;ctx.fillStyle='#e0fffb';ctx.beginPath();ctx.moveTo(x,cy-14);ctx.lineTo(x+8,cy);ctx.lineTo(x,cy+14);ctx.lineTo(x-8,cy);ctx.fill();
    const bg=ctx.createLinearGradient(x,y-100,x,y-500);bg.addColorStop(0,'rgba(94,240,224,.22)');bg.addColorStop(1,'rgba(94,240,224,0)');ctx.fillStyle=bg;ctx.fillRect(x-10,y-500,20,400);norm();}
  else{ctx.fillStyle='rgba(140,150,170,.7)';ctx.font='700 14px Cinzel, serif';ctx.textAlign='center';ctx.fillText('🔒',x,y-104);}
  label(x,y+30,on?'Waystone':'Waystone · Locked',on?'#8dffe8':'#8fa4cc');
}
function drawNexus(){
  const x=NEXUS.x,y=NEXUS.y,t=time;
  add();runeCircle(x,y,200,t*.2,'#5ef0e0',.7);runeCircle(x,y,150,-t*.35,'#ffbe5c',.6);runeCircle(x,y,95,t*.6,'#8dffc8',.8);glow(x,y,240,'#2f9cff',.25);norm();
  for(let i=0;i<6;i++){const a=i/6*TAU+t*.1,px=x+Math.cos(a)*210,py=y+Math.sin(a)*95;ell(px+6,py+4,12,5,'#000000',.4);ctx.fillStyle='#34466e';ctx.fillRect(px-7,py-60,14,60);add();glow(px,py-68+Math.sin(t*2+i)*4,18,'#8dffc8',.8);norm();}
  const cy=y-80+Math.sin(t*1.5)*8;add();glow(x,cy,90,'#5ef0e0',.6);glow(x,cy,40,'#ffffff',.5);
  ctx.fillStyle='rgba(220,255,250,.9)';ctx.beginPath();ctx.moveTo(x,cy-40);ctx.lineTo(x+18,cy);ctx.lineTo(x,cy+40);ctx.lineTo(x-18,cy);ctx.closePath();ctx.fill();
  const bg=ctx.createLinearGradient(x,y,x,y-600);bg.addColorStop(0,'rgba(94,240,224,.2)');bg.addColorStop(1,'rgba(94,240,224,0)');ctx.fillStyle=bg;ctx.fillRect(x-40,y-600,80,600);norm();
  label(x,y+120,'Grand Teleport Nexus','#8dffe8',15);
}
function drawGate(g){
  const x=g.x,y=g.y,t=time;
  add();glow(x,y,110,g.col,.3+.1*Math.sin(t*2));norm();
  ctx.save();ctx.translate(x,y);
  ctx.fillStyle='#2a3450';ctx.fillRect(-58,-80,16,86);ctx.fillRect(42,-80,16,86);
  ctx.strokeStyle='#3a4870';ctx.lineWidth=14;ctx.beginPath();ctx.arc(0,-78,50,Math.PI,TAU);ctx.stroke();
  add();const pg=ctx.createRadialGradient(0,-36,4,0,-36,48);pg.addColorStop(0,'#ffffff');pg.addColorStop(.3,rgba(g.col,.8));pg.addColorStop(1,rgba(g.col,.05));ctx.fillStyle=pg;
  ctx.beginPath();ctx.ellipse(0,-36,38,48,0,0,TAU);ctx.fill();
  ctx.strokeStyle=rgba(g.col,.7);ctx.lineWidth=2;for(let i=0;i<3;i++){ctx.beginPath();ctx.ellipse(0,-36,30-i*9,40-i*12,t*(1+i*.5),0,4.2);ctx.stroke();}
  norm();ctx.restore();
  label(x,y-140,g.label,'#ffffff',15);label(x,y-122,g.sub,g.col,12);
}
function drawMerchant_v1(n){
  const x=n.x,y=n.y,t=time;ell(x,y+8,16,6,'#000000',.4);
  const g=ctx.createLinearGradient(x,y-40,x,y+10);g.addColorStop(0,'#5a3a7a');g.addColorStop(1,'#1a1030');ctx.fillStyle=g;ctx.beginPath();ctx.moveTo(x,y-40);ctx.lineTo(x+16,y+8);ctx.lineTo(x-16,y+8);ctx.closePath();ctx.fill();
  ctx.fillStyle='#e8d4b8';ctx.beginPath();ctx.arc(x,y-36,7,0,TAU);ctx.fill();ctx.fillStyle='#3a2050';ctx.beginPath();ctx.arc(x,y-39,9,Math.PI,TAU);ctx.fill();
  add();const lx=x+20,ly=y-18+Math.sin(t*2)*2;glow(lx,ly,34,'#ffbe5c',.7);glow(lx,ly,8,'#ffffff',1);norm();
  if(n.kind==='smith'){ctx.fillStyle='#2a2a34';ctx.fillRect(x-44,y-6,30,10);ctx.fillRect(x-38,y+4,18,8);add();glow(x-30,y-8,30,'#ff8a3d',.5+.3*Math.sin(t*6));norm();}
  label(x,y+26,n.n,n.kind==='smith'?'#ff9a5c':'#ffbe5c');
}
function label(x,y,txt,col,size=12){ctx.font=`700 ${size}px Cinzel, Georgia, serif`;ctx.textAlign='center';ctx.lineWidth=3;ctx.strokeStyle='rgba(2,4,12,.85)';ctx.strokeText(txt,x,y);ctx.fillStyle=col;ctx.fillText(txt,x,y);}
function drawOrb(o){
  const col=o.kind==='hp'?'#8dffc8':o.kind==='mp'?'#5ef0e0':'#ffbe5c',y=o.y-14+Math.sin(time*3+o.ph)*4;
  ell(o.x,o.y+2,8,3,'#000000',.3);add();glow(o.x,y,o.kind==='power'?30:22,col,.8);glow(o.x,y,7,'#ffffff',1);
  for(let i=0;i<3;i++){const a=time*4+i*TAU/3;glow(o.x+Math.cos(a)*12,y+Math.sin(a)*5,4,col,.9);}norm();
}

/* ---------- Projectiles ---------- */
function drawProj(p){
  if(p.team==='e'){add();for(let i=0;i<p.trail.length;i++){const k=i/p.trail.length;glow(p.trail[i][0],p.trail[i][1],p.size*1.6*k,p.col,.4*k);}glow(p.x,p.y,p.size*2.4,p.col,.9);glow(p.x,p.y,p.size*.7,'#ffffff',.9);norm();return;}
  const pl=p.pl,a=Math.atan2(p.vy,p.vx);add();
  // light trail
  const tr=p.trail;if(tr.length>1){ctx.lineCap='round';for(let i=1;i<tr.length;i++){const k=i/tr.length;ctx.strokeStyle=rgba(pl.main,.55*k);ctx.lineWidth=(p.kind==='arrow'?3:p.size*1.1)*k;ctx.beginPath();ctx.moveTo(tr[i-1][0],tr[i-1][1]);ctx.lineTo(tr[i][0],tr[i][1]);ctx.stroke();}
    ctx.strokeStyle=rgba(pl.core,.5);ctx.lineWidth=1;ctx.beginPath();tr.forEach((q,i)=>i?ctx.lineTo(q[0],q[1]):ctx.moveTo(q[0],q[1]));ctx.stroke();}
  switch(p.kind){
    case 'arrow':ctx.save();ctx.translate(p.x,p.y);ctx.rotate(a);ctx.strokeStyle=pl.core;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-18,0);ctx.lineTo(6,0);ctx.stroke();ctx.fillStyle=pl.accent;ctx.beginPath();ctx.moveTo(10,0);ctx.lineTo(2,-4);ctx.lineTo(2,4);ctx.fill();ctx.restore();glow(p.x,p.y,16,pl.main,.9);break;
    case 'crescent':ctx.save();ctx.translate(p.x,p.y);ctx.rotate(a);ctx.fillStyle=rgba(pl.main,.8);ctx.beginPath();ctx.arc(0,0,p.size,-1.3,1.3);ctx.arc(-p.size*.45,0,p.size*.8,1.2,-1.2,true);ctx.fill();ctx.restore();glow(p.x,p.y,p.size*1.6,pl.glow,.7);break;
    case 'shield':case 'hammer':ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.rot);ctx.fillStyle=rgba(pl.accent,.8);
      if(p.kind==='shield'){ctx.beginPath();ctx.arc(0,0,p.size*.8,0,TAU);ctx.fill();ctx.strokeStyle=pl.core;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-p.size*.6,0);ctx.lineTo(p.size*.6,0);ctx.moveTo(0,-p.size*.6);ctx.lineTo(0,p.size*.6);ctx.stroke();}
      else{ctx.fillRect(-p.size*.7,-p.size*.4,p.size*1.4,p.size*.8);ctx.fillStyle=pl.core;ctx.fillRect(-2,0,4,p.size*1.2);}ctx.restore();glow(p.x,p.y,p.size*2,pl.main,.8);break;
    case 'chain':glow(p.x,p.y,14,pl.main,.9);ctx.strokeStyle=rgba(pl.accent,.8);ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(P.x,P.y-10);ctx.lineTo(p.x,p.y);ctx.stroke();break;
    case 'bone':ctx.save();ctx.translate(p.x,p.y);ctx.rotate(a);ctx.fillStyle='#e8e0ff';ctx.beginPath();ctx.moveTo(18,0);ctx.lineTo(-10,-4);ctx.lineTo(-10,4);ctx.fill();ctx.restore();glow(p.x,p.y,22,pl.main,.8);break;
    case 'hawk':{ctx.save();ctx.translate(p.x,p.y);ctx.rotate(a);const f=Math.sin(time*20)*6;ctx.fillStyle=rgba(pl.accent,.8);ctx.beginPath();ctx.moveTo(10,0);ctx.lineTo(-6,-12-f);ctx.lineTo(-2,0);ctx.lineTo(-6,12+f);ctx.fill();ctx.restore();glow(p.x,p.y,22,pl.main,.8);break;}
    default:{const s=p.size;glow(p.x,p.y,s*3.2,pl.glow,.7);glow(p.x,p.y,s*1.8,pl.main,.95);glow(p.x,p.y,s*.8,pl.core,1);
      if(pl.part==='smoke'){norm();glow(p.x,p.y,s*1.2,pl.dark,.7);add();}
      if(pl.part==='shard'){ctx.save();ctx.translate(p.x,p.y);ctx.rotate(a);ctx.fillStyle=rgba(pl.core,.9);ctx.beginPath();ctx.moveTo(s*1.8,0);ctx.lineTo(-s,-s*.5);ctx.lineTo(-s*.6,0);ctx.lineTo(-s,s*.5);ctx.fill();ctx.restore();}
      if(pl.part==='feather'){ctx.strokeStyle=rgba(pl.core,.7);ctx.lineWidth=1.5;ctx.beginPath();ctx.ellipse(p.x,p.y,s*1.6,s*.6,time*4,0,TAU);ctx.stroke();}}
  }
  norm();
}

/* ---------- Ground zones ---------- */
function drawGround(z){
  const pl=z.pl,t=time,fade=Math.min(1,z.t/.25,(z.dur-z.t)/.4),x=z.x,y=z.y,r=z.r;
  if(z.trap){add();runeCircle(x,y,r*.45,t,pl.main,z.armed>0?.3:.55+.3*Math.sin(t*6));glow(x,y,r*.4,pl.main,.25);norm();return;}
  add();
  const g=ctx.createRadialGradient(x,y,0,x,y,r);g.addColorStop(0,rgba(pl.main,.05*fade));g.addColorStop(.75,rgba(pl.glow,.14*fade));g.addColorStop(1,rgba(pl.main,.35*fade));
  ctx.fillStyle=g;ctx.beginPath();ctx.ellipse(x,y,r,r*.62,0,0,TAU);ctx.fill();
  runeCircle(x,y,r,t*.6,pl.main,.6*fade,.62);const zk=(z.o&&z.o.fxk)||1;if(zk>=1.5)runeCircle(x,y,r*.68,-t*.9,pl.accent,.5*fade,.62);if(zk>=2)glow(x,y,r*1.1,pl.glow,.25*fade);
  if(z.pull){ctx.strokeStyle=rgba(pl.accent,.6*fade);ctx.lineWidth=2;for(let k=0;k<5;k++){ctx.beginPath();for(let i=0;i<40;i++){const a=i*.18+k*TAU/5-t*3,rr=r*(1-i/40);ctx.lineTo(x+Math.cos(a)*rr,y+Math.sin(a)*rr*.62);}ctx.stroke();}norm();glow(x,y,r*.35,'#000000',.9*fade);add();}
  if(z.cross){ctx.globalAlpha=.6*fade;ctx.strokeStyle=pl.core;ctx.lineWidth=6;for(let i=0;i<3;i++){const cx=x+Math.cos(i*2.1+t)*r*.5,cy=y+Math.sin(i*2.1+t)*r*.3;ctx.beginPath();ctx.moveTo(cx,cy-24);ctx.lineTo(cx,cy+24);ctx.moveTo(cx-16,cy-8);ctx.lineTo(cx+16,cy-8);ctx.stroke();glow(cx,cy,30,pl.main,.6*fade);}}
  norm();
  if(z.briar){ctx.lineCap='round';for(let i=0;i<14;i++){const a=i/14*TAU+Math.sin(t+i)*.1,rr=r*(.3+(i%3)*.22);const bx=x+Math.cos(a)*rr,by=y+Math.sin(a)*rr*.62;
    ctx.strokeStyle=rgba('#1f4a2a',.9*fade);ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(bx,by);ctx.quadraticCurveTo(bx+10,by-22,bx+Math.sin(t*2+i)*6,by-38);ctx.stroke();
    add();glow(bx+Math.sin(t*2+i)*6,by-38,8,pl.accent,.8*fade);norm();}}
  // themed particles
  const rate=z.r/60*((z.o&&z.o.fxk)||1);for(let i=0;i<rate;i++)if(Math.random()<.35){const a=rand(0,TAU),rr=Math.sqrt(Math.random())*r;const px=x+Math.cos(a)*rr,py=y+Math.sin(a)*rr*.62;
    if(z.arrows){fx.push({k:'rainArrow',x:px,y:py,t:0,dur:.18,pl});}
    else if(pl.part==='shard'&&Math.random()<.3)part({x:px,y:py-80,vx:rand(-40,40),vy:120,life:.6,max:.6,size:rand(3,6),col:'#ffffff',type:'flake',drag:1});
    else emitThemed(px,py,pl,1,40,{ang:-Math.PI/2,spread:.5});}
}

/* ---------- FX ---------- */
function drawFx(f){
  const k=clamp(f.t/f.dur,0,1),pl=f.pl;
  switch(f.k){
    case 'ring':{add();const r=lerp(f.r0,f.r1,ease(k)),a=1-k;ctx.globalAlpha=a*.9;ctx.strokeStyle=f.col;ctx.lineWidth=f.w*(1-k*.6);ctx.beginPath();ctx.ellipse(f.x,f.y,r,r*.62,0,0,TAU);ctx.stroke();
      ctx.globalAlpha=a*.4;ctx.lineWidth=f.w*2.4;ctx.stroke();norm();break;}
    case 'cres':drawCrescent(f);break;
    case 'thrust':{add();const a=1-k,x=lerp(f.x0,f.x1,Math.min(1,k*3)),y=lerp(f.y0,f.y1,Math.min(1,k*3));ctx.lineCap='round';
      for(let i=0;i<3;i++){ctx.strokeStyle=rgba(i?pl.main:pl.core,a*(i?.45:.9));ctx.lineWidth=[2,6,12][i]*a;ctx.beginPath();ctx.moveTo(f.x0,f.y0);ctx.lineTo(x,y);ctx.stroke();}
      glow(x,y,20*a,pl.main,a);norm();break;}
    case 'star':{add();const a=1-k,s=f.s*(1+k);ctx.save();ctx.translate(f.x,f.y);ctx.rotate(k*1.5);ctx.fillStyle=rgba(pl.core,a);ctx.beginPath();
      for(let i=0;i<8;i++){const rr=i%2?s*.18:s;ctx.lineTo(Math.cos(i/8*TAU)*rr,Math.sin(i/8*TAU)*rr);}ctx.fill();ctx.restore();glow(f.x,f.y,s*1.4,pl.main,a);norm();break;}
    case 'wave':{add();const a=1-k,d=f.len*ease(Math.min(1,k*1.6)),c=Math.cos(f.ang),s=Math.sin(f.ang);
      ctx.save();ctx.translate(f.x,f.y);ctx.rotate(f.ang);
      const g=ctx.createLinearGradient(0,0,d,0);g.addColorStop(0,rgba(pl.main,0));g.addColorStop(.8,rgba(pl.main,.5*a));g.addColorStop(1,rgba(pl.core,.9*a));
      ctx.fillStyle=g;ctx.beginPath();ctx.moveTo(0,-4);ctx.lineTo(d,-f.w*.5*a);ctx.quadraticCurveTo(d+20,0,d,f.w*.5*a);ctx.lineTo(0,4);ctx.fill();
      ctx.strokeStyle=rgba(pl.accent,.6*a);ctx.lineWidth=1.5;for(let i=-1;i<=1;i+=2){ctx.beginPath();ctx.moveTo(d*.3,i*f.w*.3);ctx.lineTo(d,i*f.w*.2);ctx.stroke();}
      ctx.restore();glow(f.x+c*d,f.y+s*d,f.w*a,pl.main,a);ctx.globalAlpha=a*.6;ctx.strokeStyle=pl.main;ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(f.x+c*d,f.y+s*d,f.w*.3*(1+k),f.w*.6*(1+k),f.ang,0,TAU);ctx.stroke();norm();break;}
    case 'beam':{add();const a=k<.15?k/.15:1-(k-.15)/.85;ctx.save();ctx.translate(f.x,f.y);ctx.rotate(f.ang);
      const g=ctx.createLinearGradient(0,-f.w/2,0,f.w/2);g.addColorStop(0,rgba(pl.glow,0));g.addColorStop(.3,rgba(pl.main,.6*a));g.addColorStop(.5,rgba(pl.core,.95*a));g.addColorStop(.7,rgba(pl.main,.6*a));g.addColorStop(1,rgba(pl.glow,0));
      ctx.fillStyle=g;ctx.fillRect(0,-f.w/2*(1+k*.3),f.len,f.w*(1+k*.3));
      for(let i=0;i<5;i++){ctx.globalAlpha=a*.5;ctx.strokeStyle=pl.accent;ctx.lineWidth=1.5;const yy=Math.sin(time*20+i*2)*f.w*.35;ctx.beginPath();ctx.moveTo(0,yy);ctx.lineTo(f.len,-yy);ctx.stroke();}
      ctx.restore();glow(f.x,f.y,f.w,pl.core,a);glow(f.x+Math.cos(f.ang)*f.len,f.y+Math.sin(f.ang)*f.len,f.w*1.2,pl.main,a);norm();break;}
    case 'rift':{const a=1-k;ctx.save();ctx.translate(f.x,f.y);ctx.rotate(f.ang);ctx.globalAlpha=a;ctx.fillStyle='#000000';ctx.beginPath();ctx.moveTo(0,0);
      for(let i=0;i<=10;i++)ctx.lineTo(f.len*i/10,(i%2?-1:1)*8*a);for(let i=10;i>=0;i--)ctx.lineTo(f.len*i/10,(i%2?1:-1)*3);ctx.fill();add();ctx.strokeStyle=rgba('#ff4fd8',a);ctx.lineWidth=1.5;ctx.stroke();ctx.restore();norm();break;}
    case 'pillar':{add();const a=k<.2?k/.2:1-(k-.2)/.8,w=f.w*(1-k*.4);
      const g=ctx.createLinearGradient(f.x-w/2,0,f.x+w/2,0);g.addColorStop(0,rgba(f.col,0));g.addColorStop(.5,rgba(f.col,.8*a));g.addColorStop(1,rgba(f.col,0));
      ctx.fillStyle=g;ctx.fillRect(f.x-w/2,f.y-f.h,w,f.h);const g2=ctx.createLinearGradient(f.x-w/5,0,f.x+w/5,0);g2.addColorStop(0,'rgba(255,255,255,0)');g2.addColorStop(.5,`rgba(255,255,255,${.8*a})`);g2.addColorStop(1,'rgba(255,255,255,0)');ctx.fillStyle=g2;ctx.fillRect(f.x-w/5,f.y-f.h,w*.4,f.h);
      glow(f.x,f.y,w*1.4,f.col,a);if(Math.random()<.6)part({x:f.x+rand(-w/2,w/2),y:f.y-rand(0,f.h*.6),vx:0,vy:rand(-200,-80),life:.6,max:.6,size:rand(3,6),col:f.col,type:'star'});norm();break;}
    case 'meteor':{if(f.t<0)return;const p=clamp(f.t/f.fall,0,1),a=f.arrows;
      add();ctx.globalAlpha=.25+.4*p;ctx.strokeStyle=pl.main;ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(f.x,f.y,f.r*(a?.5:1)*(.4+.6*p),f.r*(a?.3:.62)*(.4+.6*p),0,0,TAU);ctx.stroke();
      const ox=f.x-160*(1-p)*(a?.2:1),oy=f.y-520*(1-p);
      if(a){ctx.strokeStyle=pl.core;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(ox,oy-30);ctx.lineTo(ox,oy);ctx.stroke();glow(ox,oy,12,pl.main,.9);}
      else if(f.pillar){ctx.globalAlpha=1;glow(f.x,f.y,f.r*p,pl.main,.5*p);ctx.fillStyle=rgba(pl.core,.4*p);ctx.fillRect(f.x-6*p,f.y-500,12*p,500);}
      else{ctx.lineCap='round';for(let i=0;i<6;i++){ctx.strokeStyle=rgba(i?pl.main:pl.core,.5-i*.06);ctx.lineWidth=(f.big?30:14)*(1-i*.14);ctx.beginPath();ctx.moveTo(ox,oy);ctx.lineTo(ox-60*(1+i*.3)*(1-p*.3)*.3,oy-120*(1+i*.3));ctx.stroke();}
        glow(ox,oy,f.big?70:34,pl.main,1);glow(ox,oy,f.big?26:12,'#ffffff',1);if(Math.random()<.8)emitThemed(ox,oy,pl,1,60);}
      norm();break;}
    case 'bolt':{add();const a=1-k;const pts=f.pts;for(let L=0;L<2;L++){ctx.strokeStyle=L?rgba('#ffffff',a):rgba(pl.main,a*.8);ctx.lineWidth=L?1.5:5;ctx.beginPath();ctx.moveTo(pts[0][0],pts[0][1]);
      for(let i=1;i<pts.length;i++){const [x0,y0]=pts[i-1],[x1,y1]=pts[i];for(let s=1;s<=6;s++){const tt=s/6;ctx.lineTo(lerp(x0,x1,tt)+(s<6?rand(-14,14):0),lerp(y0,y1,tt)+(s<6?rand(-14,14):0));}}ctx.stroke();}
      for(const p of pts)glow(p[0],p[1],30*a,pl.main,a);norm();break;}
    case 'rune':{add();const x=f.follow?P.x:f.x,y=f.follow?P.y:f.y,a=k<.2?k/.2:1-(k-.2)/.8;runeCircle(x,y,f.r*(.8+.2*k),time*1.5,pl.main,a*.9,.55);glow(x,y,f.r*.8,pl.glow,a*.3);norm();break;}
    case 'crossbeam':{add();const a=1-k;ctx.globalAlpha=a;ctx.fillStyle=rgba(pl.core,.7);ctx.fillRect(f.x-f.r,f.y-8,f.r*2,16);ctx.fillRect(f.x-8,f.y-f.r*.62,16,f.r*1.24);glow(f.x,f.y,f.r*.6,pl.main,a);norm();break;}
    case 'crack':{const a=k<.1?1:1-(k-.1)/.9;srand(Math.floor(f.seed));ctx.lineCap='round';
      for(let i=0;i<7;i++){let x=f.x,y=f.y;const ang=i/7*TAU+srr(-.3,.3);ctx.beginPath();ctx.moveTo(x,y);for(let s=0;s<4;s++){x+=Math.cos(ang+srr(-.5,.5))*f.r/4;y+=Math.sin(ang+srr(-.5,.5))*f.r/4*.62;ctx.lineTo(x,y);}
        ctx.strokeStyle=`rgba(5,4,10,${.7*a})`;ctx.lineWidth=4;ctx.stroke();add();ctx.strokeStyle=rgba(pl.main,.8*a);ctx.lineWidth=1.5;ctx.stroke();norm();}break;}
    case 'vines':{const a=1-k;ctx.lineCap='round';for(let i=0;i<10;i++){const an=i/10*TAU,bx=f.x+Math.cos(an)*f.r*.5,by=f.y+Math.sin(an)*f.r*.3;ctx.strokeStyle=rgba('#2f7a3a',a);ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(bx,by);ctx.quadraticCurveTo(bx+10,by-30,bx,by-50);ctx.stroke();add();glow(bx,by-50,8,pl.accent,a);norm();}break;}
    case 'ghost':{add();const a=1-k;glow(f.x,f.y-14,40,pl.main,a*.6);ctx.globalAlpha=a*.5;ctx.fillStyle=pl.main;ctx.beginPath();ctx.ellipse(f.x,f.y-8,11,14,0,0,TAU);ctx.fill();ctx.beginPath();ctx.arc(f.x,f.y-24,8,0,TAU);ctx.fill();norm();break;}
    case 'charge':{add();glow(P.x,P.y-10,30+k*30,pl.main,k*.6);norm();break;}
    case 'rainArrow':{add();const a=1-k;ctx.strokeStyle=rgba(pl.core,a);ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(f.x,f.y-60*(1-k)-30);ctx.lineTo(f.x,f.y-60*(1-k));ctx.stroke();glow(f.x,f.y,10*k,pl.main,a);norm();break;}
  }
}
function drawCrescent(f){
  const p=clamp(f.t/f.dur,0,1),head=f.a0+(f.a1-f.a0)*ease(p);
  const tp=clamp((f.t-f.dur*.3)/(f.dur*.7+f.fade),0,1),tail=f.a0+(f.a1-f.a0)*ease(tp);
  const la=f.t>f.dur?Math.max(0,1-(f.t-f.dur)/f.fade):1,span=head-tail;if(Math.abs(span)<.01||la<=0)return;
  const cx=f.follow?P.x:f.x,cy=(f.follow?P.y:f.y)-6,pl=f.pl,N=22,ccw=span<0;
  ctx.save();if(f.sq){ctx.translate(cx,cy);ctx.rotate(f.rot||0);ctx.scale(1,f.sq);ctx.rotate(-(f.rot||0));ctx.translate(-cx,-cy);}
  add();ctx.lineCap='round';
  for(let i=0;i<N;i++){const k=i/N,a1=tail+span*k,a2=tail+span*(k+1/N)+(ccw?-.02:.02),al=Math.pow(k,1.5)*la;
    ctx.strokeStyle=rgba(pl.glow,al*.35);ctx.lineWidth=f.w*(.3+.9*k)*1.9;ctx.beginPath();ctx.arc(cx,cy,f.r-f.w*.3,a1,a2,ccw);ctx.stroke();
    ctx.strokeStyle=rgba(pl.main,al*.8);ctx.lineWidth=f.w*(.2+.8*k);ctx.beginPath();ctx.arc(cx,cy,f.r-f.w*.15,a1,a2,ccw);ctx.stroke();
    ctx.strokeStyle=rgba(pl.core,al);ctx.lineWidth=Math.max(1,f.w*.18*k);ctx.beginPath();ctx.arc(cx,cy,f.r,a1,a2,ccw);ctx.stroke();}
  glow(cx+Math.cos(head)*f.r,cy+Math.sin(head)*f.r,f.w*1.6,pl.main,la);
  if(f.scythe){ctx.globalAlpha=la*.6;ctx.strokeStyle=pl.accent;ctx.lineWidth=3;ctx.beginPath();ctx.arc(cx,cy,f.r*1.15,tail,head,ccw);ctx.stroke();}
  if(f.heavy){glow(cx+Math.cos(head)*f.r*.7,cy+Math.sin(head)*f.r*.7,f.w*2,pl.glow,la*.6);}
  ctx.restore();norm();
}
function drawParts(){
  for(const p of parts){const a=clamp(p.life/p.max,0,1);
    switch(p.type){
      case 'smoke':ctx.globalCompositeOperation='source-over';glow(p.x,p.y,p.size,p.col,a*.55);break;
      case 'debris':ctx.globalCompositeOperation='source-over';ctx.globalAlpha=a;ctx.fillStyle=p.col;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.rot);ctx.fillRect(-p.size/2,-p.size/2,p.size,p.size*.7);ctx.restore();break;
      case 'flake':ctx.globalCompositeOperation='source-over';ctx.globalAlpha=a;ctx.fillStyle=p.col;ctx.beginPath();ctx.arc(p.x,p.y,p.size*.5,0,TAU);ctx.fill();break;
      case 'spark':add();ctx.globalAlpha=a;ctx.strokeStyle=p.col;ctx.lineWidth=p.size;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x-p.vx*.04,p.y-p.vy*.04);ctx.stroke();glow(p.x,p.y,p.size*3,p.col,a*.5);break;
      case 'feather':add();ctx.globalAlpha=a*.9;ctx.fillStyle=p.col;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.rot);ctx.beginPath();ctx.ellipse(0,0,p.size,p.size*.32,0,0,TAU);ctx.fill();ctx.strokeStyle='rgba(255,255,255,.6)';ctx.lineWidth=.8;ctx.beginPath();ctx.moveTo(-p.size,0);ctx.lineTo(p.size,0);ctx.stroke();ctx.restore();glow(p.x,p.y,p.size*1.6,p.col,a*.4);break;
      case 'shard':add();ctx.globalAlpha=a;ctx.fillStyle=p.col;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.rot);ctx.beginPath();ctx.moveTo(0,-p.size);ctx.lineTo(p.size*.4,0);ctx.lineTo(0,p.size);ctx.lineTo(-p.size*.4,0);ctx.fill();ctx.restore();break;
      case 'star':add();ctx.globalAlpha=a;ctx.fillStyle=p.col;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.rot);ctx.beginPath();for(let i=0;i<8;i++){const r=i%2?p.size*.2:p.size;ctx.lineTo(Math.cos(i/8*TAU)*r,Math.sin(i/8*TAU)*r);}ctx.fill();ctx.restore();glow(p.x,p.y,p.size*1.5,p.col,a*.5);break;
      case 'bubble':add();ctx.globalAlpha=a*.8;ctx.strokeStyle=p.col;ctx.lineWidth=1.2;ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,TAU);ctx.stroke();break;
      case 'mist':add();glow(p.x,p.y,p.size,p.col,a*.25);break;
      case 'flame':add();glow(p.x,p.y,p.size*1.8*(0.5+a*.5),p.col,a*.8);glow(p.x,p.y,p.size*.5,'#ffffff',a*.5);break;
      default:add();glow(p.x,p.y,p.size*2*(0.6+a*.4),p.col,a*.85);
    }
  }
  norm();
}
function drawTexts(){
  ctx.textAlign='center';
  for(const t of texts){const age=t.max-t.life,a=Math.min(1,t.life/.35),pop=1+.7*Math.max(0,1-age/.12);const size=t.size*pop;
    bb(t.x,t.y,()=>{ctx.globalAlpha=a;ctx.font=`900 ${size}px Cinzel, Georgia, serif`;ctx.lineWidth=Math.max(3,size*.16);ctx.strokeStyle='rgba(3,5,16,.9)';ctx.strokeText(t.txt,t.x,t.y);
    ctx.shadowColor=t.col;ctx.shadowBlur=size>20?16:8;ctx.fillStyle=t.col;ctx.fillText(t.txt,t.x,t.y);ctx.shadowBlur=0;});}
  ctx.globalAlpha=1;
}
