function pshadow(g,x,y,rx,ry,a=.5){softBlob(g,x,y,rx,ry/rx,0,'#000000',a);}
function rockPoly(g,cx,cy,rx,ry,c1,c2,n=8){g.beginPath();for(let i=0;i<n;i++){const a=i/n*TAU,r=srr(.78,1.05);g.lineTo(cx+Math.cos(a)*rx*r,cy+Math.sin(a)*ry*r);}g.closePath();const gr=g.createLinearGradient(cx-rx,cy-ry,cx+rx*.6,cy+ry);gr.addColorStop(0,c1);gr.addColorStop(1,c2);g.fillStyle=gr;g.fill();}
function canopy(g,cx,cy,R,n,cols,hi){
  for(let i=0;i<n;i++){const a=sr()*TAU,d=sr()*R*.62,r=R*srr(.32,.55),x=cx+Math.cos(a)*d,y=cy+Math.sin(a)*d*.8;
    const gr=g.createRadialGradient(x-r*.35,y-r*.4,r*.08,x,y,r);gr.addColorStop(0,cols[2]);gr.addColorStop(.55,cols[1]);gr.addColorStop(1,cols[0]);g.fillStyle=gr;g.globalAlpha=.95;g.beginPath();g.arc(x,y,r,0,TAU);g.fill();}
  g.globalAlpha=1;for(let i=0;i<n*1.4;i++){const a=sr()*TAU,d=sr()*R*.7;g.fillStyle=rgba(hi,srr(.12,.32));g.beginPath();g.ellipse(cx+Math.cos(a)*d-R*.12,cy+Math.sin(a)*d*.8-R*.15,R*.09,R*.04,srr(0,3),0,TAU);g.fill();}
}
function trunk(g,x,yb,yt,wb,wt,c1,c2){const gr=g.createLinearGradient(x-wb,0,x+wb,0);gr.addColorStop(0,c1);gr.addColorStop(.6,c2);gr.addColorStop(1,'#0a0604');g.fillStyle=gr;
  g.beginPath();g.moveTo(x-wb,yb);g.quadraticCurveTo(x-wt*1.1,(yb+yt)/2,x-wt,yt);g.lineTo(x+wt,yt);g.quadraticCurveTo(x+wt*1.1,(yb+yt)/2,x+wb,yb);g.closePath();g.fill();
  g.strokeStyle='rgba(0,0,0,.35)';g.lineWidth=1.5;for(let i=0;i<5;i++){const xx=x+srr(-wt,wt);g.beginPath();g.moveTo(xx,yb-2);g.lineTo(xx+srr(-4,4),yt+6);g.stroke();}}
const COR=['#ff6b8b','#ffb04c','#b98cff','#5ef0e0','#ff8a3d'];
