  const put=(t,x,y,s)=>{out.push({t,x:Math.round(x),y:Math.round(y),s:+s.toFixed(2),v:Math.floor(sr()*3),f:sr()<.5?-1:1,ph:sr()*TAU});};
  const scatter=(t,n,s0,s1,o={})=>{let placed=0,tries=0;while(placed<n&&tries<n*8){tries++;let x,y;
      if(o.a){const a=sr()*TAU,r=Math.sqrt(sr())*o.a.r;x=o.a.x+Math.cos(a)*r;y=o.a.y+Math.sin(a)*r*(o.flat||1);}else{x=srr(0,Z.w);y=srr(0,Z.h);}
      if(!ok(x,y,o.pad||60))continue;if(o.avoid&&o.avoid(x,y))continue;put(t,x,y,srr(s0,s1));placed++;}};
  const inSafe=(x,y,m=0)=>(Z.areas||[]).some(a=>a.safe&&d2(a.x,a.y,x,y)<a.r+m);
