/* ---------- anime style generator (same pixel format as the sheet) ---------- */
const HG_W=30,HG_H=38,HG_OX=7,HG_OY=3,HG_S=4;
function hgGen(n,fn){
  const v={};
  for(const vk of ['f','s','b']){
    const cx=vk==='s'?6.5:7.5,cy=12.5;
    const mk=()=>{const c=document.createElement('canvas');c.width=HG_W*HG_S;c.height=HG_H*HG_S;const g=c.getContext('2d',{willReadFrequently:true});g.scale(HG_S,HG_S);g.translate(HG_OX,HG_OY);g.fillStyle=g.strokeStyle='#fff';g.lineCap='round';g.lineJoin='round';return g;};
    const m=mk(),s=mk();
    const api={cx,cy,v:vk,
      E:(g,x,y,rx,ry,r=0)=>{g.beginPath();g.ellipse(x,y,rx,ry,r,0,TAU);g.fill();},
      poly:(g,pts)=>{g.beginPath();pts.forEach((p,i)=>i?g.lineTo(p[0],p[1]):g.moveTo(p[0],p[1]));g.closePath();g.fill();},
      spike:(g,bx,by,deg,len,w)=>{const a=deg*Math.PI/180,px=-Math.sin(a)*w/2,py=Math.cos(a)*w/2;g.beginPath();g.moveTo(bx+px,by+py);g.lineTo(bx+Math.cos(a)*len,by+Math.sin(a)*len);g.lineTo(bx-px,by-py);g.closePath();g.fill();},
      line:(g,pts,w=.55)=>{g.lineWidth=w;g.beginPath();pts.forEach((p,i)=>i?g.lineTo(p[0],p[1]):g.moveTo(p[0],p[1]));g.stroke();},
      cutFace:(g,bang)=>{g.save();g.globalCompositeOperation='destination-out';g.beginPath();
        const x0=vk==='f'?cx-5.3:cx+.3,x1=vk==='f'?cx+5.3:cx+7.5;if(vk==='b'){g.restore();return;}
        g.moveTo(x0,40);for(let x=x0;x<=x1+.01;x+=.25)g.lineTo(x,bang(x));g.lineTo(x1,40);g.closePath();g.clip();
        g.beginPath();if(vk==='f')g.ellipse(cx,cy+1.6,4.85,7.4,0,0,TAU);else g.ellipse(cx+2.3,cy+1.4,4.9,7.4,0,0,TAU);g.fill();g.restore();}};
    fn(api,m,s);
    const md=m.getImageData(0,0,HG_W*HG_S,HG_H*HG_S).data,sd=s.getImageData(0,0,HG_W*HG_S,HG_H*HG_S).data;
    const cov=(d,i,j)=>{let t=0;for(let yy=0;yy<HG_S;yy++)for(let xx=0;xx<HG_S;xx++)t+=d[((j*HG_S+yy)*HG_W*HG_S+i*HG_S+xx)*4+3];return t/(HG_S*HG_S*255);};
    const M=new Uint8Array(HG_W*HG_H),ST=new Uint8Array(HG_W*HG_H);
    for(let j=0;j<HG_H;j++)for(let i=0;i<HG_W;i++){M[j*HG_W+i]=cov(md,i,j)>.45?1:0;ST[j*HG_W+i]=cov(sd,i,j)>.3?1:0;}
    const at=(i,j)=>i>=0&&j>=0&&i<HG_W&&j<HG_H&&M[j*HG_W+i];
    let x0=1e9,y0=1e9,x1=-1,y1=-1;for(let j=0;j<HG_H;j++)for(let i=0;i<HG_W;i++)if(M[j*HG_W+i]){x0=Math.min(x0,i);x1=Math.max(x1,i);y0=Math.min(y0,j);y1=Math.max(y1,j);}
    let d='';
    for(let j=y0;j<=y1;j++)for(let i=x0;i<=x1;i++){
      if(!M[j*HG_W+i]){d+='.';continue;}
      if(!at(i-1,j)||!at(i+1,j)||!at(i,j-1)||!at(i,j+1)){d+='0';continue;}
      const x=i-HG_OX+.5,y=j-HG_OY+.5;let t=3;
      if(y>cy+3)t=2;
      const rr=Math.hypot((x-cx+1.2)/6.2,(y-cy+4.4)/5);if(rr>.42&&rr<.78&&y<cy-1.5)t=4;
      if(!at(i,j+2)||!at(i+2,j))t=Math.min(t,2);
      if(y<cy-7.5&&t<4)t=3;
      if(ST[j*HG_W+i])t=t>=3?2:1;
      d+=t;}
    v[vk]={x:x0-HG_OX,y:y0-HG_OY,w:x1-x0+1,h:y1-y0+1,d};
  }
  return {n,v};
}
