const HAIRS=HAIR_ANIME.concat(HAIR_SHEET);
const HAIR_ANCH={f:[7.5,12.5],s:[6.5,12.5],b:[7.5,12.5]};
const HAIR_TONE={'0':[58,56,64],'1':[112,110,118],'2':[160,158,166],'3':[206,204,212],'4':[246,246,250]};
const HAIR_ACC={s:[214,142,122],r:[118,22,34],R:[204,50,62]};
const HAIR_GRAY={},HAIR_TINT={};
function hairBase(i,vk){const k=i+vk;if(HAIR_GRAY[k])return HAIR_GRAY[k];const H=HAIRS[i],sp=H&&H.v[vk];if(!sp)return null;
  const mkc=()=>{const c=document.createElement('canvas');c.width=sp.w;c.height=sp.h;return c;};const g=mkc(),a=mkc(),gd=g.getContext('2d').createImageData(sp.w,sp.h),ad=a.getContext('2d').createImageData(sp.w,sp.h);
  for(let p=0;p<sp.d.length;p++){const ch=sp.d[p];if(ch==='.')continue;const o=p*4;if(HAIR_TONE[ch]){const c=HAIR_TONE[ch];gd.data[o]=c[0];gd.data[o+1]=c[1];gd.data[o+2]=c[2];gd.data[o+3]=255;}else{const c=HAIR_ACC[ch];ad.data[o]=c[0];ad.data[o+1]=c[1];ad.data[o+2]=c[2];ad.data[o+3]=255;}}
  g.getContext('2d').putImageData(gd,0,0);a.getContext('2d').putImageData(ad,0,0);return HAIR_GRAY[k]={g,a,sp};}
function isPrism(c){return c==='prism';}
function hairTinted(i,vk,col,t){const b=hairBase(i,vk);if(!b)return null;const ph=isPrism(col)?Math.floor((t||0)*8)%24:0,k=i+vk+col+ph;if(HAIR_TINT[k])return HAIR_TINT[k];
  const keys=Object.keys(HAIR_TINT);if(keys.length>400)for(const kk of keys.slice(0,200))delete HAIR_TINT[kk];
  const c=document.createElement('canvas');c.width=b.sp.w;c.height=b.sp.h;const g=c.getContext('2d');g.drawImage(b.g,0,0);g.globalCompositeOperation='multiply';
  if(isPrism(col)){const gr=g.createLinearGradient(0,0,c.width,c.height);for(let s=0;s<=6;s++)gr.addColorStop(s/6,`hsl(${(s*60+ph*15)%360},95%,68%)`);g.fillStyle=gr;}
  else{const h=hex2rgb(col).map(v=>clamp(Math.round(v*255/246),0,255));g.fillStyle=rgbHex(h);}
  g.fillRect(0,0,c.width,c.height);g.globalCompositeOperation='destination-in';g.drawImage(b.g,0,0);g.globalCompositeOperation='source-over';g.drawImage(b.a,0,0);
  return HAIR_TINT[k]={c,sp:b.sp};}
function hairView(a){const d=angDiff(Math.PI/2,a);if(Math.abs(d)<.92)return {v:'f',flip:false,sh:Math.round(Math.cos(a)*1.2)};if(Math.abs(d)>2.25)return {v:'b',flip:false,sh:0};return {v:'s',flip:Math.cos(a)<0,sh:0};}
function hairRGB(col){return isPrism(col)?[190,120,255]:hex2rgb(col||'#6b3f22');}

/* ---------- Hair Fit: per-style, per-view offsets + under-hair fill (user adjustable, saved in this browser) ---------- */
const HFIT_KEY=KEYP+'hairfit_v1';
let HAIR_FIT={};try{HAIR_FIT=JSON.parse(localStorage.getItem(HFIT_KEY)||'{}')||{};}catch(e){HAIR_FIT={};}
function hairFit(i){return HAIR_FIT[i]||{};}
function saveHairFit(){try{localStorage.setItem(HFIT_KEY,JSON.stringify(HAIR_FIT));}catch(e){}}
function setHairFit(i,key,val){const f=HAIR_FIT[i]=HAIR_FIT[i]||{};
  if(key==='fill'){if(val===true)delete f.fill;else f.fill=false;}else f[key]=val;
  for(const k of ['dx','dy','dz','fy'])if(f[k]===0)delete f[k];if(f.sc===1)delete f.sc;for(const v of ['f','s','b'])delete f[v];
  if(!Object.keys(f).length)delete HAIR_FIT[i];saveHairFit();}
function hairFillRGB(col,t){const h=isPrism(col)?[150,90,220]:hex2rgb(col||'#6b3f22');return h.map(v=>clamp(Math.round(v*.62),0,255));}

/* ---------- v12: 3D hair — every style is rebuilt as a voxel shell from its front / side / back views,
   so it turns smoothly with the head at any angle, bobs with the walk cycle and sways when running ---------- */
const HAIR_VOX={};
// drop tiny pixel islands (JPEG noise from the source sheet) so they don't become floating voxels
function cleanSprite(sp,minN=5){if(!sp||sp._clean)return;const w=sp.w,h=sp.h,d=sp.d.split(''),seen=new Uint8Array(w*h);
  for(let i=0;i<w*h;i++){if(seen[i]||d[i]==='.'||d[i]==='s')continue;const q=[i],comp=[];seen[i]=1;
    while(q.length){const k=q.pop();comp.push(k);const x=k%w,y=(k/w)|0;for(const [nx,ny] of [[x-1,y],[x+1,y],[x,y-1],[x,y+1]]){if(nx<0||ny<0||nx>=w||ny>=h)continue;const j=ny*w+nx;if(!seen[j]&&d[j]!=='.'&&d[j]!=='s'){seen[j]=1;q.push(j);}}}
    if(comp.length<minN)for(const k of comp)d[k]='.';}
  sp.d=d.join('');sp._clean=1;}
for(const H of HAIRS)for(const k of ['f','s','b'])cleanSprite(H.v[k]);
function spAt(sp,cx,cy){if(!sp)return '.';const i=cx-sp.x,j=cy-sp.y;if(i<0||j<0||i>=sp.w||j>=sp.h)return '.';const c=sp.d[j*sp.w+i];return c==='s'?'.':c;}
