function gearVis(slot,EQ){const it=EQ&&EQ[slot];if(!it||it.kind==='fash'||(it.img&&/^head/.test(slot)))return null;const n=it.name||'';
  switch(slot){
    case 'armor':return /Robe/i.test(n)?{k:'robe',c:'#3a5aa8',c2:'#d9b25a'}:/plate/i.test(n)?{k:'plate',c:'#d6b35c',c2:'#f0d68a'}:{k:'mail',c:'#8d9ab0',c2:'#5f6c84'};
    case 'headTop':return /Hood/i.test(n)?{k:'hood',c:'#4a3a7a'}:/Helm/i.test(n)?{k:'helm',c:'#9aa6ba',c2:'#c2413a'}:{k:'circlet',c:'#e3c060',c2:(RARITY[it.rar]&&/^#[0-9a-f]{6}$/i.test(RARITY[it.rar].c))?RARITY[it.rar].c:'#7fdcff'};
    case 'headMid':return /Monocle/i.test(n)?{k:'monocle'}:/Visor/i.test(n)?{k:'visor'}:{k:'goggles'};
    case 'headLow':return /Veil/i.test(n)?{k:'veil'}:/Mask/i.test(n)?{k:'mask'}:{k:'pipe'};
    case 'garment':return /Muffler/i.test(n)?{k:'muffler',c:'#c2413a'}:/Manteau/i.test(n)?{k:'cloak',c:'#5b3c9e'}:{k:'cloak',c:'#2f7f86'};
    case 'shoes':return /Sandal/i.test(n)?{c:'#c89a5a'}:/Greave/i.test(n)?{c:'#8a96aa'}:{c:'#6a4426'};
    case 'shield':return /Mirror/i.test(n)?{r:3.3,c:'#c8d6ea',c2:'#7fdcff'}:/Aegis/i.test(n)?{r:3.6,c:'#e0bc5c',c2:'#fff2b8'}:{r:2.8,c:'#8a6a40',c2:'#c9a46a'};
  }return null;}

