  if(GS&&GS.legs&&!jmp){[legL,legR,knL,knR,lean]=GS.legs;}          // spear lunge / spin footwork
  else if(GS&&WT==='spear'&&!run&&!walk&&!jmp&&!attack){legL=.3;legR=-.28;knL=.3;knR=.2;lean=.05;}
