    const E=[S[0]+Math.cos(u+bend)*l1,S[1]+Math.sin(u+bend)*l1],H=[S[0]+Math.cos(u)*d,S[1]+Math.sin(u)*d];L2.AR.E=E;L2.AR.Hd=H;armRdepth=Math.sin(wa2)*1.5+dp(AR.S);
