  const ckd=new Map();
  const kc=(c,kd)=>{let r=hex2rgb(c),h=rgbHex(r),i=0;while(ckd.has(h)&&ckd.get(h)!==kd&&i<40){r=[r[0],r[1],clamp(r[2]+(i%2?-(i+1):(i+1)),0,255)];h=rgbHex(r);i++;}ckd.set(h,kd);return h;};
