  const tsX=dress?TP.st:'tee',arX=dress?gearVis('armor',EQ):null;let hem=null;const hemOf=v=>{hem=hem==null?v:Math.min(hem,v);};
  if(dress){if(bs==='skirt')hemOf(hipY-3.6);else if(bs==='lskirt')hemOf(hipY-8.2);if(tsX==='tunic')hemOf(hipY-2.6);else if(tsX==='robe')hemOf(hipY-8.4);if(arX&&arX.k==='robe')hemOf(hipY-8.6);}
