    const zb0=new Float32Array(N).fill(-1e9),zb1=new Float32Array(N).fill(-1e9),cb0=new Uint8ClampedArray(N*4),cb1=new Uint8ClampedArray(N*4);
    const prism=LK.hairCol==='prism',hcol=prism?null:hex2rgb(LK.hairCol||'#6b3f22').map(v=>v/246);
    const toneRGB=(tn,yv)=>{if(tn>=5)return HAIR_ACC[tn===5?'r':'R'];const b=HAIR_TONE[tn],c=prism?hslRGB(((yv*14+t*70)%360+360)%360,.85,.62).map(v=>v/246):hcol;return [b[0]*c[0],b[1]*c[1],b[2]*c[2]];};
    const mv=run?1:walk?.55:0,trail=swy*1.05;
    // occlusion: a voxel sits in front of the body only if the ray towards the viewer misses the head and torso solids
    const KV=.34,prH=q=>[HOX+q[0]*R[0]+q[2]*F[0],HOY-q[1]+(q[0]*R[1]+q[2]*F[1])*KV],vX=Math.cos(a),vY=K*KV,vZ=Math.sin(a),tY=(shY+hipY)/2-headY,tRY=(shY-hipY)/2+1.2;
    const hits=(x,y,z,cx,cy,cz,rx,ry,rz)=>{const px=(x-cx)/rx,py=(y-cy)/ry,pz=(z-cz)/rz,qx=vX/rx,qy=vY/ry,qz=vZ/rz,A=qx*qx+qy*qy+qz*qz,B=2*(px*qx+py*qy+pz*qz),C=px*px+py*py+pz*pz-1;
      if(C<0)return true;const D=B*B-4*A*C;if(D<0)return false;return (-B+Math.sqrt(D))/(2*A)>0&&(-B-Math.sqrt(D))/(2*A)>-.2;};
