    const out=(wt==='bow'||wt==='gun')?0:.18,v=[out,-Math.cos(ang),Math.sin(ang)];
    const sx=v[0]*R[0]+v[2]*F[0],sy=-v[1]+v[0]*R[1]+v[2]*F[1];wa3=Math.atan2(sy,sx);
