/* =====================================================================
   v10 — Wardrobe & Paperdoll UI · Dye Alchemy · 2.5D Camera · Mobile
   ===================================================================== */

/* ---------- 2.5D camera: zoom (0.6–1.8×) · pitch (30°–90°) · yaw rotation (360°) ---------- */
const CAM_KEY=KEYP+'cam_v1';try{CAM.persp=localStorage.getItem(KEYP+'cam_persp_v2')==='1';}catch(e){}   // v2f: Depth perspective OFF unless the player turned it on
(function(){try{const s=JSON.parse(localStorage.getItem(CAM_KEY)||'null');if(s){CAM.zt=CAM.z=clamp(+s.z||1,.6,1.8);CAM.tt=CAM.tilt=clamp(+s.tilt||.866,.5,1);CAM.yt=CAM.yaw=isFinite(+s.yaw)?+s.yaw:0;/* v2f: persp has its own key (below) */CAM.touch=['auto','on','off'].includes(s.touch)?s.touch:'auto';}}catch(e){}})();
let camSaveT=0;
function camSave(){clearTimeout(camSaveT);camSaveT=setTimeout(()=>{try{localStorage.setItem(CAM_KEY,JSON.stringify({z:CAM.zt,tilt:CAM.tt,yaw:CAM.yt,persp:CAM.persp,touch:CAM.touch}));}catch(e){}},250);}
function camZ(){return ED.on?1:CAM.z;}
function camT(){return ED.on?1:CAM.tilt;}
function camY(){return ED.on?0:CAM.yaw;}
function heroK(){return .3+.2*camT();}                           // hero rig foreshortening follows the pitch
// VW/VH = world-space bounding box of the (possibly rotated) view; cam.x/cam.y = its top-left
function camSync(){const w=W/camZ(),h=H/(camZ()*camT()),c=Math.abs(Math.cos(camY())),s=Math.abs(Math.sin(camY()));VW=w*c+h*s;VH=w*s+h*c;}
function camStep(dt){const k=Math.min(1,dt*9);CAM.z+=(CAM.zt-CAM.z)*k;CAM.tilt+=(CAM.tt-CAM.tilt)*k;CAM.yaw+=angDiff(CAM.yaw,CAM.yt)*k;camSync();G.dashCd=Math.max(0,(G.dashCd||0)-dt);}
function camApply(g){g.translate(W/2,H/2);g.scale(camZ(),camZ()*camT());g.rotate(camY());g.translate(-(cam.x+VW/2),-(cam.y+VH/2));}
function s2w(sx,sy){const u=(sx-W/2)/camZ(),v=(sy-H/2)/(camZ()*camT()),th=camY(),c=Math.cos(th),s=Math.sin(th);return [cam.x+VW/2+u*c+v*s,cam.y+VH/2-u*s+v*c];}
function mwx(sx,sy){return s2w(sx,sy)[0];}
function mwy(sx,sy){return s2w(sx,sy)[1];}
function w2s(x,y){const dx=x-cam.x-VW/2,dy=y-cam.y-VH/2,th=camY(),c=Math.cos(th),s=Math.sin(th);return [W/2+(c*dx-s*dy)*camZ(),H/2+(s*dx+c*dy)*camZ()*camT()];}
function scr2wDir(u,v){const th=camY(),c=Math.cos(th),s=Math.sin(th);return [u*c+v*s,-u*s+v*c];}   // screen direction → world direction
function wl(dx,dy){const th=camY(),c=Math.cos(th),s=Math.sin(th);return [c*dx-s*dy,(s*dx+c*dy)*camT()];}   // world offset → billboard-local offset
function depthKey(e){const th=camY();return Math.sin(th)*e.x+Math.cos(th)*e.y;}
// billboard: the ground is rotated + foreshortened, upright things (characters, props, NPCs, text) stay upright,
// keep full height and get a slight depth scale (far rows smaller) for the 2.5D perspective feel
function bb(x,y,fn){const T=camT(),th=camY();if(T>.995&&Math.abs(th)<1e-3){fn();return;}const s=CAM.persp?1+(w2s(x,y)[1]/H-.55)*(1-T)*.5:1;
  ctx.save();ctx.translate(x,y);if(th)ctx.rotate(-th);ctx.scale(s,s/T);ctx.translate(-x,-y);fn();ctx.restore();}
const pitchDeg=()=>Math.round(Math.asin(clamp(CAM.tt,.5,1))*180/Math.PI);
const yawDeg=()=>{let d=Math.round(CAM.yt*180/Math.PI)%360;if(d>180)d-=360;if(d<=-180)d+=360;return d;};
function setPitch(deg){CAM.tt=clamp(Math.sin(clamp(deg,30,90)*Math.PI/180),.5,1);camSave();camUI();}
function setZoom(z){CAM.zt=clamp(z,.6,1.8);camSave();camUI();}
function setYaw(deg){let r=deg*Math.PI/180;CAM.yt=CAM.yaw+angDiff(CAM.yaw,r);camSave();camUI();}
function rotYaw(ddeg){CAM.yt+=ddeg*Math.PI/180;camSave();camUI();}
function camUI(){const z=$('#camZoom'),p=$('#camPitch');if(!z)return;z.value=Math.round(CAM.zt*100);p.value=pitchDeg();$('#camYaw').value=yawDeg();$('#camZoomV').textContent=Math.round(CAM.zt*100)+'%';$('#camPitchV').textContent=pitchDeg()+'°';$('#camYawV').textContent=yawDeg()+'°';$('#camPersp').checked=CAM.persp;$('#camTouch').value=CAM.touch;}
function initCamUI(){
  $('#bCam').addEventListener('click',()=>{const p=$('#camPanel');p.hidden=!p.hidden;camUI();});
  $('#camZoom').addEventListener('input',e=>setZoom(+e.target.value/100));
  $('#camPitch').addEventListener('input',e=>setPitch(+e.target.value));
  $('#camYaw').addEventListener('input',e=>setYaw(+e.target.value));
  $('#camRotL').addEventListener('click',()=>rotYaw(-45));$('#camRotR').addEventListener('click',()=>rotYaw(45));
  $('#camPersp').addEventListener('change',e=>{CAM.persp=e.target.checked;try{localStorage.setItem(KEYP+'cam_persp_v2',CAM.persp?'1':'0');}catch(_){}camSave();});
  $('#camTouch').addEventListener('change',e=>{CAM.touch=e.target.value;camSave();applyMobile();});
  $('#camReset').addEventListener('click',()=>{setZoom(1);setPitch(60);setYaw(0);CAM.persp=false;try{localStorage.setItem(KEYP+'cam_persp_v2','0');}catch(_){}camSave();camUI();});
  $('#camTop').addEventListener('click',()=>setPitch(90));
  cv.addEventListener('wheel',e=>{if(ED.on||G.state!=='play')return;e.preventDefault();setZoom(CAM.zt*Math.pow(1.0016,-e.deltaY));},{passive:false});
  addEventListener('keydown',e=>{if(e.target&&/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;if(G.state!=='play'||ED.on)return;
    const k=e.key;if(k==='<'||k===','){setPitch(pitchDeg()-5);}else if(k==='>'||k==='.'){setPitch(pitchDeg()+5);}
    else if(k==='['){rotYaw(-15);}else if(k===']'){rotYaw(15);}else if(k==='Home'){setYaw(0);}
    else if(k==='v'||k==='V'||k==='Shift'){if(!e.repeat)doDash();}});
  // right-click drag on the world: horizontal = rotate camera, vertical = tilt
  cv.addEventListener('pointerdown',e=>{if(e.button!==2||ED.on||G.state!=='play')return;G.rdrag={x:e.clientX,y:e.clientY,p:pitchDeg(),yw:CAM.yt};(()=>{try{cv.setPointerCapture(e.pointerId);}catch(_){}})();});
  addEventListener('pointermove',e=>{const R=G.rdrag;if(!R)return;setPitch(R.p+(R.y-e.clientY)*.3);CAM.yt=R.yw+(e.clientX-R.x)*.008;camSave();camUI();});
  addEventListener('pointerup',()=>{G.rdrag=null;});
  // two fingers on the world: pinch = zoom, twist = rotate camera
  const pts=new Map();let pinch=null;
  const geo=()=>{const [a,b]=[...pts.values()];return {d:Math.hypot(a[0]-b[0],a[1]-b[1]),an:Math.atan2(b[1]-a[1],b[0]-a[0])};};
  cv.addEventListener('pointerdown',e=>{if(e.pointerType!=='touch')return;pts.set(e.pointerId,[e.clientX,e.clientY]);if(pts.size===2){const q=geo();pinch={d:q.d,an:q.an,z:CAM.zt,yw:CAM.yt};G.touch=null;mouse.down=false;}});
  cv.addEventListener('pointermove',e=>{if(!pts.has(e.pointerId))return;pts.set(e.pointerId,[e.clientX,e.clientY]);if(pinch&&pts.size===2){const q=geo();setZoom(pinch.z*q.d/Math.max(20,pinch.d));CAM.yt=pinch.yw+angDiff(pinch.an,q.an);camSave();camUI();G.touch=null;}});
  const up=e=>{pts.delete(e.pointerId);if(pts.size<2)pinch=null;};addEventListener('pointerup',up);addEventListener('pointercancel',up);
  camUI();
}

