/* ---------- Capital NPCs: Madame Celeste (Stylist) & Alchemy Station ---------- */
const NPC_WIN={smith:'wRefine',stylist:'wWard',alchemist:'wAlch',merchant:'wShop'};
function npcPrompt(n){return n.kind==='smith'?'คุยกับ Master Smith (ตีบวก / ใส่การ์ด)':n.kind==='stylist'?'คุยกับ Madame Celeste · ห้องแต่งตัว & ย้อมสี':n.kind==='alchemist'?'ใช้ Alchemy Station · ปรุงน้ำยาย้อมสี':'คุยกับ Spirit Merchant';}
function loadZone(zid,arrive){
  loadZone_v1(zid,arrive);{const Z=ZONES[zid];P.x=clamp(P.x,40,Z.w-40);P.y=clamp(P.y,40,Z.h-40);}beaconArrive(zid);audZone(zid);raidEnter(zid);
  if(zid==='capital'){const [nx,ny]=ZONES.capital.nexus;
    if(!PROPS.some(p=>p.t==='fountain')){PROPS.push({t:'fountain',x:nx+360,y:ny+330,s:1,v:0,f:1,ph:0});buildSolids();}
    const f=PROPS.find(p=>p.t==='fountain');
    NPCS.push({x:f.x+158,y:f.y+26,n:'Madame Celeste (Stylist)',kind:'stylist'},{x:nx+400,y:ny-330,n:'Alchemy Station',kind:'alchemist'});}
}
function drawMerchant(n){if(n.kind==='stylist')drawStylist(n);else if(n.kind==='alchemist')drawAlchemist(n);else drawMerchant_v1(n);}
function drawStylist(n){const x=n.x,y=n.y,t=time;ell(x,y+8,20,7,'#000000',.4);
  // standing mirror
  ctx.fillStyle='#6a4a2a';ctx.fillRect(x+30,y-50,4,58);ctx.fillRect(x+22,y+4,20,4);
  const mg=ctx.createLinearGradient(x+20,y-70,x+46,y-30);mg.addColorStop(0,'#e8f8ff');mg.addColorStop(.5,'#8fb8d8');mg.addColorStop(1,'#dff4ff');ctx.fillStyle='#c9a46a';ctx.beginPath();ctx.ellipse(x+32,y-52,14,20,0,0,TAU);ctx.fill();
  ctx.fillStyle=mg;ctx.beginPath();ctx.ellipse(x+32,y-52,11,17,0,0,TAU);ctx.fill();add();glow(x+28,y-58,14,'#ffffff',.35+.2*Math.sin(t*2));norm();
  // gown
  const g=ctx.createLinearGradient(x,y-40,x,y+10);g.addColorStop(0,'#c25ad8');g.addColorStop(1,'#4a1a5a');ctx.fillStyle=g;
  ctx.beginPath();ctx.moveTo(x-6,y-36);ctx.quadraticCurveTo(x-24,y-4,x-22,y+8);ctx.lineTo(x+22,y+8);ctx.quadraticCurveTo(x+22,y-4,x+6,y-36);ctx.closePath();ctx.fill();
  ctx.strokeStyle='#ffd36b';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(x-20,y+4);ctx.quadraticCurveTo(x,y+10,x+20,y+4);ctx.stroke();
  ctx.fillStyle='#ff8ae0';ctx.beginPath();ctx.ellipse(x,y-30,8,5,0,0,TAU);ctx.fill();
  // head, hair, wide-brim hat with feather
  ctx.fillStyle='#f1c8a0';ctx.beginPath();ctx.arc(x,y-42,7,0,TAU);ctx.fill();
  ctx.fillStyle='#e8c24a';ctx.beginPath();ctx.ellipse(x-6,y-38,4,9,.3,0,TAU);ctx.ellipse(x+6,y-38,4,9,-.3,0,TAU);ctx.fill();
  ctx.fillStyle='#2a1030';ctx.beginPath();ctx.ellipse(x,y-48,19,5,0,0,TAU);ctx.fill();ctx.beginPath();ctx.ellipse(x,y-53,9,7,0,Math.PI,TAU);ctx.fill();
  ctx.strokeStyle='#ff8ae0';ctx.lineWidth=3;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(x+6,y-55);ctx.quadraticCurveTo(x+18,y-70+Math.sin(t*3)*2,x+24,y-60);ctx.stroke();
  ctx.fillStyle='#1a0e1a';ctx.fillRect(x-3,y-43,2,2);ctx.fillRect(x+2,y-43,2,2);
  // floating scissors / sparkles
  add();for(let i=0;i<4;i++){const a=t*1.5+i*TAU/4;glow(x+Math.cos(a)*26,y-30+Math.sin(a)*8,5,i%2?'#ff8ae0':'#ffd36b',.8);}norm();
  label(x,y+28,n.n,'#ff8ae0');}
function drawAlchemist(n){const x=n.x,y=n.y,t=time;ell(x,y+8,34,9,'#000000',.4);
  // shelf of vials
  ctx.fillStyle='#4a3020';ctx.fillRect(x-58,y-58,34,4);ctx.fillRect(x-58,y-36,34,4);ctx.fillRect(x-58,y-58,3,60);ctx.fillRect(x-27,y-58,3,60);
  const vc=['#7dff8a','#bff6ff','#ff7a2a','#9be8ff','#ff8ae0','#ffd36b'];for(let i=0;i<6;i++){const vx=x-53+(i%3)*9,vy=i<3?y-66:y-44;ctx.fillStyle=vc[i];ctx.fillRect(vx,vy,6,8);add();glow(vx+3,vy+4,7,vc[i],.4+.2*Math.sin(t*3+i));norm();}
  // alchemist
  const g=ctx.createLinearGradient(x,y-40,x,y+10);g.addColorStop(0,'#3e7a4a');g.addColorStop(1,'#12301c');ctx.fillStyle=g;ctx.beginPath();ctx.moveTo(x,y-44);ctx.lineTo(x+15,y+8);ctx.lineTo(x-15,y+8);ctx.closePath();ctx.fill();
  ctx.fillStyle='#e8d4b8';ctx.beginPath();ctx.arc(x,y-38,6.5,0,TAU);ctx.fill();ctx.fillStyle='#1e3a24';ctx.beginPath();ctx.moveTo(x-10,y-38);ctx.lineTo(x,y-60);ctx.lineTo(x+10,y-38);ctx.closePath();ctx.fill();
  ctx.fillStyle='#d8d8e0';ctx.beginPath();ctx.moveTo(x-5,y-34);ctx.lineTo(x,y-22);ctx.lineTo(x+5,y-34);ctx.fill();
  // cauldron
  const cx=x+34,cy=y-2;ctx.fillStyle='#1a1a24';ctx.beginPath();ctx.ellipse(cx,cy,20,15,0,0,Math.PI);ctx.fill();ctx.fillRect(cx-20,cy-4,40,5);ctx.fillStyle='#2a2a38';ctx.beginPath();ctx.ellipse(cx,cy-4,21,6,0,0,TAU);ctx.fill();
  const hue=(t*60)%360,lc=`hsl(${hue},90%,60%)`;ctx.fillStyle=lc;ctx.beginPath();ctx.ellipse(cx,cy-4,17,4.5,0,0,TAU);ctx.fill();
  add();glow(cx,cy-8,34,'#8dff6a',.35+.15*Math.sin(t*4));glow(cx,cy+14,22,'#ff7a2a',.5+.2*Math.sin(t*9));
  for(let i=0;i<4;i++){const k=(t*.7+i/4)%1;glow(cx+Math.sin(i*2.3+t)*8,cy-8-k*40,4+k*4,i%2?'#8dff6a':'#ff8ae0',(1-k)*.7);}norm();
  label(x,y+28,n.n,'#8dff6a');}

/* ---------- Materials, dyes & recipes ---------- */
function iconVial(g,c,cork='#8a6a40'){g.globalCompositeOperation='lighter';g.drawImage(glowSprite(c),4,4,56,56);g.globalCompositeOperation='source-over';
  g.fillStyle='rgba(220,240,255,.35)';g.beginPath();g.arc(32,40,15,0,TAU);g.fill();g.fillRect(27,14,10,14);g.fillStyle=c;g.beginPath();g.arc(32,42,12,0,TAU);g.fill();g.fillStyle=cork;g.fillRect(26,9,12,7);
  g.fillStyle='rgba(255,255,255,.7)';g.beginPath();g.arc(27,36,3,0,TAU);g.fill();}
Object.assign(ITEMS,{
  plantExtract:{n:'Rare Plant Extract',d:'สารสกัดพืชหายาก · ดรอปจากมอนสเตอร์ใน Jungle · วัตถุดิบ Prismatic Hair Dye',k:'mat',col:'#7dff8a',sell:120,icon:g=>iconVial(g,'#5ed86a','#3e7a4a')},
  lumPearl:{n:'Luminous Pearl',d:'ไข่มุกเรืองแสง · ดรอปจากมอนสเตอร์ใน DeepSea · วัตถุดิบ Prismatic Hair Dye',k:'mat',col:'#dff8ff',sell:180,
    icon:g=>{g.globalCompositeOperation='lighter';g.drawImage(glowSprite('#9be8ff'),2,2,60,60);g.globalCompositeOperation='source-over';const gr=g.createRadialGradient(26,26,2,32,32,16);gr.addColorStop(0,'#ffffff');gr.addColorStop(.6,'#d8f0ff');gr.addColorStop(1,'#8ab8d8');g.fillStyle=gr;g.beginPath();g.arc(32,32,15,0,TAU);g.fill();}},
  scorchEss:{n:'Scorched Essence',d:'แก่นเพลิงไหม้ · ดรอปจากมอนสเตอร์ใน Lava · วัตถุดิบ Royal Cloth Dye',k:'mat',col:'#ff7a2a',sell:150,
    icon:g=>{g.globalCompositeOperation='lighter';g.drawImage(glowSprite('#ff7a2a'),2,2,60,60);g.globalCompositeOperation='source-over';g.fillStyle='#ff5a1a';g.beginPath();g.moveTo(32,8);g.quadraticCurveTo(50,30,44,44);g.quadraticCurveTo(32,58,20,44);g.quadraticCurveTo(14,30,32,8);g.fill();g.fillStyle='#ffd36b';g.beginPath();g.moveTo(32,24);g.quadraticCurveTo(40,38,36,46);g.quadraticCurveTo(32,52,28,46);g.quadraticCurveTo(24,38,32,24);g.fill();}},
  frostBloom:{n:'Frost Bloom',d:'ดอกไม้น้ำแข็ง · ดรอปจากมอนสเตอร์ใน Snow · วัตถุดิบ Royal Cloth Dye',k:'mat',col:'#9be8ff',sell:180,
    icon:g=>{g.globalCompositeOperation='lighter';g.drawImage(glowSprite('#9be8ff'),2,2,60,60);g.globalCompositeOperation='source-over';for(let i=0;i<6;i++){const a=i/6*TAU;g.fillStyle=i%2?'#e8fbff':'#9be8ff';g.beginPath();g.ellipse(32+Math.cos(a)*11,32+Math.sin(a)*11,9,5,a,0,TAU);g.fill();}g.fillStyle='#ffffff';g.beginPath();g.arc(32,32,5,0,TAU);g.fill();}},
  hairDye:{n:'Prismatic Hair Dye',d:'น้ำยาย้อมผมปริซึม · ใช้ที่ Madame Celeste เพื่อเปลี่ยนสีผม (ครั้งละ 1 ขวด)',k:'dye',col:'#ff8ae0',sell:5000,
    icon:g=>{iconVial(g,'#ff8ae0','#e6c46a');const gr=g.createLinearGradient(20,30,44,54);['#ff5a5a','#ffd36b','#8dff6a','#5ef0e0','#7a4cff','#ff8ae0'].forEach((c,i)=>gr.addColorStop(i/5,c));g.fillStyle=gr;g.beginPath();g.arc(32,42,12,0,TAU);g.fill();g.fillStyle='rgba(255,255,255,.75)';g.beginPath();g.arc(27,36,3,0,TAU);g.fill();}},
  clothDye:{n:'Royal Cloth Dye',d:'น้ำยาย้อมผ้าหลวง · ใช้ที่ Madame Celeste เพื่อย้อมสีชุด (ครั้งละ 1 ขวด)',k:'dye',col:'#ffd36b',sell:10000,
    icon:g=>{iconVial(g,'#b8363a','#e6c46a');g.strokeStyle='#ffd36b';g.lineWidth=2;g.beginPath();g.arc(32,42,13,0,TAU);g.stroke();g.fillStyle='#ffd36b';g.beginPath();g.moveTo(32,34);g.lineTo(35,41);g.lineTo(32,48);g.lineTo(29,41);g.closePath();g.fill();}}
});
const MAT_DROP={jungle:['plantExtract',.04],deepsea:['lumPearl',.03],lava:['scorchEss',.04],snow:['frostBloom',.03]};
function killEnemy_v14(e){const was=e.dead;killEnemy_v3(e);if(was||!e.dead)return;const md=MAT_DROP[ZB()];if(!md)return;const m=e.m||{};
  if(rng()<Math.min(1,md[1]*(G.dropMul||1)*(m.boss?10:m.elite?3:1)))dropLoot(e.x,e.y,{item:{id:md[0],q:1}});}
const RECIPES=[
  {out:'hairDye',need:[['plantExtract',10],['lumPearl',5],['smithGem',3]],gold:50000},
  {out:'clothDye',need:[['scorchEss',10],['frostBloom',5],['smithGemUp',1]],gold:100000}];
const MAT_SRC={plantExtract:'Jungle',lumPearl:'DeepSea',scorchEss:'Lava',frostBloom:'Snow',smithGem:'ดรอปทุกโซน 0.1% / Master Smith',smithGemUp:'ดรอปหายาก / Master Smith'};
function canCraft(r){return P.gold>=r.gold&&r.need.every(([id,n])=>countItem(id)>=n);}
function renderAlch(){
  let h=`<p class="aihint">ปรุงน้ำยาย้อมระดับตำนาน — วัตถุดิบดรอปจากมอนสเตอร์ในโซนต่าง ๆ (ใช้ Economy Multiplier ของ GM ได้) · ทองที่มี <b style="color:var(--gold)">${fmt(P.gold)} G</b></p><div class="alch">`;
  RECIPES.forEach((r,i)=>{const ok=canCraft(r),d=ITEMS[r.out];
    h+=`<div class="rcp${ok?' ok':''}"><div class="rhead"><img src="${itemIcon({id:r.out})}" alt=""><div><b>${d.n}</b><small>${d.d}</small><small>มีอยู่: ${countItem(r.out)} ขวด</small></div></div><ul>`;
    for(const [id,n] of r.need){const have=countItem(id);h+=`<li class="${have>=n?'g':'r'}"><img src="${itemIcon({id})}" alt=""><span>${ITEMS[id].n}<small>${MAT_SRC[id]||''}</small></span><b>${fmt(have)} / ${n}</b></li>`;}
    h+=`<li class="${P.gold>=r.gold?'g':'r'}"><span class="coin">G</span><span>Gold</span><b>${fmt(P.gold)} / ${fmt(r.gold)}</b></li></ul><button class="btn gold" data-craft="${i}" ${ok?'':'disabled'}>ปรุง ${d.n}</button></div>`;});
  $('#alchBody').innerHTML=h+'</div>';
}
function craft(i){const r=RECIPES[i];if(!r)return;if(!canCraft(r)){notify('วัตถุดิบหรือทองไม่พอ');return;}
  if(!addItem({id:r.out,q:1})){notify('กระเป๋าเต็ม!');return;}
  for(const [id,n] of r.need)takeItem(id,n);P.gold-=r.gold;
  const al=NPCS.find(n=>n.kind==='alchemist');if(al){fx.push({k:'pillar',x:al.x+34,y:al.y,t:0,dur:1.6,col:ITEMS[r.out].col,w:60,h:380});emitThemed(al.x+34,al.y-10,{...THEMES.holy,main:ITEMS[r.out].col},50,260);}
  notify(`ปรุงสำเร็จ! ได้รับ ${ITEMS[r.out].n}`,false);log(`⚗ ปรุง ${ITEMS[r.out].n} สำเร็จ`,'g');renderAlch();saveGame();}

/* ---------- Wardrobe (Madame Celeste) ---------- */
const WARD={look:null,cat:'hair',a:Math.PI/2,spin:true,walk:false,drag:null,fitView:'f'};
const FIT_VIEWS=[['f','หน้า',Math.PI/2],['s','ข้าง',0],['b','หลัง',-Math.PI/2]];
const WTABS=[['face','Face','รูปหน้า'],['hair','Hairstyle','ทรงผม'],['eyes','Eyes','ดวงตา'],['brows','Eyebrows','คิ้ว'],['top','Top','เสื้อ'],['bottom','Bottom','ท่อนล่าง'],['dye','Dye','ย้อมสี']];
function wardThumb(c,cat,i){const lk=Object.assign({},WARD.look,{[cat]:i});if(cat!=='top'&&cat!=='bottom')lk.hideHead=true;
  const head=cat==='face'||cat==='eyes'||cat==='brows'||cat==='hair',a=cat==='hair'?Math.PI/2-.3:cat==='top'||cat==='bottom'?Math.PI/2-.35:Math.PI/2;
  heroFrame(0,0,0,0,0,0,{pv:1,a,look:lk,eq:visEquip(),wt:'fist'});const g=c.getContext('2d');g.clearRect(0,0,c.width,c.height);g.imageSmoothingEnabled=false;
  if(cat==='hair')g.drawImage(HC,10,11,28,28,0,0,c.width,c.height);else if(head)g.drawImage(HC,12,12,24,24,0,0,c.width,c.height);else g.drawImage(HC,2,8,44,44,0,0,c.width,c.height);}
function renderWard(){
  if(!WARD.look)WARD.look=Object.assign({},LOOK());
  $('#wardTabs').innerHTML=WTABS.map(([k,e,t])=>`<button class="btn${WARD.cat===k?' on':''}" data-wtab="${k}">${e}<small>${t}</small></button>`).join('');
  const grid=$('#wardGrid'),foot=$('#wardFoot');
  if(WARD.cat==='dye'){const L=WARD.look,hd=countItem('hairDye'),cd=countItem('clothDye');
    grid.className='wdye';
    grid.innerHTML=`<h3 class="sec">Hair Color · สีผม <small>ใช้ Prismatic Hair Dye (มี ${hd})</small></h3>
      <div class="sw"><button data-hc="prism" class="prism${L.hairCol==='prism'?' on':''}" title="Prismatic · สีรุ้งเคลื่อนไหว"></button>${HAIR_SWATCH.map(c=>`<button data-hc="${c}" class="${L.hairCol===c?'on':''}" style="background:${c}" title="${c}"></button>`).join('')}<label class="cpick">กำหนดเอง<input type="color" id="wHairPick" value="${L.hairCol==='prism'?'#ff8ae0':L.hairCol}"></label></div>
      <div class="row"><button class="btn gold" id="wApplyHair" ${hd?'':'disabled'}>ย้อมผม · ใช้ 1 ขวด</button><span class="aihint">${hd?'':'ไม่มีน้ำยา — ปรุงที่ Alchemy Station'}</span></div>
      <h3 class="sec">Outfit Dye · สีชุด <small>ใช้ Royal Cloth Dye (มี ${cd}) · ย้อมเสื้อ & ท่อนล่าง</small></h3>
      <div class="sw">${CLOTH_SWATCH.map(c=>`<button data-cc="${c}" class="${L.clothDye===c?'on':''}" style="background:${c}" title="${c}"></button>`).join('')}<label class="cpick">กำหนดเอง<input type="color" id="wClothPick" value="${L.clothDye||'#b8363a'}"></label></div>
      <div class="row"><button class="btn gold" id="wApplyCloth" ${cd?'':'disabled'}>ย้อมชุด · ใช้ 1 ขวด</button><button class="btn" id="wClearCloth">ล้างสีย้อม (ฟรี)</button><span class="aihint">${cd?'':'ไม่มีน้ำยา — ปรุงที่ Alchemy Station'}</span></div>
      <h3 class="sec">Display · การแสดงผล</h3>
      <label class="chk"><input type="checkbox" id="wHideHead" ${LOOK().hideHead?'checked':''}> ซ่อนหมวก (Hide Headgear)</label>`;
    foot.innerHTML=`<span class="aihint">พรีวิวแสดงสีที่เลือก · สีจะถูกบันทึกเมื่อกดย้อมเท่านั้น</span>`;return;}
  const list=CAT_LIST[WARD.cat],cur=WARD.look[WARD.cat],saved=LOOK()[WARD.cat];grid.className='wgrid';
  grid.innerHTML=list.map((p,i)=>`<button class="wtile${i===cur?' on':''}${i===saved?' cur':''}" data-pick="${i}"><canvas width="64" height="64"></canvas><span>${i+1}. ${p.n}</span></button>`).join('');
  grid.querySelectorAll('canvas').forEach((c,i)=>wardThumb(c,WARD.cat,i));
  const dirty=['face','hair','eyes','brows','top','bottom'].some(k=>WARD.look[k]!==LOOK()[k]);
  foot.innerHTML=`<button class="btn gold" id="wApply" ${dirty?'':'disabled'}>บันทึกทรง (ฟรี) · Apply Style</button><button class="btn" id="wRevert">ย้อนกลับ</button><span class="aihint">${dirty?'มีการเปลี่ยนแปลงที่ยังไม่บันทึก':'★ = ชุดที่สวมอยู่'}</span>`+(WARD.cat==='hair'?'<div id="hairFit" class="hfit"></div>':'');
  if(WARD.cat==='hair')renderHairFit();
}
function wardFx(){const s=NPCS.find(n=>n.kind==='stylist');emitThemed(P.x,P.y-20,{...THEMES.holy,main:'#ff8ae0'},40,200);ring(P.x,P.y,10,90,.6,'#ff8ae0',5);if(s)textAt(s.x,s.y-70,'Magnifique!','#ff8ae0',16);}
function initWardUI(){
  const body=$('#wWard');
  body.addEventListener('click',e=>{const L=WARD.look;if(!L)return;
    const tb=e.target.closest('[data-wtab]');if(tb){WARD.cat=tb.dataset.wtab;renderWard();return;}
    const pk=e.target.closest('[data-pick]');if(pk){L[WARD.cat]=+pk.dataset.pick;renderWard();return;}
    const hc=e.target.closest('[data-hc]');if(hc){L.hairCol=hc.dataset.hc;renderWard();return;}
    const cc=e.target.closest('[data-cc]');if(cc){L.clothDye=cc.dataset.cc;renderWard();return;}
    const id=e.target.id;
    if(id==='wApply'){for(const k of ['face','hair','eyes','brows','top','bottom'])LOOK()[k]=L[k];wardFx();notify('บันทึกทรงใหม่แล้ว!',false);saveGame();renderWard();}
    else if(id==='wRevert'){WARD.look=Object.assign({},LOOK());renderWard();}
    else if(id==='wApplyHair'){if(L.hairCol===LOOK().hairCol){notify('เลือกสีผมใหม่ก่อน');return;}if(countItem('hairDye')<1){notify('ต้องมี Prismatic Hair Dye (ปรุงที่ Alchemy Station)');return;}
      takeItem('hairDye',1);LOOK().hairCol=L.hairCol;wardFx();notify('ย้อมผมสำเร็จ!',false);log('✂ ย้อมผมด้วย Prismatic Hair Dye','g');saveGame();renderWard();}
    else if(id==='wApplyCloth'){if(!L.clothDye||L.clothDye===LOOK().clothDye){notify('เลือกสีชุดใหม่ก่อน');return;}if(countItem('clothDye')<1){notify('ต้องมี Royal Cloth Dye (ปรุงที่ Alchemy Station)');return;}
      takeItem('clothDye',1);LOOK().clothDye=L.clothDye;wardFx();notify('ย้อมชุดสำเร็จ!',false);log('✂ ย้อมชุดด้วย Royal Cloth Dye','g');saveGame();renderWard();}
    else if(id==='wClearCloth'){LOOK().clothDye=null;L.clothDye=null;saveGame();renderWard();}
    else if(id==='wSpin'){WARD.spin=!WARD.spin;e.target.classList.toggle('on',WARD.spin);}
    else if(id==='wWalk'){WARD.walk=!WARD.walk;e.target.classList.toggle('on',WARD.walk);}
    else if(id==='wRotL')WARD.a-=Math.PI/4;else if(id==='wRotR')WARD.a+=Math.PI/4;
  });
  body.addEventListener('input',e=>{const L=WARD.look;if(!L)return;if(e.target.id==='wHairPick'){L.hairCol=e.target.value;}else if(e.target.id==='wClothPick'){L.clothDye=e.target.value;}});
  body.addEventListener('change',e=>{if(e.target.id==='wHideHead'){LOOK().hideHead=WARD.look.hideHead=e.target.checked;saveGame();}
    else if(e.target.id==='wHairPick'||e.target.id==='wClothPick')renderWard();});
  const c=$('#wardCv');
  c.addEventListener('pointerdown',e=>{WARD.drag={x:e.clientX,a:WARD.a};(()=>{try{c.setPointerCapture(e.pointerId);}catch(_){}})();});
  c.addEventListener('pointermove',e=>{if(WARD.drag)WARD.a=WARD.drag.a-(e.clientX-WARD.drag.x)*.022;});
  const up=()=>{WARD.drag=null;};c.addEventListener('pointerup',up);c.addEventListener('pointercancel',up);
  $('#alchBody').addEventListener('click',e=>{const b=e.target.closest('[data-craft]');if(b)craft(+b.dataset.craft);});
}
function drawWardPreview(dt){
  if(G.win!=='wWard'||!WARD.look)return;const c=$('#wardCv'),g=c.getContext('2d'),Wc=c.width,Hc=c.height;
  if(WARD.spin&&!WARD.drag)WARD.a+=dt*1.1;
  g.clearRect(0,0,Wc,Hc);const bgc=g.createRadialGradient(Wc/2,Hc*.45,10,Wc/2,Hc*.5,Wc*.7);bgc.addColorStop(0,'rgba(194,90,216,.28)');bgc.addColorStop(1,'rgba(6,10,28,0)');g.fillStyle=bgc;g.fillRect(0,0,Wc,Hc);
  // turntable
  g.save();g.translate(Wc/2,Hc-22);g.scale(1,.3);g.strokeStyle='rgba(255,138,224,.55)';g.lineWidth=3;g.beginPath();g.arc(0,0,92,0,TAU);g.stroke();g.strokeStyle='rgba(255,211,107,.4)';g.lineWidth=2;
  for(let i=0;i<12;i++){const a=i/12*TAU-WARD.a;g.beginPath();g.moveTo(Math.cos(a)*78,Math.sin(a)*78);g.lineTo(Math.cos(a)*92,Math.sin(a)*92);g.stroke();}g.fillStyle='rgba(0,0,0,.35)';g.beginPath();g.arc(0,0,60,0,TAU);g.fill();g.restore();
  const WEQ=wardEq(),Hf=heroFrame(0,0,0,0,time,0,{pv:1,a:WARD.a,look:WARD.look,eq:WEQ,wt:P.weapon.t,walk:WARD.walk});
  const S=Math.min(5,(Hc-10)/52),ox=(Wc-48*S)/2,oy=Hc-10-52*S+6;
  const drawW=()=>{if(P.weapon.t==='fist')return;g.save();g.translate(ox,oy);g.scale(S/HS,S/HS);try{drawWeapon(g,P.weapon.t,Hf.hand[0]*HS,Hf.hand[1]*HS,Hf.wa??Math.PI/2,WSCALE[P.weapon.t]||.8,wpal(),false);}catch(e){}g.restore();};
  if(Hf.behind)drawW();g.imageSmoothingEnabled=false;cosLayer(g,Hf,[ox,oy],S,WEQ,'back');g.drawImage(HC,ox,oy,48*S,52*S);cosLayer(g,Hf,[ox,oy],S,WEQ,'front');g.imageSmoothingEnabled=true;if(!Hf.behind)drawW();
  $('#wardNote').textContent='ลากบนภาพเพื่อหมุน 360° · พรีวิวสด ยังไม่บันทึกจนกดปุ่มบันทึก';
}

/* ---------- Glow FX layer (last paperdoll layer) ---------- */
const WLEN={dagger:18,sword:30,greatsword:42,axe:30,spear:52,bow:26,staff:46,book:26,gun:40,fist:0};
function drawGlowFX_v14(x,y0,wx,wy,WA){
  const wr=P.weapon.refine||0,ar=Object.values(P.equip).reduce((s,it)=>s+(it&&it.refine||0),0),t=time;add();
  if(wr>=5&&P.weapon.t!=='fist'&&FASH.vis.weapon!==false){const k=Math.min(1,(wr-4)/6),col=wr>=10?'#ffd36b':wr>=8?'#ff8ae0':'#7fdcff',L=WLEN[P.weapon.t]||30;
    for(let i=0;i<4;i++){const d=L*(i+.6)/4;glow(wx+Math.cos(WA)*d,wy+Math.sin(WA)*d,8+k*9,col,.22+.3*k*(.7+.3*Math.sin(t*6+i)));}
    if(rng()<.25*k){const d=rand(0,L);part({x:wx+Math.cos(WA)*d,y:wy+Math.sin(WA)*d,vx:rand(-20,20),vy:rand(-50,-20),life:.6,max:.6,size:rand(1.5,3),col,type:'spark',drag:.95});}}
  if(ar>=15){const k=Math.min(1,(ar-14)/40),col=ar>=50?'#ffd36b':'#b98cff';
    for(let i=0;i<3;i++){const a=t*1.6+i*TAU/3;glow(x+Math.cos(a)*20,y0-8+Math.sin(a)*7-((t*30+i*20)%40),5,col,.55*k+.2);}
    ctx.globalAlpha=.25+.2*k;ctx.strokeStyle=col;ctx.lineWidth=1.5;ctx.beginPath();ctx.ellipse(x,y0+9,22+Math.sin(t*4)*2,7,0,0,TAU);ctx.stroke();}
  norm();}


/* ---------- Mobile: auto-detect, dynamic joystick, action buttons ---------- */
const TOUCH={on:false,joy:null};
function isMobile(){if(CAM.touch==='on')return true;if(CAM.touch==='off')return false;return (matchMedia&&matchMedia('(pointer:coarse)').matches)||innerWidth<900;}
function applyMobile(){const on=isMobile();TOUCH.on=on;document.body.classList.toggle('mobile',on);$('#touchUI').hidden=!on;if(on)buildTouchSkills();if(!on){G.joy=null;keys[' ']=false;}}
function doDash(){if(G.state!=='play'||!P||P.dead||P.dash||(G.dashCd||0)>0||P.casting)return;
  const jd=G.joy&&G.joy.m>0?scr2wDir(G.joy.x,G.joy.y/camT()):null,a=jd?Math.atan2(jd[1],jd[0]):(Math.hypot(P.vx,P.vy)>30?Math.atan2(P.vy,P.vx):P.face),sp=640,pl=pal(null);
  P.dash={vx:Math.cos(a)*sp,vy:Math.sin(a)*sp,t:.2,hit:new Set(),back:true,pl};P.invT=Math.max(P.invT,.22);G.dashCd=.85;emitThemed(P.x,P.y-10,pl,12,140);}
const TSK_POS=[[95,180],[95,148],[95,116],[95,84],[160,180],[160,157],[160,134],[160,111]];if(!/[?&]touch10=off\b/.test(location.search))TSK_POS.push([160,203],[215,196]);/* r213: phone buttons for hotkey slots R and F */
function buildTouchSkills(){const box=$('#tSkills');if(!box||!P)return;let h='';
  for(let i=0;i<TSK_POS.length;i++){const id=P.slots[i],[r,dg]=(i>=8&&innerWidth<innerHeight&&innerWidth<=640&&!/[?&]touchpt=off\b/.test(location.search))?[[225,92],[160,65]][i-8]:TSK_POS[i],a=dg*Math.PI/180;/* r217: upright phone, slots R/F go above the attack button, not onto the joystick */
    h+=`<div class="slot tsk" data-ti="${i}" ${id?`data-sk="${id}"`:''} style="left:${Math.cos(a)*r}px;top:${-Math.sin(a)*r}px">${id?`<img src="${skillIcon(id)}" alt="">`:''}<div class="cd"></div><div class="cdt"></div><kbd>${SLOT_KEYS[i].toUpperCase()}</kbd></div>`;}
  box.innerHTML=h;}
function initTouchUI(){
  const jz=$('#joyZone'),base=$('#joyBase'),knob=$('#joyKnob'),R=58;
  const rest=()=>{base.style.left='';base.style.top='';knob.style.transform='';jz.classList.remove('act');};
  jz.addEventListener('pointerdown',e=>{if(G.state!=='play')return;e.preventDefault();const r=jz.getBoundingClientRect();TOUCH.joy={id:e.pointerId,x0:e.clientX,y0:e.clientY};
    base.style.left=(e.clientX-r.left)+'px';base.style.top=(e.clientY-r.top)+'px';jz.classList.add('act');G.lastInput='touch';(()=>{try{jz.setPointerCapture(e.pointerId);}catch(_){}})();});
  jz.addEventListener('pointermove',e=>{const J=TOUCH.joy;if(!J||J.id!==e.pointerId)return;const dx=e.clientX-J.x0,dy=e.clientY-J.y0,l=Math.hypot(dx,dy)||1,m=Math.min(1,l/R);
    knob.style.transform=`translate(${dx/l*m*R}px,${dy/l*m*R}px)`;G.joy=m<.12?null:{x:dx/l,y:dy/l,m};G.lastInput='touch';});
  const end=e=>{const J=TOUCH.joy;if(!J||J.id!==e.pointerId)return;TOUCH.joy=null;G.joy=null;rest();};jz.addEventListener('pointerup',end);jz.addEventListener('pointercancel',end);
  const hold=(el,down,up)=>{el.addEventListener('pointerdown',e=>{e.preventDefault();e.stopPropagation();G.lastInput='touch';el.classList.add('press');down(e);(()=>{try{el.setPointerCapture(e.pointerId);}catch(_){}})();});
    const u=e=>{el.classList.remove('press');up&&up(e);};el.addEventListener('pointerup',u);el.addEventListener('pointercancel',u);el.addEventListener('contextmenu',e=>e.preventDefault());};
  hold($('#tAtk'),()=>{keys[' ']=true;},()=>{keys[' ']=false;});
  hold($('#tDash'),doDash);
  hold($('#tInt'),()=>{if(G.state==='play')interact()||pickupNear();});
  hold($('#tRotL'),()=>rotYaw(-45));hold($('#tRotR'),()=>rotYaw(45));
  hold($('#tHp'),()=>usePotion('hp'));hold($('#tMp'),()=>usePotion('mp'));
  $('#tSkills').addEventListener('pointerdown',e=>{const s=e.target.closest('.tsk');if(!s)return;e.preventDefault();G.lastInput='touch';const id=P.slots[+s.dataset.ti];if(id){castSkill(id);s.classList.add('flash');setTimeout(()=>s.classList.remove('flash'),350);}});
  try{$('#tHpI').src=itemIcon({id:'hpPot'});$('#tMpI').src=itemIcon({id:'mpPot'});}catch(e){}
  addEventListener('resize',applyMobile);
  applyMobile();
}
function updTouch(){if(!TOUCH.on||!P)return;const a=$('#tAtk');if(a)a.classList.toggle('dim',P.weapon.t==='fist');
  const pr=$('#tInt');if(pr)pr.classList.toggle('hot',!!G.interact||(typeof lootNear==='function'&&!!lootNear()));
  const d=$('#tDash');if(d)d.style.setProperty('--cd',(G.dashCd||0)/.85);
  const hq=$('#tHpQ'),mq=$('#tMpQ');if(hq)hq.textContent=window.POTFLAT221&&POTFLAT221.on?POTFLAT221.cnt('hp'):countItem('hpPot')+countItem('hpPot2');if(mq)mq.textContent=window.POTFLAT221&&POTFLAT221.on?POTFLAT221.cnt('mp'):countItem('mpPot');}

