function devEco(a){
  if(a==='dyemats'){addItem({id:'plantExtract',q:10});addItem({id:'lumPearl',q:5});addItem({id:'scorchEss',q:10});addItem({id:'frostBloom',q:5});addItem({id:'smithGem',q:3});addItem({id:'smithGemUp',q:1});P.gold+=150000;log('GM: วัตถุดิบย้อมสีครบ 1 ชุด + 150,000 G','v');if(G.win==='wInv')renderInv();if(G.win==='wAlch')renderAlch();return;}
  if(a==='dyes'){addItem({id:'hairDye',q:3});addItem({id:'clothDye',q:3});log('GM: +3 Prismatic Hair Dye, +3 Royal Cloth Dye','v');if(G.win==='wWard')renderWard();return;}
  if(a==='ward'){openWin('wWard');return;}
  devEco_v9(a);
}
