/* ---------- Hair Fit panel (wardrobe → Hairstyle tab) ---------- */
function renderHairFit(){const box=$('#hairFit');if(!box||!WARD.look)return;const i=WARD.look.hair,H=HAIRS[i],fit=hairFit(i),v=WARD.fitView,fill=fit.fill!==false,has=!!HAIR_FIT[i],n=Object.keys(HAIR_FIT).length;
  const step=(k,a,b,val,txt)=>`<span class="hstep"><button class="btn" data-hf="${k}:-1" title="${a}">${a}</button><output class="mono">${txt??((val>0?'+':'')+val)}</output><button class="btn" data-hf="${k}:1" title="${b}">${b}</button></span>`;
  box.innerHTML=`<div class="hfhead"><b>ปรับทรงผมให้เข้ากับหัว (3D)</b><span class="aihint">${H.n} · ผมเป็นโมเดล 3 มิติ ปรับครั้งเดียวมีผลทุกมุม · ใช้กับทุกตัวละครในเบราว์เซอร์นี้</span></div>
   <div class="hfrow"><span class="hlab">ดูมุม</span><span class="hseg">${FIT_VIEWS.map(([k,t])=>`<button class="btn${v===k&&!WARD.spin?' on':''}" data-hfv="${k}">${t}</button>`).join('')}<button class="btn${WARD.spin?' on':''}" data-hfv="spin">หมุน</button></span></div>
   <div class="hfrow"><span class="hlab">ซ้าย-ขวา</span>${step('dx','◀','▶',fit.dx||0)}<span class="hlab">ขึ้น-ลง</span>${step('dy','▼','▲',fit.dy||0)}</div>
   <div class="hfrow"><span class="hlab">หน้า-หลัง</span>${step('dz','หลัง','หน้า',fit.dz||0)}<span class="hlab">ขนาดผม</span>${step('sc','−','+',0,Math.round((fit.sc||1)*100)+'%')}</div>
   <div class="hfrow"><label class="chk"><input type="checkbox" id="hfFill" ${fill?'checked':''}> เติมผมคลุมหนังหัว (กันหนังหัวโผล่)</label><span class="hlab">ขอบผมด้านใน</span>${step('fy','▲','▼',fit.fy||0)}</div>
   <div class="hfrow"><button class="btn" id="hfReset" ${has?'':'disabled'}>คืนค่าทรงนี้</button><button class="btn" id="hfResetAll" ${n?'':'disabled'}>คืนค่าทุกทรง (${n})</button><button class="btn" id="hfCopy" ${n?'':'disabled'}>คัดลอกค่า</button><button class="btn" id="hfImport">นำเข้าค่า</button></div>
   <div class="hfrow" id="hfImp" hidden><textarea id="hfText" rows="3" placeholder='วางค่าที่คัดลอกไว้ เช่น {"9":{"dy":1,"sc":1.05}}'></textarea><button class="btn gold" id="hfDo">ใช้ค่านี้</button></div>`;}
function hairFitView(k){if(k==='spin'){WARD.spin=true;const sb=$('#wSpin');if(sb)sb.classList.add('on');renderHairFit();return;}WARD.fitView=k;const fv=FIT_VIEWS.find(x=>x[0]===k);WARD.a=fv[2];WARD.spin=false;const sb=$('#wSpin');if(sb)sb.classList.remove('on');renderHairFit();}
function refreshHairThumb(){const i=WARD.look.hair,t=document.querySelector(`#wardGrid [data-pick="${i}"] canvas`);if(t)wardThumb(t,'hair',i);}
function initHairFitUI(){
  $('#wWard').addEventListener('click',e=>{if(!WARD.look||WARD.cat!=='hair')return;const i=WARD.look.hair;
    const vb=e.target.closest('[data-hfv]');if(vb){hairFitView(vb.dataset.hfv);return;}
    const hb=e.target.closest('[data-hf]');if(hb){const [k,d]=hb.dataset.hf.split(':'),f=hairFit(i);
      if(k==='sc')setHairFit(i,'sc',Math.round(clamp((f.sc||1)+(+d)*.05,.8,1.25)*100)/100);
      else if(k==='fy')setHairFit(i,'fy',clamp((f.fy||0)+(+d),-4,6));
      else setHairFit(i,k,clamp((f[k]||0)+(+d),-6,6));
      renderHairFit();refreshHairThumb();return;}
    const id=e.target.id;
    if(id==='hfReset'){delete HAIR_FIT[i];saveHairFit();renderHairFit();refreshHairThumb();notify('คืนค่าทรงผมนี้แล้ว',false);}
    else if(id==='hfResetAll'){if(e.target.dataset.arm!=='1'){e.target.dataset.arm='1';e.target.textContent='กดอีกครั้งเพื่อยืนยัน';setTimeout(()=>{if(e.target.isConnected)renderHairFit();},3000);return;}
      HAIR_FIT={};saveHairFit();renderWard();notify('คืนค่าทุกทรงผมแล้ว',false);}
    else if(id==='hfCopy'){const txt=JSON.stringify(HAIR_FIT);const done=()=>notify('คัดลอกค่าแล้ว',false);
      try{navigator.clipboard.writeText(txt).then(done,()=>{$('#hfImp').hidden=false;$('#hfText').value=txt;$('#hfText').select();});}catch(_){$('#hfImp').hidden=false;$('#hfText').value=txt;$('#hfText').select();}}
    else if(id==='hfImport'){const b=$('#hfImp');b.hidden=!b.hidden;if(!b.hidden)$('#hfText').focus();}
    else if(id==='hfDo'){try{const j=JSON.parse($('#hfText').value);if(!j||typeof j!=='object'||Array.isArray(j))throw 0;const clean={};
        for(const k in j){const n=+k;if(!(n>=0&&n<HAIRS.length))continue;const f=j[k],o={};for(const q of ['dx','dy','dz'])if(+f[q])o[q]=clamp(Math.round(+f[q]),-6,6);if(+f.sc&&+f.sc!==1)o.sc=clamp(+f.sc,.8,1.25);if(f.fill===false)o.fill=false;if(+f.fy)o.fy=clamp(Math.round(+f.fy),-4,6);if(Object.keys(o).length)clean[n]=o;}
        HAIR_FIT=clean;saveHairFit();renderWard();notify('นำเข้าค่าทรงผมแล้ว',false);}catch(_){notify('รูปแบบค่าไม่ถูกต้อง · ต้องเป็น JSON ที่คัดลอกจากปุ่มคัดลอกค่า');}}
  });
  $('#wWard').addEventListener('change',e=>{if(e.target.id==='hfFill'&&WARD.look){setHairFit(WARD.look.hair,'fill',e.target.checked);renderHairFit();refreshHairThumb();}});
}
/* =====================================================================
   v13 — Chronicles of the Realm
   · customizable game title · fixed-size Character window with 55-slot pages
   · derived combat stats · Web Audio engine (SFX + zone BGM + custom tracks)
   · GM Creator Suite (item / costume creator, waypoint designer, audio, title)
   · Thief class line (Thief → Assassin / Rogue → Assassin Cross / Stalker → Shadow Cross / Abyss Chaser)
   ===================================================================== */

/* ---------- 0. Game title (customizable) ---------- */
const TITLE_KEY=KEYP+'title',TITLE_DEF='Chronicles of the Realm';
function gameTitle(){try{return localStorage.getItem(TITLE_KEY)||TITLE_DEF;}catch(e){return TITLE_DEF;}}
function applyTitle(){const t=gameTitle();document.title=t;document.querySelectorAll('.gtitle').forEach(e=>e.textContent=t.toUpperCase());document.querySelectorAll('.gname').forEach(e=>e.textContent=' '+t);}
function setGameTitle(t){t=String(t||'').trim().slice(0,48);try{if(!t||t===TITLE_DEF)localStorage.removeItem(TITLE_KEY);else localStorage.setItem(TITLE_KEY,t);}catch(e){}applyTitle();}

/* ---------- 1. Passive bonuses, FLEE, custom item stats, cast-time reduction ---------- */
function recalc(){
  recalc_v3();
  const pb={};
  for(const id in P.skills){const s=SK[id],lv=P.skills[id];if(!s||!lv||!s.pb)continue;
    for(const k in s.pb){const v=s.pbStep&&s.pbStep[k]!=null?s.pb[k]+s.pbStep[k]*(lv-1):s.pb[k]*lv;pb[k]=(pb[k]||0)+v;}}
  P.pb=pb;
  for(const [,it] of allEquipped()){const cx=it&&it.cx;if(!cx)continue;P.maxHp+=cx.hp||0;P.maxMp+=cx.mp||0;if(it.kind!=='wpn'){P.atk+=cx.atk||0;P.matk+=cx.matk||0;}P.crit+=cx.crit||0;P.def+=it.kind==='wpn'?(cx.def||0):0;}
  const S=P.S||P.stats;P.flee=Math.round(P.lvl*.5+S.agi*1.2+S.luk*.3);
  P.hp=Math.min(P.hp,P.maxHp);P.mp=Math.min(P.mp,P.maxMp);
}
function castRed(){const S=P.S||P.stats;return clamp(S.dex/150+S.int/450,0,.6);}
function fleeNow(){return Math.round((P.flee||0)+B('flee'));}
function dodgeChance(){const f=fleeNow();return clamp(f/(f+140+P.lvl*1.5),0,.6);}
function aspdHits(){return WEAPONS[P.weapon.t].aspd*P.aspdF*(1+B('aspd'));}
function derivedStats(){const hs=aspdHits();return {
  aspd:Math.round(Math.min(193,100+hs*25)),hits:hs,cdr:clamp(B('cdr'),0,.7)*100,cast:castRed()*100,
  crit:ST6.cc(P.crit+B('crit')),critDmg:(1.6+B('critDmg'))*100,flee:fleeNow(),dodge:dodgeChance()*100,move:Math.round(P.speed*(1+B('speed'))),movePct:Math.round((1+B('speed'))*100)};}
function hurtPlayer_v15(raw,src){
  if(!P.dead&&G.state==='play'&&!G.edit&&!(G.god||P.dome||P.invT>0)){
    if(rng()<dodgeChance()){textAt(P.x,P.y-50,'MISS','#9fb4d8',15,{life:.6});sfx('dodge');return;}
    const rd=B('redirect');if(rd>0&&src&&!src.dead&&src.hp){applyDamage(src,Math.max(1,Math.round(raw*rd)),false,{});raw*=1-clamp(rd,0,.8);if(rng()<.3)textAt(P.x,P.y-64,'SHADOW FORM','#b04cff',12);}
  }
  const hp0=P.hp;hurtPlayer_v3(raw,src);if(P.hp<hp0)sfx('hurt');
}

/* ---------- 2. Character window: fixed 920×580, 55-slot pages, derived stats ---------- */
const INV_PER=55;G.invPage=0;
function invScale(){const w=$('#wInv');if(!w)return;const s=Math.min(1,(innerWidth-12)/920,(innerHeight-12)/580);w.style.setProperty('--invScale',s.toFixed(3));}
addEventListener('resize',invScale);
function renderInv_v15(){
  invScale();
  const pages=Math.max(1,Math.ceil(Math.max(P.invSize,P.inv.length)/INV_PER));G.invPage=clamp(G.invPage|0,0,pages-1);const pg=G.invPage,cost=bagCost();
  $('#invSub').textContent=`${CLASSES[P.cls].n} · Base Lv ${P.lvl} · Job Lv ${P.jobLv}/${jobCap()} · กระเป๋า ${P.inv.length}/${P.invSize}`;
  let h=`<div class="cw"><section class="cwEq"><h3 class="sec">Equipment <em>ดับเบิลคลิกเพื่อถอด</em></h3><div class="eqlist">`;
  for(const [s,en,th] of EQ_SLOTS){const it=s==='weapon'?(P.weapon.t==='fist'?null:P.weapon):P.equip[s];
    h+=`<div class="eq2 ${it?'r'+it.rar:'empty'}" ${it?`data-uneq="${s}" data-eqtip="${s}"`:''}>${it?`<img src="${itemIcon(it)}" alt="">`:'<i></i>'}<span><small>${en.replace(' · ',' ')}</small>${it?itemNameC(it):`<em>${th}</em>`}</span></div>`;}
  h+=`</div></section><section class="cwInv"><div class="invhead"><h3 class="sec">Inventory</h3><span class="chip">${fmt(P.gold)} G</span><button class="btn gold sm" id="bBag" ${P.gold>=cost&&P.invSize<192?'':'disabled'}>+16 ช่อง · ${fmt(cost)} G</button></div><div class="invg">`;
  for(let k=0;k<INV_PER;k++){const i=pg*INV_PER+k,it=P.inv[i];if(i>=Math.max(P.invSize,P.inv.length)){h+='<div class="cell lock"></div>';continue;}if(!it){h+='<div class="cell"></div>';continue;}
    const isC=it.id&&ITEMS[it.id]&&ITEMS[it.id].k==='card',no=(it.kind==='wpn'||it.kind==='eq')&&!canEquip(it);
    h+=`<div class="cell ${it.kind?'r'+it.rar:''} ${isC?'r2':''} ${invSel===i?'sel':''} ${no?'no':''}" data-inv="${i}" data-tip="${i}"><img src="${itemIcon(it)}" alt="">${it.q>1?`<span class="q">${it.q}</span>`:''}${it.refine?`<span class="rf">+${it.refine}</span>`:''}</div>`;}
  h+=`</div><div class="pager"><button class="btn sm" data-ipg="-1" ${pg<=0?'disabled':''}>&lt; Previous</button><span>หน้า ${pg+1} / ${pages}</span><button class="btn sm" data-ipg="1" ${pg>=pages-1?'disabled':''}>Next &gt;</button><span class="muted">ดับเบิลคลิก = ใช้/สวม · คลิกขวา = ขาย</span></div></section>`;
  const S=P.stats,T=P.S||S,info={str:'ATK ประชิด',agi:'ASPD · FLEE',vit:'HP · DEF',int:'MATK · ร่ายไว',dex:'ATK ไกล · ร่ายไว',luk:'คริติคอล'};
  h+=`<section class="cwSt"><h3 class="sec">Status <em>แต้ม: <b>${P.statPts}</b> · Shift+คลิก = +10</em></h3><div class="st6">`;
  for(const k in S){const c=statCost(S[k]),bn=T[k]-S[k];h+=`<div class="strow"><b>${k.toUpperCase()}</b><span>${info[k]} · ${c} แต้ม</span><em>${S[k]}${bn?`<small> +${bn}</small>`:''}</em><button class="btn sm" data-stat="${k}" ${P.statPts>=c&&S[k]<99?'':'disabled'} aria-label="เพิ่ม ${k}">+</button></div>`;}
  const C=CLASSES[P.cls],nx=Object.keys(CLASSES).filter(c=>CLASSES[c].parent===P.cls).map(c=>CLASSES[c].n).join(' / ');
  h+=`</div><h3 class="sec" style="margin-top:8px">Profile</h3><div class="prof">${[['อาชีพ',C.n+' · T'+C.tier],['สายอาชีพ',(PATHS[C.path]||{n:'Novice'}).n],['เปลี่ยนคลาสถัดไป',nx||'สูงสุดแล้ว'],['Skill Points',P.skillPts],['Spirit',P.sp],['อาวุธ',WEAPONS[P.weapon.t].n||P.weapon.t]].map(([a,b])=>`<div class="kv"><span>${a}</span><b>${b}</b></div>`).join('')}</div>`;
  const D=derivedStats();
  h+=`</section><section class="cwDer"><h3 class="sec">Combat Stats <em>คำนวณแบบ Real-time</em></h3><div class="der">`;
  const kv=[['Max HP',fmt(P.maxHp)],['Max MP',fmt(P.maxMp)],['ATK',`${fmt(Math.round(P.atk*(1+B('atk'))))} +${P.refAtk}`],['MATK',`${fmt(Math.round(P.matk*(1+B('matk'))))} +${P.refMatk}`],['DEF',fmt(P.def)],
    ['ASPD',`${D.aspd} · ${D.hits.toFixed(2)} ครั้ง/วิ`],['CDR',D.cdr.toFixed(1)+'%'],['ลดเวลาร่าย',D.cast.toFixed(1)+'% <small>DEX+INT</small>'],['Critical',D.crit.toFixed(1)+'%'],['Crit DMG',Math.round(D.critDmg)+'%'],
    ['FLEE',`${D.flee} · หลบ ${D.dodge.toFixed(1)}%`],['Move Speed',`${D.move} (${D.movePct}%)`],['Base EXP',P.lvl>=C182cap()?'MAX':Math.floor(P.exp/need(P.lvl)*100)+'%'],['Job EXP',P.jobLv>=jobCap()?'MAX':Math.floor(P.jobExp/needJob(P.jobLv)*100)+'%']];
  for(const [a,b] of kv)h+=`<div class="kv"><span>${a}</span><b>${b}</b></div>`;
  h+=`</div></section></div>`;
  $('#invBody').innerHTML=h;
}
let invLiveT=0;function updInvLive(dt){if(G.win!=='wInv')return;invLiveT-=dt;if(invLiveT>0)return;invLiveT=.5;const b=$('#invBody .der');if(!b||$('#invBody').matches(':hover'))return;
  const D=derivedStats(),vals=b.querySelectorAll('.kv b');if(vals.length>=12){vals[5].textContent=`${D.aspd} · ${D.hits.toFixed(2)} ครั้ง/วิ`;vals[6].textContent=D.cdr.toFixed(1)+'%';vals[8].textContent=D.crit.toFixed(1)+'%';vals[9].textContent=Math.round(D.critDmg)+'%';vals[10].textContent=`${D.flee} · หลบ ${D.dodge.toFixed(1)}%`;vals[11].textContent=`${D.move} (${D.movePct}%)`;}}

/* ---------- 3. Web Audio engine ---------- */
const AUD_KEY=KEYP+'audio_v1';
const AUD={ctx:null,master:null,sfxG:null,bgmG:null,noise:null,cfg:{master:.7,sfx:.8,bgm:.45,mute:false,proc:true,zones:{}},zone:null,bgmT:0,step:0,el:null,lastHit:0,urls:{}};
try{Object.assign(AUD.cfg,JSON.parse(localStorage.getItem(AUD_KEY)||'{}'));}catch(e){}
function audSave(){try{localStorage.setItem(AUD_KEY,JSON.stringify(AUD.cfg));}catch(e){}}
function audInit_v15(){if(AUD.ctx)return AUD.ctx.state==='suspended'?AUD.ctx.resume():null;const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;
  const c=AUD.ctx=new AC();AUD.master=c.createGain();AUD.master.connect(c.destination);AUD.sfxG=c.createGain();AUD.sfxG.connect(AUD.master);AUD.bgmG=c.createGain();
  // light echo on the music bus
  const dl=c.createDelay(1),fb=c.createGain(),wet=c.createGain();dl.delayTime.value=.33;fb.gain.value=.32;wet.gain.value=.35;AUD.bgmG.connect(AUD.master);AUD.bgmG.connect(dl);dl.connect(fb);fb.connect(dl);dl.connect(wet);wet.connect(AUD.master);
  const n=c.createBuffer(1,c.sampleRate,c.sampleRate),d=n.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=rng()*2-1;AUD.noise=n;audVol();}
function audVol(){if(!AUD.ctx)return;const c=AUD.cfg,t=AUD.ctx.currentTime;AUD.master.gain.setTargetAtTime(c.mute?0:c.master,t,.05);AUD.sfxG.gain.setTargetAtTime(c.sfx,t,.05);AUD.bgmG.gain.setTargetAtTime(c.bgm,t,.1);if(AUD.el)AUD.el.volume=c.mute?0:clamp(c.master*c.bgm*((c.zones[AUD.zone]||{}).vol??1)*1.6,0,1);}
['pointerdown','keydown','touchstart'].forEach(ev=>addEventListener(ev,()=>{audInit();audZone(G.state==='play'?G.zone:'title');},{passive:true}));
function tone(o){const c=AUD.ctx;if(!c)return;const t=c.currentTime+(o.at||0),g=c.createGain(),os=c.createOscillator();os.type=o.type||'sine';os.frequency.setValueAtTime(o.f0,t);if(o.f1)os.frequency.exponentialRampToValueAtTime(Math.max(20,o.f1),t+o.dur);
  g.gain.setValueAtTime(0.0001,t);g.gain.exponentialRampToValueAtTime(o.v||.2,t+(o.a||.005));g.gain.exponentialRampToValueAtTime(0.0001,t+o.dur);
  let node=os;if(o.lp){const f=c.createBiquadFilter();f.type='lowpass';f.frequency.value=o.lp;os.connect(f);node=f;}node.connect(g);g.connect(o.bus||AUD.sfxG);os.start(t);os.stop(t+o.dur+.05);}
function noise(o){const c=AUD.ctx;if(!c)return;const t=c.currentTime+(o.at||0),s=c.createBufferSource(),f=c.createBiquadFilter(),g=c.createGain();s.buffer=AUD.noise;s.playbackRate.value=o.rate||1;
  f.type=o.ft||'bandpass';f.Q.value=o.q||1.2;f.frequency.setValueAtTime(o.f0,t);if(o.f1)f.frequency.exponentialRampToValueAtTime(Math.max(30,o.f1),t+o.dur);
  g.gain.setValueAtTime(0.0001,t);g.gain.exponentialRampToValueAtTime(o.v||.3,t+(o.a||.01));g.gain.exponentialRampToValueAtTime(0.0001,t+o.dur);s.connect(f);f.connect(g);g.connect(AUD.sfxG);s.start(t,rng()*.5);s.stop(t+o.dur+.05);}
const WHOOSH={dagger:{f0:4200,f1:1800,dur:.08,v:.28,q:2.2},sword:{f0:2600,f1:900,dur:.14,v:.32,q:1.4},greatsword:{f0:900,f1:220,dur:.26,v:.42,q:.9,thud:1},axe:{f0:1100,f1:260,dur:.24,v:.4,q:.9,thud:1},spear:{f0:1800,f1:700,dur:.12,v:.3,q:2},staff:{f0:1200,f1:500,dur:.18,v:.26,q:1,chime:1},bow:{snap:1}};
const THEME_HZ={spirit:523,holy:659,void:311,fire:392,ice:784,elemental:440};
function sfx_v15(k,a){if(!AUD.ctx||AUD.cfg.mute)return;
  switch(k){
    case 'swing':{const w=WHOOSH[a]||WHOOSH.sword;
      if(w.snap){tone({type:'square',f0:1400,f1:500,dur:.03,v:.12});tone({type:'triangle',f0:190,f1:140,dur:.22,v:.22,at:.01});noise({f0:3000,f1:6000,dur:.05,v:.1,q:3});break;}
      noise(w);if(w.thud)tone({type:'sine',f0:110,f1:45,dur:.22,v:.35,at:w.dur*.6});if(w.chime)tone({type:'sine',f0:1320,dur:.25,v:.05,at:.05});break;}
    case 'hit':{const now=performance.now();if(now-AUD.lastHit<45)return;AUD.lastHit=now;noise({ft:'lowpass',f0:1400,f1:300,dur:.09,v:.3});tone({type:'sine',f0:180,f1:70,dur:.1,v:.25});if(a)tone({type:'triangle',f0:1600,f1:2400,dur:.12,v:.12});break;}
    case 'cast':{const f=THEME_HZ[a]||500;tone({type:'sawtooth',f0:f*.5,f1:f*2,dur:.35,v:.07,lp:2400});tone({type:'sine',f0:f,f1:f*1.5,dur:.3,v:.1,at:.03});break;}
    case 'blast':{noise({ft:'lowpass',f0:2000,f1:120,dur:.55,v:.45,q:.7});tone({type:'sine',f0:140,f1:38,dur:.5,v:.4});break;}
    case 'charge':{const f=THEME_HZ[a]||500;tone({type:'triangle',f0:f*.5,f1:f*1.2,dur:.5,v:.05});break;}
    case 'level':[523,659,784,1047].forEach((f,i)=>tone({type:'triangle',f0:f,dur:.35,v:.14,at:i*.08}));break;
    case 'pickup':tone({type:'sine',f0:880,f1:1320,dur:.09,v:.09});break;
    case 'gold':tone({type:'square',f0:1568,dur:.05,v:.05});tone({type:'square',f0:2093,dur:.08,v:.05,at:.05});break;
    case 'hurt':tone({type:'sawtooth',f0:220,f1:110,dur:.12,v:.1,lp:900});break;
    case 'dodge':noise({f0:5000,f1:2500,dur:.07,v:.12,q:3});break;
    case 'stealth':noise({f0:600,f1:200,dur:.5,v:.18,q:.8});tone({type:'sine',f0:300,f1:150,dur:.5,v:.06});break;
    case 'blink':tone({type:'sine',f0:1800,f1:300,dur:.18,v:.1});noise({f0:4000,f1:900,dur:.15,v:.12,q:2});break;
    case 'ui':tone({type:'sine',f0:660,dur:.05,v:.05});break;
  }}
// procedural zone music: slow pad chords + sparse arpeggio, one mood per zone
const BGM={title:{root:57,prog:[[0,3,7,10],[-4,0,3,7],[-2,2,5,9],[-5,-1,2,5]],bpm:56,wave:'triangle',arp:.35,lp:1500},
  capital:{root:60,prog:[[0,4,7,11],[-3,0,4,7],[5,9,12,16],[7,11,14,17]],bpm:66,wave:'triangle',arp:.5,lp:2200},
  jungle:{root:62,prog:[[0,3,7,10],[5,9,12,15],[0,3,7,10],[-2,2,5,9]],bpm:72,wave:'sine',arp:.6,lp:1900},
  desert:{root:64,prog:[[0,1,4,7],[0,1,5,8],[-2,1,5,8],[0,1,4,7]],bpm:62,wave:'triangle',arp:.45,lp:1700,drone:1},
  wasteland:{root:52,prog:[[0,3,7],[1,5,8],[0,3,7],[-2,1,5]],bpm:54,wave:'sawtooth',arp:.25,lp:700,drone:1},
  snow:{root:69,prog:[[0,4,6,11],[2,6,9,14],[-1,4,7,11],[0,4,6,11]],bpm:50,wave:'sine',arp:.55,lp:2600},
  lava:{root:45,prog:[[0,3,6],[1,4,7],[0,3,6],[-1,2,6]],bpm:80,wave:'sawtooth',arp:.3,lp:600,drone:1},
  deepsea:{root:50,prog:[[0,7,14,16],[-3,4,9,12],[-5,2,7,11],[-3,4,9,12]],bpm:44,wave:'sine',arp:.35,lp:900},
  dark:{root:47,prog:[[0,3,6,9],[1,4,7,10],[0,3,6,9],[-1,2,5,8]],bpm:48,wave:'sawtooth',arp:.3,lp:800,drone:1}};
const mhz=m=>440*Math.pow(2,(m-69)/12);
function audZone(z){if(!AUD.ctx)return;if(AUD.zone===z&&(AUD.el||AUD.bgmT))return;AUD.zone=z;clearInterval(AUD.bgmT);AUD.bgmT=0;
  if(AUD.el){AUD.el.pause();AUD.el=null;}
  const zc=AUD.cfg.zones[z]||{},src=AUD.urls[z]||zc.url;
  if(src){const a=new Audio();a.src=src;a.loop=true;a.crossOrigin='anonymous';AUD.el=a;audVol();a.play().catch(()=>{AUD.el=null;audProc(z);if(G.win==='wGM')renderGM();});return;}
  audProc(z);}
function audProc(z){if(!AUD.cfg.proc)return;const S=BGM[z]||BGM[ZONES[z]?ZB(z):'capital']||BGM.capital,beat=60/S.bpm;AUD.step=0;
  const bar=()=>{if(!AUD.ctx||AUD.cfg.mute)return;const c=AUD.ctx,ch=S.prog[AUD.step%S.prog.length],t=c.currentTime+.05,len=beat*4,zv=(AUD.cfg.zones[z]||{}).vol??1;
    for(const iv of ch){for(const det of [-4,4]){const o=c.createOscillator(),g=c.createGain(),f=c.createBiquadFilter();o.type=S.wave;o.frequency.value=mhz(S.root+iv-12*(iv>12?1:0));o.detune.value=det;f.type='lowpass';f.frequency.value=S.lp;
      g.gain.setValueAtTime(0.0001,t);g.gain.linearRampToValueAtTime(.022*zv,t+len*.35);g.gain.linearRampToValueAtTime(0.0001,t+len*1.15);o.connect(f);f.connect(g);g.connect(AUD.bgmG);o.start(t);o.stop(t+len*1.2);}}
    if(S.drone){const o=c.createOscillator(),g=c.createGain();o.type='sine';o.frequency.value=mhz(S.root-24);g.gain.setValueAtTime(0.0001,t);g.gain.linearRampToValueAtTime(.05*zv,t+len*.3);g.gain.linearRampToValueAtTime(0.0001,t+len*1.1);o.connect(g);g.connect(AUD.bgmG);o.start(t);o.stop(t+len*1.15);}
    for(let i=0;i<8;i++)if(rng()<S.arp){const n=ch[(rng()*ch.length)|0]+12,at=t+i*beat/2;const o=c.createOscillator(),g=c.createGain();o.type='sine';o.frequency.value=mhz(S.root+n);g.gain.setValueAtTime(0.0001,at);g.gain.exponentialRampToValueAtTime(.03*zv,at+.02);g.gain.exponentialRampToValueAtTime(0.0001,at+beat*1.4);o.connect(g);g.connect(AUD.bgmG);o.start(at);o.stop(at+beat*1.5);}
    AUD.step++;};
  bar();AUD.bgmT=setInterval(bar,beat*4000);}
function audRestart(){const z=AUD.zone;AUD.zone=null;if(z)audZone(z);}
// custom tracks uploaded as files live in IndexedDB (per browser) so they survive reloads
const IDB={db:null,open(){return new Promise(r=>{if(this.db)return r(this.db);try{const q=indexedDB.open(KEYP+'media',1);q.onupgradeneeded=()=>q.result.createObjectStore('audio');q.onsuccess=()=>{this.db=q.result;r(this.db);};q.onerror=()=>r(null);}catch(e){r(null);}});},
  async put(k,blob){const d=await this.open();if(!d)return false;return new Promise(r=>{const t=d.transaction('audio','readwrite');t.objectStore('audio').put(blob,k);t.oncomplete=()=>r(true);t.onerror=()=>r(false);});},
  async get(k){const d=await this.open();if(!d)return null;return new Promise(r=>{const q=d.transaction('audio').objectStore('audio').get(k);q.onsuccess=()=>r(q.result||null);q.onerror=()=>r(null);});},
  async del(k){const d=await this.open();if(!d)return;d.transaction('audio','readwrite').objectStore('audio').delete(k);}};
async function audLoadFiles(){for(const z in AUD.cfg.zones){if(AUD.cfg.zones[z].file){const b=await IDB.get('bgm_'+z);if(b)AUD.urls[z]=URL.createObjectURL(b);}}}
audLoadFiles();

/* game hooks: swings, casts, hits, level up, pickups */
function basicAttack(){const cd0=P.atkCd,sw0=P.swing;const was=P.stealth>0;
  basicAttack_v5();
  if(P.atkCd>cd0||(P.swing&&P.swing!==sw0&&!P.casting)){G.basicT=time;sfx('swing',P.weapon.t);if(was){breakStealth(true);}}}
function castSkillNow(id){const s=SK[id];if(!s)return false;
  if(s.type==='custom')return castCustom(id);
  const was=P.stealth>0&&s.type!=='buff'&&s.type!=='heal'&&!s.keepStealth;if(was)P.ambushUntil=time+.35;
  const ok=castSkillNow_v1(id);
  if(ok!==false){sfx('cast',s.th);if(['nova','burst','meteor','line','execute'].includes(s.type))setTimeout(()=>sfx('blast'),s.type==='meteor'?420:60);if(was)breakStealth(false);}
  return ok;}
function hitEnemy_v15(e,m,o={}){
  if(P.ambushUntil>time&&!o.critAlways)o=Object.assign({},o,{critAlways:true});
  const r=hitEnemy_v3(e,m,o);if(r)sfx('hit',o.critAlways);
  if(!o.dot&&!o.echo&&!e.dead&&C182.procOk(e,o)){
    if(B('venom')>0&&rng()<.6)applySt(e,{poison:4},{dt:'phys',dotm:.32});
    if(time-(G.basicT||-9)<.28&&rng()<B('dbl')){const e2=e,m2=m,o2=Object.assign({},o,{echo:1});timers.push({t:.09,fn:()=>{if(!e2.dead){hitEnemy_v3(e2,m2,o2);textAt(e2.x+14,e2.y-e2.sz*2.6,'DOUBLE','#ffd36b',13,{life:.6});}}});}
    if(P.mirage&&P.mirage.t>0){for(let k=0;k<3;k++){const e2=e,a=time*1.6+k*TAU/3;timers.push({t:.07*(k+1),fn:()=>{if(e2.dead)return;const mx=P.x+Math.cos(a)*54,my=P.y+Math.sin(a)*24;fx.push({k:'bolt',pts:[[mx,my-20],[e2.x,e2.y-e2.sz*.6]],t:0,dur:.18,pl:THEMES.void});
      hitEnemy_v3(e2,m*.5,Object.assign({},o,{echo:1,true:true,critAlways:false}));}});}}
  }
  return r;}
function levelUpFx(){levelUpFx_v1();sfx('level');}
function pickLoot(l){const g=l&&l.gold,ok=pickLoot_v3(l);if(ok)sfx(g?'gold':'pickup');return ok;}

