function breakStealth(crit){if(!(P.stealth>0))return;P.stealth=0;if(crit)P.ambushUntil=time+.35;fx.push({k:'ghost',x:P.x,y:P.y,t:0,dur:.4,pl:THEMES.void});}
function stealthSpeed(){return P.stealth>0?clamp(.6+B('sneak'),.6,1.2):1;}
function behind(e,gap){const a=Math.atan2(e.y-P.y,e.x-P.x),Z=ZONES[G.zone];return {x:clamp(e.x+Math.cos(a)*(e.sz+gap),30,Z.w-30),y:clamp(e.y+Math.sin(a)*(e.sz+gap),30,Z.h-30),face:a+Math.PI};}
function pickTarget(range){const t=aimPoint(range);return nearestEnemy(t.x,t.y,240)||nearestEnemy(P.x,P.y,range);}
function castCustom(id){
  if(P.dead||G.state!=='play'||G.edit)return false;const s=SK[id],lv=P.skills[id]||0;if(!lv)return false;
  if((P.cds[id]||0)>0)return false;const cost=mpCost(s,lv);
  if(!(id==='shadowBlink'&&P.blinkBack)&&P.mp<cost){textAt(P.x,P.y-60,'MP ไม่พอ','#7fc8ff',14);return false;}
  const pl=THEMES.void,m=(s.m||0)*(1+.12*(lv-1)),o={dt:'phys',fxk:1+(lv-1)*.13,pl};
  const was=P.stealth>0;
  const done=THIEF_FX[s.fx](s,lv,m,o,pl,was);
  if(!done)return false;
  if(done!=='free'){P.mp-=cost;P.cds[id]=s.cd*(1-clamp(B('cdr'),0,.7));}
  const flash=document.querySelector(`.slot[data-sk="${id}"]`);if(flash){flash.classList.remove('flash');void flash.offsetWidth;flash.classList.add('flash');}
  return true;}
const THIEF_FX={
  stealth(s,lv,m,o,pl){P.stealth=s.dur*(1+.05*(lv-1));if(s.speed)P.buffs[s.id]={t:P.stealth,max:P.stealth,pl,speed:s.speed};for(const e of enemies)if(e.aggro&&!e.m.boss){e.aggro=false;e.calmT=0;}
    for(let i=0;i<26;i++)part({x:P.x+rand(-24,24),y:P.y+rand(-30,10),vx:rand(-40,40),vy:rand(-60,-10),life:rand(.5,1),max:1,size:rand(8,16),col:'#2a1540',type:'smoke',grow:12,drag:.97});
    textAt(P.x,P.y-80,s.name,'#b98cff',16);sfx('stealth');return true;},
  shadowStep(s,lv,m,o,pl){const e=pickTarget(s.range);if(!e){textAt(P.x,P.y-60,'ไม่มีเป้าหมาย','#8fa4cc',13);return false;}const b=behind(e,26);
    fx.push({k:'ghost',x:P.x,y:P.y,t:0,dur:.45,pl});P.x=b.x;P.y=b.y;P.face=b.face;P.invT=Math.max(P.invT,.2);sfx('blink');
    P.swing={t:0,dur:.2,type:'arc',a0:b.face-.9,a1:b.face+.9};crescent(P.x,P.y,b.face-.9,b.face+.9,90,34,.2,pl,true,{big:1});hitEnemy(e,m,o);breakStealth(false);return true;},
  blink(s,lv,m,o,pl){
    if(P.blinkBack){const b=P.blinkBack;fx.push({k:'ghost',x:P.x,y:P.y,t:0,dur:.4,pl});P.x=b.x;P.y=b.y;P.blinkBack=null;ring(P.x,P.y,8,80,.35,pl.main,5);sfx('blink');P.cds[s.id]=s.cd*(1-clamp(B('cdr'),0,.7));return 'free';}
    const mv=G.joy&&G.joy.m>0?scr2wDir(G.joy.x,G.joy.y/camT()):(Math.hypot(P.vx,P.vy)>30?[P.vx,P.vy]:[Math.cos(P.face),Math.sin(P.face)]),a=Math.atan2(mv[1],mv[0]);
    P.blinkBack={x:P.x,y:P.y,t:3};P.dash={vx:Math.cos(a)*s.range/.16,vy:Math.sin(a)*s.range/.16,t:.16,hit:new Set(),back:true,pl};P.invT=Math.max(P.invT,.2);sfx('blink');
    P.mp-=mpCost(s,lv);P.cds[s.id]=.35;return 'free';},
  ambush(s,lv,m,o,pl){const e=pickTarget(s.range);if(!e){textAt(P.x,P.y-60,'ไม่มีเป้าหมาย','#8fa4cc',13);return false;}const b=behind(e,24);
    fx.push({k:'ghost',x:P.x,y:P.y,t:0,dur:.45,pl});P.x=b.x;P.y=b.y;P.face=b.face;sfx('blink');P.swing={t:0,dur:.26,type:'thrust',ang:b.face};
    hitEnemy(e,m,o);applySt(e,{stun:s.stun},o);textAt(e.x,e.y-e.sz*2.6,'AMBUSH!','#ff4fd8',18);shake(5);breakStealth(false);return true;},
  backstab(s,lv,m,o,pl,was){const e=pickTarget(s.range);if(!e){textAt(P.x,P.y-60,'ไม่มีเป้าหมาย','#8fa4cc',13);return false;}const b=behind(e,24);
    fx.push({k:'ghost',x:P.x,y:P.y,t:0,dur:.45,pl});P.x=b.x;P.y=b.y;P.face=b.face;P.swing={t:0,dur:.26,type:'thrust',ang:b.face};if(was)P.ambushUntil=time+.35;
    hitEnemy(e,m*(was?1.5:1),o);textAt(e.x,e.y-e.sz*2.6,'BACKSTAB','#ff4fd8',17);shake(6);sfx('blink');breakStealth(false);return true;},
  sonic(s,lv,m,o,pl,was){const e=pickTarget(s.range+60);const ang=e?Math.atan2(e.y-P.y,e.x-P.x):P.face;P.face=ang;if(was)P.ambushUntil=time+1;
    for(let i=0;i<s.hits;i++)timers.push({t:i*.09,fn:()=>{const a=ang+(i%2?.5:-.5);P.swing={t:0,dur:.09,type:'arc',a0:a-.6,a1:a+.6};crescent(P.x,P.y,a-.7,a+.7,s.range*.8,26,.12,pl,true);
      sfx('swing','dagger');for(const t of enemies)if(inSector(t,P.x,P.y,ang,s.range,1.4))hitEnemy(t,m,o);if(i===s.hits-1){textAt(P.x,P.y-80,'SONIC BLOW','#ff4fd8',17);shake(6);}}});
    breakStealth(false);return true;},
  snatch(s,lv,m,o,pl){const e=pickTarget(s.range+40);const ang=e?Math.atan2(e.y-P.y,e.x-P.x):P.face;P.face=ang;P.swing={t:0,dur:.2,type:'arc',a0:ang-.8,a1:ang+.8};crescent(P.x,P.y,ang-.8,ang+.8,s.range*.8,30,.2,pl,true);
    if(e&&inSector(e,P.x,P.y,ang,s.range,1.6)){hitEnemy(e,m,o);if(!e.stolen&&rng()<.4){e.stolen=1;const r=rng();
      if(r<.6)dropLoot(e.x,e.y,{gold:Math.round((10+e.L*6)*rand(.8,1.3))});else dropLoot(e.x,e.y,{item:{id:pick(['hpPot','mpPot','shard']),q:1}});textAt(e.x,e.y-e.sz*2.6,'STEAL!','#ffd36b',16);}}
    breakStealth(false);return true;},
  confine(s,lv,m,o,pl){const e=pickTarget(s.range);if(!e){textAt(P.x,P.y-60,'ไม่มีเป้าหมาย','#8fa4cc',13);return false;}
    applySt(e,{root:s.dur},o);P.buffs[s.id]={t:s.dur,max:s.dur,pl,speed:-1,flee:20};fx.push({k:'bolt',pts:[[P.x,P.y-20],[e.x,e.y-e.sz*.5]],t:0,dur:s.dur,pl});textAt(e.x,e.y-e.sz*2.6,'CONFINED','#b98cff',15);recalc();return true;},
  raid(s,lv,m,o,pl,was){if(was)P.ambushUntil=time+.35;ring(P.x,P.y,10,s.r,.45,pl.main,12);emitThemed(P.x,P.y,pl,40,260);
    for(const e of enemies)if(d2(e.x,e.y,P.x,P.y)<s.r+e.sz){hitEnemy(e,m*(was?1.5:1),o);applySt(e,{armorBreak:4},o);}sfx('blast');shake(6);breakStealth(false);return true;},
  illusion(s,lv,m,o,pl){P.mirage={t:s.dur*(1+.05*(lv-1))};fx.push({k:'pillar',x:P.x,y:P.y,t:0,dur:1.2,col:'#b04cff',w:80,h:460});ring(P.x,P.y,10,180,.7,'#ff4fd8',8);
    textAt(P.x,P.y-96,'SHADOW ILLUSION','#ff4fd8',24,{life:1.6});sfx('blast');showBanner('SHADOW ILLUSION','ร่างเงา 3 ร่างเลียนแบบทุกการโจมตี · True Damage',2.2);return true;},
  rift(s,lv,m,o,pl){const c=aimPoint(600);const tgts=enemies.filter(e=>!e.dead&&inView(e.x,e.y,0));
    for(let i=0;i<4;i++)fx.push({k:'rift',x:c.x-Math.cos(i*.8)*260,y:c.y-Math.sin(i*.8)*120,ang:i*.8,len:520,t:0,dur:1.3,pl});
    ring(c.x,c.y,10,420,.9,'#b04cff',16);ring(c.x,c.y,420,20,1,'#ff4fd8',8);showBanner('ABYSSAL RIFT','ฉีกมิติ · ดูดศัตรูทุกตัวบนจอ',2.2);sfx('blast');setTimeout(()=>sfx('blast'),300);
    for(const e of tgts){const sx=e.x,sy=e.y;for(let k=1;k<=6;k++)timers.push({t:k*.07,fn:()=>{if(e.dead)return;e.x=lerp(sx,c.x+rand(-30,30),k/6*.8);e.y=lerp(sy,c.y+rand(-20,20),k/6*.8);}});
      timers.push({t:.5,fn:()=>{if(!e.dead){hitEnemy(e,m,Object.assign({},o,{true:true}));applySt(e,{slow:3},o);}}});}
    shake(14);textAt(P.x,P.y-96,'ABYSSAL RIFT','#b04cff',24,{life:1.6});return true;}};
function thiefTick(dt){
  if(P.stealth>0){P.stealth-=dt;if(P.stealth<=0){P.stealth=0;textAt(P.x,P.y-60,'ออกจากการซ่อนตัว','#8fa4cc',12);}else if(rng()<.15)part({x:P.x+rand(-14,14),y:P.y-rand(0,30),vx:0,vy:-20,life:.6,max:.6,size:rand(5,9),col:'#2a1540',type:'smoke',grow:8,drag:.97});}
  if(P.blinkBack){P.blinkBack.t-=dt;if(P.blinkBack.t<=0){P.blinkBack=null;const s=SK.shadowBlink;P.cds.shadowBlink=s.cd*(1-clamp(B('cdr'),0,.7));}}
  if(P.mirage){P.mirage.t-=dt;if(P.mirage.t<=0)P.mirage=null;}
  G.dashCd=Math.max(0,(G.dashCd||0));
}
function drawMirages(Hf){if(!P.mirage||!Hf)return;const k=Math.min(1,P.mirage.t/.5);ctx.save();
  for(let i=0;i<3;i++){const a=time*1.6+i*TAU/3,dx=Math.cos(a)*54,dy=Math.sin(a)*24;ctx.globalAlpha=.32*k;ctx.filter='brightness(.35) sepia(1) hue-rotate(220deg) saturate(4)';ctx.imageSmoothingEnabled=false;
    ctx.drawImage(HC,Math.round(Hf.ox+dx),Math.round(Hf.oy+dy),HC.width*HS,HC.height*HS);}
  ctx.filter='none';ctx.restore();add();for(let i=0;i<3;i++){const a=time*1.6+i*TAU/3;glow(P.x+Math.cos(a)*54,P.y-20+Math.sin(a)*24,26,'#b04cff',.35);}norm();}

/* ---------- 5. GM Creator Suite: items & costumes ---------- */
const CITEM_KEY=KEYP+'custom_items_v1';
let CITEMS=[];try{CITEMS=JSON.parse(localStorage.getItem(CITEM_KEY)||'[]')||[];}catch(e){CITEMS=[];}
function saveCItems(){try{localStorage.setItem(CITEM_KEY,JSON.stringify(CITEMS));return true;}catch(e){notify('บันทึกไอเทมไม่สำเร็จ: พื้นที่เก็บข้อมูลในเบราว์เซอร์เต็ม (ลองใช้รูปเล็กลง)');return false;}}
const CI_SLOTS=[['w:sword','อาวุธ · ดาบมือเดียว'],['w:dagger','อาวุธ · มีดสั้น'],['w:greatsword','อาวุธ · ดาบสองมือ'],['w:axe','อาวุธ · ขวาน'],['w:spear','อาวุธ · หอก'],['w:bow','อาวุธ · ธนู'],['w:staff','อาวุธ · คทา'],
  ['e:armor','เกราะ (Armor)'],['e:headTop','หมวกบน / คอสตูมหัว'],['e:headMid','หมวกกลาง'],['e:headLow','หมวกล่าง'],['e:shield','โล่'],['e:garment','ผ้าคลุม / คอสตูมตัว'],['e:shoes','รองเท้า'],['e:acc','เครื่องประดับ']];
const CI_CLS=[['','ทุกอาชีพ'],['novice','Novice'],['sword','สายดาบ'],['mage','สายเวท'],['archer','สายธนู'],['cleric','สายนักบวช'],['thief','สายนักฆ่า (Thief)']];
function makeCustomItem_v15(t){let it;const [k,type]=t.slot.split(':');
  if(k==='w'){it=makeWeapon(type,Math.max(1,t.lvl||1),t.rar|0);it.atk=+t.atk||0;it.matk=+t.matk||0;}
  else{it=makeGear(type,Math.max(1,t.lvl||1),t.rar|0);it.def=+t.def||0;}
  it.name=t.name;it.bonus={};for(const s of ['str','agi','vit','int','dex','luk'])if(+t[s])it.bonus[s]=+t[s];
  it.cx={hp:+t.hp||0,mp:+t.mp||0,crit:+t.crit||0,atk:k==='w'?0:+t.atk||0,matk:k==='w'?0:+t.matk||0,def:k==='w'?+t.def||0:0};
  if(t.cls)it.clsR=[t.cls];if(t.img)it.img=t.img;it.custom=t.id;return it;}
function giveCustom(t){const it=makeCustomItem(t);if(addItem(it)){log(`GM: สร้าง ${t.name} ใส่กระเป๋าแล้ว`,'v');sfx('pickup');if(G.win==='wInv')renderInv();return true;}notify('กระเป๋าเต็ม!');return false;}
function readCIForm_v15(){const v=id=>$('#ci_'+id).value;const t={id:'ci'+nowMs().toString(36),name:v('name').trim().slice(0,40),slot:v('slot'),cls:v('cls'),rar:+v('rar'),lvl:+v('lvl')||1,img:CI_IMG||null};
  for(const s of ['atk','matk','def','hp','mp','crit','str','agi','vit','int','dex','luk'])t[s]=+v(s)||0;return t;}
let CI_IMG=null;
function ciImage(file){if(!file)return;if(!/^image\/(png|jpeg|webp|gif)$/.test(file.type)){notify('รองรับไฟล์ PNG / JPEG / WebP / GIF');return;}
  const r=new FileReader();r.onload=()=>{const im=new Image();im.onload=()=>{const S=64,c=document.createElement('canvas');c.width=c.height=S;const g=c.getContext('2d');const k=Math.min(S/im.width,S/im.height);
      g.imageSmoothingEnabled=im.width>S*2;g.drawImage(im,(S-im.width*k)/2,(S-im.height*k)/2,im.width*k,im.height*k);CI_IMG=c.toDataURL('image/png');renderCIPreview();};im.src=r.result;};r.readAsDataURL(file);}
function renderCIPreview_v15(){const p=$('#ci_prev');if(!p)return;const t=readCIForm();p.innerHTML=t.img?`<img src="${t.img}" alt="">`:'<span class="muted">ยังไม่มีรูป · ใช้ไอคอนอัตโนมัติ</span>';
  $('#ci_sum').textContent=`${t.name||'(ไม่มีชื่อ)'} · ${CI_SLOTS.find(x=>x[0]===t.slot)[1]} · ${CI_CLS.find(x=>x[0]===t.cls)[1]}`;}

/* ---------- 6. Waypoint beacons (Map & Waypoint Node Designer) ---------- */
const BEACON_KEY=KEYP+'beacons_v1';
let BEACONS=[];try{BEACONS=JSON.parse(localStorage.getItem(BEACON_KEY)||'[]')||[];}catch(e){BEACONS=[];}
function saveBeacons(){try{localStorage.setItem(BEACON_KEY,JSON.stringify(BEACONS));}catch(e){}}
let beaconMsgT=0,beaconCool=0;
function updBeacons(){if(beaconCool>0){beaconCool-=1/60;return;}if(G.fade||G.state!=='play')return;
  for(const b of BEACONS){if(b.zone!==G.zone)continue;if(d2(b.x,b.y,P.x,P.y)<48){
    if(P.lvl<(b.minLv||1)){if(performance.now()-beaconMsgT>1500){beaconMsgT=performance.now();textAt(P.x,P.y-70,`ต้องการ Lv ${b.minLv}`,'#ff6b8b',16);}continue;}
    const to=b.to,Z=ZONES[to];let arr=b.tx!=null?{x:b.tx,y:b.ty}:(to==='capital'?{x:Z.nexus[0],y:Z.nexus[1]+170}:Z.way?{x:Z.way[0],y:Z.way[1]+80}:{x:Z.w/2,y:Z.h/2});
    if(to===G.zone){P.x=arr.x;P.y=arr.y;beaconCool=1;ring(P.x,P.y,10,120,.5,'#8dffe8',6);sfx('blink');return;}
    G.beaconArrive={z:to,x:arr.x,y:arr.y};beaconCool=1.5;travel(to,'tele');sfx('blink');return;}}}
function drawBeacons(){}
function drawBeacon(b){const ok=P.lvl>=(b.minLv||1);
  {const x=b.x,y=b.y,t=time,col=ok?'#8dffe8':'#ff8a8a';ell(x,y+4,34,10,'#000000',.35);
    add();glow(x,y-30,60,col,.35+.1*Math.sin(t*3));ctx.globalAlpha=.6;ctx.strokeStyle=col;ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(x,y+2,30+Math.sin(t*2)*3,9,0,0,TAU);ctx.stroke();norm();
    const g=ctx.createLinearGradient(x,y-70,x,y);g.addColorStop(0,'#e8fbff');g.addColorStop(1,'#3a5a7a');ctx.fillStyle=g;ctx.beginPath();ctx.moveTo(x,y-72);ctx.lineTo(x+11,y-8);ctx.lineTo(x,y);ctx.lineTo(x-11,y-8);ctx.closePath();ctx.fill();
    add();glow(x,y-44+Math.sin(t*2)*4,14,'#ffffff',.9);norm();label(x,y+24,b.label||('→ '+ZONES[b.to].n),col,12);label(x,y+38,ok?`→ ${ZONES[b.to].n}`:`🔒 Lv ${b.minLv}+`,ok?'#8fa4cc':'#ff8a8a',10);}}
function beaconArrive(zid){if(G.beaconArrive&&G.beaconArrive.z===zid){const Z=ZONES[zid];P.x=clamp(G.beaconArrive.x,30,Z.w-30);P.y=clamp(G.beaconArrive.y,30,Z.h-30);G.beaconArrive=null;camSync();cam.x=P.x-VW/2;cam.y=P.y-VH/2;clampCam();}}

