/* ---------- 0. one-time migration: saved map edits & waypoints follow the 50% map scale ---------- */
(function(){const F=KEYP+'mapscale_v1';try{if(localStorage.getItem(F))return;
  const pr=JSON.parse(localStorage.getItem(KEYP+'props_v1')||'null');if(pr&&typeof pr==='object'&&!pr._v){for(const z of ZORDER)if(Array.isArray(pr[z]))pr[z]=pr[z].map(p=>({...p,x:Math.round(p.x*MAP_SCALE),y:Math.round(p.y*MAP_SCALE)}));localStorage.setItem(KEYP+'props_v1',JSON.stringify(pr));}
  const bs=JSON.parse(localStorage.getItem(KEYP+'beacons_v1')||'null');if(Array.isArray(bs)){for(const b of bs){if(ZORDER.includes(b.zone)){b.x=Math.round(b.x*MAP_SCALE);b.y=Math.round(b.y*MAP_SCALE);}if(ZORDER.includes(b.to)&&b.tx!=null){b.tx=Math.round(b.tx*MAP_SCALE);b.ty=Math.round(b.ty*MAP_SCALE);}}localStorage.setItem(KEYP+'beacons_v1',JSON.stringify(bs));BEACONS=bs;}
  localStorage.setItem(F,'1');}catch(e){}})();

/* ---------- 1. Fashion layer & per-slot visibility ---------- */
const FASH_KEY=KEYP+'fashion_v1';
const VIS_SLOTS=['headTop','headMid','headLow','armor','garment','shield','shoes','weapon'];
const FASHION_SLOTS=[['headTop','Costume · Upper','หมวกบน'],['headMid','Costume · Middle','หมวกกลาง'],['headLow','Costume · Lower','หมวกล่าง'],['armor','Costume · Outfit','ชุด'],['garment','Costume · Garment','ผ้าคลุม'],['shield','Costume · Shield','โล่'],['shoes','Costume · Shoes','รองเท้า']];
let FASH={on:true,vis:{},fvis:{},slots:{}};
try{Object.assign(FASH,JSON.parse(localStorage.getItem(FASH_KEY)||'{}'));}catch(e){}
FASH.vis={};
function saveFash(){try{localStorage.setItem(FASH_KEY,JSON.stringify(FASH));}catch(e){}}
// what the character WEARS visually; stats still come from P.equip
function visEquip(){const o={};if(!P)return o;for(const s in P.equip){let it=null;   // ของสวมใส่จริงไม่แสดงบนตัวละครอีกต่อไป — แสดงเฉพาะแฟชั่น
    const f=FASH.slots[s];if(FASH.on&&f&&FASH.fvis[s]!==false)it=f;o[s]=it;}
  for(const [s] of FASHION_SLOTS)if(!(s in o)&&FASH.on&&FASH.slots[s]&&FASH.fvis[s]!==false)o[s]=FASH.slots[s];return o;}
function drawWeapon(g,t,x,y,a,sc,pl,live){if(live&&g===ctx&&FASH.vis.weapon===false)return;drawWeapon_v16(g,t,x,y,a,sc,pl,live);}
function fashionOK(it){return it&&it.kind==='eq'&&FASHION_SLOTS.some(([s])=>s===it.type);}
G.invView='gear';
function wearFashion(i){const it=P.inv[i];if(!fashionOK(it))return false;const s=it.type,old=FASH.slots[s];P.inv.splice(i,1);if(old)P.inv.push(old);FASH.slots[s]=it;FASH.fvis[s]=true;saveFash();log(`แฟชั่น: ใส่ ${itemName(it)} (ไม่มีค่าสถานะ)`,'v');return true;}
function removeFashion(s){const it=FASH.slots[s];if(!it)return;if((window.QBAG222?QBAG222.used(P):P.inv.length)>=P.invSize){notify('กระเป๋าเต็ม');return;}P.inv.push(it);delete FASH.slots[s];saveFash();}
function renderInv(){renderInv_v15();
  const sec=$('#invBody .cwEq');if(!sec)return;const fv=G.invView==='fash';
  let h=`<h3 class="sec">${fv?'Fashion':'Equipment'} <em>${fv?'แสดงผลอย่างเดียว · ไม่มีค่าสถานะ':'ดับเบิลคลิกเพื่อถอด'}</em></h3>
    <div class="eqtabs"><button data-ivw="gear" class="${fv?'':'on'}">อุปกรณ์</button><button data-ivw="fash" class="${fv?'on':''}">แฟชั่น</button><button class="fmaster ${FASH.on?'on':''}" data-fmaster title="สลับระหว่างชุดแฟชั่นกับชุดอุปกรณ์" aria-label="แสดงชุดแฟชั่น">✦ ${FASH.on?'ON':'OFF'}</button></div><div class="eqlist">`;
  if(!fv){for(const [s,en,th] of EQ_SLOTS){const it=s==='weapon'?(P.weapon.t==='fist'?null:P.weapon):P.equip[s],vis=false,off=FASH.vis[s]===false;
      h+=`<div class="eq2 ${it?'r'+it.rar:'empty'}" ${it?`data-uneq="${s}" data-eqtip="${s}"`:''}>${it?`<img src="${itemIcon(it)}" alt="">`:'<i></i>'}<span><small>${en.replace(' · ',' ')}</small>${it?itemNameC(it):`<em>${th}</em>`}</span>${vis?`<button class="eye ${off?'off':''}" data-eye="${s}" title="${off?'แสดง':'ซ่อน'}ภาพบนตัวละคร (ค่าสถานะยังอยู่)" aria-label="สลับการแสดงผล ${th}">👁</button>`:''}</div>`;}}
  else{for(const [s,en,th] of FASHION_SLOTS){const it=FASH.slots[s],off=FASH.fvis[s]===false;
      h+=`<div class="eq2 fash ${it?'r'+it.rar:'empty'}" ${it?`data-funeq="${s}" data-ftip="${s}"`:''}>${it?`<img src="${itemIcon(it)}" alt="">`:'<i></i>'}<span><small>${en}</small>${it?itemNameC(it):`<em>${th}</em>`}</span>${it?`<button class="eye ${off?'off':''}" data-feye="${s}" aria-label="สลับการแสดงผลแฟชั่น ${th}">👁</button>`:''}</div>`;}
    h+=`<p class="fhint">ดับเบิลคลิกชุดแฟชั่นในกระเป๋า (กรอบชมพู) เพื่อสวม · ไม่มีค่าสถานะ · ซื้อเพิ่มได้ที่ Madame Celeste</p>`;}
  sec.innerHTML=h+'</div>';
  if(fv)$('#invBody').querySelectorAll('.invg .cell[data-inv]').forEach(c=>{if(fashionOK(P.inv[+c.dataset.inv]))c.classList.add('fok');});}
function initFashionUI(){const body=$('#invBody');
  body.addEventListener('click',e=>{const t=e.target;
    const v=t.closest('[data-ivw]');if(v){G.invView=v.dataset.ivw;renderInv();return;}
    if(t.closest('[data-fmaster]')){FASH.on=!FASH.on;saveFash();renderInv();notify(FASH.on?'แสดงชุดแฟชั่น':'แสดงชุดอุปกรณ์',false);return;}
    const ey=t.closest('[data-eye]');if(ey){const s=ey.dataset.eye;FASH.vis[s]=FASH.vis[s]===false;saveFash();renderInv();return;}
    const fe=t.closest('[data-feye]');if(fe){const s=fe.dataset.feye;FASH.fvis[s]=FASH.fvis[s]===false;saveFash();renderInv();return;}});
  body.addEventListener('dblclick',e=>{const t=e.target;
    if(t.closest('.eye')){e.stopImmediatePropagation();return;}
    const fu=t.closest('[data-funeq]');if(fu){e.stopImmediatePropagation();$('#tip').hidden=true;removeFashion(fu.dataset.funeq);renderInv();return;}
    if(G.invView==='fash'){const c=t.closest('[data-inv]');if(c){e.stopImmediatePropagation();$('#tip').hidden=true;if(!wearFashion(+c.dataset.inv))notify('ช่องนี้ใส่ได้เฉพาะไอเทมชุดแฟชั่น (Costume)');invSel=-1;renderInv();}}},true);
  body.addEventListener('pointermove',e=>{const f=e.target.closest('[data-ftip]');if(f){const it=FASH.slots[f.dataset.ftip];if(it){e.stopImmediatePropagation();showTip(tipFor(it)+'<div class="tcmp">แฟชั่น · แสดงผลอย่างเดียว ไม่มีค่าสถานะ</div>',e.clientX,e.clientY);}}},true);}
function startGame_v5(cont){if(!cont){FASH={on:true,vis:{},fvis:{},slots:{}};saveFash();}startGame_v5b(cont);}

/* ---------- 2. Elite monsters ---------- */
const RAID_KEY=KEYP+'raid_v1';
let RAIDCFG={on:true,interval:30,eliteChance:4};
try{Object.assign(RAIDCFG,JSON.parse(localStorage.getItem(RAID_KEY)||'{}'));}catch(e){}
function raidSave(){try{localStorage.setItem(RAID_KEY,JSON.stringify(RAIDCFG));}catch(e){}}
const AFFIX={fast:{n:'Fast',th:'ว่องไว',c:'#8dffe8'},vamp:{n:'Vampiric',th:'ดูดเลือด',c:'#ff4f6a'},reflect:{n:'Reflect',th:'สะท้อน',c:'#ffd36b'},armored:{n:'Armored',th:'เกราะหนา',c:'#9fb4d8'},frenzy:{n:'Frenzied',th:'คลั่ง',c:'#ff8a3d'}};
function promoteElite(e){if(e.eliteX||e.m.boss)return e;e.eliteX=1;e.m=Object.assign({},e.m,{elite:1,n:'[Elite] '+e.m.n});e.sz*=2;e.maxHp=e.hp=Math.round(e.maxHp*5);e.atk*=1.5;e.def*=1.4;
  const keys=Object.keys(AFFIX),n=rng()<.4?2:1;e.affix=[];while(e.affix.length<n){const k=pick(keys);if(!e.affix.includes(k))e.affix.push(k);}
  if(e.affix.includes('fast'))e.sp*=1.55;if(e.affix.includes('armored'))e.def*=2.2;if(e.affix.includes('frenzy'))e.atk*=1.35;return e;}
function spawnEnemy(initial){const n0=enemies.length;spawnEnemy_v1(initial);const Z=ZONES[G.zone],ch=RAIDCFG.eliteChance*(Z.tier===2?2:Z.tier===1?1.5:1)/100;
  for(let i=n0;i<enemies.length;i++){const e=enemies[i];if(!e.leader&&!e.m.boss&&!e.m.elite&&rng()<ch)promoteElite(e);}}
function drawEnemy(e){
  if(e.eliteX){const s=e.sz,t=time+e.ph;add();glow(e.x,e.y-s*.5,s*2.6,'#ffd36b',.28+.08*Math.sin(t*3));ctx.globalAlpha=.55;ctx.strokeStyle='#ffd36b';ctx.lineWidth=2;
    ctx.beginPath();ctx.ellipse(e.x,e.y+s*.3,s*1.1+Math.sin(t*2)*3,s*.38,0,0,TAU);ctx.stroke();norm();
    if(rng()<.25)part({x:e.x+rand(-s,s),y:e.y-rand(0,s*1.6),vx:0,vy:rand(-60,-25),life:.8,max:.8,size:rand(3,6),col:'#ffd36b',type:'star',drag:.97});}
  drawEnemy_v1(e);
  if(e.eliteX&&e.affix&&(d2(e.x,e.y,P.x,P.y)<720||e.hitT>0)){const top=e.y-e.sz*1.9-12;ctx.font='600 10px "Noto Sans Thai", system-ui';ctx.textAlign='center';ctx.shadowColor='#000';ctx.shadowBlur=4;
    ctx.fillStyle='#ffd36b';ctx.fillText(e.affix.map(k=>AFFIX[k].n).join(' · '),e.x,top-20);ctx.shadowBlur=0;}}
function hurtPlayer(raw,src){const h0=P.hp;hurtPlayer_v15(raw,src);const d=h0-P.hp;
  if(d>0&&src&&src.affix&&src.affix.includes('vamp')&&!src.dead){const h=Math.round(d*.35);src.hp=Math.min(src.maxHp,src.hp+h);textAt(src.x,src.y-src.sz*2,'+'+fmt(h),'#ff4f6a',13,{life:.7});}}
function hitEnemy(e,m,o={}){const hp0=e.hp;const r=hitEnemy_v15(e,m,o);C182.reflect(e,r,hp0,o);
  return r;}

/* ---------- 3. World Raid Bosses on a fixed wall-clock schedule ---------- */
const RK_KEY=KEYP+'raidk_v1';let RK={};try{RK=JSON.parse(localStorage.getItem(RK_KEY)||'{}')||{};}catch(e){RK={};}
function rkSave(){try{localStorage.setItem(RK_KEY,JSON.stringify(RK));}catch(e){}}
const raidMs=()=>Math.max(1,RAIDCFG.interval)*60000;
function raidSlot(){return Math.floor(nowMs()/raidMs());}
for(const z of ZORDER)if(RK[z]==null)RK[z]=raidSlot();rkSave();       // a new player meets the first bosses at the next tick
/* v121: บอสเกิดใหม่ "หลังถูกฆ่า + interval นาที" (ต่อโซน) แทนรอบนาฬิกา — RKT[z] = เวลา(ms)ที่บอสโซนนั้นจะพร้อมออก */
const RKT_KEY=KEYP+'raidt_v1';let RKT={};try{RKT=JSON.parse(localStorage.getItem(RKT_KEY)||'{}')||{};}catch(e){RKT={};}
function rktSave(){try{localStorage.setItem(RKT_KEY,JSON.stringify(RKT));}catch(e){}}
for(const z of ZORDER)if(RKT[z]==null)RKT[z]=RK[z]<raidSlot()?0:(raidSlot()+1)*raidMs();rktSave();   // ผู้เล่นเดิม: บอสที่พร้อมอยู่แล้วยังพร้อม
function raidAvail(z){return RAIDCFG.on&&nowMs()>=(RKT[z]||0);}
function raidLeft(z){return Math.max(0,(RKT[z]||0)-nowMs());}
function raidNext(){let z=null,m=1e18;for(const k of ZORDER){const l=raidLeft(k);if(l<m){m=l;z=k;}}return z;}
function raidBossName(z){return MOBS['raid_'+z].n;}
const RTELE=[],RCHESTS=[];let raidLastSlot=raidSlot(),raidPrevLeft=null,raidHudT=0;const RAV={};
function raidAlive(){return enemies.find(e=>e.raidB&&!e.dead);}
function spawnRaid(b){const zid=b+'_sanctum';if(G.zone!==zid||raidAlive())return null;const Z=ZONES[zid];
  const e=makeEnemy('raid_'+b,Z.range[1]+4,Z.w/2,Z.h/2-40);e.raidB=b;e.aggro=true;e.phase=1;e.mech=3.5;e.special=99;enemies.push(e);
  showBanner(e.m.n,'World Raid Boss ปรากฏตัว!',3);log(`⚔ ${e.m.n} ปรากฏตัวที่ ${Z.n}!`,'r');ring(e.x,e.y,20,420,1,'#ff4f6a',14);shake(12);sfx('blast');return e;}
function raidEnter(zid){RTELE.length=0;const Z=ZONES[zid];if(Z&&Z.tier===2&&raidAvail(Z.base))setTimeout(()=>{if(G.zone===zid)spawnRaid(Z.base);},900);}
function bossAI(e,dt,dP){if(e.raidB)return raidAI(e,dt,dP);bossAI_v1(e,dt,dP);}
function raidAI(e,dt,dP){
  const k=e.hp/e.maxHp,ph=k>.66?1:k>.33?2:3;
  if(ph>e.phase){e.phase=ph;showBanner(`PHASE ${ph}`,ph===3?`${e.m.n} คลั่ง! · ใช้สกิลถี่ขึ้น · เรียกลูกสมุนอีลิท`:`${e.m.n} โจมตีแรงขึ้น!`,1.8);ring(e.x,e.y,20,520,.8,'#ff4f6a',12);shake(10);sfx('blast');
    if(ph===3){const Z=ZONES[G.zone];for(let i=0;i<2;i++){const [t,l]=pick(Z.mobs),a=rand(0,TAU);const a2=makeEnemy(t,l,e.x+Math.cos(a)*180,e.y+Math.sin(a)*140);a2.aggro=true;promoteElite(a2);enemies.push(a2);}}}
  e.mech-=dt*(e.phase>=3?1.8:1);if(e.mech>0)return;e.mech=rand(3,4.4);
  const c=e.m.c,dmg=e.atk,ZD=(()=>{const Z=ZONES[G.zone]||{};return Math.hypot(Z.w||3000,Z.h||2000);})(),pool=['meteor','cleave','nova'];if(e.phase>=2)pool.push('bullets');const m=pick(pool);e.mo={k:m,t0:time,d:({meteor:1.45,cleave:1.25,nova:1.6,bullets:.7})[m]};
  if(m==='meteor'){const n=3+2*(e.phase-1);for(let i=0;i<n;i++){const a=rand(0,TAU),r=i?rand(80,320):0;RTELE.push({k:'circle',zone:G.zone,x:P.x+Math.cos(a)*r,y:P.y+Math.sin(a)*r*.7,r:115,t:1.45,max:1.45,dmg:dmg*2.2,col:c,src:e});}textAt(e.x,e.y-e.sz*2.6,'METEOR','#ff8aa0',16);}
  else if(m==='cleave'){const ang=Math.atan2(P.y-e.y,P.x-e.x);RTELE.push({k:'line',zone:G.zone,x:e.x,y:e.y,ang,len:ZD,w:140,t:1.25,max:1.25,dmg:dmg*2.6,col:c,src:e});textAt(e.x,e.y-e.sz*2.6,'CLEAVE','#ff8aa0',16);}
  else if(m==='nova'){RTELE.push({k:'ring',zone:G.zone,x:e.x,y:e.y,r0:190,r1:ZD,t:1.6,max:1.6,dmg:dmg*2.4,col:c,src:e,follow:e});textAt(e.x,e.y-e.sz*2.6,'SHOCKWAVE · เข้าใกล้บอส!','#ff8aa0',15);}
  else{{const n0=projs.length;for(let i=0;i<18;i++)enemyShoot(e,i/18*TAU+time,250);for(let i=n0;i<projs.length;i++)projs[i].life=ZD/250;}}}
function raidResolve(T){if(T.zone!==G.zone||P.dead)return;let hit=false;const dx=P.x-T.x,dy=P.y-T.y;
  if(T.k==='circle')hit=Math.hypot(dx,dy/.7)<T.r;
  else if(T.k==='line'){const u=dx*Math.cos(T.ang)+dy*Math.sin(T.ang),v=-dx*Math.sin(T.ang)+dy*Math.cos(T.ang);hit=u>0&&u<T.len&&Math.abs(v)<T.w/2;}
  else if(T.k==='ring'){const d=Math.hypot(dx,dy/.62);hit=d>T.r0&&d<T.r1;}
  if(hit)hurtPlayer(T.dmg,T.src);
  if(T.k==='circle'){ring(T.x,T.y,10,T.r,.4,T.col,10);emitThemed(T.x,T.y,{...THEMES.fire,main:T.col},18,220);}
  else if(T.k==='line'){for(let i=1;i<=6;i++)ring(T.x+Math.cos(T.ang)*T.len*i/6,T.y+Math.sin(T.ang)*T.len*i/6,6,60,.35,T.col,6);}
  else ring(T.x,T.y,T.r0,T.r1,.5,T.col,16);
  shake(hit?8:4);}
function drawRaidTele(){for(const T of RTELE){if(T.zone!==G.zone)continue;const k=1-T.t/T.max;add();ctx.fillStyle=rgba('#ff3a5a',.12+.22*k);ctx.strokeStyle=rgba('#ff5a7a',.55+.4*k);ctx.lineWidth=3;
    if(T.k==='circle'){ctx.beginPath();ctx.ellipse(T.x,T.y,T.r,T.r*.7,0,0,TAU);ctx.stroke();ctx.beginPath();ctx.ellipse(T.x,T.y,T.r*k,T.r*.7*k,0,0,TAU);ctx.fill();}
    else if(T.k==='line'){ctx.save();ctx.translate(T.x,T.y);ctx.rotate(T.ang);ctx.strokeRect(0,-T.w/2,T.len,T.w);ctx.fillRect(0,-T.w/2,T.len*k,T.w);ctx.restore();}
    else{ctx.beginPath();ctx.ellipse(T.x,T.y,T.r1,T.r1*.62,0,0,TAU);ctx.ellipse(T.x,T.y,T.r0,T.r0*.62,0,0,TAU,true);ctx.fill('evenodd');ctx.beginPath();ctx.ellipse(T.x,T.y,T.r0,T.r0*.62,0,0,TAU);ctx.stroke();
      ctx.beginPath();ctx.ellipse(T.x,T.y,T.r0+(T.r1-T.r0)*k,(T.r0+(T.r1-T.r0)*k)*.62,0,0,TAU);ctx.stroke();}
    norm();}}
function drawChest(c){const x=c.x,y=c.y,t=time;ell(x,y+8,34,10,'#000000',.4);add();glow(x,y-16,70,'#ffd36b',.35+.12*Math.sin(t*3));norm();
  const lid=c.open?Math.min(1,c.t*2):0;ctx.fillStyle='#5a3414';ctx.fillRect(x-26,y-26,52,30);ctx.fillStyle='#ffcf6b';ctx.fillRect(x-26,y-14,52,5);ctx.fillRect(x-4,y-22,8,12);
  ctx.save();ctx.translate(x,y-26);ctx.rotate(-lid*1.1);ctx.fillStyle='#7a4a1e';ctx.fillRect(-26,-12,52,12);ctx.fillStyle='#ffcf6b';ctx.fillRect(-26,-3,52,3);ctx.restore();
  if(!c.open)label(x,y+28,'Raid Chest','#ffd36b',12);}
function openChest(c){c.open=true;c.t=0;const L=c.L,b=c.base,dx=()=>c.x+rand(-70,70),dy=()=>c.y+rand(-40,50);
  dropLoot(dx(),dy(),{gold:Math.round((400+L*40)*rand(1,1.4))});
  const relic=makeWeapon(pick(WTYPES),L,rng()<.08?6:5);relic.name=`${raidBossName(b)}'s Relic`;relic.atk=Math.round(relic.atk*1.25);relic.bonus=Object.assign(relic.bonus||{},{str:6,agi:6,dex:6});dropLoot(dx(),dy(),{item:relic,rare:1});
  dropLoot(dx(),dy(),{item:rng()<.5?makeWeapon(pick(WTYPES),L,ri(4,5)):makeGear(pick(GEAR_TYPES),L,ri(4,5)),rare:1});dropLoot(dx(),dy(),{item:makeGear(pick(GEAR_TYPES),L,ri(3,4))});
  dropLoot(dx(),dy(),{item:{id:'smithGem',q:ri(2,3)},rare:1});if(rng()<.5)dropLoot(dx(),dy(),{item:{id:'smithGemUp',q:1},rare:1});
  if(ITEMS['card_raid_'+b]&&rng()<.25)dropLoot(dx(),dy(),{item:{id:'card_raid_'+b,q:1},rare:2});
  ring(c.x,c.y,10,200,.8,'#ffd36b',10);showBanner('RAID CHEST','ของรางวัลการันตีจาก World Raid',2);sfx('level');}
function killEnemy(e){const was=e.dead;killEnemy_v17(e);if(was||!e.dead)return;
  if(e.eliteX){const dm=G.dropMul||1;if(rng()<Math.min(1,.05*dm))dropLoot(e.x,e.y,{item:{id:'smithGem',q:1},rare:1});if(rng()<Math.min(1,.01*dm))dropLoot(e.x,e.y,{item:{id:'card_'+e.type,q:1},rare:2});
    if(rng()<Math.min(1,.012*dm))dropLoot(e.x,e.y,{item:{id:'smithGemUp',q:1},rare:1});dropLoot(e.x,e.y,{gold:Math.round((20+e.L*8)*rand(1,1.6))});}
  if(e.raidB){RKT[e.raidB]=nowMs()+raidMs();rktSave();RK[e.raidB]=raidSlot();rkSave();RTELE.length=0;RCHESTS.push({chest:1,zone:G.zone,x:e.x,y:e.y,L:e.L,base:e.raidB,open:false,t:0});
    showBanner('RAID CLEAR',`${e.m.n} ถูกกำจัด · เปิดหีบรางวัล`,3);log(`🏆 กำจัด ${e.m.n} สำเร็จ! บอสจะกลับมาในรอบถัดไป`,'g');}}
function fmtLeft(ms){const s=Math.max(0,Math.ceil(ms/1000)),h=Math.floor(s/3600),m=Math.floor(s%3600/60),ss=s%60;return (h?h+':'+String(m).padStart(2,'0'):m)+':'+String(ss).padStart(2,'0');}
function raidHere(){const b=ZB();return ZORDER.includes(b)?b:null;}
function raidTick(dt){
  for(let i=RTELE.length-1;i>=0;i--){const T=RTELE[i];if(T.follow&&!T.follow.dead){T.x=T.follow.x;T.y=T.follow.y;}T.t-=dt;if(T.t<=0){RTELE.splice(i,1);raidResolve(T);}}
  for(let i=RCHESTS.length-1;i>=0;i--){const c=RCHESTS[i];if(c.zone!==G.zone)continue;if(c.open){c.t+=dt;if(c.t>6)RCHESTS.splice(i,1);}else if(d2(c.x,c.y,P.x,P.y)<70)openChest(c);}
  const b=raidHere(),zz=b||raidNext(),left=zz?raidLeft(zz):0,who=b?raidBossName(b):'World Raid Bosses';
  if(RAIDCFG.on){
    if(raidPrevLeft!=null)for(const m of [5,3,1]){const th=m*60000;if(raidPrevLeft>th&&left<=th&&raidMs()>th){log(`⚠ คำเตือน: ${zz?raidBossName(zz):who} จะปรากฏใน ${m} นาที!`,'r');if(m<=3)notify(`${zz?raidBossName(zz):who} จะปรากฏใน ${m} นาที!`,true);}}
    for(const z of ZORDER){const av=raidAvail(z);if(av&&RAV[z]===false){showBanner('WORLD RAID',`${raidBossName(z)} ปรากฏที่ ${ZONES[z+'_sanctum'].n}`,3);log(`⚔ ${raidBossName(z)} ออกมาแล้ว!`,'r');
      const Z=ZONES[G.zone];if(Z.tier===2&&Z.base===z&&raidAvail(z))spawnRaid(z);}RAV[z]=av;}}
  raidPrevLeft=left;
  raidHudT-=dt;if(raidHudT>0)return;raidHudT=.25;
  const hud=$('#raidHud'),on=RAIDCFG.on&&G.state==='play';hud.hidden=!on;
  if(on){const av=b&&raidAvail(b),alive=raidAlive();hud.classList.toggle('live',!!(av||alive));
    $('#raidT').textContent=`⚔ ${fmtLeft(left)}`;
    $('#raidS').textContent=alive?`กำลังต่อสู้ · ${alive.m.n}`:av?`${who} ออกมาแล้ว — ${ZONES[b+'_sanctum'].n}`:b?`${who} · รอบถัดไป`:'World Raid รอบถัดไป';}
  const e=raidAlive(),bar=$('#raidBar');bar.hidden=!e;
  if(e){$('#raidName').textContent=e.m.n;$('#raidPhase').textContent=`Phase ${e.phase}/3 · ${Math.ceil(e.hp/e.maxHp*100)}%`;$('#raidFill').style.width=clamp(e.hp/e.maxHp*100,0,100)+'%';}}
{const _tt=thiefTick;thiefTick=function(dt){_tt(dt);raidTick(dt);};}

/* ---------- 4. Admin audit log (changelog) ---------- */
const ALOG_KEY=KEYP+'admlog_v1';
function alogGet(){try{return JSON.parse(localStorage.getItem(ALOG_KEY)||'[]')||[];}catch(e){return [];}}
function admLog(msg,cat){if(!ADMIN)return;const L=alogGet();L.unshift({t:nowMs(),m:String(msg).slice(0,200),c:cat||'misc'});if(L.length>300)L.length=300;try{localStorage.setItem(ALOG_KEY,JSON.stringify(L));}catch(e){}
  const s=$('#admSaved');if(s)s.textContent='บันทึกล่าสุด '+new Date().toLocaleTimeString('th-TH',{hour:'2-digit',minute:'2-digit'});if(G.win==='wGM'&&G.gmTab==='log')renderLogTab();}
const debounced={};function admLogD(key,msg,cat,ms){clearTimeout(debounced[key]);debounced[key]=setTimeout(()=>admLog(msg,cat),ms||1500);}
const zn=z=>(ZONES[z]&&ZONES[z].n)||z;
// wrap the existing save paths so every admin change leaves a trace
{let prev=JSON.parse(JSON.stringify(CITEMS));const _s=saveCItems;saveCItems=function(){const ok=_s();if(ok){const P0=new Map(prev.map(t=>[t.id,t])),N=new Map(CITEMS.map(t=>[t.id,t]));
    for(const [id,t] of N){if(!P0.has(id))admLog(`เพิ่มไอเทม “${t.name}”`,'item');else if(JSON.stringify(P0.get(id))!==JSON.stringify(t)){const a=P0.get(id),d=t.drop||{},s=t.shop||{};
      admLog(JSON.stringify(a.drop)!==JSON.stringify(t.drop)?`ตั้งค่าดรอป “${t.name}”: ${d.on?`เปิด ${d.rate}%${d.zone?' · '+zn(d.zone):''}`:'ปิด'}`:JSON.stringify(a.shop)!==JSON.stringify(t.shop)?`ตั้งค่าร้านค้า “${t.name}”: ${s.on?`ขาย ${fmt(s.price|0)} G`:'ไม่ขาย'}`:`แก้ไขไอเทม “${t.name}”`,'item');}}
    for(const [id,t] of P0)if(!N.has(id))admLog(`ลบไอเทม “${t.name}”`,'item');prev=JSON.parse(JSON.stringify(CITEMS));}return ok;};}
{let prev=JSON.parse(JSON.stringify(BEACONS));const _s=saveBeacons;saveBeacons=function(){_s();const P0=new Map(prev.map(b=>[b.id,b])),N=new Map(BEACONS.map(b=>[b.id,b]));
    for(const [id,b] of N){if(!P0.has(id))admLog(`เพิ่มจุดวาร์ป “${b.label||'→ '+zn(b.to)}” ใน ${zn(b.zone)} → ${zn(b.to)} (Lv ${b.minLv||1}+)`,'map');else if(JSON.stringify(P0.get(id))!==JSON.stringify(b))admLog(`แก้ไขจุดวาร์ปใน ${zn(b.zone)} → ${zn(b.to)}`,'map');}
    for(const [id,b] of P0)if(!N.has(id))admLog(`ลบจุดวาร์ปใน ${zn(b.zone)}`,'map');prev=JSON.parse(JSON.stringify(BEACONS));};}
{const _s=setGameTitle;setGameTitle=function(t){const a=gameTitle();_s(t);const b=gameTitle();if(a!==b)admLog(`เปลี่ยนชื่อเกม “${a}” → “${b}”`,'misc');};}
{const _s=saveLayout;saveLayout=function(){_s();admLog(`บันทึกเลย์เอาต์แมพ ${zn(G.zone)} (${PROPS.length} ชิ้น)`,'map');};}
{const _s=audSave;audSave=function(){_s();admLogD('aud','ปรับการตั้งค่าเสียง / เพลง / เสียงฟัน','audio',2500);};}
{const _s=saveIntro;saveIntro=function(){_s();admLogD('intro',`ตั้งค่าฉากเปิด (${INTRO.on?'เปิด':'ปิด'}${INTRO.url?' · ลิงก์วิดีโอ':''})`,'misc');};}
{const _s=sprSave;sprSave=function(){const r=_s.apply(this,arguments);admLogD('spr',`อัปเดต Sprite Replacer (${Object.keys(SPR_OVR).length} ภาพ)`,'map');return r;};}
{const _s=saveHairFit;saveHairFit=function(){_s();admLogD('hf','ปรับ Hair Fit','misc',2500);};}
{const _p=publishWorld;publishWorld=async function(){admLog('เผยแพร่ข้อมูลกลางให้ผู้เล่นทุกคน','pub');await _p();if(PUB.bad)admLog('เผยแพร่ไม่สำเร็จ: '+PUB.msg,'pub');};}
function aiLogInit(){for(const [id,n] of [['aiAtk','ระยะโจมตีมอนสเตอร์'],['aiAggro','ระยะตรวจจับ (Aggro)'],['aiDen','ความหนาแน่นมอนสเตอร์']]){const el=$('#'+id);if(el)el.addEventListener('change',()=>admLog(`Monster AI: ${n} → ${el.value}`,'raid'));}}

/* ---------- 5. Admin: Save All, changelog tab, backup/import, raid settings ---------- */
function saveAllAdmin(){const done=[];
  const tryS=(n,f)=>{try{f();done.push(n);}catch(e){}};
  tryS('ไอเทม',()=>saveCItems());tryS('จุดวาร์ป',()=>saveBeacons());tryS('เสียง',()=>audSave());tryS('ฉากเปิด',()=>saveIntro());tryS('Hair Fit',()=>saveHairFit());
  tryS('Sprite',()=>sprSave());if(ED.dirty)tryS('แมพ',()=>saveLayout());tryS('World Raid',()=>raidSave());tryS('เซฟผู้เล่น',()=>saveGame());
  admLog(`บันทึกทั้งหมด: ${done.join(', ')}`,'save');notify(WORLD.v||HOSTED?'บันทึกทั้งหมดแล้ว · กด “เผยแพร่ให้ผู้เล่นทุกคน” เพื่อส่งถึงผู้เล่น':'บันทึกทั้งหมดแล้ว',false);
  if(G.win==='wGM'&&(G.gmTab==='pub'||G.gmTab==='log'))renderGM();}
const LOG_CATS={all:'ทั้งหมด',item:'ไอเทม/ดรอป',map:'แมพ/วาร์ป/Sprite',audio:'เสียง',raid:'Raid/AI',pub:'เผยแพร่',save:'บันทึก',misc:'อื่น ๆ'};G.logCat='all';let logClearArm=0;
function renderLogTab(){const b=$('#gmBody'),L=alogGet().filter(x=>G.logCat==='all'||x.c===G.logCat);
  b.innerHTML=`<h3 class="sec" style="margin-top:0">ประวัติการแก้ไข (Changelog)</h3>
   <p class="aihint">บันทึกทุกครั้งที่แอดมินเพิ่ม/แก้ไข/ลบ ไอเทม ดรอป ร้านค้า จุดวาร์ป แมพ Sprite เสียง Monster AI World Raid และการเผยแพร่ · ประวัตินี้ถูกเผยแพร่ไปพร้อมข้อมูลกลางเพื่อให้แอดมินคนอื่นเห็นด้วย · เก็บล่าสุด 300 รายการ</p>
   <div class="row" style="align-items:center;margin-bottom:8px"><select class="txt" id="logCat" style="width:auto">${Object.entries(LOG_CATS).map(([k,n])=>`<option value="${k}" ${G.logCat===k?'selected':''}>${n}</option>`).join('')}</select><span class="muted" style="font-size:12px">${L.length} รายการ</span><button class="btn sm" id="logClear" style="margin-left:auto">ล้างประวัติ</button></div>
   <div>${L.map(x=>`<div class="logrow"><time>${new Date(x.t).toLocaleString('th-TH',{dateStyle:'short',timeStyle:'short'})}</time><span class="lc ${x.c}">${LOG_CATS[x.c]||x.c}</span><span>${escH(x.m)}</span></div>`).join('')||'<p class="muted">ยังไม่มีประวัติ</p>'}</div>`;}
function exportConfig(){return JSON.stringify({format:'realm-config',v:1,at:new Date().toISOString(),title:gameTitle(),ls:draftLS(),ai:{atk:G.atkScale,aggro:G.aggroR,den:G.density}},null,1);}
function renderBackupTab(){const b=$('#gmBody');
  b.innerHTML=`<div class="bk"><h3 class="sec" style="margin-top:0">สำรอง / นำเข้า Config (JSON)</h3>
   <p class="aihint">ส่งออกข้อมูลแอดมินทั้งหมด (ไอเทม ดรอป ร้านค้า จุดวาร์ป แมพ Sprite การตั้งค่าเสียง ฉากเปิด ชื่อเกม World Raid Monster AI ประวัติ) เป็นไฟล์ JSON เพื่อเก็บสำรองหรือย้ายไปเครื่องอื่น · ไฟล์เสียง/วิดีโอที่อัปโหลดไม่รวมในไฟล์นี้ (ใช้ปุ่มเผยแพร่เพื่อส่งไฟล์เหล่านั้นถึงผู้เล่น)</p>
   <div class="row"><button class="btn gold" id="bkDl">ดาวน์โหลด JSON</button><button class="btn" id="bkCopy">คัดลอก</button></div>
   <textarea id="bkOut" readonly aria-label="Config JSON">${escH(exportConfig())}</textarea>
   <h3 class="sec">นำเข้า</h3><p class="aihint">วาง JSON หรือเลือกไฟล์ แล้วกดนำเข้า — ร่างในเครื่องนี้จะถูกแทนที่และหน้าเกมจะรีโหลด</p>
   <div class="row"><label class="btn" for="bkFile">เลือกไฟล์ .json</label><input type="file" id="bkFile" accept="application/json,.json" hidden><button class="btn gold" id="bkImp">นำเข้า</button></div>
   <textarea id="bkIn" placeholder='{"format":"realm-config", ...}' aria-label="วาง JSON เพื่อนำเข้า"></textarea><p class="pubmsg" id="bkMsg" hidden></p></div>`;}
function importConfig(txt){let o;try{o=JSON.parse(txt);}catch(e){return 'อ่าน JSON ไม่ได้';}if(!o||o.format!=='realm-config'||!o.ls)return 'ไฟล์นี้ไม่ใช่ config ของเกม';
  try{for(const k of WORLD_KEYS){if(!(k in o.ls))continue;const v=o.ls[k];if(v==null)localStorage.removeItem(KEYP+k);else localStorage.setItem(KEYP+k,String(v));}}catch(e){return 'บันทึกลงเบราว์เซอร์ไม่สำเร็จ (พื้นที่เต็ม?)';}
  if(o.ai){G.atkScale=o.ai.atk||G.atkScale;G.aggroR=o.ai.aggro||G.aggroR;G.density=o.ai.den||G.density;}admLog(`นำเข้า config (${o.at||'ไม่ทราบวันที่'})`,'save');try{saveGame();}catch(e){}setTimeout(()=>location.reload(),600);return null;}
function renderRaidTab(){const b=$('#gmBody'),left=raidLeft(raidNext());
  b.innerHTML=`<h3 class="sec" style="margin-top:0">World Raid Boss &amp; Elite</h3>
   <p class="aihint">บอสประจำแต่ละโซนอยู่ในวิหารชั้นในสุด (พื้นที่ย่อยที่ 2) เกิดใหม่หลังถูกฆ่าครบตามเวลาที่ตั้ง (นับแยกต่อโซน) · มีแจ้งเตือน 5 / 3 / 1 นาทีก่อนออก · 3 เฟส พร้อมท่าโจมตีวงกว้างที่มีสัญญาณเตือน · ล้มแล้วได้หีบรางวัลการันตี</p>
   <div class="gmform" style="grid-template-columns:repeat(3,1fr);max-width:620px">
    <label class="chk"><input type="checkbox" id="rc_on" ${RAIDCFG.on?'checked':''}> เปิดระบบ World Raid</label>
    <label>รอบเกิดบอส (นาที)<input id="rc_int" class="txt" type="number" min="5" max="240" value="${RAIDCFG.interval}"></label>
    <label>โอกาสเกิดอีลิท (%)<input id="rc_el" class="txt" type="number" min="0" max="30" step="0.5" value="${RAIDCFG.eliteChance}"></label></div>
   <p class="muted" style="font-size:12px">รอบถัดไปในอีก ${fmtLeft(left)} · อีลิทในพื้นที่ย่อยชั้นลึก ×1.5 และวิหาร ×2 · อีลิท: ขนาด ×2, HP ×5, ออร่าทอง, ค่าพิเศษสุ่ม (Fast, Vampiric, Reflect, Armored, Frenzied), ดรอป Smithing Gem 5% และการ์ด 1%</p>
   <table class="dtab rtab"><thead><tr><th>โซน</th><th>World Raid Boss</th><th>วิหาร</th><th>สถานะ (เครื่องนี้)</th><th></th></tr></thead><tbody>${ZORDER.map(z=>`<tr><td>${ZONES[z].n}</td><td><b>${raidBossName(z)}</b></td><td>${ZONES[z+'_sanctum'].n} · Lv ${ZONES[z+'_sanctum'].range[0]}+</td><td class="${raidAvail(z)?'ok':'wait'}">${raidAvail(z)?'ออกมาแล้ว':'รอรอบถัดไป'}</td><td><button class="btn sm" data-rgo="${z}">วาร์ปไปวิหาร</button><button class="btn sm" data-rnow="${z}">เรียกบอสตอนนี้ (ทดสอบ)</button></td></tr>`).join('')}</tbody></table>`;}
{const _r=renderGM;renderGM=function(){const t=G.gmTab;if(t==='log'||t==='backup'||t==='raid'){$('#gmTabs').querySelectorAll('[data-gmt]').forEach(x=>x.classList.toggle('on',x.dataset.gmt===t));$('#gmBody').hidden=false;for(const k of ADM_STATIC){const p=$('#admP_'+k);if(p)p.hidden=true;}
    return t==='log'?renderLogTab():t==='backup'?renderBackupTab():renderRaidTab();}return _r();};}
function initV17UI(){initFashionUI();aiLogInit();
  $('#admSaveAll').addEventListener('click',saveAllAdmin);
  const body=$('#gmBody');
  body.addEventListener('change',async e=>{const t=e.target;
    if(t.id==='logCat'){G.logCat=t.value;renderLogTab();return;}
    if(t.id==='bkFile'&&t.files[0]){$('#bkIn').value=await t.files[0].text();t.value='';return;}
    if(t.id==='rc_on'||t.id==='rc_int'||t.id==='rc_el'){const a={...RAIDCFG};RAIDCFG.on=$('#rc_on').checked;RAIDCFG.interval=clamp(Math.round(+$('#rc_int').value||30),5,240);RAIDCFG.eliteChance=clamp(+$('#rc_el').value||0,0,30);raidSave();raidLastSlot=raidSlot();raidPrevLeft=null;
      if(a.on!==RAIDCFG.on)admLog(`World Raid: ${RAIDCFG.on?'เปิด':'ปิด'}ระบบ`,'raid');if(a.interval!==RAIDCFG.interval)admLog(`ปรับรอบเกิด World Raid Boss ${a.interval} → ${RAIDCFG.interval} นาที`,'raid');if(a.eliteChance!==RAIDCFG.eliteChance)admLog(`ปรับโอกาสเกิดอีลิท ${a.eliteChance}% → ${RAIDCFG.eliteChance}%`,'raid');renderRaidTab();}});
  body.addEventListener('click',e=>{const t=e.target,id=t.id;
    if(id==='logClear'){const now=performance.now();if(now-logClearArm<4000){try{localStorage.setItem(ALOG_KEY,'[]');}catch(_){}admLog('ล้างประวัติการแก้ไข','misc');}else{logClearArm=now;notify('กด “ล้างประวัติ” อีกครั้งภายใน 4 วินาทีเพื่อยืนยัน');}return;}
    if(id==='bkCopy'){const ta=$('#bkOut');ta.select();try{navigator.clipboard.writeText(ta.value).then(()=>notify('คัดลอกแล้ว',false),()=>{document.execCommand('copy');notify('คัดลอกแล้ว',false);});}catch(_){document.execCommand('copy');}return;}
    if(id==='bkDl'){(async()=>{const name=`realm-config-${new Date().toISOString().slice(0,10)}.json`,m=$('#bkMsg');const say=(t,bad)=>{m.hidden=false;m.className='pubmsg'+(bad?' bad':'');m.textContent=t;};
      const dl=HOSTED?await window.claude.use('downloads'):null;
      if(!dl){say('ดาวน์โหลดไฟล์ไม่ได้ในมุมมองนี้ — ใช้ปุ่ม “คัดลอก” แล้ววางเก็บไว้แทน',true);return;}
      try{await dl.save({filename:name,data:new Blob([exportConfig()],{type:'application/json'})});admLog('ส่งออก config JSON','save');say('บันทึกไฟล์ '+name+' แล้ว');}
      catch(err){const c=err&&err.code;say(c==='declined'?'ยกเลิกการดาวน์โหลด':c==='rate_limited'?'มีหน้าต่างยืนยันเปิดอยู่ ลองใหม่อีกครั้ง':'ดาวน์โหลดไม่ได้ — ใช้ปุ่ม “คัดลอก” แทน',c!=='declined');}})();return;}
    if(id==='bkImp'){const err=importConfig($('#bkIn').value);const m=$('#bkMsg');m.hidden=false;m.className='pubmsg'+(err?' bad':'');m.textContent=err||'นำเข้าแล้ว — กำลังรีโหลด…';return;}
    const g=t.closest('[data-rgo]');if(g){closeWin();travel(g.dataset.rgo+'_sanctum','gate');return;}
    const n=t.closest('[data-rnow]');if(n){const z=n.dataset.rnow;RKT[z]=0;rktSave();RK[z]=-1;rkSave();admLog(`เรียก ${raidBossName(z)} ทันที (ทดสอบ)`,'raid');if(G.zone===z+'_sanctum')spawnRaid(z);else notify('บอสพร้อมแล้ว — วาร์ปไปวิหารเพื่อพบบอส',false);renderRaidTab();}});}
/* =====================================================================
   v18 — 7-grade items · refine auras (+7 grade aura, +10 intense aura)
         · 4-piece armor set aura · lighter prop density on the smaller maps
   ===================================================================== */

/* ---------- 1. saves made with the old 4-grade table move to the new 7 grades ---------- */
const RAR_MAP={0:0,1:2,2:3,3:5},RAR_KEY=KEYP+'rar7';
function migRar(it){if(!it||!(it.kind==='wpn'||it.kind==='eq')||it._r7)return;const o=it.rar|0;it.rar=RAR_MAP[o]??o;it._r7=1;
  if(typeof it.name==='string'&&o===1)it.name=it.name.replace(/^Fine /,'Rare ');}
function migrateRarities(){for(const it of P.inv)migRar(it);for(const k in P.equip)migRar(P.equip[k]);migRar(P.weapon);for(const k in FASH.slots)migRar(FASH.slots[k]);saveFash();}
(function(){try{if(localStorage.getItem(RAR_KEY))return;let ch=false;for(const t of CITEMS){if(t.rar!=null&&!t._r7){t.rar=RAR_MAP[t.rar|0]??t.rar;t._r7=1;ch=true;}}if(ch)localStorage.setItem(CITEM_KEY,JSON.stringify(CITEMS));}catch(e){}})();
{const _s=startGame_v5;startGame_v5=function(cont){_s(cont);try{if(!localStorage.getItem(RAR_KEY)){if(cont)migrateRarities();localStorage.setItem(RAR_KEY,'1');saveGame();}}catch(e){}};}
// freshly made items are already on the new table
{const _w=makeWeapon;makeWeapon=function(){const it=_w.apply(this,arguments);it._r7=1;return it;};const _g=makeGear;makeGear=function(){const it=_g.apply(this,arguments);it._r7=1;return it;};}
{const _tf=tipFor;tipFor=function(it){let h=_tf(it);if(it&&(it.kind==='wpn'||it.kind==='eq')&&RARITY[it.rar]){const R=RARITY[it.rar];h=h.replace('</b>',`</b> <span class="gtag g${it.rar}">${R.g}</span>`);}return h;};}

/* ---------- 2. refine auras ---------- */
function auraCol(rar,ph){return rarCol(rar,ph);}
function drawGlowFX(x,y0,wx,wy,WA){
  const t=time,w=P.weapon;add();
  // weapon: +1…+6 plain, +7…+9 aura in the grade colour, +10 intense aura
  if(w&&w.t!=='fist'&&FASH.vis.weapon!==false&&typeof wAuraDraw==='function'&&wAuraDraw(wx,wy,WA,w)){}
  else if(w&&w.t!=='fist'&&FASH.vis.weapon!==false&&(w.refine||0)>=7){
    const r=w.refine,hi=r>=10,L=(WLEN[w.t]||30)*((WSCALE[w.t]||.8)/.8)*(w.img?(xfOf(w).sc||1):1),n=hi?7:5;
    for(let i=0;i<n;i++){const d=L*(i+.5)/n,px=wx+Math.cos(WA)*d,py=wy+Math.sin(WA)*d,c=auraCol(w.rar,i*40),pulse=.75+.25*Math.sin(t*(hi?9:6)+i);
      glow(px,py,(hi?15:10)*pulse,c,hi?.62:.38);if(hi)glow(px,py,4.5,'#ffffff',.32*pulse);}
    if(hi){const tip=[wx+Math.cos(WA)*L,wy+Math.sin(WA)*L];glow(tip[0],tip[1],22+6*Math.sin(t*7),auraCol(w.rar,200),.5);}
    const pr=hi?.9:.3;if(rng()<pr){const d=rand(0,L);part({x:wx+Math.cos(WA)*d,y:wy+Math.sin(WA)*d,vx:rand(-25,25),vy:rand(hi?-120:-60,-20),life:hi?.8:.55,max:hi?.8:.55,size:rand(hi?2:1.5,hi?4.5:3),col:auraCol(w.rar,rand(0,360)),type:hi&&rng()<.5?'flame':'spark',drag:.95});}}
  // armor set: helmet + armor + garment + shoes, all the same grade, all at least +7
  const S=setAura();
  if(S&&S.min>=(typeof a10Style==='function'&&a10Style()===6?5:10)&&typeof aura10Front==='function'&&aura10Front(x,y0,S)){}
  else if(S&&S.min>=7){const hi=S.min>=10,c=i=>auraCol(S.rar,i*60);
    ctx.globalAlpha=hi?.75:.5;ctx.strokeStyle=c(0);ctx.lineWidth=hi?2.5:1.6;ctx.beginPath();ctx.ellipse(x,y0+9,24+Math.sin(t*3)*2,8,0,0,TAU);ctx.stroke();
    if(hi){ctx.globalAlpha=.45;ctx.strokeStyle=c(2);ctx.beginPath();ctx.ellipse(x,y0+9,34+Math.sin(t*2)*3,11,0,0,TAU);ctx.stroke();
      for(let i=0;i<6;i++){const a=t*1.2+i*TAU/6;glow(x+Math.cos(a)*34,y0+9+Math.sin(a)*11,6,c(i),.8);}
      glow(x,y0-14,40+Math.sin(t*3)*5,c(1),.12);}
    const m=hi?5:3;for(let i=0;i<m;i++){const a=t*1.6+i*TAU/m,rise=(t*(hi?42:30)+i*17)%46;glow(x+Math.cos(a)*20,y0+4-rise+Math.sin(a)*6,hi?6:4.5,c(i),(hi?.9:.6)*(1-rise/46));}
    if(rng()<(hi?.6:.18))part({x:x+rand(-18,18),y:y0+rand(-30,6),vx:rand(-10,10),vy:rand(-70,-30),life:1,max:1,size:rand(2,hi?4.5:3),col:c(rand(0,6)|0),type:'star',drag:.97});}
  norm();}
const SET_SLOTS=['headTop','armor','garment','shoes'];
function setAura(){if(!P||!P.equip)return null;let rar=null,min=99;for(const s of SET_SLOTS){const it=P.equip[s];if(!it)return null;if(rar==null)rar=it.rar;else if(it.rar!==rar)return null;min=Math.min(min,it.refine||0);}return min>=5?{rar,min}:null;}
function setProgress(){const it0=P.equip.armor||P.equip.headTop;const out=SET_SLOTS.map(s=>P.equip[s]);const rar=it0?it0.rar:null;
  const same=out.filter(it=>it&&it.rar===rar).length,min=Math.min(...out.map(it=>it?it.refine||0:0));return {rar,same,min};}
// Character window: show set status in the Profile block
{const _r=renderInv;renderInv=function(){_r();const prof=$('#invBody .prof');if(!prof||!P)return;const S=setAura(),p=setProgress(),R=RARITY[p.rar]||RARITY[0];
  const txt=S?`${RARITY[S.rar].g} +${S.min} ${S.min>=9?'✦✦':S.min>=7?'✦':'◆'}`:`${p.same}/4 ${R.g} · ต่ำสุด +${p.min}`;
  prof.insertAdjacentHTML('beforeend',`<div class="kv" title="หมวกบน + เกราะ + ผ้าคลุม + รองเท้า เกรดเดียวกัน ตีบวกครบ +7 = ออร่าชุด · +10 = ออร่าเข้ม"><span>ออร่าชุด</span><b style="color:${S?rarCol(S.rar):'var(--muted)'}">${txt}</b></div>`);};}

/* ---------- 3. lighter prop density on the smaller maps ---------- */
const KEEP_ALL=new Set(['hut','torch','waterfall','oasis','tent','crystalLamp','streetlight','ruinArch']);
const PROP_KEEP={jungleTree:.16,ancientTree:.25,pine:.18,palm:.3,deadTree:.2,bush:.22,vines:.2,mushroom:.3,snowdrift:.3,seaweed:.2,coral:.22,lavaPool:.25,bubbleVent:.5,iceCrystal:.28,snowman:.35,mossRock:.22,boulder:.22,sandstone:.25,obsidian:.22,seaRock:.25,ruinPillar:.3,bones:.35,cactus:.25,tumbleweed:.3,voidShard:.18,voidRift:.55};
// v20.1 · walkable world: blocking circles of natural props shrink to the trunk / core so they no longer wall off paths
for(const [k,f] of Object.entries({ancientTree:.6,jungleTree:.55,palm:.55,pine:.55,deadTree:.55,mossRock:.7,boulder:.7,sandstone:.7,obsidian:.7,voidShard:.6,seaRock:.7,snowman:.7,iceCrystal:.65,cactus:.6,bones:.6,ruinPillar:.8,lavaPool:.6,waterfall:.7,hut:.8,oasis:.7}))
  if(PROP_DEFS[k]&&PROP_DEFS[k].solid)PROP_DEFS[k].solid=PROP_DEFS[k].solid.map(o=>({...o,r:Math.round(o.r*f)}));
// v20.2 · second thinning pass: roughly half again, collision circles trimmed further
const PROP_THIN2=.55;
// admin-tunable density for generated maps (Backoffice › Map Editor), shared with players through the published world
const PROPCFG_KEY=KEYP+'propcfg_v1';let PROP_CFG={dens:1};try{PROP_CFG={dens:1,...(JSON.parse(localStorage.getItem(PROPCFG_KEY)||'null')||{})};}catch(e){}
for(const k of ['ancientTree','jungleTree','palm','pine','deadTree','mossRock','boulder','sandstone','obsidian','seaRock','iceCrystal','cactus','voidShard','lavaPool'])
  if(PROP_DEFS[k]&&PROP_DEFS[k].solid)PROP_DEFS[k].solid=PROP_DEFS[k].solid.map(o=>({...o,r:Math.max(6,Math.round(o.r*.8))}));
function genProps_v20(zid){const all=genProps_v1(zid),Z=ZONES[zid];if(zid==='capital')return all;
  let s=(Z.seed*9301+49297)%233280;const rnd=()=>(s=(s*9301+49297)%233280)/233280;
  const out=[];for(const p of all){if(Z.base&&(p.t==='hut'||p.t==='tent'))continue;if(KEEP_ALL.has(p.t)){out.push(p);continue;}if(rnd()<(PROP_KEEP[p.t]??.5)*PROP_THIN2*(PROP_CFG.dens??1))out.push(p);}
  // never park a big prop right on a gate, the waystone or a sub-zone portal
  const clear=[...GATES.map(g=>[g.x,g.y]),...(Z.way&&!Z.base?[Z.way]:[]),...(Z.subPos?[Z.subPos]:[])];
  return out.filter(p=>!clear.some(([x,y])=>d2(p.x,p.y,x,y)<150));}

/* v20.3 · layouts saved in the Map Editor before the maps shrank kept every prop, so they became ~4× denser.
   Thin every saved zone layout once with the same rules as the generated maps. */
function thinLayout(zid,arr){const Z=ZONES[zid];if(!Z||!Array.isArray(arr))return arr;
  let s=((Z.seed||7)*7919+13)%233280;const rnd=()=>(s=(s*9301+49297)%233280)/233280;
  const out=[];for(const p of arr){if(!PROP_DEFS[p.t]){out.push(p);continue;}if(KEEP_ALL.has(p.t)||LANDMARK_T.has(p.t)){out.push(p);continue;}if(rnd()<(PROP_KEEP[p.t]??.5)*PROP_THIN2)out.push(p);}
  const clear=[...(typeof gatesFor==='function'?gatesFor(zid):[]).map(g=>[g.x,g.y]),...(Z.way&&!Z.base?[Z.way]:[]),...(Z.subPos?[Z.subPos]:[])];
  return out.filter(p=>KEEP_ALL.has(p.t)||!clear.some(([x,y])=>d2(p.x,p.y,x,y)<150));}
const LANDMARK_T=new Set(['volcano','peak','fortKeep','pyramid','darkCastle','treehouse','foundry','voidVortex','skull','stall']);
(function(){const F=KEYP+'propthin_v3';try{if(localStorage.getItem(F))return;
  const pr=JSON.parse(localStorage.getItem(KEYP+'props_v1')||'null');
  if(pr&&typeof pr==='object'&&!pr._v){for(const z in pr)if(z!=='capital'&&Array.isArray(pr[z]))pr[z]=thinLayout(z,pr[z]);pr._v=3;localStorage.setItem(KEYP+'props_v1',JSON.stringify(pr));}
  localStorage.setItem(F,'1');}catch(e){}})();
/* =====================================================================
   v19 — Costume system (ชุดแฟชั่น)
   · costumes are their own item kind ('fash'): no stats, worn only in fashion slots
   · 35 built-in costumes (5 per slot) drawn as pixel art, sold by Madame Celeste
   · admin PNG costumes with front / side / back views, fitted to the 3D rig at any angle
   · NPCs use the player's hero model; admins style their face, hair, clothes and costumes
   ===================================================================== */

/* ---------- 1. slot geometry (hero-pixel units, 1 unit = one pixel of the hero sprite) ---------- */
const CSLOT={
  headTop:{w:22,h:18,ax:11,ay:14,j:'head',oy:-1.2,sq:.78,side:1,label:'หมวกบน'},
  headMid:{w:16,h:7,ax:8,ay:3.5,j:'head',oy:-.3,sq:.62,side:1.8,noBack:1,label:'หมวกกลาง'},
  headLow:{w:14,h:9,ax:7,ay:2,j:'head',oy:2.7,sq:.62,side:1.8,noBack:1,label:'หมวกล่าง'},
  armor:{w:15,h:17,ax:7.5,ay:.5,j:'neck',oy:0,sq:.72,side:0,label:'ชุด'},
  garment:{w:26,h:21,ax:13,ay:1,j:'neck',oy:.4,sq:.42,side:-3.2,behind:1,label:'ผ้าคลุม/ปีก'},
  shield:{w:12,h:13,ax:6,ay:6.5,j:'handL',oy:0,sq:.55,side:0,label:'โล่'},
  shoes:{w:6,h:4,ax:3,ay:2.6,j:'feet',oy:0,sq:.85,side:.6,label:'รองเท้า'}};
const CSLOT_ORDER=['headTop','headMid','headLow','armor','garment','shield','shoes'];

/* ---------- 2. built-in pixel-art painters ---------- */
function pxCanvas(w,h){const c=document.createElement('canvas');c.width=w;c.height=h;return c;}
function outline(c,col){const g=c.getContext('2d'),w=c.width,h=c.height,d=g.getImageData(0,0,w,h),s=d.data,o=new Uint8ClampedArray(s);const [r,gg,b]=hex2rgb(col);
  for(let y=0;y<h;y++)for(let x=0;x<w;x++){const i=(y*w+x)*4;if(s[i+3]>40)continue;let n=false;for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]){const X=x+dx,Y=y+dy;if(X<0||Y<0||X>=w||Y>=h)continue;if(s[(Y*w+X)*4+3]>120){n=true;break;}}
    if(n){o[i]=r;o[i+1]=gg;o[i+2]=b;o[i+3]=235;}}
  d.data.set(o);g.putImageData(d,0,0);return c;}
function paint(slot,fn,ol){const G=CSLOT[slot],c=pxCanvas(G.w,G.h),g=c.getContext('2d');
  const R=(x,y,w,h,col)=>{g.fillStyle=col;g.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h));};
  const E=(cx,cy,rx,ry,col)=>{g.fillStyle=col;for(let y=Math.floor(cy-ry);y<=Math.ceil(cy+ry);y++)for(let x=Math.floor(cx-rx);x<=Math.ceil(cx+rx);x++){const dx=(x+.5-cx)/rx,dy=(y+.5-cy)/ry;if(dx*dx+dy*dy<=1)g.fillRect(x,y,1,1);}};
  const T=(pts,col)=>{g.fillStyle=col;g.beginPath();g.moveTo(pts[0][0],pts[0][1]);for(const p of pts.slice(1))g.lineTo(p[0],p[1]);g.closePath();g.fill();};
  const Px=(x,y,col)=>{g.fillStyle=col;g.fillRect(x,y,1,1);};
  g.imageSmoothingEnabled=false;fn({g,R,E,T,Px,w:G.w,h:G.h});
  // snap anti-aliased polygon edges to hard pixels
  const d=g.getImageData(0,0,G.w,G.h),s=d.data;for(let i=3;i<s.length;i+=4)s[i]=s[i]>110?255:0;g.putImageData(d,0,0);
  return ol===false?c:outline(c,ol||'#1a0f1a');}
