  const vbox=(k,n)=>`<div class="cfv"><div class="cfimg">${CF[k]?`<img src="${CF[k]}" alt="">`:'<span class="muted">—</span>'}</div><label class="btn sm" for="cf_${k}">${n}</label><input type="file" id="cf_${k}" data-cff="${k}" accept="image/png,image/webp,image/gif,image/jpeg" hidden>${CF[k]&&k!=='f'?`<button class="btn sm" data-cfx="${k}">ลบ</button>`:''}</div>`;
