      g.strokeStyle='#3a2416';g.lineWidth=16;g.lineCap='round';g.beginPath();g.moveTo(185,470);g.quadraticCurveTo(140,466,110,476);g.moveTo(222,470);g.quadraticCurveTo(270,466,300,478);g.stroke();
