for(const c of CPROPS)if(Array.isArray(c.views)&&c.views.length>1)cpRegister(c);

/* ---------- import ---------- */
async function edImportMulti(target){if(PV8.busy)return;const f=(await pickFiles('image/png,image/jpeg,image/webp,image/gif',false))[0];if(!f)return;PV8.busy=true;
  try{const r=await imageToPropMulti(f);let c=target;
    if(c){const old={views:c.views,map8:c.map8,src:c.src,iw:c.iw,ih:c.ih};Object.assign(c,{views:r.views,map8:r.map8,src:r.views[0],iw:r.iw,ih:r.ih});
      if(!saveCProps()){Object.assign(c,old);return;}}
    else{c={id:nowMs().toString(36)+rng().toString(36).slice(2,6),n:r.name,src:r.views[0],views:r.views,map8:r.map8,iw:r.iw,ih:r.ih,size:Math.min(300,Math.max(80,Math.round(Math.max(r.iw,r.ih)*.6))),col:.25,shadow:true,ground:false};
      CPROPS.push(c);if(!saveCProps()){CPROPS.pop();return;}}
    cpRegister(c);admLog(`นำเข้าพร็อพหลายมุม “${c.n}” (${r.nEff} มุม)`,'map');
    ED.cat='custom';ED.pick=cpKey(c);ED.tool='place';ED.rand=false;renderEditor();
    edStatus(`ได้ภาพ ${r.n} มุม (${r.cols}×${r.rows})${r.nEff!==r.n?` · สร้างเพิ่มเป็น ${r.nEff} มุม`:''} — คลิกบนแมพเพื่อวาง แล้วใช้แถบ “หมุน” หันพร็อพ`);}
  catch(e){notify(e==='empty'?'ไม่พบรูปในไฟล์ — ลองปิด “ลบพื้นหลัง” หรือเลือกจำนวนมุมเอง':'อ่านไฟล์ไม่ได้ — รองรับ PNG / JPG / WebP');}
  finally{PV8.busy=false;}}

