function mirrorIoU(a,b,N=24){let I=0,U=0;for(let j=0;j<N;j++)for(let i=0;i<N;i++){const p=a[j*N+i],q=b[j*N+(N-1-i)];if(p&&q)I++;if(p||q)U++;}return U?I/U:0;}
