    if(t.id==='vbAdd'){const ev=$('#vbEv').value,fxid=$('#vbFx').value;if(!fxid)return;let key=ev;if(ev.startsWith('skill-')){const sk=$('#vbSk').value;if(!sk){notify('เลือกสกิลก่อน');return;}key='skill:'+sk+':'+ev.slice(6);}
      VFXL.map[key]=fxid;VUI.vid=fxid;vfxlSave();try{admLog(`ผูกเอฟเฟกต์ ${vbLabel(key)}`,'item');}catch(_){}renderVfxTab();return;}
