{const _r=renderGM;renderGM=function(){if(G.gmTab==='vfx'){$('#gmTabs').querySelectorAll('[data-gmt]').forEach(x=>x.classList.toggle('on',x.dataset.gmt==='vfx'));$('#gmBody').hidden=false;for(const k of ADM_STATIC){const p=$('#admP_'+k);if(p)p.hidden=true;}return renderVfxTab();}return _r();};}
