{const _g=gfxCap;gfxCap=function(){const c=_g();return RES_CAP>0?Math.min(c,RES_CAP):c;};}
function stuckKill(){for(const id in P.buffs)if(P.buffs[id]&&P.buffs[id].revive)delete P.buffs[id];P.invT=0;P.dash=null;log('ตัวละครติดอยู่ — กดตายเพื่อกลับเมืองหลวง','r');playerDeath();}

/* ---------- 2. character slots ---------- */
const CH_KEY=KEYP+'chars_v1',CH_N=5;
let CH={cur:-1,list:new Array(CH_N).fill(null)};
try{const s=JSON.parse(localStorage.getItem(CH_KEY)||'null');if(s&&Array.isArray(s.list)){CH.cur=s.cur??-1;for(let i=0;i<CH_N;i++)CH.list[i]=s.list[i]||null;}
  else{const sv=localStorage.getItem(SAVE_KEY);if(sv){CH.cur=0;CH.list[0]={name:'Spirit Knight',save:sv,fash:localStorage.getItem(FASH_KEY),t:nowMs()};}}}catch(e){}
function chSave(){try{localStorage.setItem(CH_KEY,JSON.stringify(CH));}catch(e){notify('พื้นที่เก็บข้อมูลเต็ม — ลบตัวละครที่ไม่ใช้');}}
function chReloadFromStore(){try{const s=JSON.parse(localStorage.getItem(CH_KEY)||'null');if(s&&Array.isArray(s.list)){CH.cur=s.cur??-1;for(let i=0;i<CH_N;i++)CH.list[i]=s.list[i]||null;}}catch(e){}try{if(typeof chRender==='function'&&document.querySelector('#chBox'))chRender();}catch(e){}}window.__chReload=chReloadFromStore;
chSave();
function chStash(){if(CH.cur<0||!CH.list[CH.cur])return;try{if(P&&!P.dead&&G.state==='play')saveGame();CH.list[CH.cur].save=localStorage.getItem(SAVE_KEY);CH.list[CH.cur].fash=localStorage.getItem(FASH_KEY);CH.list[CH.cur].t=nowMs();}catch(e){}chSave();}
function chSaveOf(i){try{const raw=i===CH.cur?localStorage.getItem(SAVE_KEY):(CH.list[i]&&CH.list[i].save);return raw?JSON.parse(raw):null;}catch(e){return null;}}
function chActivate(i){chStash();CH.cur=i;const r=CH.list[i];
  try{if(r&&r.save)localStorage.setItem(SAVE_KEY,r.save);else localStorage.removeItem(SAVE_KEY);
    if(r&&r.fash)localStorage.setItem(FASH_KEY,r.fash);else localStorage.removeItem(FASH_KEY);}catch(e){}
  FASH=Object.assign({on:true,vis:{},fvis:{},slots:{}},(()=>{try{return JSON.parse((r&&r.fash)||'{}')||{};}catch(e){return {};}})());FASH.vis={};chSave();}
function chName(){return (CH.cur>=0&&CH.list[CH.cur]&&CH.list[CH.cur].name)||'Spirit Knight';}
function chHud(){const h=document.querySelector('.hname');if(h)h.textContent=chName();}
// keep the active slot's snapshot fresh (cheap: only a string copy)
{const _s=saveGame;saveGame=function(){const r=_s.apply(this,arguments);try{if(CH.cur>=0&&CH.list[CH.cur]){CH.list[CH.cur].save=localStorage.getItem(SAVE_KEY);CH.list[CH.cur].fash=localStorage.getItem(FASH_KEY);chSave();}}catch(e){}return r;};}

/* hero preview on any canvas */
function chDrawHero(cv,look,a,t){heroFrame(0,0,0,0,t||0,0,{pv:1,a,look:normLook(Object.assign({},look)),eq:{},wt:'fist'});
  const g=cv.getContext('2d');g.clearRect(0,0,cv.width,cv.height);g.imageSmoothingEnabled=false;const s=Math.min(cv.width/48,cv.height/52);g.drawImage(HC,0,0,48,52,(cv.width-48*s)/2,(cv.height-52*s)/2,48*s,52*s);}

const CHV={mode:'list',slot:-1,look:null,name:'',a:Math.PI/2,spin:true,raf:0,del:-1};
function chOverlay(){let o=$('#chOv');if(!o){document.body.insertAdjacentHTML('beforeend','<div class="ov" id="chOv" hidden><div class="chbox" id="chBox"></div></div>');o=$('#chOv');chWire();}return o;}
function chOpen(){const o=chOverlay();o.hidden=false;CHV.mode='list';chRender();}
function chClose(){const o=$('#chOv');if(o)o.hidden=true;cancelAnimationFrame(CHV.raf);}
function chRender(){const b=$('#chBox');if(!b)return;cancelAnimationFrame(CHV.raf);
  if(CHV.mode==='list'){
    b.innerHTML=`<h2>เลือกตัวละคร</h2><p class="muted" style="margin:0">สร้างได้สูงสุด ${CH_N} ตัว · แต่ละตัวมีเลเวล อาชีพ กระเป๋า และชุดแฟชั่นของตัวเอง</p>
      <div class="chgrid">${CH.list.map((r,i)=>{if(!r)return `<div class="chcard empty" data-chnew="${i}"><div style="font-size:34px">＋</div><div>สร้างตัวละครใหม่</div><small>ช่อง ${i+1}</small></div>`;
        const s=chSaveOf(i),p=(s&&s.P)||{},cls=CLASSES[p.cls]||CLASSES.novice,z=s&&ZONES[s.zone];
        return `<div class="chcard${i===CH.cur?' cur':''}"><canvas width="120" height="130" data-chcv="${i}"></canvas><b>${escH(r.name)}</b>
          <small>Lv ${p.lvl||1} · ${escH(cls.n)}<br>${z?escH(z.n):'Capital City'}</small>
          <div class="row"><button class="btn gold sm" data-chplay="${i}">เล่น</button><button class="btn sm" data-chdel="${i}">${CHV.del===i?'ยืนยันลบ?':'ลบ'}</button></div></div>`;}).join('')}</div>
      <div class="row" style="justify-content:flex-end;margin-top:12px"><button class="btn" id="chBack">กลับ</button></div>`;
    const cvs=[...b.querySelectorAll('[data-chcv]')];const t0=performance.now();
    const step=()=>{if($('#chOv').hidden||CHV.mode!=='list')return;const t=(performance.now()-t0)/1000;
      for(const c of cvs){const s=chSaveOf(+c.dataset.chcv);chDrawHero(c,(s&&s.P&&s.P.look)||defaultLook(),Math.PI/2-.35,t);}CHV.raf=requestAnimationFrame(step);};
    step();return;}
  // creator
  const L=CHV.look,row=(k,label)=>{const list=CAT_LIST[k];return `<div class="chrow"><span>${label}</span><button class="btn" data-chstep="${k}:-1">◀</button><output>${L[k]+1}. ${escH(list[L[k]].n)}</output><button class="btn" data-chstep="${k}:1">▶</button></div>`;};
  b.innerHTML=`<h2>สร้างตัวละคร <small class="muted" style="font-family:var(--body);font-size:13px;letter-spacing:0">ช่อง ${CHV.slot+1}</small></h2>
    <div class="chmk"><div class="chprev"><canvas id="chBig" width="240" height="260"></canvas>
      <div class="row"><button class="btn sm" id="chRotL">⟲</button><button class="btn sm${CHV.spin?' on':''}" id="chSpin">หมุนอัตโนมัติ</button><button class="btn sm" id="chRotR">⟳</button></div>
      <button class="btn" id="chRand">🎲 สุ่มทั้งหมด</button></div>
    <div><label class="chk" style="display:block;margin:0 0 8px!important">ชื่อตัวละคร <input class="txt" id="chNameIn" maxlength="16" value="${escH(CHV.name)}" placeholder="2–16 ตัวอักษร" style="margin-top:4px"></label>
      ${row('face','รูปหน้า')}${row('hair','ทรงผม')}${row('eyes','ดวงตา')}${row('brows','คิ้ว')}${row('top','เสื้อ')}${row('bottom','ท่อนล่าง')}
      <div class="setsec" style="margin-top:10px;font-family:var(--display);letter-spacing:.12em;font-size:12px;color:var(--gold)">สีผม</div>
      <div class="chsw"><button class="prism adminprism${L.hairCol==='prism'?' on':''}" data-chhc="prism" title="สีรุ้ง (แอดมิน)"></button>${HAIR_SWATCH.map(c=>`<button data-chhc="${c}" class="${L.hairCol===c?'on':''}" style="background:${c}"></button>`).join('')}<input type="color" id="chHairPick" value="${L.hairCol==='prism'?'#ff8ae0':L.hairCol}" title="กำหนดเอง"></div>
      <div class="setsec" style="font-family:var(--display);letter-spacing:.12em;font-size:12px;color:var(--gold)">สีชุด</div>
      <div class="chsw"><button class="none${!L.clothDye?' on':''}" data-chcc="" title="สีเดิม"></button>${CLOTH_SWATCH.map(c=>`<button data-chcc="${c}" class="${L.clothDye===c?'on':''}" style="background:${c}"></button>`).join('')}<input type="color" id="chClothPick" value="${L.clothDye||'#b8363a'}" title="กำหนดเอง"></div>
      <p class="hint">เปลี่ยนทรงผม เสื้อผ้า และสีได้ฟรีตอนสร้าง · ในเกมเปลี่ยนต่อได้ที่ห้องแต่งตัว Madame Celeste</p>
      <div class="row" style="justify-content:flex-end;margin-top:10px"><button class="btn" id="chCancel">ยกเลิก</button><button class="btn gold big" id="chCreate">สร้างตัวละคร</button></div></div></div>`;
  const cv=$('#chBig'),t0=performance.now();let last=t0;
  const step=()=>{if($('#chOv').hidden||CHV.mode!=='make')return;const now=performance.now();if(CHV.spin)CHV.a+=(now-last)/1000*.9;last=now;chDrawHero(cv,CHV.look,CHV.a,(now-t0)/1000);CHV.raf=requestAnimationFrame(step);};step();}
function chRandLook(){const L=defaultLook();for(const k in CAT_LIST)L[k]=Math.floor(rng()*CAT_LIST[k].length);L.hairCol=pick(HAIR_SWATCH);L.clothDye=rng()<.5?null:pick(CLOTH_SWATCH);return L;}
function chWire(){const o=$('#chOv');
  o.addEventListener('click',e=>{const t=e.target.closest('button,[data-chnew]');if(!t)return;const L=CHV.look;
    if(t.dataset.chnew!=null){CHV.mode='make';CHV.slot=+t.dataset.chnew;CHV.look=defaultLook();CHV.name='';CHV.del=-1;chRender();return;}
    if(t.dataset.chplay!=null){chPlay(+t.dataset.chplay);return;}
    if(t.dataset.chdel!=null){const i=+t.dataset.chdel;if(CHV.del!==i){CHV.del=i;chRender();setTimeout(()=>{if(CHV.del===i){CHV.del=-1;if(CHV.mode==='list'&&!$('#chOv').hidden)chRender();}},4000);return;}
      CHV.del=-1;const nm=CH.list[i]&&CH.list[i].name;CH.list[i]=null;if(CH.cur===i){CH.cur=-1;try{localStorage.removeItem(SAVE_KEY);localStorage.removeItem(FASH_KEY);}catch(_){}}chSave();notify(`ลบ “${nm}” แล้ว`,false);chRender();return;}
    if(t.id==='chBack'){chClose();return;}
    if(t.dataset.chstep){const [k,d]=t.dataset.chstep.split(':'),n=CAT_LIST[k].length;L[k]=((L[k]+ +d)%n+n)%n;chRender();return;}
    if(t.dataset.chhc!=null){if(t.dataset.chhc==='prism'&&!ADMIN)return;L.hairCol=t.dataset.chhc;chRender();return;}
    if(t.dataset.chcc!=null){L.clothDye=t.dataset.chcc||null;chRender();return;}
    if(t.id==='chRotL'){CHV.a-=Math.PI/4;return;}if(t.id==='chRotR'){CHV.a+=Math.PI/4;return;}
    if(t.id==='chSpin'){CHV.spin=!CHV.spin;t.classList.toggle('on',CHV.spin);return;}
    if(t.id==='chRand'){CHV.look=chRandLook();chRender();return;}
    if(t.id==='chCancel'){CHV.mode='list';chRender();return;}
    if(t.id==='chCreate'){const nm=String($('#chNameIn').value||'').trim();if(nm.length<2){notify('ตั้งชื่อตัวละคร 2–16 ตัวอักษร');return;}
      if(CH.list.some((r,j)=>r&&r.name.toLowerCase()===nm.toLowerCase()&&j!==CHV.slot)){notify('มีตัวละครชื่อนี้แล้ว');return;}chCreate(CHV.slot,nm,CHV.look);}});
  o.addEventListener('input',e=>{const t=e.target;if(t.id==='chNameIn'){CHV.name=t.value;return;}
    if(t.id==='chHairPick'){CHV.look.hairCol=t.value;}else if(t.id==='chClothPick'){CHV.look.clothDye=t.value;}});
  o.addEventListener('change',e=>{if(e.target.id==='chHairPick'||e.target.id==='chClothPick')chRender();});}
function chPlay(i){if(!CH.list[i])return;if(i!==CH.cur)chActivate(i);chClose();const io=INTRO.on;INTRO.on=false;try{startGame(true);}finally{INTRO.on=io;}   // intro plays only when a character is created
  if(P){P.dead=false;P.hp=P.maxHp;P.mp=P.maxMp;}$('#over').hidden=true;setTimeout(chHud,50);}
function chCreate(i,name,look){chStash();CH.list[i]={name,save:null,fash:null,t:nowMs()};CH.cur=-1;chActivate(i);chClose();
  startGame(false);const done=()=>{if(!P||G.state!=='play'){setTimeout(done,120);return;}const lk=normLook(Object.assign({},look));if(lk.hairCol==='prism'&&!ADMIN)lk.hairCol=defaultLook().hairCol;lk._v=11;P.look=lk;
    saveGame();chHud();log(`ยินดีต้อนรับ ${name}!`,'g');};done();}
// back to the character list from inside the game
function chBackToSelect(){if(G.state==='play'&&P&&!P.dead)saveGame();chStash();closeWin&&closeWin();if(G.auto)toggleAuto();
  loadZone('capital',capSpawn());G.state='title';$('#over').hidden=true;$('#title').hidden=false;chOpen();}

/* title screen: one entry point → character select (runs after the original title wiring) */
setTimeout(function(){const s=$('#bStart');if(!s)return;const n=s.cloneNode(true);n.textContent='เข้าสู่เกม · เลือกตัวละคร';s.replaceWith(n);n.addEventListener('click',chOpen);
  const c=$('#bCont');if(c){c.hidden=true;const n2=c.cloneNode(true);n2.hidden=true;c.replaceWith(n2);}
  const r=$('#bRestart');if(r){const n3=r.cloneNode(true);n3.hidden=true;n3.style.display='none';r.replaceWith(n3);}},0);   // death screen: revive only
{const _s=startGame;startGame=function(){const r=_s.apply(this,arguments);setTimeout(chHud,60);return r;};}
chHud();

/* ---------- 3. rainbow hair: admins only ---------- */
(function(){const w=$('#wWard');if(!w)return;w.addEventListener('click',e=>{const hc=e.target.closest('[data-hc="prism"]');if(hc&&!ADMIN){e.stopImmediatePropagation();e.preventDefault();}},true);})();
