/* =====================================================================
   v51 — Bag fixes & tabs
     · Fix: items whose id no longer exists (e.g. a card for a test dummy) broke the whole Character window.
       Such items are never created or picked up any more, and old ones are removed from the bag.
     · Same items always stack (cards etc.); stray duplicate stacks from old saves are merged.
     · Bag tabs: ทั้งหมด (everything except fashion) · แฟชั่น — follows the Equipment ⇄ Fashion panel.
   ===================================================================== */
function validItem(it){if(!it)return false;if(it.id)return !!ITEMS[it.id];return it.kind==='wpn'||it.kind==='eq'||it.kind==='fash';}
function invSanitize(){if(!P||!Array.isArray(P.inv))return;let bad=0;const seen={};
  for(let i=P.inv.length-1;i>=0;i--){const it=P.inv[i];if(!validItem(it)){P.inv.splice(i,1);bad++;}}
  for(let i=0;i<P.inv.length;i++){const it=P.inv[i];if(!it.id)continue;const sk=it.id+(it.st?JSON.stringify(it.st):'')+(it.br?'b':'');const f=seen[sk];if(f){f.q=(f.q||1)+(it.q||1);P.inv.splice(i,1);i--;}else seen[sk]=it;}
  if(bad)console.warn('removed',bad,'invalid items');}
{const _a=addItemTo;addItemTo=function(p,it){if(!validItem(it))return true;return _a.apply(this,arguments);};}
{const _d=dropLoot;dropLoot=function(x,y,o){if(o&&o.item&&!validItem(o.item))return;return _d.apply(this,arguments);};}
{const _i=itemIcon;itemIcon=function(it){try{return _i.apply(this,arguments);}catch(e){return _i({id:'shard'});}};}
{const _s=startGame_v5;startGame_v5=function(cont){_s(cont);try{invSanitize();}catch(e){}};}

/* ---------- bag tabs ---------- */
let INV_TABS_ON=true;
G.invTab=G.invTab||'all';const INV_TAB_PG={all:0,gear:0,fash:0,misc:0};
