/* =====================================================================
   v53 — Secondary stats (Options) + option stones
     · Weapons / gear roll "Option" lines when appraised (sealed drops) or created (shop / admin).
       Lines by grade: Common 0 · Uncommon 1 · Rare 1 · Epic 2 · Legend 3 · Mythic 4 · Immortal 5 (capped by the slot's pools).
       Line N always comes from Pool N of the item's category (Melee / Ranged / Magic weapon, Accessory,
       Headgear, Chest & Shield, Garment (= Legwear pool), Shoes). Value = 20–100% of the pool max (higher grades roll higher).
     · Stones (Master Smith › ออฟ Option):
         Option Stone  (หินออปชั่น)  re-roll every line (stat + value)
         Polish Stone  (หินขัดเกลา) re-roll values only, stats stay
         Lock Stone    (หินล็อก)    keep a line untouched during a re-roll (1 stone per locked line)
       The new result replaces the old one immediately.
   ===================================================================== */
const OPT={
  atkPct:['ATK','%'],matkPct:['MATK','%'],dmgMelee:['ดาเมจระยะประชิด','%'],dmgRanged:['ดาเมจระยะไกล','%'],dmgMagic:['ดาเมจเวท','%'],
  crit:['Critical','%'],critDmg:['Crit Damage','%'],hit:['HIT',''],leech:['ดูดเลือด','%'],aspd:['ASPD','%'],chain:['Chain (ตีกระโดด)',' เป้า'],
  atk:['ATK','',1],matk:['MATK','',1],multi:['Multistrike (ตีซ้ำ)','%'],range:['ระยะยิง','',0,40],castSpd:['ร่ายเร็ว','%'],cdr:['Cooldown','%'],
  mpCost:['SP ที่ใช้','%'],healing:['พลังฮีล','%'],castRange:['ระยะสกิล','',0,60],hpPct:['Max HP','%'],mpPct:['Max SP','%'],def:['DEF','',1],defPct:['DEF','%'],
  mdef:['MDEF','',1],mdefPct:['MDEF','%'],dmgFromMelee:['ดาเมจประชิดที่ได้รับ','%'],dmgFromMagic:['ดาเมจเวท/ไกลที่ได้รับ','%'],healRecv:['ฮีลที่ได้รับ','%'],
  perfDodge:['Perfect Dodge','%'],hpRegen:['ฟื้น HP','%'],mpRegen:['ฟื้น SP','%'],flee:['FLEE',''],moveSpd:['ความเร็วเดิน','%'],aspdLimit:['เพดาน ASPD',' ครั้ง/วิ']};
const OPT_POOLS={
  melee:[[['atkPct',5],['matkPct',5]],[['dmgMelee',5],['dmgMagic',5]],[['crit',10],['hit',20],['aspd',10],['atk',5],['matk',5]],[['critDmg',10],['leech',5],['chain',1],['multi',25]]],
  ranged:[[['atkPct',5],['matkPct',5]],[['dmgRanged',5],['dmgMagic',5]],[['crit',10],['hit',20],['aspd',10],['atk',5],['matk',5]],[['critDmg',10],['leech',5],['range',1],['multi',25]]],
  magic:[[['atkPct',5],['matkPct',5]],[['dmgMelee',5],['dmgMagic',5]],[['castSpd',10],['mpCost',-10],['aspd',10],['atk',5],['matk',5]],[['cdr',10],['healing',10],['castRange',1]]],
  acc:[[['hpPct',2],['mpPct',2]],[['atkPct',2],['matkPct',2]],[['crit',5],['hit',10],['aspd',5]]],
  head:[[['hpPct',2],['mpPct',2]],[['atkPct',2],['matkPct',2]],[['atk',3],['matk',3]],[['def',5],['mdef',5]]],
  chest:[[['hpPct',10],['mpPct',10]],[['def',10],['mdef',10]],[['defPct',5],['mdefPct',5]],[['dmgFromMelee',-5],['dmgFromMagic',-5]],[['healRecv',10],['perfDodge',5]]],
  legs:[[['hpRegen',25],['mpRegen',25]],[['leech',5],['castSpd',10]],[['flee',15],['perfDodge',5]],[['mpCost',-10]]],
  shoes:[[['aspd',10]],[['moveSpd',10]],[['castSpd',10]],[['aspdLimit',1]]]};
// weapons: Pool 5 = any option from every pool of that weapon type
for(const c of ['melee','ranged','magic'])OPT_POOLS[c].push(OPT_POOLS[c].flat());
const OPT_CAT_TH={melee:'อาวุธระยะประชิด',ranged:'อาวุธระยะไกล',magic:'อาวุธเวท',acc:'เครื่องประดับ',head:'หมวก',chest:'เกราะ & โล่',legs:'ผ้าคลุม',shoes:'รองเท้า'};
const OPT_LINES=[0,1,1,2,3,4,5];
function optCat(it){if(!isGear(it))return null;if(it.kind==='wpn'){const W_=WEAPONS[it.t];if(!W_||it.t==='fist')return null;return W_.magic||it.t==='staff'?'magic':W_.ranged?'ranged':'melee';}
  const t=it.type;return t==='acc'?'acc':/^head/.test(t)?'head':t==='armor'||t==='shield'?'chest':t==='garment'?'legs':t==='shoes'?'shoes':null;}
function optMaxLines(it){const c=optCat(it);return c?Math.min(OPT_LINES[clamp(it.rar|0,0,6)],OPT_POOLS[c].length):0;}
function optMaxVal(it,k,base){const f=OPT[k]&&OPT[k][2];return f?Math.round(base*(1+(it.lvl||1)/20)):base;}
function optRollVal(it,k,base){const mx=optMaxVal(it,k,base),a=Math.abs(mx);if(a<=2)return Math.sign(mx)*ri(1,a);const lo=.2+.08*clamp(it.rar|0,0,6);return Math.sign(mx)*Math.max(1,Math.round(a*rand(lo,1)));}
function optLine(it,i,keep){const pool=OPT_POOLS[optCat(it)][i];const pk=keep?pool.find(p=>p[0]===keep)||pick(pool):pick(pool);return {k:pk[0],v:optRollVal(it,pk[0],pk[1]),m:optMaxVal(it,pk[0],pk[1])};}
function optRollAll(it,locks){const n=optMaxLines(it),old=it.op||[];it.op=[];for(let i=0;i<n;i++)it.op.push(locks&&locks.has(i)&&old[i]?old[i]:optLine(it,i));return it.op;}
function optPolish(it,locks){it.op=(it.op||[]).map((o,i)=>locks&&locks.has(i)?o:optLine(it,i,o.k));return it.op;}
function optFmt(o){const d=OPT[o.k]||[o.k,''];const v=o.k==='range'||o.k==='castRange'?o.v*(d[3]||1):o.v;return `${d[0]} ${v>0?'+':''}${v}${d[1]}`;}
// every identification (appraisal / shop / admin) also rolls the options
{const _r=rsRoll;rsRoll=function(it){const r=_r.apply(this,arguments);try{optRollAll(it);}catch(e){}return r;};}
{const _s=sealItem;sealItem=function(it){const r=_s.apply(this,arguments);if(isGear(it))it.op=null;return r;};}

/* ---------- stones ---------- */
