/* ---------- effects ---------- */
function optSum(){const S={};if(!P)return S;const add=it=>{if(!isGear(it)||it.seal||!it.op)return;for(const o of it.op)S[o.k]=(S[o.k]||0)+o.v;};
  for(const s in P.equip)add(P.equip[s]);if(P.weapon&&P.weapon.t!=='fist')add(P.weapon);return S;}
{const _rc=recalc;recalc=function(){if(!P)return _rc.apply(this,arguments);const hr=P.maxHp?P.hp/P.maxHp:1,mr=P.maxMp?P.mp/P.maxMp:1;const r=_rc.apply(this,arguments);
  const O=P.opt=optSum(),pb=P.pb=P.pb||{},add=(k,v)=>{if(v)pb[k]=(pb[k]||0)+v;};
  add('atk',(O.atkPct||0)/100);add('matk',(O.matkPct||0)/100);add('crit',O.crit||0);add('critDmg',(O.critDmg||0)/100);add('lifesteal',(O.leech||0)/100);
  add('aspd',(O.aspd||0)/100);add('dbl',(O.multi||0)/100);add('cdr',(O.cdr||0)/100);add('speed',(O.moveSpd||0)/100);add('regen',.004*(O.hpRegen||0)/100);
  P.atk+=O.atk||0;P.matk+=O.matk||0;P.hit=(P.hit||0)+(O.hit||0);P.flee=(P.flee||0)+(O.flee||0);
  P.def=Math.round((P.def+(O.def||0))*(1+(O.defPct||0)/100));P.mdef=Math.round(((P.mdef||0)+(O.mdef||0))*(1+(O.mdefPct||0)/100));
  if(O.hpPct)P.maxHp=Math.round(P.maxHp*(1+O.hpPct/100));if(O.mpPct)P.maxMp=Math.round(P.maxMp*(1+O.mpPct/100));
  if(!P.dead){P.hp=clamp(Math.round(P.maxHp*hr),1,P.maxHp);P.mp=clamp(Math.round(P.maxMp*mr),0,P.maxMp);}
  return r;};}
function optO(){return (P&&P.opt)||{};}
{const _c=castRed;castRed=function(){return clamp(_c()+(optO().castSpd||0)/100,0,.8);};}
{const _m=mpCost;mpCost=function(){const v=_m.apply(this,arguments),o=optO().mpCost||0;return o?Math.max(0,Math.round(v*(1+o/100))):v;};}
