    ell(x-10,y-4,14,5,'#3a6a2e',.9);ell(x+12,y-3,10,4,'#4a7a36',.85);ell(x-19,y-30,4,9,'#3a6a2e',.7);
    ctx.strokeStyle=on?'#8dffe8':'#5a6274';ctx.lineWidth=2;ctx.lineCap='round';
