/* ---------- admin picker (top of the Map Editor tab) ---------- */
{const _r=renderMapTab;renderMapTab=function(){const r=_r.apply(this,arguments);const b=$('#gmBody');const host=b&&(b.querySelector('.admpane')||b);
  if(host)host.insertAdjacentHTML('afterbegin',`<div class="cos8" style="margin-bottom:10px;border-color:rgba(94,240,224,.45)"><h5 style="color:var(--mint)">เสา Waystone (จุดวาร์ปทุกแมพ)</h5>
    <div class="row" style="gap:6px;flex-wrap:wrap">${WSTONE_N.map((n,i)=>`<button class="btn sm${WSTONE.style===i?' gold':''}" data-wst="${i}">${i?i+' · ':''}${n}</button>`).join('')}</div></div>`);return r;};}
(function(){const body=$('#gmBody');if(!body)return;body.addEventListener('click',e=>{const t=e.target.closest('[data-wst]');if(!t)return;
  WSTONE.style=+t.dataset.wst;try{localStorage.setItem(WSTONE_KEY,JSON.stringify(WSTONE));}catch(_){}try{admLog(`เสา Waystone: ${WSTONE_N[WSTONE.style]}`,'misc');}catch(_){}renderGM();});})();
/* =====================================================================
   v58 — Boss skill: Summon minions
     Every boss / raid boss in combat calls normal monsters and elites around itself:
       · a wave every ~20 s (first one ~8 s into the fight): 3 minions, 35% chance of +1 elite
       · every 3rd wave is big: 4 minions + 1–2 elites (time-based only, HP doesn't matter)
       · max 8 living minions per boss · minions come from the boss's own map (or monsters of a similar level)
     Telegraph: the boss roars "SUMMON!", rune circles glow on the ground, minions rise 0.8 s later.
     Minions give 30% EXP and only Gold; they vanish when their boss dies.
   ===================================================================== */
const BSUM={cd:20,first:8,cap:8,elite:.35};
function bsumPool(boss){const Z=ZONES[G.zone],L=boss.L,out=[];
  const ok=t=>MOBS[t]&&!MOBS[t].boss&&!MOBS[t].raid&&!MOBS[t].elite&&!/^devdummy/.test(t);
  if(Z&&Z.mobs&&Z.mobs.length)for(const [t,lv] of Z.mobs)if(ok(t)&&lv<=L+2)out.push([t,lv]);
  if(!out.length)for(const z in ZONES){const m=ZONES[z].mobs;if(!m)continue;for(const [t,lv] of m)if(ok(t)&&Math.abs(lv-L)<=18)out.push([t,lv]);}
  if(!out.length)out.push(['wisp',Math.max(1,L-5)]);return out;}
function bossSummon(boss,big){if(!boss||boss.dead)return;const alive=enemies.filter(e=>!e.dead&&e.sumBoss===boss).length,room=C182.bsum(boss,'cap')-alive;if(room<=0)return;
  const nN=Math.min(room,C182.bsum(boss,'n',big)),nE=Math.min(Math.max(0,room-nN),C182.bsumElite(boss,big,room,ri,rng)),pool=bsumPool(boss),Z=ZONES[G.zone];
  textAt(boss.x,boss.y-boss.sz*2.9,big?'SUMMON LEGION!':'SUMMON!','#ff6a5a',big?24:19,{life:1.3});ring(boss.x,boss.y,boss.sz,boss.sz*4,.7,'#ff4f6a',8);shake(big?6:3);try{sfx('blast');}catch(e){}
  const n=nN+nE;for(let i=0;i<n;i++){const a=(i/n)*TAU+rand(-.3,.3);let x=boss.x+Math.cos(a)*(boss.sz*1.4+rand(40,90)),y=boss.y+Math.sin(a)*(boss.sz*1.1+rand(30,70));
    x=clamp(x,70,Z.w-70);y=clamp(y,70,Z.h-70);{const q=C182.bsumSpot(boss,x,y);x=q.x;y=q.y;}if(blocked(x,y,20)){const s=typeof freeSpotNear==='function'?freeSpotNear(x,y,20):null;if(s){x=s.x;y=s.y;}}
    const elite=i>=nN,[type,lv]=pick(pool);
    fx.push({k:'rune',x,y,r:elite?46:32,t:0,dur:.9,pl:elite?THEMES.fire:THEMES.void});
    timers.push({t:.8,fn:()=>{if(boss.dead||G.state!=='play')return;const e=makeEnemy(type,clamp(Math.min(boss.L-ri(2,6),lv+ri(0,4)),1,255),x,y);e.sumBoss=boss;e.summoned=1;e.aggro=true;e.alertT=.6;C182.addGrace(e,boss);
      if(elite&&typeof promoteElite==='function')promoteElite(e);enemies.push(e);ring(x,y,6,elite?80:55,.5,elite?'#ffb347':'#b04cff',elite?6:4);
      emitThemed(x,y-10,elite?THEMES.fire:THEMES.void,elite?30:16,elite?260:180);if(elite)textAt(x,y-e.sz*2.4,'ELITE','#ffb347',15,{life:1});}});}}
{const _u=updEnemies;updEnemies=function(dt){const r=_u.apply(this,arguments);
  if(G.state==='play'&&!G.edit)for(const e of enemies){if(e.dead||!e.m||!e.m.boss||e.dev||e.summoned)continue;
    if(!e.aggro){e.sumT=C182.bsum(e,'first');continue;}
    // v58b: time-based only — every BSUM.cd s; every 3rd wave is a big one (Legion)
    if(e.sumT==null)e.sumT=C182.bsum(e,'first');e.sumT-=dt;
    if(e.sumT<=0){e.sumN=(e.sumN||0)+1;bossSummon(e,e.sumN%3===0);e.sumT=C182.bsum(e,'cd');}}
  return r;};}
// minions: 30% EXP, Gold only; they vanish when their boss falls
let BSUM_KILL=null;
{const _k=killEnemy;killEnemy=function(e){if(!e||e.dead||!(e.summoned||(e.m&&e.m.boss)))return _k.apply(this,arguments);
  if(e.summoned){const ge=gainExp,gj=gainJobExp;BSUM_KILL=e;gainExp=function(v,...a){return ge.call(this,Math.round(v*.3),...a);};gainJobExp=function(v,...a){return gj.call(this,Math.round(v*.3),...a);};
    try{return _k.apply(this,arguments);}finally{gainExp=ge;gainJobExp=gj;BSUM_KILL=null;}}
  const r=_k.apply(this,arguments);
  for(const m of enemies){if(m.dead||m.sumBoss!==e)continue;m.dead=true;m.hp=0;emitThemed(m.x,m.y-10,THEMES.void,14,160);ring(m.x,m.y,4,40,.4,'#b04cff',3);}
  return r;};}
{const _d=dropLoot;dropLoot=function(x,y,o){if(BSUM_KILL&&o&&o.item)return;return _d.apply(this,arguments);};}
/* =====================================================================
   v58 — Master Smith › การ์ด tab + socket drilling
     · Card slots moved out of the refine tab into their own "การ์ด" tab (slot frames, compatible cards, drill).
     · Every weapon / equipment has 1 card slot; drilling opens 1 extra slot (max 2 cards).
     · Drilling needs an Abyssal Drill (หัวเจาะมิติ) — dropped by bosses and World Raid chests only — plus a Gold fee.
     · The second card works exactly like the first (stats, race / size / element damage, resistances).
   ===================================================================== */
ITEMS.abyssDrill={n:'Abyssal Drill',d:'หัวเจาะมิติ · เจาะรูการ์ดเพิ่ม 1 ช่องให้อุปกรณ์ (ใช้ที่ Master Smith › การ์ด) · ดรอปจากบอสเท่านั้น',k:'drill',col:'#c98cff',sell:5000,
  icon(g){g.globalCompositeOperation='lighter';g.drawImage(glowSprite('#c98cff'),4,4,56,56);g.globalCompositeOperation='source-over';
    g.fillStyle='#5a3a7a';g.fillRect(26,8,12,14);g.fillStyle='#8a6ab0';g.fillRect(28,10,8,10);
    const gr=g.createLinearGradient(20,22,44,22);gr.addColorStop(0,'#b8b0d8');gr.addColorStop(.5,'#ffffff');gr.addColorStop(1,'#8a80b0');g.fillStyle=gr;
    g.beginPath();g.moveTo(20,22);g.lineTo(44,22);g.lineTo(32,56);g.closePath();g.fill();g.strokeStyle='#6a5a9a';g.lineWidth=1.5;for(let i=0;i<4;i++){g.beginPath();g.moveTo(22+i*1.5,26+i*7);g.lineTo(42-i*1.5,30+i*7);g.stroke();}
    g.fillStyle='#fff';g.beginPath();g.arc(32,54,2.5,0,TAU);g.fill();}};
