{const _n=itemName;itemName=function(it){let s=_n.apply(this,arguments);if(it&&it.sock2&&(it.kind==='wpn'||it.kind==='eq')){const c2=it.card2&&ITEMS[it.card2]?MOBS[ITEMS[it.card2].mob].n:'1';s=s.replace(/\[([^\]]*)\]$/,(m,a)=>`[${a} · ${c2}]`);}return s;};}
{const _m=itemStatMap;itemStatMap=function(it){const m=_m.apply(this,arguments);const c=it&&it.card2&&ITEMS[it.card2];if(c&&c.eff){const e=c.eff,add=(k,v)=>{if(v)m[k]=(m[k]||0)+v;};
  if(e.stat)for(const k in e.stat)add(k.toUpperCase(),e.stat[k]);if(e.hp)add('Max HP %',Math.round(e.hp*100));if(e.crit)add('Critical %',e.crit);
  for(const [grp,lab] of [['race','vs'],['size','vs'],['ele','vs ธาตุ'],['redRace','กันเผ่า'],['redEle','กันธาตุ']])if(e[grp])for(const k in e[grp])add(`${lab} ${cap1(k)} %`,Math.round(e[grp][k]*100));}return m;};}
