  const txt=`ช่องการ์ด: ${c1?c1.n:'ว่าง'}${it.sock2?` · ${c2?c2.n:'ว่าง'}`:''} [${cardSlots(it)}]${it.sock2?' <span style="color:#c98cff">◆ เจาะรูแล้ว</span>':''}`;
