/* =====================================================================
   v60 — Weapon styles · dagger / sword / greatsword  (5 looks each, code-drawn)
     1 Lunar (silver, crescents, blue glow)      2 Dragonjaw (bone-gold, fangs, ember)
     3 Runeforge (gold trim, cyan runes)         4 Frostreaver (ice crystal)
     5 Abyssal (obsidian, spikes, void glow)
   ===================================================================== */
function wPoly(g,pts,fill,stroke,lw){g.beginPath();g.moveTo(pts[0][0],pts[0][1]);for(let i=1;i<pts.length;i++)g.lineTo(pts[i][0],pts[i][1]);g.closePath();if(fill){g.fillStyle=fill;g.fill();}if(stroke){g.strokeStyle=stroke;g.lineWidth=lw||1;g.stroke();}}
function wGem(g,x,y,r,col,live){g.save();g.fillStyle='#1a1226';g.beginPath();g.arc(x,y,r+1,0,TAU);g.fill();g.globalCompositeOperation='lighter';g.fillStyle=col;g.shadowColor=col;g.shadowBlur=live?9:6;g.beginPath();g.arc(x,y,r,0,TAU);g.fill();g.restore();}
