function wRim(g,c){g.strokeStyle=c||'#8a6ad0';g.lineWidth=1;g.stroke();}
function wGrip(g,x0,x1,w,c0,c1,wrap){axHaft(g,x0,x1,w,c0,c1);if(wrap)axWrap(g,x0+1,x1-1,wrap);}

