/* =====================================================================
   v60 — Weapon styles · spear / bow / staff  (5 looks each, code-drawn)
   ===================================================================== */
function wLimb(g,cx,cy,r,a0,a1,w0,w1,fill,stroke){const N=16,o=[],i2=[];for(let i=0;i<=N;i++){const t=i/N,a=a0+(a1-a0)*t,w=w0+(w1-w0)*Math.sin(t*Math.PI);o.push([cx+Math.cos(a)*(r+w),cy+Math.sin(a)*(r+w)]);i2.push([cx+Math.cos(a)*(r-w),cy+Math.sin(a)*(r-w)]);}
  g.beginPath();g.moveTo(o[0][0],o[0][1]);for(const p of o)g.lineTo(p[0],p[1]);for(let i=N;i>=0;i--)g.lineTo(i2[i][0],i2[i][1]);g.closePath();if(fill){g.fillStyle=fill;g.fill();}if(stroke){g.strokeStyle=stroke;g.lineWidth=.9;g.stroke();}}
function wBowPull(live){return live&&P&&P.swing&&P.swing.type==='bow'?Math.sin(Math.min(1,P.swing.t/P.swing.dur)*Math.PI)*8:0;}
function wString(g,col,live,x0=-6,r=22,w=1.1){const pl=wBowPull(live);g.save();g.globalCompositeOperation='lighter';g.strokeStyle=col;g.lineWidth=w;g.shadowColor=col;g.shadowBlur=live?6:3;g.beginPath();g.moveTo(x0+Math.cos(-1.2)*r,Math.sin(-1.2)*r);g.lineTo(-pl-8,0);g.lineTo(x0+Math.cos(1.2)*r,Math.sin(1.2)*r);g.stroke();g.restore();}

