function wUniqueEntries(){const out=[];for(const t in WUQ){if(!WEAPONS[t])continue;for(const s of [1,2,3,4,5]){const D=WUQ[t][s];if(!D)continue;const zs=wStyleZones(s);
  out.push({id:t+':'+s,name:D.n,sub:`${WEAPONS[t].th} · ${D.role}`,chip:t,col:'#ffd36b',icon:()=>itemIcon({kind:'wpn',t,rar:4,sty:s,lvl:1}),search:[D.n,D.tn,D.role,WEAPONS[t].n,WEAPONS[t].th,...zs.map(z=>ZONES[z].n)].join(' '),
    html:()=>{const rc=WREC[s],lv=WREF[s];return `<div class="wkHero"><img src="${itemIcon({kind:'wpn',t,rar:4,sty:s,lvl:1})}" alt=""><div><span class="wkTag" style="--c:#ffd36b">${wkE(D.tn)}</span><div class="wkMeta">${wkLink('weapon',t,WEAPONS[t].th)} · ${wkE(D.role)}${D.hand?' · '+D.hand:''}</div></div></div>
      <h4>ดรอปที่</h4><div class="wkChips">${zs.map(z=>wkLink('zone',z,ZONES[z].n+(ZONES[z].range?' · Lv '+ZONES[z].range[0]+'–'+ZONES[z].range[1]:''))).join('')}</div><p class="muted" style="font-size:12px">ดรอปจากมอนสเตอร์/บอสในพื้นที่ (รวมมอนสเตอร์ในพื้นที่ย่อย ชั้นลึก และแมพเก็บเลเวลของแผนที่นั้น) เป็นของผนึก ต้องส่อง · เกรดแนะนำ ${RARITY[rc[0]].g}–${RARITY[rc[1]].g}</p>
      <h4>สเตตัสหลัก</h4><table class="wkT"><tr><th>ATK</th><td>${D.atk?D.atk+' (ที่เกรดแนะนำ · Lv ~'+lv+')':'ตามเลเวลและเกรด ×'+WMUL[s]}</td></tr>${(D.matk||(s===3&&t!=='axe'))?`<tr><th>MATK</th><td>${D.matk?D.matk:'+ ตามเลเวล'}</td></tr>`:''}${t==='staff'?'<tr><th>MATK</th><td>ตามเลเวลและเกรด (คทา)</td></tr>':''}</table>
      <h4>สเตตัสรอง</h4><ul class="wkUl">${wSubLines(D.sub).map(l=>`<li>${wkE(l)}</li>`).join('')}</ul>
      <h4>ความสามารถพิเศษ — ${wkE(D.tn)}</h4><ul class="wkUl">${wFxLines(D.fx).map(l=>`<li>${wkE(l)}</li>`).join('')}</ul>`;}});}}return out;}
wikiRegister('unique','อาวุธเฉพาะ','✦',()=>wUniqueEntries());
