  for(let i=0;i<16;i++){const a=i/16*TAU,X=Math.cos(a)*R,Y=cy+Math.sin(a)*R;ctx.save();ctx.translate(X,Y);ctx.rotate(a+Math.PI/2);ctx.fillStyle=i%2?'#4a5676':'#414d6c';ctx.strokeStyle='#1a2038';ctx.lineWidth=1.5;ctx.beginPath();ctx.rect(-12,-9,24,18);ctx.fill();ctx.stroke();ctx.fillStyle='rgba(255,255,255,.1)';ctx.fillRect(-12,-9,24,4);if(i%3===0){ctx.fillStyle='rgba(70,140,70,.55)';ctx.beginPath();ctx.ellipse(-4,5,7,3,0,0,TAU);ctx.fill();}ctx.restore();}
