/* ---------- gate style by destination theme ---------- */
const GATE_THEME={capital:3,outskirts:0,jungle:7,serpent:7,desert:1,sands:1,wasteland:9,ironclad:9,snow:2,lava:4,foundry:9,deepsea:6,coral:6,dark:8,voidfront:8,twilight:5,devlab:0};
function gateStyleFor(to){if(GATE_THEME[to]!=null)return GATE_THEME[to];const m=/^(.*)_(deep|sanctum)$/.exec(to||'');if(m)return m[2]==='sanctum'?5:(GATE_THEME[m[1]]||0);return 0;}
{const _gf=gatesFor;gatesFor=function(zid){const out=_gf.apply(this,arguments);for(const g of out)if(g.style==null)g.style=gateStyleFor(g.to);return out;};}

/* ---------- Skill VFX v2 library: detailed layered effects (slash · nova · ground · projectile · meteor · heal · buff · dome · beam · summon · dash) ---------- */
const V2={};
const v2H=i=>{const s=Math.sin(i*91.7+17.3)*43758.5453;return s-Math.floor(s);};
V2.PAL={
  fire:{core:'#fff4d6',main:'#ff8a3d',glow:'#ff3d1f',accent:'#ffd36b',dark:'#2a0600'},
  ice:{core:'#f6ffff',main:'#9be8ff',glow:'#3f8cff',accent:'#e0fbff',dark:'#06203a'},
  holy:{core:'#fffbea',main:'#ffd36b',glow:'#ffa62e',accent:'#fff2b8',dark:'#4a2e06'},
  void:{core:'#f3dcff',main:'#b04cff',glow:'#6a1bd1',accent:'#ff4fd8',dark:'#07000f'},
  spirit:{core:'#effffc',main:'#5ef0e0',glow:'#2f9cff',accent:'#8dffc8',dark:'#06203a'},
  nature:{core:'#f4ffe8',main:'#8dff6a',glow:'#2fb97a',accent:'#d8ff9a',dark:'#0a2a10'},
  shadow:{core:'#e8e0ff',main:'#8a7cff',glow:'#3a2a9a',accent:'#ff6bd8',dark:'#05030f'},
  steel:{core:'#ffffff',main:'#cfe4ff',glow:'#6a8ad8',accent:'#ffe7a8',dark:'#10162a'}};
for(const k in V2.PAL)V2.PAL[k].key=k;
const v2Ring=(x,y,rx,ry,col,a,w,rot,dash)=>{ctx.save();ctx.translate(x,y);ctx.scale(1,ry/rx);ctx.rotate(rot||0);ctx.globalAlpha=Math.max(0,a);ctx.strokeStyle=col;ctx.lineWidth=w/(ry/rx>.3?1:1);if(dash)ctx.setLineDash(dash);ctx.beginPath();ctx.arc(0,0,Math.max(.1,rx),0,TAU);ctx.stroke();ctx.restore();};
const v2Glyphs=(x,y,rx,ry,n,col,a,rot,s)=>{ctx.strokeStyle=col;ctx.lineWidth=1.6;ctx.globalAlpha=Math.max(0,a);for(let i=0;i<n;i++){const t=i/n*TAU+rot,X=x+Math.cos(t)*rx,Y=y+Math.sin(t)*ry,sc=s||6;ctx.beginPath();const q=3+(i*7)%3;let px=X,py=Y-sc*.6;ctx.moveTo(px,py);for(let j=0;j<q;j++){px=X+(v2H(i*5+j)-.5)*sc*1.4;py=Y-sc*.6+(j+1)/q*sc*1.3;ctx.lineTo(px,py);}ctx.stroke();}};
const v2Spark=(x,y,n,spread,col,a,k,seed)=>{for(let i=0;i<n;i++){const ang=v2H(seed+i)*TAU,d=spread*(.25+.75*v2H(seed+i+50))*k,life=1-k;glow(x+Math.cos(ang)*d,y+Math.sin(ang)*d*.7-k*k*spread*.25,2+3*v2H(seed+i+9),col,a*life);}};
// ---- slash: layered crescent sweep with bright edge, echo and sparks
V2.slash=(o,k)=>{const {x,y,ang,r,pl}=o,sw=o.arc||2.1,a=1-Math.max(0,(k-.45)/.55),prog=Math.min(1,k*2.4),eh=1-Math.pow(1-prog,3);ctx.save();ctx.translate(x,y);ctx.rotate(ang);add();
  const N=28,head=-sw/2+sw*eh;for(const [rs,th,al,col] of [[1.0,.5,.55,pl.glow],[.98,.36,.85,pl.main],[.96,.16,1,pl.core]]){for(let i=0;i<N;i++){const q0=i/N,q1=(i+1)/N,a0=-sw/2+(head+sw/2)*q0,a1=-sw/2+(head+sw/2)*q1,tp=Math.pow(q1,1.6),R=r*rs,T=r*th*tp*(1-k*.5);
    ctx.fillStyle=rgba(col,al*a*Math.pow(q1,1.4));ctx.beginPath();ctx.arc(0,0,R,a0,a1);ctx.arc(0,0,R-T,a1,a0,true);ctx.closePath();ctx.fill();}}
  ctx.strokeStyle=rgba(pl.core,.95*a);ctx.lineWidth=2.4;ctx.beginPath();ctx.arc(0,0,r,-sw/2+(head+sw/2)*.55,head);ctx.stroke();
  ctx.strokeStyle=rgba(pl.accent,.55*a);ctx.lineWidth=1.4;ctx.beginPath();ctx.arc(0,0,r*1.09,-sw/2+(head+sw/2)*.35,head-.08+.0);ctx.stroke();
  if(!o.noBlade)V2.blade(pl,r,head,Math.min(1,a*1.3),k,k*1.2);add();const hx=Math.cos(head)*r,hy=Math.sin(head)*r;glow(hx,hy,r*.32*a+4,pl.core,.9*a);glow(hx,hy,r*.55*a+6,pl.main,.5*a);
  for(let i=0;i<10;i++){const q=v2H(i)*.9,an=-sw/2+(head+sw/2)*q,dr=r*(1+ (v2H(i+20)-.3)*.25+k*.25);glow(Math.cos(an)*dr,Math.sin(an)*dr,2+2.5*v2H(i+3),i%2?pl.core:pl.accent,.85*a*(1-q*.4));}
  for(let i=0;i<3;i++){const an=head-.05-i*.3;ctx.strokeStyle=rgba(pl.main,.5*a*(1-i*.3));ctx.lineWidth=1.6;ctx.beginPath();ctx.moveTo(Math.cos(an)*r*.62,Math.sin(an)*r*.62);ctx.lineTo(Math.cos(an)*r*(1.22+i*.06),Math.sin(an)*r*(1.22+i*.06));ctx.stroke();}
  if(k<.35){const f=1-k/.35;ctx.save();ctx.translate(hx,hy);ctx.rotate(k*3);ctx.fillStyle=rgba(pl.core,f);ctx.beginPath();for(let i=0;i<8;i++){const rr=i%2?5:r*.28*f+6;ctx.lineTo(Math.cos(i/8*TAU)*rr,Math.sin(i/8*TAU)*rr);}ctx.fill();ctx.restore();}
  ctx.restore();norm();};

// sword drawn at the head of a slash (blade is radial from the wielder); look follows the element
V2.blade=(pl,r,head,a,k,t)=>{const key=pl.key||'steel',L=r*.98,S=r*.2;ctx.save();ctx.rotate(head);ctx.globalCompositeOperation='source-over';ctx.globalAlpha=Math.min(1,a*1.4);
  const body={fire:['#ffe7b0','#ff8a3d','#7a1206'],void:['#3a2070','#150826','#05000a'],holy:['#ffffff','#ffe9a0','#c88a2a'],ice:['#ffffff','#bfefff','#3f8cff']}[key]||['#ffffff','#cfe4ff','#6a7a9a'];
  const g=ctx.createLinearGradient(0,-8,0,8);g.addColorStop(0,body[0]);g.addColorStop(.5,body[1]);g.addColorStop(1,body[2]);ctx.fillStyle=g;
  ctx.beginPath();ctx.moveTo(S*.9,-5);ctx.lineTo(L-16,-6.5);ctx.lineTo(L+10,0);ctx.lineTo(L-16,4.5);ctx.lineTo(S*.9,5);ctx.closePath();ctx.fill();
  ctx.strokeStyle=key==='void'?pl.main:body[0];ctx.lineWidth=1.4;ctx.beginPath();ctx.moveTo(S*.9,-5);ctx.lineTo(L-16,-6.5);ctx.lineTo(L+10,0);ctx.stroke();
  ctx.strokeStyle='rgba(0,0,0,.35)';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(S*1.2,0);ctx.lineTo(L-6,0);ctx.stroke();
  ctx.fillStyle=key==='void'?'#2a1250':'#7a5a20';ctx.fillRect(S*.85-3,-15,6,30);ctx.fillStyle=key==='void'?pl.accent:'#ffd36b';ctx.fillRect(S*.85-3,-15,6,3);ctx.fillRect(S*.85-3,12,6,3);
  ctx.fillStyle='#2a1c10';ctx.fillRect(S*.9-S*.7,-3.5,S*.7,7);ctx.beginPath();ctx.arc(S*.9-S*.72,0,5,0,TAU);ctx.fillStyle=key==='void'?pl.accent:'#ffd36b';ctx.fill();
  add();ctx.globalAlpha=a;
  if(key==='fire'){for(let i=0;i<9;i++){const q=(i+.5)/9,px=S+(L-S)*q,fl=8+7*Math.sin(t*30+i*2);ctx.fillStyle=rgba(i%2?pl.accent:pl.main,.75);ctx.beginPath();ctx.moveTo(px-7,-5);ctx.quadraticCurveTo(px-2,-5-fl*.7,px+6,-5-fl);ctx.quadraticCurveTo(px+5,-6,px+8,-5);ctx.fill();ctx.beginPath();ctx.moveTo(px-7,5);ctx.quadraticCurveTo(px-2,5+fl*.5,px+6,5+fl*.7);ctx.quadraticCurveTo(px+5,6,px+8,5);ctx.fill();}}
  else if(key==='void'){for(let i=0;i<8;i++){const q=(i+.5)/8,px=S+(L-S)*q,fl=7+6*Math.sin(t*22+i*3);ctx.strokeStyle=rgba(i%2?pl.accent:pl.main,.8);ctx.lineWidth=1.6;ctx.beginPath();ctx.moveTo(px,-6);ctx.bezierCurveTo(px-6,-6-fl*.5,px+6,-6-fl,px+2,-6-fl*1.6);ctx.stroke();ctx.beginPath();ctx.moveTo(px,6);ctx.bezierCurveTo(px+6,6+fl*.5,px-6,6+fl,px-2,6+fl*1.5);ctx.stroke();}}
  glow(L*.6,0,L*.5,pl.main,.35);glow(L,0,r*.16+6,pl.core,.9);ctx.restore();norm();};
// ---- cross slash: two light blades + flare
V2.cross=(o,k)=>{const {x,y,r,pl}=o,a=1-k,e=Math.min(1,k*3);add();ctx.save();ctx.translate(x,y);ctx.rotate(o.ang||0);
  for(const rot of [0,Math.PI/2]){ctx.save();ctx.rotate(rot);const L=r*1.35*e,g=ctx.createLinearGradient(-L,0,L,0);g.addColorStop(0,rgba(pl.main,0));g.addColorStop(.5,rgba(pl.core,.95*a));g.addColorStop(1,rgba(pl.main,0));ctx.fillStyle=g;ctx.beginPath();ctx.moveTo(-L,0);ctx.lineTo(0,-9*a-2);ctx.lineTo(L,0);ctx.lineTo(0,9*a+2);ctx.closePath();ctx.fill();
    ctx.fillStyle=rgba(pl.main,.35*a);ctx.beginPath();ctx.moveTo(-L,0);ctx.lineTo(0,-24*a);ctx.lineTo(L,0);ctx.lineTo(0,24*a);ctx.closePath();ctx.fill();ctx.restore();}
  ctx.restore();glow(x,y,r*.6*a+8,pl.core,.95*a);glow(x,y,r*1.1,pl.main,.35*a);v2Ring(x,y,r*(.3+k*.9),r*(.3+k*.9)*.62,pl.accent,.8*a,3,0);v2Spark(x,y,14,r*1.3,pl.core,.9,k,7);norm();};
// ---- nova: perspective shock ring + rune ring + cracks + rising petals
V2.nova=(o,k)=>{const {x,y,r,pl}=o,a=1-k,e=1-Math.pow(1-Math.min(1,k*1.5),3),R=r*e;add();
  glow(x,y,r*.9*(1-k*.4),pl.glow,.35*a);glow(x,y,r*.35*(1-k),pl.core,.9*(1-k));
  v2Ring(x,y,R,R*.62,pl.glow,.35*a,r*.16*(1-k*.6),0);v2Ring(x,y,R,R*.62,pl.main,.85*a,r*.05*(1-k*.6)+2,0);v2Ring(x,y,R*.97,R*.97*.62,pl.core,.95*a,2,0);
  v2Ring(x,y,R*.72,R*.72*.62,pl.accent,.6*a,1.6,k*2,[10,7]);v2Glyphs(x,y,R*.85,R*.85*.62,14,pl.core,.75*a,k*3,7);
  ctx.strokeStyle=rgba(pl.main,.6*a);ctx.lineWidth=1.6;for(let i=0;i<10;i++){const an=i/10*TAU+v2H(i)*.4,L=R*(.5+.5*v2H(i+3));ctx.beginPath();ctx.moveTo(x+Math.cos(an)*R*.25,y+Math.sin(an)*R*.25*.62);ctx.lineTo(x+Math.cos(an)*L,y+Math.sin(an)*L*.62);ctx.stroke();}
  for(let i=0;i<12;i++){const an=i/12*TAU,px=x+Math.cos(an)*R*.92,py=y+Math.sin(an)*R*.92*.62,h=(18+v2H(i)*30)*Math.sin(Math.min(1,k*1.6)*Math.PI)*(r/140+.4);ctx.fillStyle=rgba(pl.main,.5*a);ctx.beginPath();ctx.moveTo(px-4,py);ctx.lineTo(px,py-h);ctx.lineTo(px+4,py);ctx.closePath();ctx.fill();}
  v2Spark(x,y,16,r*1.05,pl.core,.9,k,3);norm();};
// ---- ground zone: persistent rune circle, pulsing fill, motes, light pillars
V2.ground=(o,t)=>{const {x,y,r,pl}=o,fade=Math.min(1,t*4)*Math.min(1,(o.dur-t)*3),pu=.5+.5*Math.sin(t*4);add();ctx.globalAlpha=fade;
  const g=ctx.createRadialGradient(x,y,r*.1,x,y,r);g.addColorStop(0,rgba(pl.main,.05));g.addColorStop(.75,rgba(pl.main,.18+.08*pu));g.addColorStop(1,rgba(pl.glow,0));ctx.save();ctx.translate(x,y);ctx.scale(1,.62);ctx.fillStyle=g;ctx.beginPath();ctx.arc(0,0,r,0,TAU);ctx.fill();ctx.restore();
  v2Ring(x,y,r,r*.62,pl.main,.85*fade,3,0);v2Ring(x,y,r*.86,r*.86*.62,pl.accent,.6*fade,1.6,t*.8,[14,8]);v2Ring(x,y,r*.62,r*.62*.62,pl.main,.5*fade,1.6,-t*1.1,[3,7]);
  v2Glyphs(x,y,r*.93,r*.93*.62,18,pl.core,.8*fade,t*.6,7);v2Glyphs(x,y,r*.5,r*.5*.62,8,pl.accent,.7*fade,-t*.9,5);
  ctx.save();ctx.translate(x,y);ctx.scale(1,.62);ctx.rotate(t*.5);ctx.strokeStyle=rgba(pl.core,.55*fade);ctx.lineWidth=1.4;for(const n of [3,6]){ctx.beginPath();for(let i=0;i<=n;i++){const an=i/n*TAU;i?ctx.lineTo(Math.cos(an)*r*.42,Math.sin(an)*r*.42):ctx.moveTo(Math.cos(an)*r*.42,Math.sin(an)*r*.42);}ctx.stroke();}ctx.restore();
  for(let i=0;i<14;i++){const q=((t*.5+v2H(i))%1),an=v2H(i+5)*TAU,d=Math.sqrt(v2H(i+8))*r*.9;glow(x+Math.cos(an)*d,y+Math.sin(an)*d*.62-q*r*.45,2+2.5*v2H(i),i%3?pl.main:pl.core,.85*(1-q)*fade);}
  for(let i=0;i<3;i++){const ph=(t*.9+i/3)%1,an=i*2.1+t*.2,px=x+Math.cos(an)*r*.55,py=y+Math.sin(an)*r*.55*.62,h=r*.8*Math.sin(ph*Math.PI);const gr=ctx.createLinearGradient(0,py-h,0,py);gr.addColorStop(0,rgba(pl.core,0));gr.addColorStop(1,rgba(pl.main,.5*fade));ctx.fillStyle=gr;ctx.fillRect(px-5,py-h,10,h);glow(px,py,14,pl.main,.6*fade*Math.sin(ph*Math.PI));}
  norm();};
// ---- projectile heads by element
V2.proj=(o,t)=>{const {x,y,ang,pl,kind}=o,s=o.size||18,tr=o.trail||70;ctx.save();ctx.translate(x,y);ctx.rotate(ang);add();
  const trail=(col,w)=>{const g=ctx.createLinearGradient(-tr,0,0,0);g.addColorStop(0,rgba(col,0));g.addColorStop(1,rgba(col,.7));ctx.fillStyle=g;ctx.beginPath();ctx.moveTo(-tr,0);ctx.lineTo(0,-w);ctx.lineTo(0,w);ctx.closePath();ctx.fill();};
  if(kind==='arrow'){trail(pl.main,4);ctx.strokeStyle=rgba(pl.core,.95);ctx.lineWidth=2.2;ctx.beginPath();ctx.moveTo(-26,0);ctx.lineTo(10,0);ctx.stroke();ctx.fillStyle=rgba(pl.core,1);ctx.beginPath();ctx.moveTo(18,0);ctx.lineTo(8,-5);ctx.lineTo(10,0);ctx.lineTo(8,5);ctx.closePath();ctx.fill();
    ctx.strokeStyle=rgba(pl.main,.9);ctx.lineWidth=1.6;for(const sg of [-1,1]){ctx.beginPath();ctx.moveTo(-26,0);ctx.lineTo(-33,sg*6);ctx.moveTo(-21,0);ctx.lineTo(-28,sg*6);ctx.stroke();}glow(14,0,16,pl.main,.8);}
  else if(kind==='ice'){trail(pl.main,7);for(let i=0;i<4;i++)glow(-i*14-6,(v2H(i)-.5)*10,3,pl.core,.7);ctx.fillStyle=rgba(pl.core,.95);ctx.strokeStyle=rgba(pl.main,1);ctx.lineWidth=1.6;ctx.beginPath();ctx.moveTo(s*1.4,0);ctx.lineTo(0,-s*.34);ctx.lineTo(-s*.8,0);ctx.lineTo(0,s*.34);ctx.closePath();ctx.fill();ctx.stroke();ctx.beginPath();ctx.moveTo(s*1.4,0);ctx.lineTo(-s*.8,0);ctx.stroke();glow(0,0,s*1.4,pl.glow,.6);}
  else if(kind==='holy'){trail(pl.accent,6);ctx.fillStyle=rgba(pl.core,1);ctx.beginPath();ctx.moveTo(s*1.7,0);ctx.lineTo(0,-s*.22);ctx.lineTo(-s*.9,0);ctx.lineTo(0,s*.22);ctx.closePath();ctx.fill();for(const sg of [-1,1]){ctx.fillStyle=rgba(pl.main,.7);ctx.beginPath();ctx.moveTo(-s*.2,0);ctx.quadraticCurveTo(-s*.9,sg*s*.9,-s*1.7,sg*s*.5);ctx.quadraticCurveTo(-s*1.1,sg*s*.3,-s*.2,0);ctx.fill();}glow(0,0,s*1.6,pl.main,.6);}
  else if(kind==='void'){ctx.save();ctx.rotate(-ang);for(let i=0;i<4;i++){const an=t*8+i*1.57,rr=s*(.9+.15*Math.sin(t*9+i));glow(Math.cos(an)*rr-Math.cos(ang)*i*8,Math.sin(an)*rr-Math.sin(ang)*i*8,s*.35,pl.accent,.6);}ctx.restore();ctx.globalCompositeOperation='source-over';ctx.fillStyle='#04000a';ctx.beginPath();ctx.arc(0,0,s*.7,0,TAU);ctx.fill();add();ctx.strokeStyle=rgba(pl.main,1);ctx.lineWidth=2.4;ctx.beginPath();ctx.arc(0,0,s*.75,0,TAU);ctx.stroke();glow(0,0,s*1.7,pl.glow,.55);trail(pl.glow,s*.5);}
  else if(kind==='wind'){ctx.strokeStyle=rgba(pl.core,.9);ctx.lineWidth=3;for(let i=0;i<3;i++){ctx.beginPath();ctx.arc(-s*.5-i*8,0,s*(1-i*.15),-1,1);ctx.stroke();}trail(pl.main,5);glow(0,0,s*1.2,pl.main,.5);}
  else{trail(pl.glow,s*.55);ctx.save();ctx.rotate(-ang);for(let i=0;i<7;i++){const an=Math.PI+(v2H(i)-.5)*1.1+Math.sin(t*14+i)*.15,L=s*(.9+v2H(i+3)*1.4);ctx.fillStyle=rgba(i%2?pl.main:pl.accent,.6);ctx.beginPath();ctx.moveTo(0,-4);ctx.quadraticCurveTo(Math.cos(an+ang)*L*.6,Math.sin(an+ang)*L*.6-6,Math.cos(an+ang)*L,Math.sin(an+ang)*L);ctx.quadraticCurveTo(Math.cos(an+ang)*L*.6,Math.sin(an+ang)*L*.6+6,0,4);ctx.fill();}ctx.restore();glow(0,0,s*1.6,pl.main,.75);glow(0,0,s*.8,pl.core,1);}
  glow(0,0,s*.5,pl.core,.95);ctx.restore();norm();};
V2.projImpact=(o,k)=>{const {x,y,pl,r}=o,a=1-k,R=(r||46)*(.3+.7*Math.min(1,k*2));add();glow(x,y,R*1.4,pl.main,.5*a);glow(x,y,R*.6,pl.core,.9*a);v2Ring(x,y,R,R*.62,pl.core,.9*a,3*a+1,0);v2Spark(x,y,12,R*1.3,pl.core,.9,k,o.seed||2);ctx.save();ctx.translate(x,y);ctx.rotate(k*2);ctx.fillStyle=rgba(pl.core,.8*a);ctx.beginPath();for(let i=0;i<8;i++){const rr=i%2?3:R*.9;ctx.lineTo(Math.cos(i/8*TAU)*rr,Math.sin(i/8*TAU)*rr*.62);}ctx.fill();ctx.restore();norm();};
// ---- meteor: falling body + tail + impact
V2.meteor=(o,k)=>{const {x,y,r,pl}=o,fall=.55;add();if(k<fall){const p=k/fall,ex=p*p,h=440*(1-ex),X=x-h*.32,Y=y-h;
    v2Ring(x,y,r*(.35+.65*p),r*(.35+.65*p)*.62,pl.main,.35+.5*p,2,0);v2Ring(x,y,r*.5*p,r*.5*p*.62,pl.core,.6*p,1.5,p*6,[6,5]);
    const g=ctx.createLinearGradient(X,Y,X+h*.32*.9,Y+h*.9);g.addColorStop(0,rgba(pl.glow,0));g.addColorStop(1,rgba(pl.main,.85));ctx.strokeStyle=g;ctx.lineWidth=26;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(X,Y);ctx.lineTo(X+h*.32*.9,Y+h*.9);ctx.stroke();ctx.lineWidth=10;ctx.strokeStyle=rgba(pl.core,.7);ctx.stroke();
    for(let i=0;i<10;i++){const q=i/10;glow(X+h*.32*q*.9+(v2H(i)-.5)*14,Y+h*q*.9,4+6*(1-q),i%2?pl.accent:pl.main,.7);}glow(X,Y,r*.55,pl.main,.8);glow(X,Y,r*.28,pl.core,1);
    ctx.fillStyle=rgba(pl.dark,1);ctx.globalCompositeOperation='source-over';ctx.beginPath();ctx.arc(X,Y,r*.16,0,TAU);ctx.fill();add();}
  else{const q=(k-fall)/(1-fall),a=1-q;glow(x,y,r*(1.1+q),pl.glow,.5*a);glow(x,y,r*.6*(1-q*.6),pl.core,.95*a);v2Ring(x,y,r*(.3+1.1*q),r*(.3+1.1*q)*.62,pl.main,.9*a,5*a+1,0);v2Ring(x,y,r*(.2+.8*q),r*(.2+.8*q)*.62,pl.core,.9*a,2,0);
    for(let i=0;i<9;i++){const an=i/9*TAU+v2H(i),h=(30+50*v2H(i+4))*Math.sin(Math.min(1,q*2)*Math.PI)*(r/110+.4),px=x+Math.cos(an)*r*.55*q*1.4,py=y+Math.sin(an)*r*.55*q*1.4*.62;const gr=ctx.createLinearGradient(0,py-h,0,py);gr.addColorStop(0,rgba(pl.core,0));gr.addColorStop(1,rgba(pl.main,.75*a));ctx.fillStyle=gr;ctx.beginPath();ctx.moveTo(px-8,py);ctx.quadraticCurveTo(px,py-h*1.2,px+8,py);ctx.fill();}
    v2Spark(x,y-10,20,r*1.6,pl.core,.9,q,11);}
  norm();};
// ---- heal: helix ribbons + cross glyph + soft ground ring
V2.heal=(o,k)=>{const {x,y,pl,r}=o,R=r||70,a=Math.sin(Math.min(1,k)*Math.PI);add();glow(x,y,R*1.2,pl.main,.3*a);v2Ring(x,y,R*(.5+.5*Math.min(1,k*2)),R*(.5+.5*Math.min(1,k*2))*.62,pl.accent,.85*a,3,0);v2Ring(x,y,R*.7,R*.7*.62,pl.core,.6*a,1.4,k*4,[6,6]);
  for(let h=0;h<2;h++){ctx.strokeStyle=rgba(h?pl.core:pl.main,.8*a);ctx.lineWidth=2.4;ctx.beginPath();for(let s=0;s<=40;s++){const q=s/40,an=q*TAU*1.6+k*6+h*Math.PI,X=x+Math.cos(an)*R*.42*(1-q*.4),Y=y+Math.sin(an)*R*.2-q*R*1.35;s?ctx.lineTo(X,Y):ctx.moveTo(X,Y);}ctx.stroke();}
  for(let i=0;i<16;i++){const q=((k*1.2+v2H(i))%1);glow(x+(v2H(i+3)-.5)*R*1.2+Math.sin(q*9+i)*6,y-q*R*1.4,2+3*v2H(i+7),i%3?pl.main:pl.core,.85*(1-q)*a);}
  ctx.save();ctx.translate(x,y-R*.5-k*20);ctx.globalAlpha=.9*a;ctx.fillStyle=rgba(pl.core,.9);const cw=5;ctx.fillRect(-cw,-16,cw*2,32);ctx.fillRect(-16,-cw,32,cw*2);ctx.restore();norm();};
// ---- buff: helix aura + orbiting runes + pulse
V2.buff=(o,t)=>{const {x,y,pl,r}=o,R=r||46,fade=Math.min(1,t*5)*Math.min(1,(o.dur-t)*4);add();ctx.globalAlpha=fade;
  v2Ring(x,y+8,R*1.15,R*1.15*.4,pl.main,.75*fade,2.4,0);v2Ring(x,y+8,R*.9,R*.9*.4,pl.accent,.6*fade,1.5,t*1.3,[6,6]);v2Glyphs(x,y+8,R*1.02,R*1.02*.4,10,pl.core,.7*fade,-t*.8,5);
  for(let h=0;h<3;h++){ctx.strokeStyle=rgba(h%2?pl.core:pl.main,.6*fade);ctx.lineWidth=2;ctx.beginPath();for(let s=0;s<=30;s++){const q=s/30,an=q*TAU*1.4+t*2.4+h*2.09,X=x+Math.cos(an)*R*.8,Y=y+10-q*R*2.6+Math.sin(an)*R*.16;s?ctx.lineTo(X,Y):ctx.moveTo(X,Y);}ctx.stroke();}
  const pu=(t*1.2)%1;v2Ring(x,y+8,R*(.4+pu),R*(.4+pu)*.4,pl.core,.7*(1-pu)*fade,2,0);
  for(let i=0;i<10;i++){const q=((t*.6+v2H(i))%1);glow(x+Math.cos(i*2.4+t)*R*.8,y+8-q*R*2.4,2+2*v2H(i),i%2?pl.main:pl.core,.8*(1-q)*fade);}norm();};
// ---- dome: hex barrier
V2.dome=(o,t)=>{const {x,y,pl,r}=o,R=r||110,fade=Math.min(1,t*4)*Math.min(1,(o.dur-t)*3);add();ctx.globalAlpha=fade;
  ctx.save();ctx.translate(x,y);const gr=ctx.createRadialGradient(0,-R*.3,R*.2,0,-R*.3,R*1.05);gr.addColorStop(0,rgba(pl.main,.02));gr.addColorStop(.85,rgba(pl.main,.16));gr.addColorStop(1,rgba(pl.core,.5));ctx.fillStyle=gr;ctx.beginPath();ctx.ellipse(0,-R*.15,R,R*.85,0,Math.PI,TAU);ctx.lineTo(R,0);ctx.ellipse(0,0,R,R*.3,0,0,Math.PI);ctx.closePath();ctx.fill();
  ctx.clip();ctx.strokeStyle=rgba(pl.core,.4*fade);ctx.lineWidth=1.2;const hs=R*.24;for(let row=-4;row<3;row++)for(let col=-5;col<=5;col++){const hx=col*hs*1.5,hy=row*hs*1.73+(col%2?hs*.87:0)-R*.35,d=Math.hypot(hx,hy+R*.35),sh=.35+.65*Math.max(0,Math.sin(t*3-d/R*6));ctx.globalAlpha=(.2+.5*sh)*fade;ctx.beginPath();for(let i=0;i<6;i++){const an=i/6*TAU;ctx.lineTo(hx+Math.cos(an)*hs*.55,hy+Math.sin(an)*hs*.55);}ctx.closePath();ctx.stroke();}ctx.restore();
  ctx.globalAlpha=fade;v2Ring(x,y,R,R*.3,pl.main,.95,3.5,0);v2Ring(x,y,R*1.02,R*.31,pl.core,.9,1.4,0);glow(x,y,R*.9,pl.main,.15);
  for(let i=0;i<6;i++){const an=t*.8+i/6*TAU;glow(x+Math.cos(an)*R,y+Math.sin(an)*R*.3,5,pl.core,.9);}norm();};
// ---- beam / line lance
V2.beam=(o,k)=>{const {x,y,ang,pl,len,w}=o,W=w||36,L=len||420,a=k<.15?k/.15:1-(k-.15)/.85;ctx.save();ctx.translate(x,y);ctx.rotate(ang);add();
  for(const [ww,col,al] of [[W*1.6,pl.glow,.28],[W,pl.main,.5],[W*.45,pl.accent,.8],[W*.16,pl.core,1]]){const g=ctx.createLinearGradient(0,-ww/2,0,ww/2);g.addColorStop(0,rgba(col,0));g.addColorStop(.5,rgba(col,al*a));g.addColorStop(1,rgba(col,0));ctx.fillStyle=g;ctx.fillRect(0,-ww/2,L,ww);}
  ctx.strokeStyle=rgba(pl.core,.7*a);ctx.lineWidth=1.6;for(let h=0;h<2;h++){ctx.beginPath();for(let s=0;s<=40;s++){const q=s/40;const yy=Math.sin(q*14-k*40+h*Math.PI)*W*.32;s?ctx.lineTo(q*L,yy):ctx.moveTo(0,yy);}ctx.stroke();}
  for(let i=0;i<14;i++){const q=((k*2+v2H(i))%1);glow(q*L,(v2H(i+4)-.5)*W*.9,2+3*v2H(i),pl.core,.8*a);}
  ctx.restore();glow(x,y,W*1.2,pl.core,.8*a);const ex=x+Math.cos(ang)*L,ey=y+Math.sin(ang)*L;glow(ex,ey,W*1.4,pl.main,.7*a);v2Spark(ex,ey,10,W*1.4,pl.core,.9,k,5);norm();};
// ---- summon circle + pillar
V2.summon=(o,k)=>{const {x,y,pl,r}=o,R=r||60,a=Math.sin(Math.min(1,k)*Math.PI),e=Math.min(1,k*2.5);add();glow(x,y,R*1.4,pl.glow,.35*a);
  v2Ring(x,y,R*e,R*e*.62,pl.main,.9*a,3,0);v2Ring(x,y,R*.72*e,R*.72*e*.62,pl.accent,.7*a,1.6,k*3,[10,6]);v2Glyphs(x,y,R*.86*e,R*.86*e*.62,12,pl.core,.8*a,-k*3,6);
  ctx.save();ctx.translate(x,y);ctx.scale(1,.62);ctx.rotate(k*2);ctx.strokeStyle=rgba(pl.core,.7*a);ctx.lineWidth=1.6;ctx.beginPath();for(let i=0;i<=5;i++){const an=i*TAU*2/5;i?ctx.lineTo(Math.cos(an)*R*.6*e,Math.sin(an)*R*.6*e):ctx.moveTo(Math.cos(an)*R*.6*e,Math.sin(an)*R*.6*e);}ctx.stroke();ctx.restore();
  const h=R*3*Math.sin(Math.min(1,k*1.2)*Math.PI)*.9,gr=ctx.createLinearGradient(x-R*.4,0,x+R*.4,0);gr.addColorStop(0,rgba(pl.main,0));gr.addColorStop(.5,rgba(pl.core,.7*a));gr.addColorStop(1,rgba(pl.main,0));ctx.fillStyle=gr;ctx.fillRect(x-R*.4,y-h,R*.8,h);
  for(let i=0;i<14;i++){const q=((k*1.5+v2H(i))%1);glow(x+(v2H(i+3)-.5)*R*.9,y-q*h,2+2.5*v2H(i),pl.core,.85*(1-q)*a);}norm();};
// ---- dash / blink: afterimages + speed lines + rings
V2.dash=(o,k)=>{const {x,y,x2,y2,pl}=o,a=1-k,ang=Math.atan2(y2-y,x2-x),d=Math.hypot(x2-x,y2-y);add();
  const g=ctx.createLinearGradient(x,y,x2,y2);g.addColorStop(0,rgba(pl.main,0));g.addColorStop(1,rgba(pl.main,.6*a));ctx.strokeStyle=g;ctx.lineWidth=26*a;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x2,y2);ctx.stroke();ctx.strokeStyle=rgba(pl.core,.8*a);ctx.lineWidth=6*a;ctx.stroke();
  for(let i=0;i<8;i++){const q=i/8,px=lerp(x,x2,q),py=lerp(y,y2,q);ctx.fillStyle=rgba(pl.main,.28*a*q);ctx.beginPath();ctx.ellipse(px,py-16,10,20,0,0,TAU);ctx.fill();}
  for(let i=0;i<8;i++){const q=v2H(i),off=(v2H(i+9)-.5)*40;ctx.strokeStyle=rgba(pl.core,.6*a);ctx.lineWidth=1.4;ctx.beginPath();ctx.moveTo(lerp(x,x2,q)-Math.sin(ang)*off,lerp(y,y2,q)+Math.cos(ang)*off);ctx.lineTo(lerp(x,x2,Math.min(1,q+.18))-Math.sin(ang)*off,lerp(y,y2,Math.min(1,q+.18))+Math.cos(ang)*off);ctx.stroke();}
  v2Ring(x,y,30*(1+k*2),30*(1+k*2)*.62,pl.main,.8*a,3,0);v2Ring(x2,y2,20+50*k,(20+50*k)*.62,pl.core,.9*a,3,0);glow(x2,y2,50*a,pl.core,.8*a);v2Spark(x2,y2,10,60,pl.core,.9,k,4);norm();};

/* ---------- Skill VFX v2: wire the detailed effects into every skill cast ---------- */
function drawGroundV2(z){
  const pl=z.pl,t=time,fade=Math.min(1,z.t/.25,(z.dur-z.t)/.4),x=z.x,y=z.y,r=z.r;
  if(z.trap){add();runeCircle(x,y,r*.45,t,pl.main,z.armed>0?.3:.55+.3*Math.sin(t*6));glow(x,y,r*.4,pl.main,.25);norm();return;}
  norm();V2.ground({x,y,r,pl,dur:z.dur},Math.max(0,z.t));add();
  if(z.pull){ctx.strokeStyle=rgba(pl.accent,.6*fade);ctx.lineWidth=2;for(let k=0;k<5;k++){ctx.beginPath();for(let i=0;i<40;i++){const a=i*.18+k*TAU/5-t*3,rr=r*(1-i/40);ctx.lineTo(x+Math.cos(a)*rr,y+Math.sin(a)*rr*.62);}ctx.stroke();}norm();glow(x,y,r*.35,'#000000',.9*fade);add();}
  if(z.cross){ctx.globalAlpha=.6*fade;ctx.strokeStyle=pl.core;ctx.lineWidth=6;for(let i=0;i<3;i++){const cx=x+Math.cos(i*2.1+t)*r*.5,cy=y+Math.sin(i*2.1+t)*r*.3;ctx.beginPath();ctx.moveTo(cx,cy-24);ctx.lineTo(cx,cy+24);ctx.moveTo(cx-16,cy-8);ctx.lineTo(cx+16,cy-8);ctx.stroke();glow(cx,cy,30,pl.main,.6*fade);}}
  norm();
  if(z.briar){ctx.lineCap='round';for(let i=0;i<14;i++){const a=i/14*TAU+Math.sin(t+i)*.1,rr=r*(.3+(i%3)*.22);const bx=x+Math.cos(a)*rr,by=y+Math.sin(a)*rr*.62;
    ctx.strokeStyle=rgba('#1f4a2a',.9*fade);ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(bx,by);ctx.quadraticCurveTo(bx+10,by-22,bx+Math.sin(t*2+i)*6,by-38);ctx.stroke();
    add();glow(bx+Math.sin(t*2+i)*6,by-38,8,pl.accent,.8*fade);norm();}}
  // themed particles
  const rate=z.r/60*((z.o&&z.o.fxk)||1);for(let i=0;i<rate;i++)if(Math.random()<.35){const a=rand(0,TAU),rr=Math.sqrt(Math.random())*r;const px=x+Math.cos(a)*rr,py=y+Math.sin(a)*rr*.62;
    if(z.arrows){fx.push({k:'rainArrow',x:px,y:py,t:0,dur:.18,pl});}
    else if(pl.part==='shard'&&Math.random()<.3)part({x:px,y:py-80,vx:rand(-40,40),vy:120,life:.6,max:.6,size:rand(3,6),col:'#ffffff',type:'flake',drag:1});
    else emitThemed(px,py,pl,1,40,{ang:-Math.PI/2,spread:.5});}
}

const V2_KILL=new Set(['ring','cres','rune','crossbeam','pillar','ghost']);
function v2Push(fn,o){fx.push(Object.assign({k:'v2',fn,t:0,dur:.6},o));}
function v2Cast(id,n0,px,py,dome0){const s=SK[id],pl=pal(s),tgt=aimPoint(s.range||450),ang=Math.atan2(tgt.y-py,tgt.x-px);
  fx=fx.filter((f,i)=>i<n0||!V2_KILL.has(f.k));
  for(let i=n0;i<fx.length;i++){const f=fx[i];if(f.k==='meteor'||f.k==='beam')f.v2=1;}
  for(const z of gfx)if(z.id===id&&!z.trap&&z.t<.05)z.v2=1;
  switch(s.type){
    case 'slash':case 'execute':v2Push('slash',{x:px,y:py-14,ang,r:s.r*(s.type==='execute'?1:.9),arc:s.arc,pl,dur:.46,follow:1});if(s.cross)v2Push('cross',{x:px+Math.cos(ang)*s.r*.55,y:py+Math.sin(ang)*s.r*.55-10,ang,r:s.r*.8,pl,dur:.7});break;
    case 'nova':v2Push('nova',{x:px,y:py,r:s.r,pl,dur:.85});if(s.cross)v2Push('cross',{x:px,y:py-10,ang:0,r:s.r*.8,pl,dur:.7});break;
    case 'burst':v2Push('nova',{x:tgt.x,y:tgt.y,r:s.r,pl,dur:.8});break;
    case 'heal':v2Push('heal',{x:px,y:py,r:90,pl,dur:1.15,follow:1});break;
    case 'revive':v2Push('heal',{x:px,y:py,r:120,pl,dur:1.4,follow:1});v2Push('cross',{x:px,y:py-40,ang:0,r:100,pl,dur:1});break;
    case 'buff':v2Push('buff',{x:px,y:py,r:46,pl,dur:Math.min(8,s.dur||6),follow:1,persist:1});break;
    case 'dome':v2Push('dome',{x:px,y:py,r:s.r,pl,dur:Math.min(s.dur||6,10),follow:1,persist:1});if(P.dome)P.dome.v2=1;break;
    case 'summon':v2Push('summon',{x:px,y:py,r:72,pl,dur:1.3});break;
    case 'dash':{const a=s.back?ang+Math.PI:ang;v2Push('dash',{x:px,y:py,x2:px+Math.cos(a)*(s.range||200),y2:py+Math.sin(a)*(s.range||200),pl,dur:.5});break;}
    case 'leap':v2Push('dash',{x:px,y:py,x2:tgt.x,y2:tgt.y,pl,dur:.55});break;
    case 'blink':v2Push('dash',{x:px,y:py,x2:P.x,y2:P.y,pl,dur:.55});break;
  }
  if(s.dome&&P.dome&&!P.dome.v2){v2Push('dome',{x:px,y:py,r:P.dome.r,pl,dur:Math.min(s.dome,10),follow:1,persist:1});P.dome.v2=1;}
}
{const _c=castSkillNow;castSkillNow=function(id){const n0=fx.length,px=P.x,py=P.y,r=_c.apply(this,arguments);if(r&&SK[id]&&!(WT2&&WT2.noV2)){try{v2Cast(id,n0,px,py);}catch(e){}}return r;};}
{const _d=drawFx;drawFx=function(f){
  if(f.k==='v2'){if(f.t<0)return;const o=f;if(f.follow){o.x=P.x;o.y=P.y-(f.fn==='slash'?14:0);}const k=clamp(f.t/f.dur,0,1);const fn=V2[f.fn];if(!fn)return;
    fn(o,f.persist||['ground','buff','dome'].includes(f.fn)?f.t:k);return;}
  if(f.k==='meteor'&&f.v2&&!f.arrows){if(f.t<0)return;const p=clamp(f.t/f.fall,0,1);V2.meteor({x:f.x,y:f.y,r:f.r,pl:f.pl},p*.55);return;}
  if(f.k==='beam'&&f.v2){const k=clamp(f.t/f.dur,0,1);V2.beam({x:f.x,y:f.y,ang:f.ang,len:f.len,w:f.w,pl:f.pl},k);return;}
  return _d.apply(this,arguments);};}
{const _u=updFx;updFx=function(dt){for(const f of fx)if(f.k==='meteor'&&f.v2&&!f.arrows&&!f.v2i&&f.t+dt>=f.fall){f.v2i=1;fx.push({k:'v2',fn:'meteorHit',x:f.x,y:f.y,r:f.r,pl:f.pl,t:0,dur:.75});}return _u.apply(this,arguments);};}
V2.meteorHit=(o,k)=>V2.meteor(o,.55+.45*k);
{const _dg=drawGround;drawGround=function(z){if(z.v2&&!z.trap)return drawGroundV2(z);return _dg.apply(this,arguments);};}
{const _dp=drawProj;drawProj=function(p){if(p.team==='e'||!p.pl)return _dp.apply(this,arguments);
  const k=p.kind,pl=p.pl;let vk=null;if(k==='arrow')vk='arrow';else if(k==='crescent')vk='wind';else if(!k||k==='orb'){vk=p.elem==='fire'?'fire':p.elem==='ice'?'ice':p.elem==='holy'?'holy':p.elem==='void'?'void':pl.part==='smoke'?'void':pl.part==='shard'?'ice':pl.part==='feather'?'holy':'orb';}
  if(!vk)return _dp.apply(this,arguments);V2.proj({x:p.x,y:p.y,ang:Math.atan2(p.vy,p.vx),pl,kind:vk,size:Math.max(12,Math.min(30,(p.size||10)*1.5)),trail:70},time);};}

