  // ground disc + stone ring
  const dg=ctx.createRadialGradient(x,y,10,x,y,300);dg.addColorStop(0,'rgba(60,110,190,.55)');dg.addColorStop(.55,'rgba(22,40,84,.55)');dg.addColorStop(1,'rgba(10,18,44,0)');
  ctx.save();ctx.translate(x,y);ctx.scale(1,NXK);ctx.fillStyle=dg;ctx.beginPath();ctx.arc(0,0,300,0,TAU);ctx.fill();ctx.restore();
  for(let i=0;i<48;i++){const a0=i/48*TAU,a1=(i+1)/48*TAU-.012;nxBand(x,y,262,290,a0,a1,i%2?'rgba(46,66,116,.85)':'rgba(66,92,150,.85)');}
  for(let i=0;i<24;i++){const a0=i/24*TAU,a1=(i+1)/24*TAU-.02;nxBand(x,y,206,252,a0,a1,i%2?'rgba(24,38,78,.6)':'rgba(34,54,104,.6)');}
  add();
  nxRing(x,y,290,2.2,'#7fc8ff',.55);nxRing(x,y,262,1.6,'#5ef0e0',.7);nxRing(x,y,252,1,'#ffbe5c',.5);nxRing(x,y,206,2,'#ffbe5c',.75);
  nxRing(x,y,235,1.6,'#5ef0e0',.6,[18,8,4,8],t*.3);nxRing(x,y,176,2.4,'#8dffc8',.7,[30,10],-t*.4);nxRing(x,y,150,1.4,'#7fc8ff',.55,[4,6],t*.5);nxRing(x,y,118,2,'#ffbe5c',.7);nxRing(x,y,84,2.2,'#5ef0e0',.85,[12,5],-t*.8);
  for(let i=0;i<72;i++){const an=i/72*TAU,r0=i%6?196:186,X0=x+Math.cos(an)*206,Y0=y+Math.sin(an)*206*NXK,X1=x+Math.cos(an)*r0,Y1=y+Math.sin(an)*r0*NXK;ctx.strokeStyle=rgba('#ffbe5c',i%6?.35:.8);ctx.lineWidth=i%6?1:1.6;ctx.beginPath();ctx.moveTo(X0,Y0);ctx.lineTo(X1,Y1);ctx.stroke();}
  nxGlyphRing(x,y,276,32,6,'#7fc8ff',.9,t*.05,1);nxGlyphRing(x,y,229,24,5,'#5ef0e0',.9,-t*.12,7);nxGlyphRing(x,y,192,18,5,'#ffbe5c',.9,t*.18,3);nxGlyphRing(x,y,134,12,6,'#8dffc8',.9,-t*.3,5);
  nxStar(x,y,176,6,2,t*.15,'#8dffc8',.8,1.8);nxStar(x,y,176,6,2,t*.15+Math.PI,'#5ef0e0',.6,1.2);nxStar(x,y,150,12,5,-t*.22,'#ffbe5c',.55,1.2);nxStar(x,y,118,5,2,t*.3,'#ffffff',.65,1.4);
  for(let i=0;i<6;i++){const an=i/6*TAU+t*.15,X=x+Math.cos(an)*176,Y=y+Math.sin(an)*176*NXK;glow(X,Y,9,'#8dffc8',.7);glow(X,Y,3,'#ffffff',.9);}
  glow(x,y,130,'#5ef0e0',.35+.1*Math.sin(t*2));glow(x,y,240,'#2f9cff',.22);
  const pk=(t%3.2)/3.2;nxRing(x,y,300*pk,3.5*(1-pk)+.5,'#ffffff',.6*(1-pk));nxRing(x,y,300*Math.max(0,pk-.18),2*(1-pk)+.4,'#5ef0e0',.5*(1-pk));
