  // energy arcs pillar tops → crystal and between neighbours
  add();for(let i=0;i<6;i++){const c=caps[i],d=caps[(i+1)%6];if(!c||!d)continue;const on=.35+.35*Math.sin(t*2.2+i);
    ctx.strokeStyle=rgba('#8dffc8',on*.5);ctx.lineWidth=1.2;ctx.beginPath();ctx.moveTo(c[0],c[1]);ctx.lineTo(x,cyC);ctx.stroke();
    const k=(t*.5+i/6)%1;glow(c[0]+(x-c[0])*k,c[1]+(cyC-c[1])*k,5,'#ffffff',.9*Math.sin(k*Math.PI));
    ctx.strokeStyle=rgba('#5ef0e0',on);ctx.lineWidth=1.4;ctx.beginPath();ctx.moveTo(c[0],c[1]);const N=12;for(let j=1;j<=N;j++){const q=j/N,X=c[0]+(d[0]-c[0])*q,Y=c[1]+(d[1]-c[1])*q-Math.sin(q*Math.PI)*26+(j<N?(nxH(j+Math.floor(t*10)*3+i)-.5)*7:0);ctx.lineTo(X,Y);}ctx.stroke();}
