/* ---------- Void slash: demon hand instead of sword (3 designs) ---------- */
V2.VH=2;
function vhFinger(bx,by,ang,len,w,curl,fill,edge,claw,clawCol,segs,knuckle){
  const n=segs||3;let x=bx,y=by,a=ang;const L=[],R=[],J=[];
  for(let i=0;i<=n;i++){const q=i/n,ww=w*(1-q*.5);L.push([x+Math.cos(a+1.5708)*ww/2,y+Math.sin(a+1.5708)*ww/2]);R.push([x+Math.cos(a-1.5708)*ww/2,y+Math.sin(a-1.5708)*ww/2]);J.push([x,y,a,ww]);if(i<n){x+=Math.cos(a)*len/n;y+=Math.sin(a)*len/n;a+=curl;}}
  ctx.fillStyle=fill;ctx.beginPath();ctx.moveTo(L[0][0],L[0][1]);for(let i=1;i<=n;i++)ctx.lineTo(L[i][0],L[i][1]);ctx.lineTo(R[n][0],R[n][1]);for(let i=n-1;i>=0;i--)ctx.lineTo(R[i][0],R[i][1]);ctx.closePath();ctx.fill();
  if(edge){ctx.strokeStyle=edge;ctx.lineWidth=1.2;ctx.stroke();}
  if(knuckle)for(let i=1;i<n;i++){ctx.fillStyle=knuckle;ctx.beginPath();ctx.arc(J[i][0],J[i][1],J[i][3]*.62,0,TAU);ctx.fill();if(edge){ctx.stroke();}}
  if(claw){const tx=x,ty=y,ww=w*.45;ctx.fillStyle=clawCol;ctx.beginPath();ctx.moveTo(tx+Math.cos(a+1.5708)*ww/2,ty+Math.sin(a+1.5708)*ww/2);
    ctx.quadraticCurveTo(tx+Math.cos(a)*claw*.6+Math.cos(a+1.5708)*ww*.3,ty+Math.sin(a)*claw*.6+Math.sin(a+1.5708)*ww*.3,tx+Math.cos(a+.35)*claw,ty+Math.sin(a+.35)*claw);
    ctx.quadraticCurveTo(tx+Math.cos(a)*claw*.5+Math.cos(a-1.5708)*ww*.5,ty+Math.sin(a)*claw*.5+Math.sin(a-1.5708)*ww*.5,tx+Math.cos(a-1.5708)*ww/2,ty+Math.sin(a-1.5708)*ww/2);ctx.closePath();ctx.fill();}
  return [x,y,a];
}
