    ctx.fillStyle=sh;ctx.beginPath();ctx.ellipse(x,hipY,z*.48,z*.21,0,0,TAU);ctx.fill();
    skBone(x,hipY,x+f*1,shY,3.2,bone,ed);
    // chest plate
    ctx.fillStyle=iron;ctx.strokeStyle=ed;ctx.lineWidth=1.2;ctx.beginPath();ctx.moveTo(x-z*.5,shY);ctx.lineTo(x+z*.5,shY);ctx.lineTo(x+z*.36,shY+H*.25);ctx.lineTo(x-z*.36,shY+H*.25);ctx.closePath();ctx.fill();ctx.stroke();
    ctx.fillStyle=iron2;for(const rx of [-.3,.3])for(const ry of [.06,.18]){ctx.beginPath();ctx.arc(x+rx*z,shY+H*ry,1,0,TAU);ctx.fill();}
    ctx.strokeStyle=bone;ctx.lineWidth=1.5;for(let i=0;i<2;i++){const yy=shY+H*.28+i*4;ctx.beginPath();ctx.moveTo(x,yy);ctx.quadraticCurveTo(x+f*z*.35,yy,x+f*z*.3,yy+3);ctx.stroke();}
