  g.fillStyle='rgba(255,255,255,.22)';g.beginPath();g.moveTo(pts[5][0],pts[5][1]);g.lineTo(pts[6][0],pts[6][1]);g.lineTo(pts[7][0],pts[7][1]);g.lineTo(x,y-14*s);g.fill();
