    ctx.setLineDash([26,20]);ctx.lineDashOffset=-t*90;ctx.strokeStyle=rgba('#ffffff',.7*fade);ctx.lineWidth=2.4;ctx.beginPath();ctx.ellipse(x,y,r*.28,r*.28*.32,-.12,0,TAU);ctx.stroke();ctx.setLineDash([]);
