    for(let j=1;j<=9;j++){const rr=r*j/9,al=(.25+.5*(1-j/9))*fade,wave=.5+.5*Math.sin(-t*5+j*.9);ctx.strokeStyle=rgba(j%3?pl.main:pl.accent,al*(.55+.45*wave));ctx.lineWidth=1.4+wave*1.6;ctx.beginPath();ctx.ellipse(x,y+dep(rr),rr,rr*K,0,0,TAU);ctx.stroke();}
