    for(let a=0;a<20;a++){const ang=a/20*TAU+t*.12;ctx.strokeStyle=rgba(pl.main,.42*fade);ctx.lineWidth=1.2;ctx.beginPath();for(let s=0;s<=16;s++){const rr=r*(1-s/16*.96);const X=x+Math.cos(ang)*rr,Y=y+Math.sin(ang)*rr*K+dep(rr);s?ctx.lineTo(X,Y):ctx.moveTo(X,Y);}ctx.stroke();}
