    const cy=y+dep(r*.04);glow(x,cy,r*.3,pl.glow,.7*fade);norm();const cg=ctx.createRadialGradient(x-6,cy-8,2,x,cy,r*.12);cg.addColorStop(0,'#3a2070');cg.addColorStop(.6,'#0a0218');cg.addColorStop(1,'#000000');ctx.globalAlpha=fade;ctx.fillStyle=cg;ctx.beginPath();ctx.ellipse(x,cy,r*.12,r*.12*.9,0,0,TAU);ctx.fill();ctx.strokeStyle=rgba(pl.accent,.9);ctx.lineWidth=2;ctx.stroke();add();
    // orbiting rock debris dragged in
    for(let i=0;i<9;i++){const k=(t*.26+i/9)%1,u=1-k,rr=r*.96*u,a=i*2.7+k*3.6,X=x+Math.cos(a)*rr,Y=y+Math.sin(a)*rr*K+dep(rr)-Math.sin(k*Math.PI)*22;norm();ctx.globalAlpha=fade*Math.min(1,k*6)*Math.min(1,u*5);const sz=(5+((i*7)%6))*(.4+u*.6);ctx.fillStyle='rgba(0,0,0,.35)';ctx.beginPath();ctx.ellipse(X,Y+sz*1.6,sz*.9,sz*.3,0,0,TAU);ctx.fill();ctx.fillStyle=cVG(ctx,0,Y-sz,Y+sz,'#b8a8d8','#4a3a78');ctx.beginPath();for(let q=0;q<6;q++){const aa=q/6*TAU+i,rr2=sz*(.75+((q*5+i)%3)*.18);q?ctx.lineTo(X+Math.cos(aa)*rr2,Y+Math.sin(aa)*rr2*.8):ctx.moveTo(X+Math.cos(aa)*rr2,Y+Math.sin(aa)*rr2*.8);}ctx.closePath();ctx.fill();ctx.strokeStyle='rgba(20,10,40,.6)';ctx.lineWidth=1;ctx.stroke();add();}
    gvMotes(x,y+dep(r*.4)*.4,r*.8,K,t,14,'#e8d0ff',3.6,2.8);v2Ring(x,y,r,r*K,pl.main,.7*fade,2.4,0);norm();
