    // ground cracks (fixed pattern)
    ctx.strokeStyle=rgba('#0a0018',.85*fade);ctx.lineWidth=3;ctx.lineCap='round';for(let i=0;i<11;i++){const a=i/11*TAU+.3;ctx.beginPath();let px=x+Math.cos(a)*r*.12,py=y+Math.sin(a)*r*.12*K;ctx.moveTo(px,py);for(let s=1;s<=6;s++){const rr=r*(.12+s*.14)+((i*13+s*7)%9)-4,aa=a+(((i*5+s*3)%7)-3)*.035;px=x+Math.cos(aa)*rr;py=y+Math.sin(aa)*rr*K;ctx.lineTo(px,py);}ctx.stroke();}
    add();ctx.strokeStyle=rgba(pl.accent,.45*fade);ctx.lineWidth=1.2;for(let i=0;i<11;i++){const a=i/11*TAU+.3;ctx.beginPath();let px=x+Math.cos(a)*r*.12,py=y+Math.sin(a)*r*.12*K;ctx.moveTo(px,py);for(let s=1;s<=6;s++){const rr=r*(.12+s*.14)+((i*13+s*7)%9)-4,aa=a+(((i*5+s*3)%7)-3)*.035;px=x+Math.cos(aa)*rr;py=y+Math.sin(aa)*rr*K;ctx.lineTo(px,py);}ctx.stroke();}
    // seal rings + hexagram + pentagon
    v2Ring(x,y,r,r*K,pl.main,.9*fade,3.2,0);v2Ring(x,y,r*.9,r*.9*K,pl.accent,.6*fade,1.6,t*.5,[16,9]);v2Ring(x,y,r*.5,r*.5*K,pl.main,.6*fade,2,-t*.7,[4,8]);
    const poly=(n,rad,rot,col,al,lw,skip)=>{ctx.strokeStyle=rgba(col,al*fade);ctx.lineWidth=lw;ctx.beginPath();for(let i=0;i<=n;i++){const a=rot+i*(skip||1)*TAU/n;const X=x+Math.cos(a)*rad,Y=y+Math.sin(a)*rad*K;i?ctx.lineTo(X,Y):ctx.moveTo(X,Y);}ctx.stroke();};
    poly(3,r*.8,t*.35-Math.PI/2,pl.core,.85,2.2);poly(3,r*.8,t*.35+Math.PI/2,pl.core,.85,2.2);poly(5,r*.44,-t*.5,pl.accent,.85,1.8,2);
    v2Glyphs(x,y,r*.95,r*.95*K,22,pl.core,.75*fade,t*.4,7);v2Glyphs(x,y,r*.66,r*.66*K,10,pl.accent,.7*fade,-t*.8,5);
