    // heavy centre: crushing orb + weight rings
    glow(x,y,r*.32,pl.glow,.7*fade);norm();const og=ctx.createRadialGradient(x-6,y-10,2,x,y,r*.14);og.addColorStop(0,'#5a3a9a');og.addColorStop(.6,'#100428');og.addColorStop(1,'#000');ctx.globalAlpha=fade;ctx.fillStyle=og;ctx.beginPath();ctx.ellipse(x,y-8,r*.13,r*.13,0,0,TAU);ctx.fill();ctx.strokeStyle=rgba(pl.accent,.95);ctx.lineWidth=2.2;ctx.stroke();add();
    gvPulseIn(x,y,r,K,t,pl.accent,2,.6*fade);
    // dark pillars pressing down
    for(let i=0;i<6;i++){const a=i/6*TAU+t*.25,px=x+Math.cos(a)*r*.6,py=y+Math.sin(a)*r*.6*K,h=110+18*Math.sin(t*3+i);const gr=ctx.createLinearGradient(px,py-h,px,py);gr.addColorStop(0,rgba(pl.main,0));gr.addColorStop(1,rgba(pl.main,.42*fade));ctx.fillStyle=gr;ctx.fillRect(px-7,py-h,14,h);glow(px,py,16,pl.accent,.5*fade);}
