  g.strokeStyle=p.inlay;g.lineWidth=2;g.globalAlpha=.55;for(let j=0;j*T<H;j++){g.beginPath();g.moveTo(0,j*T);g.lineTo(W,j*T);g.stroke();}for(let i=0;i*T<W;i++){g.beginPath();g.moveTo(i*T,0);g.lineTo(i*T,H);g.stroke();}g.globalAlpha=1;
