  g.strokeStyle=p.inlay;g.lineWidth=8;g.globalAlpha=.8;g.strokeRect(70,30,W-140,H-90);g.globalAlpha=.45;g.lineWidth=3;g.strokeRect(92,52,W-184,H-134);g.globalAlpha=1;
  // aisle carpet
  const cx=CTH_CX,x0=cx-100,x1=cx+100,y0=560;
