  g.fillStyle=cVG(g,0,0,B,p.wall0,p.wall2);g.fillRect(0,0,W,B);
  g.save();g.beginPath();g.ellipse(cx,320,cx,320,0,Math.PI,0);g.lineTo(W,320);g.lineTo(0,320);g.closePath();g.clip();
  g.fillStyle=cVG(g,0,0,320,p.v0,p.v1);g.fillRect(0,0,W,330);
  for(let k=0;k<6;k++){const s=1-k*.15;g.strokeStyle=k%2?p.goldD:p.gold;g.lineWidth=k%2?4:9;g.beginPath();g.ellipse(cx,320,cx*s,320*s,0,Math.PI,0);g.stroke();
    if(k<5){g.fillStyle=`rgba(255,240,200,${.05+.02*k})`;g.beginPath();g.ellipse(cx,320,cx*(s-.075),320*(s-.075),0,Math.PI,0);g.fill();}}
