  const med=[[cx,150,190,84],[cx-540,210,150,70],[cx+540,210,150,70],[cx-1050+150,280,90,44]];
  const pm=(mx,my,rx,ry)=>{g.save();g.beginPath();g.ellipse(mx,my,rx,ry,0,0,TAU);g.clip();g.fillStyle=cVG(g,0,my-ry,my+ry,p.sky0,p.sky1);g.fillRect(mx-rx,my-ry,rx*2,ry*2);
    g.fillStyle='rgba(255,255,255,.55)';for(let i=0;i<6;i++)g.beginPath(),g.ellipse(mx+srr(-rx*.7,rx*.7),my+srr(-ry*.5,ry*.6),rx*srr(.18,.34),ry*srr(.16,.3),0,0,TAU),g.fill();
    g.fillStyle=CATHV?'rgba(255,255,255,.9)':'rgba(255,214,120,.55)';if(CATHV){for(let i=0;i<40;i++){g.beginPath();g.arc(mx+srr(-rx,rx),my+srr(-ry,ry),srr(.8,2),0,TAU);g.fill();}}else{g.beginPath();g.arc(mx,my-ry*.1,ry*.34,0,TAU);g.fill();}
    g.restore();g.strokeStyle=p.gold;g.lineWidth=6;g.beginPath();g.ellipse(mx,my,rx,ry,0,0,TAU);g.stroke();g.strokeStyle=p.goldD;g.lineWidth=2;g.beginPath();g.ellipse(mx,my,rx+6,ry+6,0,0,TAU);g.stroke();};
  pm(med[0][0],med[0][1],med[0][2],med[0][3]);pm(med[1][0],med[1][1],med[1][2],med[1][3]);pm(med[2][0],med[2][1],med[2][2],med[2][3]);
  g.restore();
  // cornice
  cthGold(g,0,318,W,22);g.fillStyle=p.goldD;for(let x=6;x<W;x+=26)g.fillRect(x,340,12,10);cthGold(g,0,350,W,10);
  // pilasters + bays
  const bays=[[40,300],[300,560],[560,790],[1110,1340],[1340,1600],[1600,1860]];
  for(const [a,b] of bays)cthBay(g,a,b,B-8,230,(a/100|0),120);
  for(const x of [40,300,560,790,1110,1340,1600,1860])cthPilaster(g,x,372,B,x===40||x===1860?70:52);
  // central apse: arched opening full of light
  const aw=520,ah=380,ab=B-8;
  cArch(g,cx,ab,aw+60,ah+30,true);g.fillStyle=cVG(g,0,ab-ah,ab,p.gold,p.goldD);g.fill();
  cArch(g,cx,ab,aw,ah,true);g.save();g.clip();
  const rg=g.createRadialGradient(cx,ab-ah*.42,10,cx,ab-ah*.42,300);rg.addColorStop(0,'#ffffff');rg.addColorStop(.3,p.light);rg.addColorStop(1,CATHV?'#5a78e0':'#e8a850');g.fillStyle=rg;g.fillRect(cx-aw,ab-ah-10,aw*2,ah+20);
  g.strokeStyle='rgba(255,255,255,.4)';g.lineWidth=3;for(let i=0;i<22;i++){const a=(i/22)*TAU;g.beginPath();g.moveTo(cx,ab-ah*.42);g.lineTo(cx+Math.cos(a)*360,ab-ah*.42+Math.sin(a)*360);g.stroke();}
  for(let r=1;r<=4;r++){g.strokeStyle=`rgba(255,255,255,${.5-r*.08})`;g.lineWidth=2;g.beginPath();g.arc(cx,ab-ah*.42,r*58,0,TAU);g.stroke();}
  g.restore();
  for(const s of [-1,1]){g.fillStyle=cVG(g,0,ab-ah,ab,p.gold,p.goldD);g.fillRect(cx+s*(aw/2+20)-8,ab-ah*.62,16,ah*.62);}
  // banners beside the apse
  for(const s of [-1,1]){const bx=cx+s*370;g.fillStyle=p.ban;g.beginPath();g.moveTo(bx-28,380);g.lineTo(bx+28,380);g.lineTo(bx+28,600);g.lineTo(bx,626);g.lineTo(bx-28,600);g.closePath();g.fill();
    g.strokeStyle=p.gold;g.lineWidth=3;g.stroke();g.fillStyle=p.gold;cPoly(g,[[bx,430],[bx+12,480],[bx,530],[bx-12,480]],p.gold);cthGold(g,bx-34,372,68,10);}
  // bottom shade + vignette
  const vs=g.createLinearGradient(0,B-150,0,B);vs.addColorStop(0,'rgba(0,0,0,0)');vs.addColorStop(1,`rgba(${CATHV?'6,10,44':'58,34,10'},.35)`);g.fillStyle=vs;g.fillRect(0,B-150,W,150);
