/* ===== p75: Spear stance & attack poses (Inquisitor / Judicator) — two-handed grip on top of the v31 IK rig (p36) =====
   x = right, y = up, z = forward (body space). h = rear (right) hand, d = shaft direction, ls = front-hand offset along the shaft.
   Ready · Carry(run) · Couch(charge) · Raise(cast) · Draw→Lunge (3 thrust variants) · Sweep · Spin(360°) · Sky→Dive (leap)                */
const SPG={
  ready:{h:[2.5,10.8,1.0],d:V3n([-.14,.40,1])},
  carry:{h:[2.9,10.0,.3],d:V3n([-.06,.22,1])},
  couch:{h:[3.6,11.2,2.2],d:V3n([-.02,.04,1])},
  raise:{h:[2.6,17.2,.6],d:V3n([.1,.95,.3])},
  drawA:{h:[3.0,11.8,-1.8],d:V3n([-.05,.16,1])},  lungeA:{h:[2.4,12.6,4.6],d:V3n([-.02,.05,1])},
  drawB:{h:[2.8,9.4,-.8],d:V3n([0,-.30,1])},      lungeB:{h:[2.4,13.8,4.2],d:V3n([-.02,.34,1])},
  sweepA:{h:[4.6,17.6,-.8],d:V3n([.5,.62,.5])},   sweepB:{h:[-1.2,11.0,3.4],d:V3n([-.78,-.28,.6])},
  sky:{h:[2.8,19.2,.2],d:V3n([.1,.92,.4])},       dive:{h:[2.6,18.4,1.8],d:V3n([0,-.86,.5])}};
const SP_LS=-3.0;
const spMix=(A,B,k)=>gmix(A,B,k);
function spPose(o){const t=o.t||0,sw=o.sw;let g,legs=null;
  const L=(a,b,c,d2,e)=>[a,b,c,d2,e];
  if(o.attack&&sw){
    const k=Math.min(1,sw.t/sw.dur);
    if(sw.type==='arc'&&Math.abs((sw.a1||0)-(sw.a0||0))>5){                 // Whirling Lance: 360° spin, shaft held level at the chest
      const th=k*Math.PI*2;g={h:[.8,13.0,.9],d:V3n([Math.sin(th),.06,Math.cos(th)])};legs=L(.35,-.35,.5,.5,.06);}
    else if(sw.type==='arc'||sw.type==='heavy'){                            // overhead diagonal cut
      const e=gsEase(Math.min(1,k/.85));g=spMix(SPG.sweepA,SPG.sweepB,e);legs=L(.6+e*.4,-.55,.3+e*.3,.1,.16+e*.06);}
    else{                                                                    // thrust — 3 variants (or a quick jab chain from the skill)
      const v=sw.sp!=null?sw.sp:(((P.chain||1)-1)%3+3)%3;
      if(v===2){const e=gsEase(Math.min(1,k/.8));g=spMix(SPG.sweepA,SPG.sweepB,e);legs=L(.7+e*.35,-.6,.35+e*.3,.1,.2);}
      else{const D=v===0?SPG.drawA:SPG.drawB,U=v===0?SPG.lungeA:SPG.lungeB;
        const a1=.26,a2=.5,a3=.68;let p;
        if(k<a1){g=spMix(SPG.ready,D,eOut(k/a1));p=eOut(k/a1)*0;}
        else if(k<a2){p=gsEase((k-a1)/(a2-a1));g=spMix(D,U,p);}
        else if(k<a3){g=U;p=1;}
        else{p=1-gsEase((k-a3)/(1-a3));g=spMix(SPG.ready,U,p*.9);}
        legs=L(.3+.7*p,-.3-.5*p,.35+.3*p,.12,.08+.16*p);}}
  }else if(o.jmp){
    const D=!o.pv&&P.dash&&P.dash.leap?P.dash:null,k=D?clamp(1-D.t/D.dur,0,1):.4;
    g=k<.5?spMix(SPG.raise,SPG.sky,eOut(k*2)):spMix(SPG.sky,SPG.dive,gsEase((k-.5)*2));
  }else if(o.cast)g=SPG.raise;
  else if(o.dash){g=SPG.couch;}
  else if(o.run){const b=Math.sin(o.ph||0)*.3;g={h:[SPG.carry.h[0],SPG.carry.h[1]+b,SPG.carry.h[2]],d:SPG.carry.d};}
  else{const M=SPG.ready,bob=o.walk?Math.abs(Math.cos(o.ph||0))*.3:Math.sin(t*2.2)*.12;g={h:[M.h[0],M.h[1]+bob,M.h[2]],d:M.d};}
  return {h:g.h,d:g.d,ls:SP_LS,legs};}
{const _g=gsPose;gsPose=function(o){return o&&o.wt==='spear'?spPose(o):_g.apply(this,arguments);};}
// spear foreshortening (shaft pointing at the camera looks shorter) — same trick as the greatsword
{const _dw=drawWeapon_v1;drawWeapon_v1=function(g,wt,x,y,a,sc,pl,live){if(wt!=='spear'||!live)return _dw.apply(this,arguments);
  g.save();g.translate(x,y);g.rotate(a);g.scale(Math.max(.5,GS_FORE)*1.4,1.1);g.rotate(-a);g.translate(-x,-y);try{return _dw.apply(this,arguments);}finally{g.restore();}};}
