{const _gs=wkGuideSpec;wkGuideSpec=function(cat,id){return _gs.call(this,cat==='weapon'&&String(id).includes(':')?'unique':cat,id);};}
{const _r=wkRender;wkRender=function(){
  const E0=WK.E;
  for(const e of E0)if(e.cat==='card'&&!e._s){e._s=1;e.search=(e.search||'')+' ใส่เฉพาะ '+(SLOT_CAT_TH[e.chip]||'')+' '+(SLOT_CAT_TH[e.chip]||'');}
  const base=E0.filter(e=>e.cat!=='unique'),uq=E0.filter(e=>e.cat==='unique').map(e=>Object.assign({},e,{cat:'weapon'}));
  const wi=base.map(e=>e.cat).lastIndexOf('weapon');base.splice(wi<0?base.length:wi+1,0,...uq);
  WK.E=base;try{return _r.apply(this,arguments);}finally{WK.E=E0;}};}
