/* ===== p88 (v99): combat warp-lock hardening — ANY damage to the player, or an awake monster right next to them, keeps the 4 s warp lock on ===== */
{const _hp=hurtPlayer;hurtPlayer=function(raw,src){if(G.zone!=='devlab'&&!(src&&src.dev))CMB.t=time;return _hp.apply(this,arguments);};}
{const _u=update;update=function(dt){_u.apply(this,arguments);
  if(G.state==='play'&&P&&!P.dead&&G.zone!=='devlab'&&!(ZONES[G.zone]&&ZONES[G.zone].safe))
    for(const e of enemies)if(!e.dead&&!e.dev&&e.aggro&&(e.hp>0)&&d2(e.x,e.y,P.x,P.y)<e.sz+130){CMB.t=time;break;}};}
/* p89 (v100): themed impassable border on every map + camera overscroll so the character never hides behind the HUD at edges */
window.EDGE_BG=null;
PROP_DEFS.edgeBlock={n:'Edge Block',cat:'misc',w:2,h:2,ax:1,ay:1,solid:[{dx:0,dy:0,r:46}],draw(){}};
const EDGE_THEME={
  capital:['jungleTree','crystalLamp','jungleTree','streetlight'],
  jungle:['ancientTree','jungleTree','mossRock','jungleTree','jungleTree'],
  desert:['sandstone','palm','cactus','sandstone','palm'],
  wasteland:['ruinPillar','deadTree','boulder','ruinArch','deadTree'],
  snow:['pine','iceCrystal','pine','boulder','snowman'],
  lava:['obsidian','deadTree','obsidian','ruinPillar','lavaPool'],
  deepsea:['seaRock','coral','seaweed','seaRock','coral'],
  dark:['voidShard','ruinPillar','obsidian','voidShard','deadTree']
};
function edgeEligible(zid){const Z=ZONES[zid];return !!Z&&!Z.interior&&zid!=='devlab'&&zid!=='cathedral';}
function edgeProps(zid){
  const Z=ZONES[zid],th=EDGE_THEME[Z.base||zid]||EDGE_THEME[Z.pk]||EDGE_THEME.dark,out=[];
  let gs=[];try{gs=gatesFor(zid).map(g=>[g.x,g.y]);}catch(e){}
  if(Z.way)gs.push(Z.way);if(Z.nexus)gs.push(Z.nexus);
  const nearG=(x,y,d)=>gs.some(g=>Math.hypot(g[0]-x,g[1]-y)<d);
  let s=(Z.seed||7)*131+17;const rn=()=>{s=(s*1103515245+12345)&0x7fffffff;return s/0x7fffffff;};
  const W=Z.w,H=Z.h;
  const line=(fn,L)=>{
    // invisible solid wall (spacing 64, radius 46) + two rows of themed props
    for(let d=0;d<=L;d+=64){const [x,y]=fn(d,62);if(nearG(x,y,175))continue;out.push({t:'edgeBlock',x,y,s:1,v:0,f:1,ph:0,edge:1,nc:0});}
    let i=0;for(let d=20;d<=L;d+=78+Math.floor(rn()*26)){
      for(const row of [0,1]){const dd=d+(row?38:0);if(dd>L)continue;const [x,y]=fn(dd,row?118:38);if(nearG(x,y,520))continue;
        const t=th[(i+row*2)%th.length];i++;out.push({t,x:Math.round(x),y:Math.round(y),s:+(0.95+rn()*.55).toFixed(2),v:Math.floor(rn()*3),f:rn()<.5?-1:1,ph:rn()*6.28,edge:1});}}
  };
  line((d,o)=>[d,o],W);line((d,o)=>[d,H-o],W);line((d,o)=>[o,d],H);line((d,o)=>[W-o,d],H);
  return out;
}
{const _b=buildSolids;buildSolids=function(){
  try{if(edgeEligible(G.zone)){if(!PROPS.some(p=>p.edge))for(const p of edgeProps(G.zone))PROPS.push(p);const Z=ZONES[G.zone];EDGE_BG=(Z.ground&&Z.ground[3])||null;}else EDGE_BG=null;}catch(e){}
  return _b.apply(this,arguments);};}
{const _c=cleanProps;cleanProps=function(){const all=PROPS;PROPS=all.filter(p=>!p.edge);try{return _c();}finally{PROPS=all;}};}
/* camera overscroll: bottom 190 (clears HUD), top 90, sides 70 */
clampCam=function(){const Z=ZONES[G.zone];
  cam.x=Z.w<VW?(Z.w-VW)/2:clamp(cam.x,-70,Z.w-VW+70);cam.y=Z.h<VH?(Z.h-VH)/2:clamp(cam.y,-90,Z.h-VH+190);};
