function rgSync(){const Z=ZONES[G.zone];if(!Z||Z.tier!==2||!/_sanctum$/.test(G.zone))return false;const b=Z.base;
  const has=PROPS.findIndex(p=>p.t==='raidGrave'),want=!!RGRAVE[b]&&!raidAlive();
  if(has>=0&&!want){PROPS.splice(has,1);return true;}
  if(has<0&&want){const p=rgMake(b);if(p){PROPS.push(p);return true;}}return false;}
