function vilShuffle(a){a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function vilStock(kind){
  if(kind==='blackmarket'){const it=vilShuffle(BM_POOL).slice(0,5).map(([id,p])=>({id,p}));
    return {items:it,w:vilShuffle(WTYPES).slice(0,2),g:vilShuffle(GEAR_TYPES).slice(0,2)};}
  const R=VIL_ROLE[kind],n=Math.min(R.pool.length,R.min+Math.floor(rng()*(R.pool.length-R.min+1)));
  return {items:vilShuffle(R.pool).slice(0,n).map(id=>({id,p:VIL_BUY[id]||ITEMS[id].price||100}))};}
function vilSpawn(){
  const Z=ZONES.jungle_sylva_village,cx=Z.w/2,cy=Z.h/2;
  const slots=vilShuffle([[-330,-150],[330,-170],[-300,230],[310,250],[0,-330]]);
  const kinds=vilShuffle(['v_herb','v_forager','v_hunter','v_elder']).slice(0,2+(rng()<.5?1:0));
  kinds.forEach((k,i)=>{const s=freeSpotNear(cx+slots[i][0],cy+slots[i][1],30)||{x:cx+slots[i][0],y:cy+slots[i][1]};NPCS.push({x:s.x,y:s.y,n:NPC_DEF[k].n,kind:k,id:'v'+i,stock:vilStock(k)});});
  if(rng()<window.SYLVA_BM_CHANCE){const s=freeSpotNear(cx,cy-40,30)||{x:cx,y:cy-40};NPCS.push({x:s.x,y:s.y,n:NPC_DEF.blackmarket.n,kind:'blackmarket',id:'bm',stock:vilStock('blackmarket')});
    setTimeout(()=>{if(G.zone==='jungle_sylva_village')log('🕶 พ่อค้าตลาดมืดปรากฏตัวกลางหมู่บ้าน — ของทุกอย่างแพงขึ้น 50%','v');},1200);}
}
