/* p94 (v106): "Gate Lock" status — taking damage seals zone gates for 5 s (no gate-escape from a fight) */
window.GLOCK={until:0,dur:5};
function gateLocked(){return !G.god&&typeof time!=='undefined'&&time<GLOCK.until;}
