/* p97 (v109): item names are coloured by weapon/gear rarity everywhere they are rendered as HTML */
function itemNameC(it){const n=itemName(it);if(!it||it.rar==null||!RARITY[it.rar]||!(it.kind==='wpn'||it.kind==='eq'||it.kind==='fash'))return typeof escH==='function'?escH(n):n;
  const c=typeof rarCol==='function'?rarCol(it.rar):RARITY[it.rar].c;return `<span class="inm" style="color:${c}">${typeof escH==='function'?escH(n):n}</span>`;}
/* v111 — "always online": the world keeps simulating while the tab is hidden / unfocused / screen folded.
   Browsers stop requestAnimationFrame in the background, so a Web Worker heartbeat drives update() with fixed 50ms steps
   and catches up on elapsed real time (capped) when the tab wakes. */
window.AWAY={on:false,last:performance.now(),ms:0,steps:0,cap:600};
{const _u=update;update=function(dt){AWAY.last=performance.now();return _u.apply(this,arguments);};}
function awayCatchUp(){
  const now=performance.now(),el=now-AWAY.last;
  if(el<200||G.state!=='play'||typeof P==='undefined'||!P)return;      // RAF is alive (or not in a run) — nothing to do
  const secs=Math.min(el/1000,AWAY.cap);let n=Math.floor(secs/.05);
  AWAY.on=true;AWAY.ms+=el;
  const t0=performance.now();
  while(n-->0&&performance.now()-t0<400){try{update(.05);}catch(e){break;}AWAY.steps++;}   // time-boxed so a tick never freezes the tab
  AWAY.last=performance.now()-Math.max(0,n)*50;   // any unsimulated remainder is handled on the next tick
}
try{
  const w=new Worker(URL.createObjectURL(new Blob(['setInterval(()=>postMessage(1),100)'],{type:'text/javascript'})));
  w.onmessage=()=>{try{awayCatchUp();}catch(e){}};
  AWAY.worker=w;
}catch(e){AWAY.fallback=setInterval(awayCatchUp,250);}
document.addEventListener('visibilitychange',()=>{if(!document.hidden)AWAY.on=false;});
/* v112 — Phase 0 online-prep (no behaviour change offline)
   1) Command layer: every state-changing player action goes through cmd(name,args) → validated → applied → {ok,err?}.
      The same commands become the network protocol later; the server will run the handlers, the client only sends them.
   2) Versioned save: SAVE_VER + saveMigrate() so old saves upgrade in one place.
   3) rng()/nowMs() live in p2.js (seedable RNG, single clock).  */
const SAVE_VER=1;
const SAVE_MIGRATIONS={ /* from-version → fn(save) — 0 = legacy saves without a "v" field */
  0(s){s.v=1;return s;}
};
function saveMigrate(s){if(!s||typeof s!=='object')return s;let v=+s.v||0;while(v<SAVE_VER){const m=SAVE_MIGRATIONS[v];if(m)s=m(s)||s;v++;s.v=v;}return s;}

const CMD={handlers:{},log:[],max:200};
function cmdDef(name,fn){CMD.handlers[name]=fn;}
function cmd(name,args){
  args=args||{};const h=CMD.handlers[name];
  if(!h)return{ok:false,err:'unknown_cmd'};
  if(typeof P==='undefined'||!P||P.dead)return{ok:false,err:'no_player'};
  let r;try{r=h(args)||{ok:true};}catch(e){r={ok:false,err:'exception',msg:String(e&&e.message||e).slice(0,120)};}
  CMD.log.push({t:nowMs(),n:name,a:args,ok:!!r.ok,err:r.err});if(CMD.log.length>CMD.max)CMD.log.shift();
  return r;
}
cmdDef('buyItem',a=>{
  const d=ITEMS[a.id];if(!d)return{ok:false,err:'bad_item'};
  const p=+a.price;if(!(p>=0)||P.gold<p)return{ok:false,err:'no_gold'};
  if(!addItem({id:a.id,q:1}))return{ok:false,err:'bag_full'};
  P.gold-=p;if(a.id==='bagScroll')P.bagUp++;log(`ซื้อ ${d.n}`);return{ok:true};});
cmdDef('buyGear',a=>{
  if(!GEAR[a.type])return{ok:false,err:'bad_item'};
  const p=+a.price;if(!(p>=0)||P.gold<p)return{ok:false,err:'no_gold'};
  const it=makeGear(a.type,P.lvl,1);if(!addItem(it))return{ok:false,err:'bag_full'};
  P.gold-=p;log(`ซื้อ ${it.name}`,'g');return{ok:true};});
cmdDef('buyWeapon',a=>{
  if(!WEAPONS[a.t])return{ok:false,err:'bad_item'};
  const p=+a.price;if(!(p>=0)||P.gold<p)return{ok:false,err:'no_gold'};
  const it=makeWeapon(a.t,P.lvl,1);if(!addItem(it))return{ok:false,err:'bag_full'};
  P.gold-=p;log(`ซื้อ ${it.name}`,'g');return{ok:true};});
cmdDef('sellShards',()=>{const n=countItem('shard'),v=((window.GOLD262&&GOLD262.on)?5:25);P.gold+=n*v;takeItem('shard',n);log(`ขาย Spirit Shard ${n} ชิ้น ได้ ${n*v} G`,'g');return{ok:true,n};});
cmdDef('refine',a=>{const f=refineList().find(o=>o.it.uid===a.uid);if(!f)return{ok:false,err:'bad_item'};refineItem(f.it);return{ok:true};});
