/* ===== p105 (v124): weapon rules by CLASS (not path) · Novice starts with a dagger · class change keeps valid gear =====
   dagger      Novice · Thief line (Thief, Assassin, Assassin Cross, Shadow Cross, Rogue, Stalker, Abyss Chaser)
   1H sword    Swordsman · Paladin · Templar · Holy Guardian
   greatsword / axe   Greatsword · Berserker · Warlord
   spear       Inquisitor · Crusader · Judicator
   bow         Archer · Ranger · Beastmaster · Warden of the Wild
   gun         Sniper · Sharpshooter · Phantom Marksman
   staff       Mage · Sorcerer · Archmage · Elemental Lord · Cleric · Priest · High Priest · Saint
   grimoire    Warlock · Necromancer · Soul Reaper
   Armor / shields keep the old path-based rules. Existing equipped items are grandfathered (never removed on load). */
const WCLASS={
  dagger:['novice','thief','assassin','assassincross','shadowcross','rogue','stalker','abysschaser'],
  sword:['swordsman','paladin','templar','holyguardian'],
  greatsword:['greatsword','berserker','warlord'],
  axe:['greatsword','berserker','warlord'],
  spear:['inquisitor','crusader','judicator'],
  bow:['archer','ranger','beastmaster','warden'],
  gun:['sniper','sharpshooter','phantombow'],
  staff:['mage','sorcerer','archmage','elementallord','cleric','priest','highpriest','saint'],
  book:['warlock','necromancer','soulreaper']
};
for(const t in WCLASS){WEAPON_CLS[t]=WCLASS[t].slice();}
for(const k in CLASSES)if(!PATH_LABEL[k])PATH_LABEL[k]=CLASSES[k].n;
const wpnRuled=it=>!!it&&it.kind==='wpn'&&it.t!=='fist'&&!!WCLASS[it.t];
{const _ic=itemClasses;itemClasses=function(it){if(wpnRuled(it))return WCLASS[it.t].slice();return _ic.apply(this,arguments);};}
{const _ce=canEquip;canEquip=function(it){if(wpnRuled(it))return WCLASS[it.t].includes(P.cls);return _ce.apply(this,arguments);};}
{const _cl=classLabel;classLabel=function(it){if(wpnRuled(it))return WCLASS[it.t].map(k=>CLASSES[k].n).join(' · ');return _cl.apply(this,arguments);};}
function canEquipAs(it,cls){const o=P.cls;P.cls=cls;try{return canEquip(it);}finally{P.cls=o;}}

/* ---------- class change: only remove what the new class cannot use (no more "strip everything") ---------- */
function stripInvalid(c){const out=[];
  for(const [s] of EQ_SLOTS){const it=P.equip&&P.equip[s]||(s==='weapon'?P.weapon:null);if(!it||(it.kind==='wpn'&&it.t==='fist'))continue;
    if(!canEquipAs(it,c)){const nm=itemName(it);if(unequip(s,true))out.push(nm);}}
  recalc();return out;}
function setClass_v3(c,silent){
  const gone=stripInvalid(c);
  setClassBase(c,silent);
  if(gone.length){log(`เปลี่ยนคลาส: ${gone.join(', ')} ใช้กับอาชีพใหม่ไม่ได้ — เก็บเข้ากระเป๋าแล้ว`,'v');if(!silent)notify(`อุปกรณ์ที่ใช้ไม่ได้ ${gone.length} ชิ้นถูกเก็บเข้ากระเป๋า`,false);}
  grantClassWeapon(silent);
  if(G.win==='wInv')renderInv();
}
/* if the new class ends up bare-handed: pick a usable weapon from the bag, else hand out a plain class weapon */
function grantClassWeapon(silent){
  if(!P.weapon||P.weapon.t!=='fist')return;
  let i=P.inv.findIndex(it=>it&&it.kind==='wpn'&&canEquip(it));
  if(i<0){const C=CLASSES[P.cls],w=makeWeapon(C.wp,Math.max(1,P.lvl),1,{plain:1});w.seal=0;
    if(!addItem(w))return;i=P.inv.indexOf(w);if(!silent)log(`ได้รับอาวุธประจำอาชีพ: ${itemName(w)}`,'g');}
  if(i>=0){equipItem(i);}
}
