/* ---------- drawing helpers ---------- */
const _tm=()=>(typeof time==='number'?time:0);
function bkRR(g,x,y,w,h,r){g.beginPath();g.roundRect(x,y,w,h,r);}
/* ---------- basic attacks ---------- */
function gunRay(a,range,w,skip){const cs=Math.cos(a),sn=Math.sin(a);let best=null,bd=1e9;
  for(const e of enemies){if(e.dead||(skip&&skip.has(e)))continue;const al=(e.x-P.x)*cs+(e.y-P.y)*sn;if(al<0||al>range+e.sz)continue;if(inLine(e,P.x,P.y,a,range,w)&&al<bd){bd=al;best=e;}}
  return best;}
function gunShot(a,range,m,pl,o){o=o||{};const w0=wCur(),mx=P.x+Math.cos(a)*26,my=P.y-10+Math.sin(a)*26,skip=new Set();let ex=P.x+Math.cos(a)*range,ey=P.y-10+Math.sin(a)*range,n=o.pierce||1,first=null;
  for(let i=0;i<n;i++){const e=gunRay(a,range,26,skip);if(!e)break;skip.add(e);if(!first)first=e;ex=e.x;ey=e.y-e.sz*.5;
    fx.push({k:'star',x:e.x,y:e.y-e.sz*.5,t:0,dur:.18,pl,s:18});hitEnemy(e,m*(i?.7:1),{dt:'phys',pl,wb:1,kb:o.kb||0});}
  fx.push({k:'tracer',x0:mx,y0:my,x1:ex,y1:ey,t:0,dur:o.dur||.16,pl,w:o.w||3});
  fx.push({k:'star',x:mx,y:my,t:0,dur:.12,pl,s:o.flash||16});
  return first;}
function gunAttack(k,ang,mm,pl,W_,dt){
  P.swing={t:0,dur:.14,type:'bow',ang};
  const w=wCur(),F=w?wDef(w).fx:null;let m=mm;
  if(F&&F.primed&&WT4.primeT>time){m*=1+F.primed.m;WT4.primeT=0;textAt(P.x,P.y-84,'PRIMED SHOT','#ffd36b',14,{life:.7});}
  const R=W_.range;
  if(k===0)gunShot(ang,R,m,pl);
  else if(k===1){gunShot(ang-.025,R,m*.62,pl);timers.push({t:.07,fn:()=>{if(!P.dead)gunShot(ang+.025,R,m*.62,pl);}});}
  else{gunShot(ang,R,m*1.2,pl,{pierce:2,kb:60,w:5,flash:26,dur:.22});shake(2);ring(P.x+Math.cos(ang)*22,P.y-8+Math.sin(ang)*22,4,44,.3,pl.accent,4);}
  emitThemed(P.x+Math.cos(ang)*24,P.y-10+Math.sin(ang)*24,pl,4,120,{ang,spread:.5});
}
function bookAttack(k,ang,mm,pl,W_,dt){
  P.swing={t:0,dur:.22,type:'cast',ang};const R=W_.range,sp=640;
  if(k===0)fireProj({ang,spd:sp,m:mm,dt,pl,kind:'orb',size:10,range:R});
  else if(k===1){for(const d of [-.13,.13])fireProj({ang:ang+d,spd:sp,m:mm*.62,dt,pl,kind:'orb',size:8,range:R});}
  else{fireProj({ang,spd:500,m:mm*1.15,dt,pl,kind:'orb',size:16,range:R,aoe:70});ring(P.x+Math.cos(ang)*26,P.y-10+Math.sin(ang)*26,4,54,.35,pl.main,5);}
}

