/* ---------- text ---------- */
{const _f=wFxLines;wFxLines=function(F){const p=v=>Math.round(v*1000)/10,o=_f.apply(this,arguments);
  for(const k in F){const v=F[k];switch(k){
    case 'skillAmp':o.push(`Skill Amplify: ดาเมจสกิลทุกชนิดของคุณ +${p(v.m)}%`);break;
    case 'primed':o.push(`Primed Round: หลังร่ายสกิล การยิงปกตินัดถัดไปภายใน ${v.dur} วิ แรงขึ้น +${p(v.m)}%`);break;
    case 'loader':o.push(`Rune Loader: ยิงปกติติดคริติคอลลดคูลดาวน์สกิลทั้งหมด ${v.cut} วิ (ทำงานได้ทุก ${v.cd} วิ)`);break;
    case 'farAmp':o.push(`Glacial Scope: เป้าหมายไกลเกิน ${v.far} หน่วย รับดาเมจ +${p(v.m)}%`);break;
    case 'chill':o.push(`Frost Round: สกิลที่โดนทำให้ศัตรูช้าลง ${p(v.slow)}% นาน ${v.dur} วิ`);break;
    case 'railEcho':o.push(`Void Rail: สกิล ${p(v.ch)}% ยิงซ้ำอีกระลอก (Rail Echo) ดาเมจ ${p(v.m)}% ไม่เสีย SP/คูลดาวน์`);break;
    case 'cdrS':o.push(`Skill CDR −${p(v.v)}%`);break;
    case 'curse':o.push(`Lunar Curse: โจมตีปกติมีโอกาส ${p(v.ch)}% สาปเป้าหมาย ${v.dur} วิ — เป้าหมายที่ถูกสาปรับดาเมจจากคุณ +${p(v.m)}%`);break;
    case 'plague':o.push(`Plague Pages: เวทที่โดนแฝงกาฬโรค ดาเมจเวท ${p(v.dps)}% ของ MATK ต่อวินาที ต่อ 1 ขั้น (ซ้อนทับ ${v.max} ขั้น, ${v.dur} วิ)`);break;
    case 'leech':o.push(`Runic Leech: ดาเมจเวทฟื้น HP ${p(v.p)}% ของดาเมจ (สูงสุด ${p(v.cap)}% Max HP ต่อครั้ง) และฟื้น SP ${p(v.sp)}%`);break;
    case 'soulHarvest':o.push(`Soul Harvest: กำจัดศัตรูได้ MATK +${p(v.atk)}% นาน ${v.dur} วิ (ซ้อนทับ ${v.n} ขั้น) และฟื้น SP ${p(v.sp)}%`);break;
  }}
  return o;};}
