/* ---------- migration: refund old skill points, clear old hotbar slots (called from the save loader) ---------- */
function snipMigrate(){if(!P||P._snipMig)return;let back=0;
  for(const id of SNIP_OLD){if(P.skills&&P.skills[id]){back+=P.skills[id];delete P.skills[id];}if(P.cds)delete P.cds[id];}
  if(P.slots)P.slots=P.slots.map(x=>x&&SNIP_OLD.includes(x)?null:x);
  P._snipMig=1;if(back){P.skillPts=(P.skillPts||0)+back;try{log(`ระบบสกิลสายสไนเปอร์ถูกปรับใหม่ — คืนแต้มสกิล ${back} แต้ม เรียนสกิลใหม่ได้ที่หน้า Skill`,'g');}catch(e){}}}

