/* ---------- v125: save progress whenever the page is hidden / closed (autosave alone ran every 20s → progress "rolled back" on reopen) ---------- */
{const _sv=()=>{try{if(G.state==='play'&&P&&!P.dead)saveGame();}catch(e){}};
document.addEventListener('visibilitychange',()=>{if(document.hidden)_sv();});window.addEventListener('pagehide',_sv);window.addEventListener('beforeunload',_sv);}
/* verify that the save really landed (quota-full / blocked storage used to fail silently → progress "rolled back" after reload) */
{const _sg=saveGame;let warned=0;saveGame=function(){const r=_sg.apply(this,arguments);
  try{if(P&&!P.dead){const raw=localStorage.getItem(SAVE_KEY),ok=raw&&raw.indexOf('"lvl":'+P.lvl+',')>=0;
    if(window.__SV2){/* savev2: failures are reported by the shim with the exact step */}else if(!ok&&!warned&&G.state==='play'){warned=1;setTimeout(()=>{warned=0;},60000);notify('⚠ บันทึกเกมไม่สำเร็จ (พื้นที่เก็บข้อมูลเต็ม/ถูกบล็อก) — ลองล้างตัวละครสำรองหรือส่งออกเซฟ',true);}}}catch(e){}return r;};}
