  if(Z.way)Z.way=[Math.round(Z.way[0]*sx),Math.round(Z.way[1]*sy)];
  if(Z.subPos)Z.subPos=[Math.round(Z.subPos[0]*sx),Math.round(Z.subPos[1]*sy)];
  if(Z.areas)Z.areas=Z.areas.map(a=>Object.assign({},a,{x:Math.round(a.x*sx),y:Math.round(a.y*sy),r:Math.round(a.r*sr)}));
  if(Z.nexus)Z.nexus=[Z.nexus[0]*sx,Z.nexus[1]*sy];
