/* 5 · prop generator driven by the briefs */
function brGen(zid){
  const Z=ZONES[zid],B=BR[zid];let s=((Z.seed|0)*2654435761+97)>>>0;
  const rnd=()=>{s=(s+0x6D2B79F5)>>>0;let t=s;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296;};
  const gates=gatesFor(zid),out=[],grid=new Map(),CX=Z.w/2,CY=Z.h/2,village=!!B.village,MG=130;
  const lanes=gates.map(g=>[g.x,g.y,CX,CY]);
  const segD=(x,y,l)=>{const dx=l[2]-l[0],dy=l[3]-l[1],t=clamp(((x-l[0])*dx+(y-l[1])*dy)/(dx*dx+dy*dy||1),0,1);return Math.hypot(l[0]+dx*t-x,l[1]+dy*t-y);};
  const rad=(t,s)=>PROP_DEFS[t].w*.22*s,key=(x,y)=>Math.floor(x/260)+','+Math.floor(y/260);
  const place=(t,x,y,s,force)=>{const d=PROP_DEFS[t];if(!d||x<MG||y<MG||x>Z.w-MG||y>Z.h-MG)return false;
    const f=rnd()<.5?-1:1;
    for(const g of gates)if(Math.hypot(g.x-x,g.y-y)<290)return false;
    if(Z.way&&Math.hypot(Z.way[0]-x,Z.way[1]-y)<(village?300:230))return false;
    if(d.solid){for(const so of d.solid){const sx=x+so.dx*s*f,sy=y+so.dy*s,sr=so.r*s;
      for(const g of gates)if(Math.hypot(g.x-sx,g.y-sy)<sr+215)return false;
      if(Z.way&&Math.hypot(Z.way[0]-sx,Z.way[1]-sy)<sr+170)return false;
      if(!force){if(Math.hypot(CX-sx,CY-sy)<sr+130)return false;for(const l of lanes)if(segD(sx,sy,l)<sr+70)return false;}}}
    const r=rad(t,s);const gx=Math.floor(x/260),gy=Math.floor(y/260);
    for(let i=-1;i<=1;i++)for(let j=-1;j<=1;j++){const l=grid.get((gx+i)+','+(gy+j));if(l)for(const o of l)if(Math.hypot(o.x-x,o.y-y)<r+o.r)return false;}
    const p={t,x:Math.round(x),y:Math.round(y),s:+s.toFixed(2),v:Math.floor(rnd()*3),f,ph:rnd()*TAU};out.push(p);
    const k=key(x,y);let l=grid.get(k);if(!l)grid.set(k,l=[]);l.push({x,y,r:force?PROP_DEFS[t].w*.4*s:r});return true;};
  /* landmarks first (nudged off gates / lanes by a small spiral) */
  for(const [t,fx,fy,s] of (B.lm||[])){let done=false;
    for(let k=0;k<40&&!done;k++){const a=k*2.4,rr=k*70;done=place(t,fx*Z.w+Math.cos(a)*rr,fy*Z.h+Math.sin(a)*rr,s,false);}
    if(!done)console.warn('brief landmark dropped',zid,t);}
  /* villages: buildings on rings around the waystone/fountain */
  if(village){const [cx,cy]=Z.way||[CX,CY];
    if(B.village.center)place(B.village.center,cx,cy-20,1.25,true);
    for(const [t,n,r0,r1,s0,s1] of B.village.ring)for(let i=0;i<n;i++){let ok=false;for(let k=0;k<14&&!ok;k++){const a=(i+rnd()*.5)/n*TAU+(k?rnd()*.4:0),rr=r0+rnd()*(r1-r0);ok=place(t,cx+Math.cos(a)*rr,cy+Math.sin(a)*rr*.78,s0+rnd()*(s1-s0),true);}}
    for(const [t,n,r0,r1,s0,s1] of B.village.outer)for(let i=0;i<n;i++)for(let k=0;k<20;k++){const a=rnd()*TAU,rr=r0+rnd()*(r1-r0);if(place(t,cx+Math.cos(a)*rr,cy+Math.sin(a)*rr*.85,s0+rnd()*(s1-s0),false))break;}}
  /* scattered sets */
  for(const [t,perM,s0=.85,s1=1.2,reg=ALL] of (B.set||[])){const area=(reg[2]-reg[0])*(reg[3]-reg[1])*Z.w*Z.h/1e6,f=perM*area*BR_PD*((t==='bones'||t==='skull')?.6:1),n=Math.floor(f)+(rnd()<f%1?1:0);
    let placed=0,tries=0;while(placed<n&&tries<n*14){tries++;const x=(reg[0]+rnd()*(reg[2]-reg[0]))*Z.w,y=(reg[1]+rnd()*(reg[3]-reg[1]))*Z.h;if(place(t,x,y,s0+rnd()*(s1-s0),false))placed++;}}
  return out;}
{const _g=genProps;genProps=function(zid){if(!BR[zid]||!ZONES[zid]||zid==='capital')return _g.apply(this,arguments);
  try{return brGen(zid);}catch(e){console.error('brGen',zid,e);return _g.apply(this,arguments);}};}

/* ===== v127.3 · Capital ground drawn in crisp chunks (code-drawn at runtime instead of one blurry 0.34× bake) =====
   genBG(capital) bakes only the soft base; the paving / roads / rings / houses (FEAT.capital) are redrawn per 512px chunk at 1.25× the first time a chunk is seen. */
const CAPX={S:MAPCFG.chunkSize,K:1,cache:new Map(),skip:false,mode:null};
