function foldInit(){try{
  const hud=document.getElementById('hud'),menu=document.getElementById('menu');if(!hud||!menu||document.getElementById('hudFold'))return;
  const get=k=>{try{return localStorage.getItem(k)==='1';}catch(e){return false;}},set=(k,v)=>{try{localStorage.setItem(k,v?'1':'0');}catch(e){}};
  const hb=document.createElement('button');hb.id='hudFold';hb.className='foldbtn';hb.title='พับ/กางแถบสถานะ';hud.appendChild(hb);
  const mb=document.createElement('button');mb.id='menuFold';mb.className='foldbtn';mb.title='พับ/กางเมนู';menu.insertBefore(mb,menu.firstChild);
  const apply=()=>{hb.textContent=hud.classList.contains('fold')?'▸':'▾';mb.textContent=menu.classList.contains('fold')?'☰':'✕';};
  hud.classList.toggle('fold',get('realm_fold_hud'));menu.classList.toggle('fold',get('realm_fold_menu'));apply();
  hb.addEventListener('click',e=>{e.stopPropagation();hud.classList.toggle('fold');set('realm_fold_hud',hud.classList.contains('fold'));apply();});
  mb.addEventListener('click',e=>{e.stopPropagation();menu.classList.toggle('fold');set('realm_fold_menu',menu.classList.contains('fold'));apply();});
  for(const b of [hb,mb])b.addEventListener('pointerdown',e=>e.stopPropagation());
}catch(e){}}
foldInit();setTimeout(foldInit,600);

