/* ===== p113 (v128 · Map Architecture Phase 1): Asset Registry (read-only view) + Map Recipe reader + Automated Diff =====
   Goal of Phase 1 = PROVE  Recipe → PROPS  without changing anything players see or feel.
   · Default: every zone keeps using the OLD generator (flag list is empty).
   · A zone only uses its Recipe when (a) it is switched on (localStorage MAPCFG.recipe.flagKey, GM panel in SET) AND
     (b) RECIPE_DATA has a recipe for it AND (c) validation passes. Otherwise it silently falls back to the old generator
     and shows a plain-language message. Nothing else (collision, y-sort, AI, spawn, save, warp, camera, lighting) is touched.
   · Recipe 'fixed' block (gates / waystone / nexus / npcs) is reference data in Phase 1: it is only CHECKED against the game, never used to build it.
   API for admins / tests: window.RECIPE */
const RCP={ZON:new Set(),log:[],last:{},orig:loadPropsFor};
function rcpFlagsLoad(){try{const a=JSON.parse(localStorage.getItem(MAPCFG.recipe.flagKey)||'[]');RCP.ZON=new Set(Array.isArray(a)?a.filter(z=>typeof z==='string'):[]);}catch(e){RCP.ZON=new Set();}}
function rcpFlagsSave(){try{localStorage.setItem(MAPCFG.recipe.flagKey,JSON.stringify([...RCP.ZON]));}catch(e){}}
rcpFlagsLoad();
const rcpClone=o=>JSON.parse(JSON.stringify(o));
function rcpHash(s){let x=5381;for(let i=0;i<s.length;i++)x=((x<<5)+x+s.charCodeAt(i))|0;return (x>>>0).toString(16);}
const rcpFin=n=>typeof n==='number'&&isFinite(n);

/* ---------- Asset Registry: a read-only, normalised view of PROP_DEFS (+ PROP_LIGHT). Nothing is moved or renamed. ---------- */
function assetRegistry(){return (typeof ASSETREG!=='undefined')?ASSETREG.view():assetRegistryLegacy();}
function assetRegistryLegacy(){const R={};
  for(const k in PROP_DEFS){const d=PROP_DEFS[k],L=PROP_LIGHT[k];
    R[k]={id:k,name:d.n||k,cat:d.cat||'',size:[d.w,d.h],anchor:[d.ax,d.ay],layer:d.layer||'object',
      solid:(d.solid||[]).map(o=>({dx:o.dx,dy:o.dy,r:o.r})),light:L?{r:L[0],color:L[1]}:null,live:!!d.live,multi:d.multi||0,custom:!!d.custom,fade:!(d.nofade||d.layer)};}
  return R;}
function regValidate(R){const e=[];
  for(const k in R){const a=R[k];
    if(!(rcpFin(a.size[0])&&rcpFin(a.size[1])&&a.size[0]>0&&a.size[1]>0))e.push({code:'asset-size',msg:`วัตถุ «${k}» ในทะเบียนมีขนาดภาพไม่ถูกต้อง`});
    if(!(rcpFin(a.anchor[0])&&rcpFin(a.anchor[1])))e.push({code:'asset-anchor',msg:`วัตถุ «${k}» ในทะเบียนไม่มีจุดยึดภาพ`});
    for(const o of a.solid)if(!(rcpFin(o.dx)&&rcpFin(o.dy)&&rcpFin(o.r)&&o.r>=0))e.push({code:'asset-solid',msg:`วัตถุ «${k}» ในทะเบียนมีรูปทรงชนไม่ถูกต้อง`});}
  return e;}

/* ---------- Recipe v1 ---------- */
function rcpFixedNow(zid){const Z=ZONES[zid];
  return {gates:gatesFor(zid).map(g=>({to:g.to,x:g.x,y:g.y})),way:(Z.way&&!Z.base)?[Z.way[0],Z.way[1]]:null,nexus:Z.nexus?[Z.nexus[0],Z.nexus[1]]:null};}
function rcpExport(zid){const Z=ZONES[zid];if(!Z)throw new Error('ไม่มีโซนชื่อ '+zid);
  const props=rcpClone(RCP.orig(zid));
  const placed=props.map((p,i)=>{const o={id:'p'+String(i+1).padStart(4,'0')};for(const k in p)o[k]=p[k];if(LANDMARK_T.has(p.t))o.lock=1;return o;});
  const fixed=rcpFixedNow(zid);
  fixed.npcs=(zid==='capital'&&typeof G!=='undefined'&&G.zone===zid&&Array.isArray(NPCS))?NPCS.map(n=>({n:n.n,kind:n.kind||null,x:n.x,y:n.y})):null;   // only the capital has fixed NPCs. null = not recorded (villages pick NPCs at random on every visit — p93 — so they cannot be part of a recipe yet)
  return {v:MAPCFG.recipe.version,zone:zid,meta:{size:[Z.w,Z.h],count:placed.length,hash:rcpHash(JSON.stringify(props)),source:'old generator (loadPropsFor)',note:'Phase 1 baked recipe: every prop listed explicitly; "lock":1 = landmark (never moved by seed in later phases)'},fixed,placed};}
function rcpValidate(rc,zid,R){const e=[],Z=ZONES[zid],add=(code,msg)=>{if(e.length<20)e.push({code,msg});};R=R||assetRegistry();
  if(!rc||typeof rc!=='object'||Array.isArray(rc)){add('format','ไฟล์ Recipe อ่านไม่ได้ (รูปแบบไม่ใช่ข้อมูลที่ถูกต้อง)');return e;}
  if(rc.v!==MAPCFG.recipe.version)add('version',`เวอร์ชันของ Recipe (${rc.v}) ไม่ตรงกับที่เกมอ่านได้ (v${MAPCFG.recipe.version})`);
  if(rc.zone!==zid)add('zone',`Recipe นี้เป็นของโซน «${rc.zone}» ไม่ใช่โซน «${zid}»`);
  if(!Z){add('zone','ไม่พบข้อมูลโซนนี้ในเกม');return e;}
  const sz=rc.meta&&rc.meta.size;
  if(!Array.isArray(sz)||sz[0]!==Z.w||sz[1]!==Z.h)add('size',`ขนาดแมพใน Recipe (${sz&&sz[0]}×${sz&&sz[1]}) ไม่ตรงกับขนาดโซนปัจจุบัน (${Z.w}×${Z.h}) — แมพถูกเปลี่ยนขนาดหลังสร้าง Recipe ต้องสร้าง Recipe ใหม่`);
  if(!Array.isArray(rc.placed)){add('placed','Recipe ไม่มีรายการวัตถุ (placed)');return e;}
  if(rc.placed.length>MAPCFG.recipe.maxProps)add('too-many',`Recipe มีวัตถุ ${rc.placed.length} ชิ้น เกินที่อนุญาต (${MAPCFG.recipe.maxProps})`);
  const re=regValidate(R);for(const x of re.slice(0,5))add(x.code,x.msg);
  const ids=new Set(),unknown=new Set();
  rc.placed.forEach((p,i)=>{const at=`วัตถุลำดับที่ ${i+1}`;
    if(!p||typeof p!=='object'){add('entry',at+' อ่านไม่ได้');return;}
    if(p.id!==undefined){if(ids.has(p.id))add('dup-id',`${at}: รหัส ${p.id} ซ้ำกัน`);ids.add(p.id);}
    if(typeof p.t!=='string'||!R[p.t]){if(!unknown.has(p.t)){unknown.add(p.t);add('asset-missing',`${at}: ไม่พบวัตถุชื่อ «${p.t}» ในทะเบียน Asset`);}}
    if(!(rcpFin(p.x)&&rcpFin(p.y)))add('pos',`${at} (${p.t}): ตำแหน่งไม่ใช่ตัวเลข`);
    else if(p.x<0||p.y<0||p.x>Z.w||p.y>Z.h)add('out-of-map',`${at} (${p.t}): ตำแหน่ง (${Math.round(p.x)}, ${Math.round(p.y)}) อยู่นอกแมพ ${Z.w}×${Z.h}`);
    if(!(rcpFin(p.s)&&p.s>0&&p.s<=MAPCFG.recipe.maxScale))add('scale',`${at} (${p.t}): ขนาด (scale) ต้องเป็นตัวเลข 0–${MAPCFG.recipe.maxScale}`);
    if(!(Number.isInteger(p.v)&&p.v>=0))add('variant',`${at} (${p.t}): รุ่น (variant) ต้องเป็นจำนวนเต็มตั้งแต่ 0`);
    if(p.f!==1&&p.f!==-1)add('flip',`${at} (${p.t}): การกลับด้าน (flip) ต้องเป็น 1 หรือ -1`);
    if(p.ph!==undefined&&!rcpFin(p.ph))add('phase',`${at} (${p.t}): ค่าอนิเมชัน (ph) ไม่ใช่ตัวเลข`);});
  return e;}
function rcpAssemble(rc){return rc.placed.map(e=>{const o={};for(const k in e){if(k==='id'||k==='lock')continue;o[k]=e[k];}return o;});}
function rcpSolids(props){const out=[];for(const p of props){const d=PROP_DEFS[p.t];if(!d||!d.solid)continue;for(const so of d.solid)out.push([Math.round((p.x+so.dx*p.s*(p.f<0?-1:1))*100)/100,Math.round((p.y+so.dy*p.s)*100)/100,Math.round(so.r*p.s*100)/100]);}return out;}

/* ---------- Automated Diff: old generator PROPS  vs  Recipe PROPS (field by field, nothing judged by eye) ---------- */
function rcpDiff(zid,rc){rc=rc||RECIPE_DATA[zid];if(!rc)return {zone:zid,ok:false,error:'ยังไม่มีไฟล์ Recipe ของโซนนี้'};
  const verr=rcpValidate(rc,zid),A=rcpClone(RCP.orig(zid));let B;
  try{B=rcpAssemble(rc);}catch(e){return {zone:zid,ok:false,validation:verr,error:'ประกอบแผนที่ไม่สำเร็จ: '+e.message};}
  const diffs=[];let total=0;const push=(d)=>{total++;if(diffs.length<30)diffs.push(d);};
  if(A.length!==B.length)push({field:'count',old:A.length,new:B.length});
  const n=Math.min(A.length,B.length),tol=MAPCFG.recipe.phTol;
  for(let i=0;i<n;i++){const a=A[i],b=B[i],keys=new Set([...Object.keys(a),...Object.keys(b)]);
    for(const k of keys){
      if(k==='ph'){if(!(rcpFin(a.ph)&&rcpFin(b.ph)&&Math.abs(a.ph-b.ph)<=tol))push({i,t:a.t,field:'ph',old:a.ph,new:b.ph});}
      else if(JSON.stringify(a[k])!==JSON.stringify(b[k]))push({i,t:a.t,field:k,old:a[k],new:b[k]});}}
  const sa=rcpSolids(A),sb=rcpSolids(B);let solidDiff=sa.length!==sb.length?1:0;for(let i=0;!solidDiff&&i<sa.length;i++)if(sa[i][0]!==sb[i][0]||sa[i][1]!==sb[i][1]||sa[i][2]!==sb[i][2])solidDiff++;
  const fx=rcpFixedNow(zid),f=rc.fixed||{},fixedDiff={gates:JSON.stringify(f.gates)!==JSON.stringify(fx.gates),way:JSON.stringify(f.way)!==JSON.stringify(fx.way),nexus:JSON.stringify(f.nexus)!==JSON.stringify(fx.nexus)};
  let npcs='ไม่ได้ตรวจ (โซนไม่ได้โหลดอยู่ หรือ Recipe ไม่ได้บันทึก NPC)';
  if(G.zone===zid&&Array.isArray(f.npcs)){const cur=NPCS.map(n=>({n:n.n,kind:n.kind||null,x:n.x,y:n.y}));fixedDiff.npcs=JSON.stringify(f.npcs)!==JSON.stringify(cur);npcs=fixedDiff.npcs?'ต่างกัน':'ตรงกัน';}
  const lockOld=A.filter(p=>LANDMARK_T.has(p.t)).length,lockNew=rc.placed.filter(p=>p.lock).length;
  const ok=!total&&!verr.length&&!solidDiff&&!Object.values(fixedDiff).some(Boolean)&&lockOld===lockNew;
  return {zone:zid,ok,propsOld:A.length,propsNew:B.length,fieldDiffs:total,sample:diffs,validation:verr,
    solids:{old:sa.length,new:sb.length,different:!!solidDiff},fixed:fixedDiff,npcs,landmarks:{old:lockOld,new:lockNew},hash:{recipe:rc.meta&&rc.meta.hash,old:rcpHash(JSON.stringify(A))}};}
function rcpDiffAll(){const out=[];for(const z in WG){let r;try{r=rcpDiff(z,rcpExport(z));}catch(e){r={zone:z,ok:false,error:String(e)};}out.push({zone:z,ok:r.ok,props:r.propsOld,fieldDiffs:r.fieldDiffs,error:r.error});}return out;}

/* ---------- the loader: Recipe only when switched on + valid, otherwise the old generator ---------- */
function rcpFail(zid,errs,why){const Z=ZONES[zid]||{n:zid},first=errs&&errs[0]&&errs[0].msg||why||'ไม่ทราบสาเหตุ';
  RCP.last[zid]={ok:false,errs:errs||[{msg:first}]};RCP.log.push({t:Date.now(),zone:zid,errs:errs||[{msg:first}]});if(RCP.log.length>50)RCP.log.shift();
  try{console.warn('[Recipe] fallback',zid,errs);}catch(e){}
  try{notify(`โซน «${Z.n}»: ระบบแผนที่แบบ Recipe ใช้ไม่ได้ (${first}) — กลับไปใช้ระบบเดิมให้อัตโนมัติ เล่นต่อได้ตามปกติ`,true);}catch(e){}}
loadPropsFor=function(zid){
  if(!RCP.ZON.has(zid))return RCP.orig.apply(this,arguments);
  const rc=RECIPE_DATA[zid];if(!rc){rcpFail(zid,null,'ยังไม่มีไฟล์ Recipe ของโซนนี้');return RCP.orig.apply(this,arguments);}
  try{const errs=rcpValidate(rc,zid);if(errs.length){rcpFail(zid,errs);return RCP.orig.apply(this,arguments);}
    const out=rcpAssemble(rc);RCP.last[zid]={ok:true,n:out.length};ED.source='default';return out;}
  catch(e){rcpFail(zid,null,'ประกอบแผนที่ไม่สำเร็จ ('+(e&&e.message)+')');return RCP.orig.apply(this,arguments);}
};

/* ---------- benchmark (separate from correctness; reports what was measured, never claims mobile results) ---------- */
async function rcpBench(opt){opt=opt||{};const C=MAPCFG.perf,F=opt.frames||C.benchFrames;
  if(typeof G==='undefined'||G.state!=='play')return {error:'ต้องเข้าเกมด้วยตัวละครก่อน (G.state ไม่ใช่ play)'};
  const nObj=opt.n!==undefined?opt.n:C.benchProps,natural=!!opt.natural,Z=ZONES[G.zone],R=assetRegistry(),keys=Object.keys(R).filter(k=>R[k].layer==='object'&&!R[k].custom&&!R[k].multi);
  const ua=navigator.userAgent,env={userAgent:ua,cores:navigator.hardwareConcurrency||null,dpr:devicePixelRatio,viewport:[innerWidth,innerHeight],headless:/Headless/i.test(ua),mobileUA:/Mobile|Android|iPhone|iPad/i.test(ua),zone:G.zone,
    note:'ตัวเลขนี้วัดบนเครื่อง/เบราว์เซอร์ที่รันอยู่เท่านั้น ถ้าเป็นเบราว์เซอร์บนเซิร์ฟเวอร์ (headless) ห้ามถือเป็นผลของมือถือจริง'};
  const keep={PROPS,god:G.god,px:P.x,py:P.y,enemies:enemies.length};G.god=true;
  const scen=natural?[{name:'แมพจริงตามปกติ (ไม่เพิ่มวัตถุ)',natural:true}]:[{name:'กระจายทั้งแมพ',box:[Z.w-400,Z.h-400],cx:Z.w/2,cy:Z.h/2},{name:'หนาแน่นสุดขั้ว (ทุกชิ้นอยู่ในกรอบเล็ก)',box:C.benchDenseBox,cx:Z.w/2,cy:Z.h/2}],results=[];
  try{for(const sc of scen){
      let s=123456789;const rnd=()=>(s=(Math.imul(s,1664525)+1013904223)>>>0)/4294967296,arr=[];
      for(let i=0;!sc.natural&&i<nObj;i++)arr.push({t:keys[i%keys.length],x:Math.round(sc.cx+(rnd()-.5)*sc.box[0]),y:Math.round(sc.cy+(rnd()-.5)*sc.box[1]),s:+(.7+rnd()*.6).toFixed(2),v:i%3,f:i%2?1:-1,ph:rnd()*TAU});
      if(!sc.natural){PROPS=arr;buildSolids();P.x=sc.cx;P.y=sc.cy+400;}await new Promise(r=>setTimeout(r,700));for(let i=0;i<30;i++)await new Promise(r=>requestAnimationFrame(r));   // warm-up
      const rms=[],dts=[],_r=render;render=function(){const a=performance.now();const o=_r.apply(this,arguments);rms.push(performance.now()-a);return o;};
      try{let last=performance.now();for(let i=0;i<F;i++){await new Promise(r=>requestAnimationFrame(r));const t=performance.now();dts.push(t-last);last=t;}}finally{render=_r;}
      const vis=PROPS.filter(propVisible),lit=vis.filter(p=>PROP_LIGHT[p.t]).length,srt=a=>a.slice().sort((x,y)=>x-y),avg=a=>a.reduce((x,y)=>x+y,0)/Math.max(1,a.length),pc=(a,q)=>srt(a)[Math.min(a.length-1,Math.floor(a.length*q))]||0;
      results.push({scenario:sc.name,objectsInjected:sc.natural?0:nObj,objectsTotal:PROPS.length,objectsVisible:vis.length,lightsVisible:lit+LIGHTS.length,propLights:lit,bakedLights:LIGHTS.length,frames:dts.length,
        renderCallMs:{avg:+avg(rms).toFixed(2),p95:+pc(rms,.95).toFixed(2),max:+Math.max(...rms).toFixed(2)},frameIntervalMs:{avg:+avg(dts).toFixed(2),p95:+pc(dts,.95).toFixed(2),max:+Math.max(...dts).toFixed(2)},fpsAvg:+(1000/avg(dts)).toFixed(1)});}}
  finally{PROPS=keep.PROPS;buildSolids();G.god=keep.god;P.x=keep.px;P.y=keep.py;}
  return {env,note:'objectsTotal = ทุกชิ้นที่อยู่ในแมพขณะวัด (รวมวัตถุกำแพงขอบแมพที่เกมเพิ่มเอง) · renderCallMs = เวลา CPU ของฟังก์ชันวาดต่อเฟรม · frameIntervalMs = ระยะห่างระหว่างเฟรมจริง · ไม่รวมเวลา GPU',config:{objects:nObj,frames:F,natural},results};}

