window.RECIPE={enable(z){if(!RECIPE_DATA[z])return false;RCP.ZON.add(z);rcpFlagsSave();return true;},disable(z){RCP.ZON.delete(z);rcpFlagsSave();},disableAll(){RCP.ZON.clear();rcpFlagsSave();},
  enabled:()=>[...RCP.ZON],hasRecipe:z=>!!RECIPE_DATA[z],status:z=>RCP.last[z]||null,export:rcpExport,validate:rcpValidate,diff:rcpDiff,diffAll:rcpDiffAll,registry:assetRegistry,bench:rcpBench,log:RCP.log,data:RECIPE_DATA,config:MAPCFG};
function rcpPanel(){const cp=document.getElementById('camPanel');if(!cp)return;let d=document.getElementById('rcBox');
  if(!d){d=document.createElement('details');d.id='rcBox';d.hidden=true;d.innerHTML=`<summary>🧪 แผนที่แบบ Recipe (ทดลอง · แอดมิน)</summary><div class="muted" style="font-size:11px;margin:6px 0">ค่าเริ่มต้น = ปิด (ใช้ระบบเดิมทุกโซน) · เปลี่ยนแล้วมีผลเมื่อเข้าโซนนั้นครั้งถัดไป · ถ้า Recipe ผิดพลาดเกมจะกลับไปใช้ระบบเดิมเอง</div><div id="rcList"></div><div class="row" style="display:flex;gap:6px;flex-wrap:wrap;margin-top:6px"><button class="btn sm" id="rcAllOff">ปิดทั้งหมด</button><button class="btn sm" id="rcBench">วัดประสิทธิภาพ (${MAPCFG.perf.benchProps} วัตถุ)</button></div><pre id="rcOut" style="white-space:pre-wrap;font-size:11px;max-height:200px;overflow:auto;margin:6px 0 0"></pre>`;
    const st=document.createElement('style');st.textContent='#rcBox{margin-top:10px;border-top:1px solid var(--line);padding-top:8px}#rcBox summary{cursor:pointer;font-family:var(--display);letter-spacing:.06em;font-size:12px;color:#fff}#rcBox .rr{display:flex;align-items:center;gap:6px;font-size:12px;margin:3px 0;flex-wrap:wrap}';document.head.appendChild(st);cp.appendChild(d);
    const out=d.querySelector('#rcOut');
    d.querySelector('#rcAllOff').onclick=()=>{RECIPE.disableAll();rcpPanelList(d);out.textContent='ปิด Recipe ทุกโซนแล้ว — กลับไปใช้ระบบเดิมเมื่อเข้าโซนครั้งถัดไป';};
    d.querySelector('#rcBench').onclick=async e=>{const b=e.target;b.disabled=true;out.textContent='กำลังวัด… (ประมาณ 10–20 วินาที ตัวละครจะอยู่ในโหมดอมตะชั่วคราว)';
      try{const r=await rcpBench();out.textContent=r.error?r.error:`เครื่อง: ${r.env.headless?'เบราว์เซอร์บนเซิร์ฟเวอร์ (ไม่ใช่มือถือจริง)':r.env.mobileUA?'มือถือ/แท็บเล็ต':'คอมพิวเตอร์'} · DPR ${r.env.dpr} · ${r.env.viewport.join('×')}\n`+r.results.map(x=>`• ${x.scenario}\n  วัตถุทั้งหมด ${x.objectsTotal} · เห็นในจอ ${x.objectsVisible} · แสง ${x.lightsVisible}\n  FPS เฉลี่ย ${x.fpsAvg} · เฟรม ${x.frameIntervalMs.avg} ms (p95 ${x.frameIntervalMs.p95}) · วาด ${x.renderCallMs.avg} ms`).join('\n');}
      catch(err){out.textContent='วัดไม่สำเร็จ: '+err;}b.disabled=false;};}
  d.hidden=!(typeof G!=='undefined'&&G.god);if(!d.hidden&&!d.dataset.built){rcpPanelList(d);d.dataset.built='1';}}
function rcpPanelList(d){const L=d.querySelector('#rcList'),zs=Object.keys(RECIPE_DATA);L.innerHTML=zs.length?'':'<div class="muted" style="font-size:11px">ยังไม่มีไฟล์ Recipe ในเกมนี้</div>';
  for(const z of zs){const r=document.createElement('div');r.className='rr';r.innerHTML=`<label><input type="checkbox" ${RCP.ZON.has(z)?'checked':''}> ${(ZONES[z]&&ZONES[z].n)||z}</label><button class="btn sm">ตรวจ Diff</button><span class="muted"></span>`;
    r.querySelector('input').onchange=e=>{e.target.checked?RECIPE.enable(z):RECIPE.disable(z);};
    r.querySelector('button').onclick=()=>{const x=rcpDiff(z);r.querySelector('span').textContent=x.error?x.error:x.ok?`✓ ตรงกัน ${x.propsNew} ชิ้น (ต่าง 0 จุด)`:`✗ ต่างกัน ${x.fieldDiffs} จุด`;};L.appendChild(r);}}
