  probe:pdProbe,connCheck:o=>pdConnCheck(pdConnList(DECOR_DATA.zones[G.zone],pdContext(G.zone)),o),connCheckList:(l,o)=>pdConnCheck(l,o),clearGrid:pdClearGrid,agentR:pdAgentR,scatterSafe:pdScatterSafe,sig:pdSig,findById:pdFindById,blocked:()=>PDC.blocked,
  validate:pdValidate,compile:pdCompile,diff:pdDiff,regen:pdRegen,debug(v){PDC.dbg=v===undefined?!PDC.dbg:!!v;try{pdLegend();}catch(e){}return PDC.dbg;},isDebug:()=>PDC.dbg,
