/* ---------- public API + GM panel ---------- */
function oblApply(){if(typeof G!=='undefined'&&G.zone){delete OBL.failed[G.zone];oblEnter(G.zone);}}
window.COLOBJ={
  enable(z){if(!ZONES[z])return false;delete OBL.failed[z];OBL.zones.add(z);oblFlagsSave();if(G.zone===z)oblApply();return true;},
  disable(z){OBL.zones.delete(z);oblFlagsSave();if(G.zone===z)oblApply();},
  disableAll(){const had=OBL.zones.has(G.zone);OBL.zones.clear();oblFlagsSave();if(had)oblApply();},
  enabled:()=>[...OBL.zones],isActive:()=>!!OBL.active,isInstalled:()=>OBL.inst,
  status:()=>({enabledZones:[...OBL.zones],active:OBL.active,errors:OBL.err,failed:OBL.failed,hooks:OBL.inst,stats:{...OBL.st},sprites:OBL.spr.size,log:OBL.log.slice(-8)}),
  stats:()=>({...OBL.st}),resetStats(){for(const k in OBL.st)OBL.st[k]=0;},validate:oblValidate,apply:oblApply,
  visible:()=>OBL.S.map(e=>e.p),shadowRects:()=>OBL.S.filter(e=>e.shv).map(e=>({p:e.p,x:e.sb.x,y:e.sb.y,w:e.sb.w,h:e.sb.h})),entries:()=>[...OBL.idx.values()],
  sprite:(t,v)=>oblSprite(t,v),block:oblBlock,stress:oblStress,env:oblEnv,session:{start:oblSesStart,stop:oblSesStop},BUILD:OBL_BUILD,
  debug(v){OBL.dbg=v===undefined?!OBL.dbg:!!v;try{oblLegend();}catch(e){}return OBL.dbg;},isDebug:()=>OBL.dbg,config:MAPCFG.objects,log:OBL.log};
const OBS={ses:null,auto:null,last:null};
