function oblSesStop(){const s=OBS.ses;if(!s)return null;const rep=COLPERF.report();const r={startedAt:s.at,seconds:Math.round((performance.now()-s.t0)/100)/10,envAtStart:s.env,gfxAtStart:s.gfx0,gfxAtEnd:G.gfx,gfxChangedDuringSession:s.gfx0!==G.gfx,zoneAtStart:s.zone0,zoneAtEnd:G.zone,colperf:rep};COLPERF.on(!!s.pf0);OBS.ses=null;return r;}
