/* ===== p120 (v134 · Map Architecture Phase 7): Editor Overrides — LIMITED (pilot zone only, opt-in, default OFF) =====
   Lets an admin ADD / MOVE / DELETE decoration objects of a procedurally generated zone with the EXISTING Map Editor, without touching code, and keeps the result after a reload.
   Nothing here replaces a generator: the zone is still built by recipe + seed (Phase 4); an override is a small difference stored next to it.
     move / delete : stored as (pid, sig, new fields) — applied ONLY when the object with that pid still has the same sig (same check as COLDEC.findById). 'moved' / 'missing' → skipped + reported, never guessed, never deleted from storage.
     add           : stored with a stable id  ov:<n>  (a counter that is never re-used) — cannot collide with a procedural pid.
   Priority: an admin-saved legacy layout (Save Layout) ALWAYS wins and is never converted or overwritten; overrides are then simply not applied.
   Safety: nothing is written while dragging; Save validates (types, scatter-safety, map edge, no-place zones, requiredConnections with the existing path-clearance) and REFUSES with a Thai message otherwise;
   every write keeps a backup history, is read back and compared, and can be rolled back.  Locked: fixed objects (portals / warp / NPC pads / landmarks / fixed buildings / quest / boss) and the boundary ring.
   Not touched: Y-sort (L2), AI / Combat, Character, collision rules (the editor's own buildSolids path is used), Phase 6 code (only its public `dirty` flag is set when the editor is left).
   Hooks are installed lazily when a zone is switched on and removed when the last one is switched off (switched off = exactly rc3 behaviour).  API: window.COLED */
const OVR_BUILD='v134-phase7-rc4';
if(typeof MAPCFG==='object'&&!MAPCFG.overrides)MAPCFG.overrides={
  version:1,
  flagKey:'realm_overrides_zones_v1',      // localStorage: zone ids where Editor Overrides are switched on (default: none)
  dataKey:'realm_overrides_v1',            // localStorage: the saved overrides {v,zones:{zid:{rev,next,seed,savedAt,ops:[]}}}
  bakKey:'realm_overrides_v1_bak',         // localStorage: backup history {v,zones:{zid:[zoneDoc,…]}} (written BEFORE every change)
  allowedZones:['jungle_sylva_village'],   // pilot — any other zone is refused even if its flag is set
  maxHistory:5,maxOps:400,margin:150       // backups kept per zone · operations per zone · objects must stay this far (px) inside the map edge
};
const OV={cancelAsk:0,zones:new Set(),inst:false,orig:null,w:null,mode:false,zid:null,base:null,view:null,st:{},log:[],pend:null,skipOnce:null,guard:null,elig:new Map(),closeAsk:0,lastCheck:null};
function ovNote(m){OV.log.push((new Date()).toISOString().slice(11,19)+' '+m);if(OV.log.length>80)OV.log.shift();}
const ovC=()=>MAPCFG.overrides;
const ovFin=n=>typeof n==='number'&&isFinite(n);
function ovFlagsLoad(){try{const a=JSON.parse(localStorage.getItem(ovC().flagKey)||'[]');OV.zones=new Set(Array.isArray(a)?a.filter(z=>typeof z==='string'&&ovC().allowedZones.indexOf(z)>=0):[]);}catch(e){OV.zones=new Set();}}
function ovFlagsSave(){try{if(OV.zones.size)localStorage.setItem(ovC().flagKey,JSON.stringify([...OV.zones]));else localStorage.removeItem(ovC().flagKey);}catch(e){}}
function ovToast(m,kind){try{if(typeof notify==='function')notify(m,kind||'bad');}catch(e){}}

/* ---------- storage: versioned, validated, backed up ---------- */
function ovRaw(k){try{return localStorage.getItem(k);}catch(e){return null;}}
function ovReadDoc(){const raw=ovRaw(ovC().dataKey);if(raw===null)return {state:'none',doc:{v:ovC().version,zones:{}}};
  let d;try{d=JSON.parse(raw);}catch(e){return {state:'corrupt',why:'อ่านข้อมูล overrides ไม่ได้ (ไม่ใช่ JSON ที่ถูกต้อง)',raw};}
  if(!d||typeof d!=='object'||Array.isArray(d)||!Number.isInteger(d.v)||d.v<1||!d.zones||typeof d.zones!=='object'||Array.isArray(d.zones))return {state:'corrupt',why:'ข้อมูล overrides รูปแบบไม่ถูกต้อง',raw};
  if(d.v>ovC().version)return {state:'newer',why:'ข้อมูล overrides เป็นเวอร์ชัน '+d.v+' ใหม่กว่าที่เกมนี้รองรับ ('+ovC().version+')',raw};
  return {state:'ok',doc:d};}
function ovReadBak(){const raw=ovRaw(ovC().bakKey);if(raw===null)return {v:ovC().version,zones:{}};try{const d=JSON.parse(raw);if(d&&typeof d==='object'&&d.zones&&typeof d.zones==='object'&&!Array.isArray(d.zones))return d;}catch(e){}return {v:ovC().version,zones:{},broken:true};}
function ovZoneOk(z){return !!z&&typeof z==='object'&&!Array.isArray(z)&&Number.isInteger(z.rev)&&z.rev>=0&&Number.isInteger(z.next)&&z.next>=1&&Array.isArray(z.ops);}
function ovOpCheck(op){const C=ovC();
  if(!op||typeof op!=='object'||Array.isArray(op))return 'ไม่ใช่รายการที่ถูกต้อง';
  const fields=()=>{if(!ovFin(op.x)||!ovFin(op.y))return 'ตำแหน่งไม่ใช่ตัวเลข';if(!ovFin(op.s)||!(op.s>0)||op.s>MAPCFG.recipe.maxScale)return 'ขนาด (scale) ไม่ถูกต้อง';
    if(!Number.isInteger(op.v)||op.v<0||op.v>2)return 'แบบ (variant) ไม่ถูกต้อง';if(op.f!==1&&op.f!==-1)return 'การกลับด้านไม่ถูกต้อง';return null;};
  if(op.k==='del')return typeof op.pid==='string'&&op.pid&&typeof op.sig==='string'&&op.sig?null:'ลบ: ต้องมี pid และ sig';
  if(op.k==='mov')return (typeof op.pid==='string'&&op.pid&&typeof op.sig==='string'&&op.sig)?fields():'ย้าย: ต้องมี pid และ sig';
  if(op.k==='add'){if(typeof op.id!=='string'||!/^ov:\d+$/.test(op.id))return 'เพิ่ม: id ต้องเป็นรูป ov:<เลข>';if(typeof op.t!=='string'||!PROP_DEFS[op.t])return 'เพิ่ม: ไม่มีวัตถุชนิด «'+op.t+'» ในเกม';return fields();}
  return 'ชนิดรายการไม่รู้จัก';}
/* write one zone's document. Order: backup first → main. Any failure leaves the previous good data in place and returns {ok:false,error}. */
function ovWrite(zid,zd){
  const rd=ovReadDoc();if(rd.state==='newer')return {ok:false,error:rd.why+' — ไม่เขียนทับ'};
  const prevRawMain=ovRaw(ovC().dataKey),prevRawBak=ovRaw(ovC().bakKey);
  try{
    if(rd.state==='corrupt'){localStorage.setItem(ovC().dataKey+'_corrupt_'+Date.now(),rd.raw);}                 // never destroy unreadable data: keep a copy first
    const doc=rd.state==='ok'?rd.doc:{v:ovC().version,zones:{}},bak=ovReadBak();
    if(bak.broken){try{localStorage.setItem(ovC().bakKey+'_corrupt_'+Date.now(),prevRawBak||'');}catch(e){}bak.zones={};delete bak.broken;}
    const cur=doc.zones[zid];if(cur!==undefined&&!ovZoneOk(cur)){try{localStorage.setItem(ovC().dataKey+'_corruptzone_'+zid+'_'+Date.now(),JSON.stringify(cur));}catch(e){}}   // an unreadable zone entry is kept as a copy before it is replaced
    if(ovZoneOk(cur)){const h=bak.zones[zid]=Array.isArray(bak.zones[zid])?bak.zones[zid]:[];h.push(cur);while(h.length>ovC().maxHistory)h.shift();}
    doc.v=ovC().version;doc.zones[zid]=zd;bak.v=ovC().version;
    localStorage.setItem(ovC().bakKey,JSON.stringify(bak));
    try{localStorage.setItem(ovC().dataKey,JSON.stringify(doc));}
    catch(e2){try{if(prevRawBak===null)localStorage.removeItem(ovC().bakKey);else localStorage.setItem(ovC().bakKey,prevRawBak);}catch(e3){}throw e2;}
    return {ok:true};}
  catch(e){return {ok:false,error:'เขียนข้อมูลไม่สำเร็จ (เบราว์เซอร์ไม่อนุญาตหรือพื้นที่เต็ม) — คงข้อมูลที่ดีล่าสุดไว้ตามเดิม'};}}
function ovRestoreRaw(mainRaw,bakRaw){try{if(mainRaw===null)localStorage.removeItem(ovC().dataKey);else localStorage.setItem(ovC().dataKey,mainRaw);if(bakRaw===null)localStorage.removeItem(ovC().bakKey);else localStorage.setItem(ovC().bakKey,bakRaw);return true;}catch(e){return false;}}

/* ---------- object rules ---------- */
const ovLocked=p=>!!p&&(typeof p.pid==='string'&&p.pid.indexOf('fx:')===0||!!p.edge);
function ovTypeOk(t,s){const k=t+'|'+(Math.round((s||1)*100)/100);if(OV.elig.has(k))return OV.elig.get(k);let r;
  try{r=PROP_DEFS[t]&&!PROP_DEFS[t].custom?pdScatterSafe(t,s||1,s||1):{ok:false,why:`«${t}» ไม่มีในเกม`};}catch(e){r={ok:false,why:'ตรวจความปลอดภัยของวัตถุไม่ได้'};}
  if(OV.elig.size>600)OV.elig.clear();OV.elig.set(k,r);return r;}
const ovPh=id=>pdHash(id)/4294967296*TAU;
const ovSigOf=b=>pdSig(b);

/* ---------- apply: stored overrides → the zone's props (called from loadPropsFor) ---------- */
function ovAvail(zid){
  if(!OV.zones.has(zid))return {ok:false,code:'off',why:'ปิดอยู่'};
  if(ovC().allowedZones.indexOf(zid)<0)return {ok:false,code:'zone',why:'โซนนี้ไม่อยู่ในรายการนำร่อง'};
  if(!pdWanted(zid))return {ok:false,code:'decor',why:'ต้องเปิดระบบตกแต่งแมพแบบสูตร (Phase 4) ของโซนนี้ก่อน (แผง GM → 🌲)'};
  try{if(Array.isArray(savedLayouts()[zid]))return {ok:false,code:'legacy',why:'โซนนี้มีเลย์เอาต์ที่แอดมินบันทึกไว้เดิม (Save Layout) — ของเดิมมีลำดับก่อนเสมอ ระบบ Overrides จึงไม่ทำงาน (ไม่ทับ ไม่แปลงข้อมูลเดิม)'};}catch(e){}
  return {ok:true};}
function ovBaseOf(list){const m=new Map();for(const p of list){if(typeof p.pid!=='string')continue;const o={t:p.t,x:p.x,y:p.y,s:p.s,v:p.v,f:p.f,locked:ovLocked(p)};const e=m.get(p.pid);if(e)e.dup=true;else m.set(p.pid,o);}return m;}
function ovApply(zid,props){
  const st=OV.st[zid]={zone:zid,active:false,build:OVR_BUILD,applied:{mov:0,del:0,add:0},skipped:[],rev:0,why:'',at:Date.now()};
  const av=ovAvail(zid);if(!av.ok){st.why=av.why;st.code=av.code;if(OV.zid===zid){OV.base=null;}return props;}
  if(!(PDC.last[zid]&&PDC.last[zid].ok!==false)||!props.some(p=>typeof p.pid==='string')){st.why='ระบบตกแต่งแบบสูตร (Phase 4) ไม่ได้สร้างโซนนี้ในรอบนี้ (ใช้ระบบเดิม)';st.code='decor';OV.base=null;return props;}
  OV.zid=zid;OV.base=ovBaseOf(props);OV.view=PDC.view&&PDC.viewZone===zid?PDC.view:null;OV.elig.clear();st.baseCount=OV.base.size;
  const rd=ovReadDoc();st.store=rd.state;
  if(rd.state==='corrupt'||rd.state==='newer'){st.why=rd.why+' — ไม่ใช้ overrides (ข้อมูลยังอยู่ ไม่ถูกลบ)';st.code=rd.state;st.active=true;ovToast('⚠ '+st.why);return props;}
  const zd=rd.doc.zones[zid];if(zd===undefined){st.active=true;st.code='empty';return props;}
  if(!ovZoneOk(zd)){st.why='ข้อมูล overrides ของโซนนี้เสีย (รูปแบบไม่ถูกต้อง) — ไม่ใช้ (ข้อมูลยังอยู่ ไม่ถูกลบ)';st.code='corrupt';st.active=true;ovToast('⚠ '+st.why);return props;}
  st.active=true;st.rev=zd.rev;st.next=zd.next;st.code='ok';
  if(OV.rejected&&OV.rejected[zid]===zd.rev){st.why='overrides rev '+zd.rev+' ทำให้เส้นทางที่จำเป็นถูกบล็อก จึงไม่ใช้ (ข้อมูลยังอยู่)';st.code='rejected';return props;}
  const byPid=new Map();for(const p of props)if(typeof p.pid==='string'&&!byPid.has(p.pid))byPid.set(p.pid,p);
  const del=new Set(),adds=[],ids=new Set(),skip=(op,why)=>st.skipped.push({k:op&&op.k,id:op&&(op.pid||op.id),why});
  for(const op of zd.ops.slice(0,ovC().maxOps)){const bad=ovOpCheck(op);if(bad){skip(op,'ข้อมูลผิดรูปแบบ: '+bad);continue;}
    if(op.k==='add'){if(ids.has(op.id)){skip(op,'id ซ้ำกัน');continue;}if(OV.base.has(op.id)){skip(op,'id ชนกับ pid ของวัตถุสูตร');continue;}
      const q=ovTypeOk(op.t,op.s);if(!q.ok){skip(op,'ชนิดวัตถุไม่ผ่านกฎความปลอดภัย: '+(q.why||''));continue;}
      ids.add(op.id);adds.push(op);continue;}
    const b=OV.base.get(op.pid);
    if(!b){skip(op,'missing — ไม่พบวัตถุ '+op.pid+' (สูตร/seed เปลี่ยน?)');continue;}
    if(b.dup){skip(op,'pid ซ้ำในสูตร');continue;}
    if(b.locked){skip(op,'วัตถุล็อก (ห้ามย้าย/ลบ)');continue;}
    if(ovSigOf(b)!==op.sig){skip(op,'moved — วัตถุ '+op.pid+' ไม่ใช่ชิ้นเดิมแล้ว (sig ไม่ตรง)');continue;}
    if(op.k==='del'){del.add(op.pid);st.applied.del++;}
    else{const p=byPid.get(op.pid);p.x=Math.round(op.x);p.y=Math.round(op.y);p.s=+(+op.s).toFixed(2);p.v=op.v;p.f=op.f;st.applied.mov++;}}
  adds.sort((a,b)=>+a.id.slice(3)-+b.id.slice(3));
  const out=props.filter(p=>!(typeof p.pid==='string'&&del.has(p.pid)));
  for(const a of adds){out.push({t:a.t,x:Math.round(a.x),y:Math.round(a.y),s:+(+a.s).toFixed(2),v:a.v,f:a.f,ph:ovPh(a.id),pid:a.id});st.applied.add++;}
  if(st.skipped.length){st.why=st.skipped.length+' รายการถูกข้าม (วัตถุเปลี่ยนไป/หาย/ไม่ผ่านกฎ) — ข้อมูลยังเก็บไว้';ovToast('⚠ Overrides: '+st.why,'bad');ovNote(zid+': '+st.why);}
  const n=st.applied.mov+st.applied.del+st.applied.add;
  if(n>0){OV.pend={zid,rev:zd.rev};try{if(PDC.chk&&PDC.chk.zid===zid)PDC.chk=null;}catch(e){}}      // the Phase-4 connection check runs once, after the solids exist: here, so a failure drops only the overrides (not the whole recipe)
  ovNote(`${zid}: rev ${zd.rev} → ย้าย ${st.applied.mov} · ลบ ${st.applied.del} · เพิ่ม ${st.applied.add} · ข้าม ${st.skipped.length}`);
  return out;}

/* ---------- hooks (lazy) ---------- */
function ovInstall(){if(OV.inst)return;
  const o={loadPropsFor,buildSolids,toggleEditor},w={};OV.orig=o;OV.w=w;
  w.loadPropsFor=function(zid){
    const r=o.loadPropsFor.apply(this,arguments);
    if(!OV.inst)return r;
    if(!OV.zones.has(zid)){if(OV.zid===zid){OV.base=null;}return r;}
    if(OV.skipOnce===zid){OV.skipOnce=null;OV.base=null;OV.st[zid]={zone:zid,active:false,code:'rejected',why:'ใช้สูตรล้วน (overrides ถูกข้ามรอบนี้)',applied:{mov:0,del:0,add:0},skipped:[],rev:0};try{const a=ovBaseOf(r);OV.base=a;OV.zid=zid;OV.view=PDC.view&&PDC.viewZone===zid?PDC.view:null;}catch(e){}return r;}
    try{return ovApply(zid,r);}catch(err){ovNote('apply error: '+(err&&err.message||err));OV.pend=null;ovToast('⚠ ระบบ Overrides ทำงานผิดพลาด จึงใช้สูตรล้วนในรอบนี้ (ข้อมูลยังอยู่)');return o.loadPropsFor.apply(this,arguments);}};
  w.buildSolids=function(){const r=o.buildSolids.apply(this,arguments);if(!OV.inst)return r;const k=OV.pend;if(!k)return r;OV.pend=null;
    try{if(G.zone!==k.zid)return r;const rc=DECOR_DATA.zones[k.zid],c=pdContext(k.zid),res=pdConnCheck(pdConnList(rc,c));
      if(PDC.last[k.zid])PDC.last[k.zid].conn={ok:res.ok,n:res.n,failed:res.failed.map(f=>f.id),narrow:res.narrow||[],withOverrides:true};
      if(!res.ok){(OV.rejected=OV.rejected||{})[k.zid]=k.rev;const why='Overrides ทำให้เส้นทางที่จำเป็นถูกบล็อก ('+res.failed.map(f=>f.id).join(', ')+') จึงไม่ใช้ overrides ในรอบนี้ — ข้อมูลยังเก็บไว้ ไม่ถูกลบ';
        ovNote('REJECT '+k.zid+': '+why);ovToast('⚠ '+why);OV.skipOnce=k.zid;PROPS=loadPropsFor(k.zid);return buildSolids();}}
    catch(e){ovNote('connection check error: '+e);}
    return r;};
  w.toggleEditor=function(force){
    if(!OV.inst)return o.toggleEditor.apply(this,arguments);
    const was=ED.on,leaving=was&&(force===false||force===undefined);
    if(leaving&&OV.mode){let dropped=false;if(ovDirty()){ovRevert(true);dropped=true;}ovModeEnd();if(dropped)ovToast('ทิ้งการแก้ไข Overrides ที่ยังไม่บันทึกแล้ว (กลับสถานะที่บันทึกไว้ล่าสุด)','warn');}
    const r=o.toggleEditor.apply(this,arguments);
    if(ED.on&&!was){try{ovModeStart();}catch(e){ovNote('mode start error: '+e);}}
    return r;};
  loadPropsFor=w.loadPropsFor;buildSolids=w.buildSolids;toggleEditor=w.toggleEditor;OV.inst=true;ovStyle();}
function ovUninstall(){if(!OV.inst)return;if(OV.mode)ovModeEnd();OV.inst=false;OV.pend=null;const o=OV.orig,w=OV.w;     // a hook somebody wrapped on top of ours stays as a pass-through (OV.inst=false)
  if(loadPropsFor===w.loadPropsFor)loadPropsFor=o.loadPropsFor;if(buildSolids===w.buildSolids)buildSolids=o.buildSolids;if(toggleEditor===w.toggleEditor)toggleEditor=o.toggleEditor;OV.orig=null;OV.w=null;OV.base=null;}

/* ---------- editor session (override mode) ---------- */
const OV_BLOCK='#edSave,#edRevert,#edReset,#edExport,#edImport,#edClear,#edApply,#edCopy,#edFileDl,#edFileOpen,#edImgImp';
function ovModeOk(){return OV.inst&&OV.zones.has(G.zone)&&OV.zid===G.zone&&!!OV.base&&ovAvail(G.zone).ok;}
function ovModeStart(){const zid=G.zone;OV.mode=false;OV.closeAsk=0;ovPanel();
  const av=ovAvail(zid);
  if(!OV.zones.has(zid)){ovPanelSay();return;}
  if(!av.ok||OV.zid!==zid||!OV.base){OV.mode=false;document.body.classList.remove('ovmode');ovPanelSay(av.ok?'โซนนี้ยังไม่ได้ถูกสร้างด้วยสูตร (ลองเข้าโซนใหม่หลังเปิด Phase 4)':av.why);return;}
  const rd=ovReadDoc();if(rd.state==='newer'){ovPanelSay(rd.why+' — ยังไม่เปิดโหมดแก้ไข (ไม่เขียนทับข้อมูลเวอร์ชันใหม่กว่า)');return;}
  OV.mode=true;document.body.classList.add('ovmode');ovGuards(true);
  try{ED.cat=ED.cat||'trees';ED.sel=null;ED.tool='select';ED.pick=null;ED.hover=null;ED.drag=null;OV.pp=null;ED.dirty=false;if(typeof edHistReset==='function')edHistReset();renderEditor();}catch(e){}
  ovSyncCompact();ovPanelSay();ovNote('mode start '+zid);}
function ovModeEnd(){if(!OV.mode&&!document.body.classList.contains('ovmode'))return;OV.mode=false;ovGuards(false);document.body.classList.remove('ovmode');document.body.classList.remove('ovmin');try{ovSyncCompact();const m=document.getElementById('ovMini');if(m)m.hidden=true;}catch(e){}OV.closeAsk=0;OV.cancelAsk=0;
  try{if(typeof OBL!=='undefined'&&OBL)OBL.dirty=true;}catch(e){}   // Phase 6 re-indexes the CURRENT props on its next frame (an in-place move keeps the array identity, which its sync check cannot see)
  ovPanelSay();ovNote('mode end');}
const ovLockWhy=()=>'🔒 วัตถุล็อก (ประตู/NPC/อาคาร/กำแพงขอบ) — เลือกดูได้ แต่ย้ายหรือลบไม่ได้';
function ovFirePlace(){const pp=OV.pp;OV.pp=null;if(!pp||!OV.mode||ED.tool!=='place'||!ED.pick||Date.now()-pp.t>1500)return;const g=OV.guard;if(!g)return;
  const q=ovTypeOk(ED.pick,ED.scale*1.12),q2=ovTypeOk(ED.pick,ED.scale*.88);if(!q.ok||!q2.ok){ovSay('วางไม่ได้: '+((!q.ok?q:q2).why||'ชนิดนี้ไม่ผ่านกฎความปลอดภัย'));return;}
  const n=PROPS.length;g.edPointerDown.call(null,{clientX:pp.cx,clientY:pp.cy,button:0});
  if(PROPS.length>n){const np=PROPS[PROPS.length-1];ED.tool='select';ED.pick=null;ED.hover=null;ED.drag=null;ED.sel=np;ovSay('เพิ่มแล้ว 1 ชิ้น — กลับสู่โหมดเลือก/ย้าย (ชิ้นที่เพิ่งเพิ่มถูกเลือกอยู่ ลากเพื่อย้ายได้)');try{renderEditor();renderEdSel();}catch(e){}ovPanelSay();}}
function ovDrawSel(){const p=ED.sel;if(!p||!OV.mode)return;const b=propBounds(p),lk=ovLocked(p),col=lk?'#ff6b8b':'#ffffff',pad=6;ctx.save();ctx.lineWidth=4;ctx.strokeStyle='rgba(0,0,0,.65)';ctx.setLineDash([]);ctx.strokeRect(b.x-pad,b.y-pad,b.w+pad*2,b.h+pad*2);
  ctx.lineWidth=2.5;ctx.strokeStyle=col;if(lk)ctx.setLineDash([10,6]);ctx.strokeRect(b.x-pad,b.y-pad,b.w+pad*2,b.h+pad*2);ctx.setLineDash([]);ctx.fillStyle=col;for(const [cx,cy] of [[b.x-pad,b.y-pad],[b.x+b.w+pad,b.y-pad],[b.x-pad,b.y+b.h+pad],[b.x+b.w+pad,b.y+b.h+pad]])ctx.fillRect(cx-5,cy-5,10,10);
  ctx.font='bold 13px sans-serif';ctx.textAlign='center';const t=lk?'🔒 ล็อก':'เลือกอยู่ · ลากเพื่อย้าย';ctx.lineWidth=3;ctx.strokeStyle='rgba(0,0,0,.8)';ctx.strokeText(t,b.x+b.w/2,b.y-pad-8);ctx.fillStyle=col;ctx.fillText(t,b.x+b.w/2,b.y-pad-8);ctx.restore();}
/* guards that exist ONLY while override mode is active */
function ovGuards(on){
  if(on&&!OV.guard){const g=OV.guard={propAt,edEraseAt,edPointerDown,edPointerMove,edPointerUp,edDelete,drawEditorOverlay,cleanProps,renderEditor,edMark,edPlaceAt};
    propAt=function(wx,wy){let best=null,by=-1e9;for(const p of PROPS){const b=propBounds(p);if(wx<b.x||wx>b.x+b.w||wy<b.y||wy>b.y+b.h)continue;const cx=b.x+b.w/2,cy=b.y+b.h*.55,nx=(wx-cx)/(b.w*.5),ny=(wy-cy)/(b.h*.55);if(nx*nx+ny*ny>1.05)continue;if(p.y>by){by=p.y;best=p;}}return best;};
    edEraseAt=function(wx,wy){let n=0,locked=0;for(let i=PROPS.length-1;i>=0;i--){const p=PROPS[i];if(d2(p.x,p.y,wx,wy)<ED.erR){if(ovLocked(p)){locked++;continue;}if(ED.sel===p)ED.sel=null;PROPS.splice(i,1);n++;}}
      if(n){edMark();emitThemed(wx,wy,THEMES.void,6,90);}else if(locked)ovSay('วัตถุล็อก (ประตู/NPC/อาคาร/กำแพงขอบ) ลบไม่ได้ในโหมดนี้');};
    edPointerDown=function(e){OV.pp=null;
      if(ED.tool==='place'){if(!ED.pick){ovSay('โหมดเพิ่มวัตถุ: เลือกชนิดวัตถุจากแผงก่อน (หรือกด “เลือก/ย้าย” เพื่อกลับ)');return;}
        OV.pp={cx:e.clientX,cy:e.clientY,t:Date.now()};return;}   // a placement is decided on pointer-UP (and only if the finger did not travel): a drag / pan / panel tap never creates anything
      if(ED.tool==='delete'){const p=propAt(mwx(e.clientX,e.clientY),mwy(e.clientX,e.clientY));if(p&&ovLocked(p)){ED.sel=p;ED.drag=null;ovSay(ovLockWhy());try{renderEdSel();}catch(_){}return;}}
      const r=g.edPointerDown.apply(this,arguments);
      if((ED.tool==='select')&&ED.sel&&ovLocked(ED.sel)){ED.drag=null;ovSay(ovLockWhy());}else if(ED.tool==='select'&&OV.msg&&/^🔒/.test(OV.msg))OV.msg='';
      try{ovMiniSay();}catch(_){}return r;};
    edPointerMove=function(e){if(OV.pp&&Math.hypot(e.clientX-OV.pp.cx,e.clientY-OV.pp.cy)>10)OV.pp=null;return g.edPointerMove.apply(this,arguments);};
    edPointerUp=function(){const r=g.edPointerUp.apply(this,arguments);try{ovFirePlace();}catch(e){ovNote('place error '+e);}return r;};
    edDelete=function(){if(ED.sel&&ovLocked(ED.sel)){ovSay(ovLockWhy());return;}return g.edDelete.apply(this,arguments);};
    drawEditorOverlay=function(){g.drawEditorOverlay.apply(this,arguments);try{ovDrawSel();}catch(e){}};
    edPlaceAt=function(wx,wy){const q=ovTypeOk(ED.pick,ED.scale);if(!q.ok){ovSay('วางไม่ได้: '+(q.why||''));return {t:ED.pick,x:wx,y:wy,s:1,v:0,f:1,ph:0,_void:1};}return g.edPlaceAt.apply(this,arguments);};
    cleanProps=function(){return PROPS.map(p=>{const o={t:p.t,x:Math.round(p.x),y:Math.round(p.y),s:+(+p.s).toFixed(2),v:p.v,f:p.f};if(p.pid)o.pid=p.pid;if(p.edge)o.edge=1;return o;});};   // `edge` must survive an Undo/Redo snapshot: without it the boundary ring is no longer recognised (locked / already present) and the old generator adds a second ring
    renderEditor=function(){const r=g.renderEditor.apply(this,arguments);try{ovFilterPalette();ovMiniSay();}catch(e){}return r;};
    edMark=function(){let bad=false;for(const p of PROPS){if(p.r){delete p.r;bad=true;}if(p.nc){p.nc=0;bad=true;}}   // rotation / per-object "no collision" are not part of an override: refuse them instead of previewing something that Save would silently drop
      if(bad)ovSay('หมุนวัตถุ / ปิดการชนรายชิ้น ยังไม่รองรับในโหมด Overrides — ไม่ได้ใช้ (ใช้ได้แค่ เพิ่ม ย้าย ลบ ขนาด พลิก แบบ)');
      const r=g.edMark.apply(this,arguments);try{ovPanelSay();}catch(e){}return r;};}
  else if(!on&&OV.guard){const g=OV.guard;OV.guard=null;
    if(typeof propAt==='function'&&propAt!==g.propAt)propAt=g.propAt;if(edEraseAt!==g.edEraseAt)edEraseAt=g.edEraseAt;if(edPointerDown!==g.edPointerDown)edPointerDown=g.edPointerDown;if(edPointerMove!==g.edPointerMove)edPointerMove=g.edPointerMove;if(edPointerUp!==g.edPointerUp)edPointerUp=g.edPointerUp;if(edDelete!==g.edDelete)edDelete=g.edDelete;if(drawEditorOverlay!==g.drawEditorOverlay)drawEditorOverlay=g.drawEditorOverlay;
    if(cleanProps!==g.cleanProps)cleanProps=g.cleanProps;if(renderEditor!==g.renderEditor)renderEditor=g.renderEditor;if(edMark!==g.edMark)edMark=g.edMark;if(edPlaceAt!==g.edPlaceAt)edPlaceAt=g.edPlaceAt;}}
function ovFilterPalette(){const gr=document.getElementById('edGrid');if(!gr)return;let hid=0;gr.querySelectorAll('[data-prop]').forEach(b=>{const ok=ovTypeOk(b.dataset.prop,1).ok;b.hidden=!ok;b.style.display=ok?'':'none';if(!ok)hid++;});OV.hiddenTypes=hid;}

/* ---------- classify the editor's current props against the generated base ---------- */
function ovNorm(p){return {t:p.t,x:Math.round(p.x),y:Math.round(p.y),s:+(+p.s).toFixed(2),v:p.v|0,f:p.f<0?-1:1};}
function ovDiff(zd){   // → {ops,errors,counts,assign}. Pure: touches neither storage nor the props. `next` = the id counter new objects are numbered from; `assign` = [{p,id}] to apply when (and only when) the save goes ahead.
  const base=OV.base,errors=[],ops=[],assign=[],seen=new Set(),addSeen=new Set(),cnt={mov:0,del:0,add:0},pidAdd=/^ov:(\d+)$/;
  let next=zd&&Number.isInteger(zd.next)?zd.next:1;
  for(const p of PROPS){const m=typeof p.pid==='string'&&!base.has(p.pid)?pidAdd.exec(p.pid):null;if(m)next=Math.max(next,+m[1]+1);}   // an id an object already carries is never handed out again
  for(const p of PROPS){const n=ovNorm(p),pid=typeof p.pid==='string'?p.pid:null;
    if(pid&&base.has(pid)&&!seen.has(pid)){seen.add(pid);const b=base.get(pid);
      if(n.t!==b.t){errors.push(`เปลี่ยนชนิดของ ${pid} ไม่ได้`);continue;}
      const ch=n.x!==b.x||n.y!==b.y||n.s!==b.s||n.v!==b.v||n.f!==b.f;
      if(ch){if(b.locked){errors.push(`${pid} (${b.t}) เป็นวัตถุล็อก ย้ายหรือแก้ไม่ได้`);continue;}
        ops.push({k:'mov',pid,sig:ovSigOf(b),x:n.x,y:n.y,s:n.s,v:n.v,f:n.f});cnt.mov++;}
      continue;}
    if(pid&&pidAdd.test(pid)&&!addSeen.has(pid)&&!base.has(pid)){addSeen.add(pid);ops.push({k:'add',id:pid,...n});cnt.add++;continue;}
    const id='ov:'+(next++);ops.push({k:'add',id,...n});cnt.add++;assign.push({p,id});}   // a new object (placed, brushed, duplicated, or a copy that carried a pid) gets its own never-reused id
  for(const [pid,b] of base){if(seen.has(pid))continue;if(b.locked){errors.push(`${pid} (${b.t}) เป็นวัตถุล็อก ลบไม่ได้`);continue;}if(b.dup){errors.push(`${pid} ซ้ำในสูตร แก้ไม่ได้`);continue;}ops.push({k:'del',pid,sig:ovSigOf(b)});cnt.del++;}
  return {ops,errors,counts:cnt,next,assign};}
function ovCounts(){try{const rd=ovReadDoc(),zd=rd.state==='ok'?rd.doc.zones[G.zone]:null;
  // counts only (no id assignment): compare fields by pid
  const base=OV.base;let mov=0,add=0,seen=new Set();for(const p of PROPS){const pid=typeof p.pid==='string'?p.pid:null;if(pid&&base.has(pid)&&!seen.has(pid)){seen.add(pid);const b=base.get(pid),n=ovNorm(p);if(n.x!==b.x||n.y!==b.y||n.s!==b.s||n.v!==b.v||n.f!==b.f||n.t!==b.t)mov++;}else add++;}
  let del=0;for(const [pid] of base)if(!seen.has(pid))del++;return {mov,del,add};}catch(e){return {mov:0,del:0,add:0};}}
function ovStoredKey(){const st=OV.st[G.zone];return st?`${st.applied.mov}/${st.applied.del}/${st.applied.add}`:'';}
function ovDirty(){return !!(OV.mode&&ED.dirty);}

/* ---------- validate (heavy: only on Save / the Check button, never per frame) ---------- */
function ovValidate(){
  const zid=G.zone,res={ok:false,errors:[],warnings:[],ops:[],counts:{mov:0,del:0,add:0},conn:null,ms:0};const t0=performance.now();
  if(!OV.mode){res.errors.push('ไม่ได้อยู่ในโหมด Overrides');return res;}
  {const av=ovAvail(zid);if(!av.ok||!OV.base){res.errors.push('บันทึกไม่ได้ — '+(av.ok?'ฐานสูตรของโซนนี้หายไป (เข้าโซนใหม่แล้วลองอีกครั้ง)':av.why)+' · ข้อมูล Overrides เดิมยังอยู่ครบ');return res;}}
  const rd=ovReadDoc();if(rd.state==='newer'){res.errors.push(rd.why);return res;}
  const zd=rd.state==='ok'?rd.doc.zones[zid]:null;if(zd!==undefined&&zd!==null&&!ovZoneOk(zd)){res.warnings.push('ข้อมูล overrides ที่บันทึกไว้ของโซนนี้เสีย — เมื่อกดบันทึกจะเก็บสำเนาไว้ก่อนแล้วเขียนใหม่');}
  const keepNext=(zd&&ovZoneOk(zd))?zd.next:1;
  const d=ovDiff(zd&&ovZoneOk(zd)?zd:{next:keepNext});res.ops=d.ops;res.counts=d.counts;res.next=d.next;res.assign=d.assign;
  for(const e of d.errors)res.errors.push(e);
  if(d.ops.length>ovC().maxOps)res.errors.push(`แก้ไขมากเกินไป (${d.ops.length} > ${ovC().maxOps} รายการ)`);
  const Z=ZONES[zid],m=ovC().margin,V=OV.view;
  for(const op0 of d.ops){if(op0.k==='del')continue;const op={...op0,t:op0.t||(OV.base.get(op0.pid)||{}).t},id=op.pid||op.id,nm=(PROP_DEFS[op.t]||{}).n||op.t;
    const bad=ovOpCheck(op);if(bad){res.errors.push(`${id}: ${bad}`);continue;}
    const q=ovTypeOk(op.t,op.s);if(!q.ok){res.errors.push(`${nm} (${id}): ไม่ผ่านกฎความปลอดภัยของวัตถุ — ${q.why||''}`);continue;}
    if(op.x<m||op.y<m||op.x>Z.w-m||op.y>Z.h-m){res.errors.push(`${nm} (${id}) อยู่ใกล้ขอบแมพเกินไป (ต้องห่างขอบอย่างน้อย ${m} px)`);continue;}
    if(V){const fr=pdFoot(op.t,op.s)*.5;let hit=null;
      for(const p of V.protect)if(pdSD(p.sh,op.x,op.y)<fr){hit=`เขตห้ามวาง «${p.id}»`;break;}
      if(!hit)for(const sh of V.fixedPads)if(pdSD(sh,op.x,op.y)<fr){hit='ใกล้อาคาร/วัตถุถาวร';break;}
      if(!hit)for(const dz of V.density)if(dz.lv===0&&pdSD(dz.sh,op.x,op.y)<=0){hit=`โซนห้ามมี «${dz.id}»`;break;}
      if(hit){res.errors.push(`${nm} (${id}) ทับ${hit}`);continue;}}}
  // collision / nav as the existing editor path builds them, then the recipe's requiredConnections with the existing PATH CLEARANCE
  try{buildSolids();const rc=DECOR_DATA.zones[zid],c=pdContext(zid),r=pdConnCheck(pdConnList(rc,c));res.conn={ok:r.ok,n:r.n,failed:r.failed.map(f=>f.id),narrow:r.narrow||[],agentR:r.agentR};
    if(!r.ok)res.errors.push('วางขวางเส้นทางที่จำเป็นต่อเกม: '+r.failed.map(f=>f.id+(r.narrow&&r.narrow.indexOf(f.id)>=0?' (ช่องแคบกว่าตัวละคร)':'')).join(', '));}
  catch(e){res.errors.push('ตรวจเส้นทางไม่สำเร็จ: '+(e&&e.message||e));}
  res.ok=!res.errors.length;res.ms=+(performance.now()-t0).toFixed(1);OV.lastCheck=res;return res;}

/* ---------- save / cancel / rollback / clear ---------- */
function ovSame(a,b){if(a.length!==b.length)return false;for(let i=0;i<a.length;i++){const p=a[i],q=b[i];if((p.pid||null)!==(q.pid||null)||p.t!==q.t||Math.round(p.x)!==Math.round(q.x)||Math.round(p.y)!==Math.round(q.y)||+(+p.s).toFixed(2)!==+(+q.s).toFixed(2)||(p.v|0)!==(q.v|0)||(p.f<0?-1:1)!==(q.f<0?-1:1))return false;}return true;}
function ovReload(){const zid=G.zone;PROPS=loadPropsFor(zid);try{ED.sel=null;ED.dirty=false;ED.drag=null;ED.hover=null;}catch(e){}buildSolids();try{if(typeof edHistReset==='function')edHistReset();}catch(e){}try{if(typeof OBL!=='undefined'&&OBL)OBL.dirty=true;}catch(e){}try{renderEditor();}catch(e){}}
function ovRevert(silent){if(!OV.mode&&!silent)return false;ovReload();if(!silent)ovSay('ยกเลิกแล้ว — กลับสู่สถานะที่บันทึกไว้ล่าสุด');ovPanelSay();return true;}
function ovSave(){
  if(!OV.mode)return {ok:false,errors:['ไม่ได้อยู่ในโหมด Overrides']};
  const zid=G.zone,v=ovValidate();
  if(!v.ok){ovSay('บันทึกไม่ผ่าน — ไม่ได้เขียนอะไรเลย: '+v.errors[0]+(v.errors.length>1?` (และอีก ${v.errors.length-1} ข้อ)`:''));ovToast('บันทึก Overrides ไม่ผ่าน: '+v.errors[0]);ovPanelSay();return {ok:false,errors:v.errors,ops:v.ops};}
  const rd=ovReadDoc(),prev=rd.state==='ok'?rd.doc.zones[zid]:null,pr=ovZoneOk(prev)?prev:null;
  {const canon=a=>JSON.stringify((a||[]).map(o=>JSON.stringify(o)).sort());if(canon(v.ops)===canon(pr?pr.ops:[])&&!(v.assign&&v.assign.length)&&rd.state!=='corrupt'){ovSay('ไม่มีการเปลี่ยนแปลงจากที่บันทึกไว้ — ไม่ได้เขียนอะไร');ovPanelSay();return {ok:true,noop:true,rev:pr?pr.rev:0,counts:v.counts,ops:v.ops};}}
  const zd={rev:(pr?pr.rev:0)+1,next:Math.max(v.next,pr?pr.next:1),seed:pdSeedFor(zid,DECOR_DATA.zones[zid]),savedAt:new Date().toISOString(),build:OVR_BUILD,ops:v.ops};
  for(const a of (v.assign||[]))a.p.pid=a.id;      // only now (validation passed) do new objects receive their ids
  // normalise what is on screen to exactly what will be stored
  for(const p of PROPS){if(typeof p.pid==='string'&&(OV.base.has(p.pid)&&!OV.base.get(p.pid).locked||/^ov:\d+$/.test(p.pid))){p.x=Math.round(p.x);p.y=Math.round(p.y);p.s=+(+p.s).toFixed(2);}}
  const shot=PROPS.map(p=>({pid:p.pid,t:p.t,x:p.x,y:p.y,s:p.s,v:p.v,f:p.f}));
  const mainRaw=ovRaw(ovC().dataKey),bakRaw=ovRaw(ovC().bakKey),w=ovWrite(zid,zd);
  if(!w.ok){for(const a of (v.assign||[]))delete a.p.pid;ovSay(w.error);ovToast(w.error);ovPanelSay();return {ok:false,errors:[w.error]};}   // the preview stays as it was: ids handed out for this attempt are taken back
  // read it back through the REAL loader and compare with what the admin saw
  let np=null,okBack=false;try{OV.rejected&&delete OV.rejected[zid];np=loadPropsFor(zid);okBack=ovSame(np,shot);}catch(e){okBack=false;}
  if(!okBack){ovRestoreRaw(mainRaw,bakRaw);try{delete OV.rejected[zid];}catch(e){}ovSay('ตรวจย้อนหลังหลังบันทึกไม่ตรงกับที่เห็น — คืนข้อมูลเดิมแล้ว ไม่ได้บันทึก');ovToast('บันทึก Overrides ไม่สำเร็จ: ตรวจย้อนหลังไม่ตรง (คืนข้อมูลเดิมแล้ว)');ovReload();ovPanelSay();return {ok:false,errors:['readback mismatch']};}
  PROPS=np;ED.sel=null;ED.dirty=false;ED.drag=null;ED.hover=null;buildSolids();
  try{if(typeof edHistReset==='function')edHistReset();}catch(e){}try{if(typeof OBL!=='undefined'&&OBL)OBL.dirty=true;}catch(e){}try{renderEditor();}catch(e){}
  ovSay(`บันทึกแล้ว ✓ rev ${zd.rev} · ย้าย ${v.counts.mov} · ลบ ${v.counts.del} · เพิ่ม ${v.counts.add} (ตรวจเส้นทางผ่าน ${v.conn?v.conn.n:0} เส้น)`);ovPanelSay();ovNote(`save ${zid} rev ${zd.rev} ops ${v.ops.length}`);
  return {ok:true,rev:zd.rev,counts:v.counts,ops:v.ops};}
function ovHistory(zid){zid=zid||G.zone;const b=ovReadBak();return (Array.isArray(b.zones[zid])?b.zones[zid]:[]).map((z,i)=>({index:i,rev:z.rev,savedAt:z.savedAt,ops:Array.isArray(z.ops)?z.ops.length:0}));}
function ovRestoreTo(zid,mk,label){   // write a NEW revision whose ops come from `mk(prev)`; the replaced revision goes to the history
  const rd=ovReadDoc();if(rd.state==='newer')return {ok:false,error:rd.why};const prev=rd.state==='ok'&&ovZoneOk(rd.doc.zones[zid])?rd.doc.zones[zid]:null;
  const nz=mk(prev);if(!nz)return {ok:false,error:'ไม่มีข้อมูลให้คืน'};
  const mainRaw=ovRaw(ovC().dataKey),bakRaw=ovRaw(ovC().bakKey),zd={rev:(prev?prev.rev:0)+1,next:Math.max(nz.next||1,prev?prev.next:1),seed:nz.seed!==undefined?nz.seed:null,savedAt:new Date().toISOString(),build:OVR_BUILD,ops:nz.ops,from:label};
  const w=ovWrite(zid,zd);if(!w.ok)return w;try{delete OV.rejected[zid];}catch(e){}
  if(G.zone===zid){try{ovReload();}catch(e){ovRestoreRaw(mainRaw,bakRaw);return {ok:false,error:'โหลดผลหลังคืนข้อมูลไม่สำเร็จ — คืนข้อมูลเดิมแล้ว'};}}
  return {ok:true,rev:zd.rev};}
function ovRollback(zid,index){zid=zid||G.zone;const h=ovReadBak().zones[zid];if(!Array.isArray(h)||!h.length)return {ok:false,error:'ยังไม่มีเวอร์ชันก่อนหน้าให้ย้อนกลับ'};
  const i=index===undefined?h.length-1:index;if(!(i>=0&&i<h.length)||!ovZoneOk(h[i]))return {ok:false,error:'เวอร์ชันที่เลือกไม่ถูกต้อง'};
  const r=ovRestoreTo(zid,()=>({ops:h[i].ops,next:h[i].next,seed:h[i].seed}),'rollback rev '+h[i].rev);if(r.ok)ovNote(`rollback ${zid} → ops ของ rev ${h[i].rev} (เป็น rev ${r.rev})`);return r;}
function ovClear(zid){zid=zid||G.zone;const r=ovRestoreTo(zid,p=>({ops:[],next:p?p.next:1,seed:p?p.seed:null}),'clear');if(r.ok)ovNote(`clear ${zid} → rev ${r.rev}`);return r;}

/* ---------- UI (inside the existing #editor panel; works with touch) ---------- */
function ovStyle(){if(document.getElementById('ovStyle'))return;const st=document.createElement('style');st.id='ovStyle';
  st.textContent='#ovBox{margin:8px 0;padding:8px;border:1px solid var(--gold,#e7c35c);border-radius:8px;background:rgba(231,195,92,.07);font-size:12px;line-height:1.5}#ovBox b.t{font-family:var(--display);letter-spacing:.05em}#ovBox .row{margin-top:6px;flex-wrap:wrap;gap:6px}#ovBox .btn{min-height:40px}#ovBox .sm{font-size:11px;opacity:.85}#ovBox pre{white-space:pre-wrap;margin:4px 0 0;font-size:11px;max-height:110px;overflow:auto}'
  +'#ovBox .pad{display:grid;grid-template-columns:repeat(3,44px);grid-template-rows:repeat(2,44px);gap:4px;justify-content:start;margin-top:6px}#ovBox .pad button{touch-action:none;font-size:18px;padding:0}'
  +'body.ovmode #editor :is('+OV_BLOCK+'){display:none!important}body.ovmin #editor{display:none!important}body.ovmode #editor #edStatus,body.ovmode #editor #edJson,body.ovmode #editor #edJsonBtns{display:none!important}body.ovmode #editor .hint{display:none}'
  +'#ovMini{position:fixed;left:6px;right:6px;bottom:calc(6px + env(safe-area-inset-bottom,0px));z-index:70;display:flex;flex-wrap:wrap;gap:4px;align-items:center;background:rgba(8,12,24,.94);border:1px solid var(--gold,#e7c35c);border-radius:12px;padding:5px;box-sizing:border-box}#ovMini[hidden],#ovStat[hidden],#ovPad[hidden]{display:none!important}'
  +'#ovMini .btn{min-width:44px;min-height:44px;padding:0 6px;margin:0;font-size:15px;flex:none;touch-action:manipulation}#ovMini #ovMiniShow{font-size:12.5px}#ovMini #ovMiniTool{order:-1;flex:1 1 100%;min-height:44px;min-width:0;font-size:13px;font-weight:700;text-align:left;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;border-color:var(--cyan,#5ef0e0);color:var(--cyan,#5ef0e0)}#ovMini[data-mode=place] #ovMiniTool{border-color:var(--gold,#e7c35c);color:var(--gold,#e7c35c);background:rgba(231,195,92,.14)}#ovMini #ovMiniAdd{flex:1 1 auto;min-width:0;font-size:12px;white-space:nowrap;padding:0 4px}#ovMini #ovMiniHud[aria-pressed=true]{outline:2px solid var(--cyan,#5ef0e0)}'
  +'@media (min-width:520px){#ovMini #ovMiniTool{order:0;flex:1 1 auto;font-size:13px}#ovMini #ovMiniAdd{flex:none}}@media (min-width:520px){#ovPad{bottom:calc(66px + env(safe-area-inset-bottom,0px))}}'
  +'#ovStat{position:fixed;left:8px;top:calc(8px + env(safe-area-inset-top,0px));max-width:calc(100vw - 16px);z-index:69;pointer-events:none;font-size:11.5px;line-height:1.35;padding:4px 8px;border-radius:8px;background:rgba(8,12,24,.82);color:#fff;border:1px solid rgba(231,195,92,.5)}'
  +'#ovPad{position:fixed;right:8px;bottom:calc(116px + env(safe-area-inset-bottom,0px));z-index:69;display:none;grid-template-columns:repeat(3,44px);grid-template-rows:repeat(2,44px);gap:4px;opacity:.88}body.ovmin #ovPad:not([hidden]){display:grid}#ovPad button{touch-action:none;font-size:18px;padding:0;min-width:44px;min-height:44px;margin:0}'
  +'body.ovcompact :is(#log,#banner,#autoChip,#tPots,#touchUI){display:none!important}body.ovcompact:not(.ovhud) :is(#hud,#menu,#zoneTag){display:none!important}'
  +'body.ovcompact:not(.ovmin) #editor{left:6px!important;right:6px!important;top:auto!important;bottom:calc(118px + env(safe-area-inset-bottom,0px))!important;width:auto!important;max-height:min(56vh,calc(100vh - 100px))!important;max-height:min(56dvh,calc(100dvh - 100px))!important;border-radius:14px!important}'
  +'body.ovcompact #editor :is(.btn,[data-tool]){min-height:44px}body.ovcompact #ovBox .ovx{display:none!important}body.ovcompact #ovBox{margin:4px 0}'
  +'@media (orientation:landscape) and (max-height:520px){body.ovcompact:not(.ovmin) #editor{left:auto!important;right:6px!important;top:6px!important;bottom:calc(118px + env(safe-area-inset-bottom,0px))!important;width:min(54vw,420px)!important;max-height:none!important}}';
  document.head.appendChild(st);}
function ovSay(m){OV.msg=m;const e=document.getElementById('ovMsg');if(e)e.textContent=m;try{ovMiniSay();}catch(_){}}
function ovPanel(){if(!OV.inst)return;const ed=document.getElementById('editor');if(!ed)return;let d=document.getElementById('ovBox');
  if(!d){d=document.createElement('div');d.id='ovBox';d.hidden=true;
    d.innerHTML=`<b class="t">🧩 โหมด Overrides (Phase 7 · ทดลอง)</b> <span class="muted" style="font-size:11px">${OVR_BUILD}</span>
<div id="ovState" class="ovx" style="margin-top:4px"></div><div id="ovCnt" class="ovx" style="margin-top:4px"></div>
<div class="row"><button class="btn gold ovx" id="ovSave">💾 บันทึก Overrides</button><button class="btn" id="ovCheck">🔍 ตรวจก่อนบันทึก</button><button class="btn ovx" id="ovCancel">↩ ยกเลิก (กลับสถานะก่อนแก้)</button></div>
<div class="row ovx"><button class="btn" id="ovHide">🗺 ย่อแผง เพื่อแตะ/ลากแก้บนฉาก (มือถือ)</button></div>
<div class="row"><button class="btn sm" id="ovBack">⏪ ย้อนเวอร์ชันบันทึกก่อนหน้า</button><button class="btn sm" id="ovClear">🗑 ล้าง overrides (กลับสูตรล้วน)</button></div>
<div class="muted sm ovx" style="margin-top:6px">เลื่อนกล้อง (มือถือ):</div>
<div class="pad ovx"><span></span><button class="btn" data-k="arrowup" aria-label="เลื่อนขึ้น">▲</button><span></span><button class="btn" data-k="arrowleft" aria-label="เลื่อนซ้าย">◀</button><button class="btn" data-k="arrowdown" aria-label="เลื่อนลง">▼</button><button class="btn" data-k="arrowright" aria-label="เลื่อนขวา">▶</button></div>
<div id="ovMsg" style="margin-top:6px"></div><pre id="ovList"></pre>
<div class="muted sm ovx" style="margin-top:6px">ล็อก (ย้าย/ลบไม่ได้): ประตู · วาร์ป · NPC · Landmark · อาคารถาวร · เควส/บอส · กำแพงและต้นไม้ขอบแมพ · ไม่รองรับวัตถุนำเข้า/กำหนดเอง · ลาก/แก้ยังไม่เขียนข้อมูลจนกด “บันทึก Overrides”</div>`;
    const hd=ed.querySelector('header');if(hd&&hd.parentNode===ed)ed.insertBefore(d,hd.nextSibling);else ed.insertBefore(d,ed.firstChild);   // right under the title: the save / cancel buttons must not be scrolled out of reach on a phone
    const $q=s=>d.querySelector(s);
    $q('#ovSave').onclick=()=>ovSave();
    $q('#ovCheck').onclick=()=>{const v=ovValidate();ovSay(v.ok?`ตรวจผ่าน ✓ (ย้าย ${v.counts.mov} · ลบ ${v.counts.del} · เพิ่ม ${v.counts.add} · เส้นทาง ${v.conn?v.conn.n:0} เส้น · ${v.ms} ms) — ยังไม่ได้บันทึก`:'ตรวจไม่ผ่าน: '+v.errors.slice(0,5).join(' · '));ovPanelSay(null,v);};
    $q('#ovCancel').onclick=()=>ovRevert();
    $q('#ovBack').onclick=e=>{if(!ovHistory().length){ovSay('ยังไม่มีเวอร์ชันก่อนหน้าให้ย้อนกลับ');return;}confirmBtn(e.target,'⏪ ย้อนเวอร์ชันบันทึกก่อนหน้า',()=>{const r=ovRollback();ovSay(r.ok?`ย้อนกลับแล้ว ✓ (เป็น rev ${r.rev})`:r.error);ovPanelSay();});};
    $q('#ovClear').onclick=e=>confirmBtn(e.target,'🗑 ล้าง overrides (กลับสูตรล้วน)',()=>{const r=ovClear();ovSay(r.ok?`ล้างแล้ว ✓ (เป็น rev ${r.rev}) — เวอร์ชันก่อนหน้ายังย้อนกลับได้`:r.error);ovPanelSay();});
    const bindPad=root=>root.querySelectorAll('.pad [data-k]').forEach(b=>{const k=b.dataset.k,on=e=>{e.preventDefault();keys[k]=true;},off=()=>{keys[k]=false;};b.addEventListener('pointerdown',on);['pointerup','pointercancel','pointerleave','blur'].forEach(ev=>b.addEventListener(ev,off));});
    bindPad(d);
    $q('#ovHide').onclick=()=>ovMini(true);
    let m=document.getElementById('ovMini');if(!m){m=document.createElement('div');m.id='ovMini';m.hidden=true;
      m.innerHTML=`<button class="btn" id="ovMiniShow" aria-label="เปิด/ย่อแผงเครื่องมือ">☰ แผง</button><button class="btn" id="ovMiniTool" aria-label="โหมดปัจจุบัน (แตะเพื่อเปิดแผง)"></button><button class="btn" id="ovMiniAdd" aria-label="เพิ่มวัตถุ">＋ เพิ่มวัตถุ</button><button class="btn gold" id="ovMiniSave" aria-label="บันทึก">💾</button><button class="btn" id="ovMiniCancel" aria-label="ยกเลิกการแก้">↩</button><button class="btn" id="ovMiniHud" aria-label="แสดง/ซ่อน HUD เกม" aria-pressed="false">👁</button><button class="btn" id="ovMiniExit" aria-label="ออกจาก Editor">✕</button>`;
      document.body.appendChild(m);
      const st=document.createElement('div');st.id='ovStat';st.hidden=true;document.body.appendChild(st);
      const pd=document.createElement('div');pd.id='ovPad';pd.className='pad';pd.hidden=true;pd.innerHTML=`<span></span><button class="btn" data-k="arrowup" aria-label="เลื่อนขึ้น">▲</button><span></span><button class="btn" data-k="arrowleft" aria-label="เลื่อนซ้าย">◀</button><button class="btn" data-k="arrowdown" aria-label="เลื่อนลง">▼</button><button class="btn" data-k="arrowright" aria-label="เลื่อนขวา">▶</button>`;document.body.appendChild(pd);bindPad(pd);
      const tgl=()=>{document.body.classList.toggle('ovmin');ovSyncCompact();};
      m.querySelector('#ovMiniShow').onclick=tgl;m.querySelector('#ovMiniTool').onclick=tgl;
      m.querySelector('#ovMiniAdd').onclick=()=>{OV.pp=null;if(ED.tool==='place'){ED.tool='select';ED.pick=null;ED.hover=null;ovSay('กลับสู่โหมดเลือก/ย้าย');}else{ED.tool='place';ED.pick=null;ED.sel=null;ED.hover=null;ED.drag=null;document.body.classList.remove('ovmin');ovSyncCompact();ovSay('โหมดเพิ่มวัตถุ: เลือกชนิดจากแผง แล้วแตะแผนที่ 1 ครั้ง');}try{renderEditor();}catch(e){}ovMiniSay();};
      m.querySelector('#ovMiniSave').onclick=()=>{ovSave();ovMiniSay();};
      m.querySelector('#ovMiniCancel').onclick=()=>{if(ED.dirty&&OV.cancelAsk<Date.now()){OV.cancelAsk=Date.now()+3500;ovSay('มีการแก้ที่ยังไม่บันทึก — แตะ ↩ อีกครั้งเพื่อยกเลิกทั้งหมด');ovMiniSay();return;}OV.cancelAsk=0;ovRevert();ovMiniSay();};   // two taps when there is something to lose: the button sits next to Save
      m.querySelector('#ovMiniHud').onclick=()=>{const on=document.body.classList.toggle('ovhud');m.querySelector('#ovMiniHud').setAttribute('aria-pressed',on?'true':'false');ovMiniSay();};
      m.querySelector('#ovMiniExit').onclick=()=>{const c=document.getElementById('edClose');if(c)c.click();};}   // the normal close button: its "unsaved edits" guard applies
    {const lockStop=e=>{if(!OV.mode||!ED.sel||!ovLocked(ED.sel))return;e.preventDefault();e.stopImmediatePropagation();ovSay(ovLockWhy());};   // a locked object can be selected to look at, never changed (flip / variant / duplicate / delete / size)
      ed.addEventListener('click',e=>{if(e.target&&e.target.closest&&e.target.closest('#edSel [data-ed]'))lockStop(e);},true);
      ed.addEventListener('input',e=>{if(e.target&&e.target.id==='edScale'){lockStop(e);try{$('#edScale').value=ED.sel.s;$('#edScaleV').textContent=(+ED.sel.s).toFixed(2);}catch(_){}}},true);
      cv.addEventListener('wheel',e=>{if(OV.mode&&ED.on)lockStop(e);},true);
      addEventListener('pointercancel',()=>{OV.pp=null;},true);}
    // legacy save / import / clear controls are hidden by CSS in this mode; this capture guard also stops any other path (keyboard focus, other panels)
    ed.addEventListener('click',e=>{if(!OV.mode)return;const t=e.target&&e.target.closest&&e.target.closest(OV_BLOCK);if(t&&ed.contains(t)){e.preventDefault();e.stopImmediatePropagation();ovSay('โหมด Overrides: ใช้ปุ่ม “บันทึก Overrides” แทน (ปุ่มเลย์เอาต์เดิมถูกปิดไว้เพื่อไม่ให้ทับข้อมูลเดิม)');}},true);
    const cl=document.getElementById('edClose');if(cl)cl.addEventListener('click',e=>{if(!OV.mode||!ovDirty()||OV.closeAsk>Date.now())return;e.preventDefault();e.stopImmediatePropagation();OV.closeAsk=Date.now()+4000;ovSay('มีการแก้ไขที่ยังไม่บันทึก — กด × อีกครั้งภายใน 4 วินาทีเพื่อทิ้งการแก้ไข หรือกด “บันทึก Overrides”');},true);}
  return d;}
function ovIsCompact(){try{return document.body.classList.contains('mobile')||(window.matchMedia&&matchMedia('(pointer:coarse)').matches)||innerWidth<720||innerHeight<520;}catch(e){return false;}}
/* phone edit mode: while the Overrides editor is open on a small / touch screen the game HUD, menu, log and the (invisible!) joystick zone are hidden by CSS classes only — nothing is stored or moved, so leaving the editor just removes the classes and everything is back exactly as it was */
function ovSyncCompact(){const b=document.body,on=!!(OV.mode&&ED.on&&ovIsCompact()),was=b.classList.contains('ovcompact');
  if(on&&!was){b.classList.add('ovcompact','ovmin');b.classList.remove('ovhud');}
  else if(!on&&was){b.classList.remove('ovcompact','ovhud','ovmin');}
  const m=document.getElementById('ovMini'),pd=document.getElementById('ovPad'),st=document.getElementById('ovStat'),show=!!(OV.mode&&ED.on&&(on||b.classList.contains('ovmin')));
  if(m)m.hidden=!show;if(pd)pd.hidden=!show;if(st)st.hidden=!show;ovMiniSay();}
function ovMini(on){if(on)document.body.classList.add('ovmin');else document.body.classList.remove('ovmin');ovSyncCompact();}
const OV_TOOLS={select:'✋ โหมด: เลือก/ย้าย',place:'＋ โหมด: เพิ่มวัตถุ',delete:'🗑 ลบ',brush:'🖌 พู่กัน',erase:'◌ ยางลบ'};
function ovMiniSay(){if(!OV.mode)return;const k=ovCounts(),b=document.body;
  const sh=document.getElementById('ovMiniShow');if(sh)sh.textContent=b.classList.contains('ovmin')?'☰':'▾';
  const tl=document.getElementById('ovMiniTool');if(tl){const pk=ED.pick&&PROP_DEFS[ED.pick]?PROP_DEFS[ED.pick].n:'';tl.textContent=(OV_TOOLS[ED.tool]||ED.tool||'')+(ED.tool==='place'?(pk?' · '+pk+' (แตะแผนที่ 1 ครั้ง)':' · เลือกชนิดจากแผง'):ED.tool==='brush'&&pk?' · '+pk:ED.tool==='select'&&ED.sel?(ovLocked(ED.sel)?' · 🔒 ล็อก':' · เลือก: '+((PROP_DEFS[ED.sel.t]||{}).n||ED.sel.t)):'');const m=document.getElementById('ovMini');if(m)m.dataset.mode=ED.tool||'';const ad=document.getElementById('ovMiniAdd');if(ad)ad.textContent=ED.tool==='place'?'✋ กลับเลือก':'＋ เพิ่มวัตถุ';}
  const c=document.getElementById('ovStat');if(c)c.textContent=`ย้าย ${k.mov} · ลบ ${k.del} · เพิ่ม ${k.add}${ED.dirty?' ● ยังไม่บันทึก':''}${OV.msg?' — '+OV.msg.slice(0,90):''}`;}
function ovPanelSay(reason,v){try{ovMiniSay();}catch(e){}const d=ovPanel();if(!d)return;const on=OV.zones.has(G.zone)&&ED.on;d.hidden=!on;if(!on)return;
  const st=OV.st[G.zone]||{},sv=d.querySelector('#ovState'),ct=d.querySelector('#ovCnt'),ls=d.querySelector('#ovList');
  d.querySelectorAll('button.btn').forEach(b=>{b.disabled=!OV.mode&&!b.closest('.pad');});
  if(!OV.mode){sv.innerHTML='<span style="color:var(--rose,#ff6b8b)">⛔ ยังใช้โหมดนี้ไม่ได้:</span> '+(reason||st.why||'โซนนี้ยังไม่พร้อม');ct.textContent='Editor เดิมใช้งานได้ตามปกติ (บันทึกแบบเลย์เอาต์เดิม) · ถ้าบันทึกแบบเดิม ระบบนี้จะไม่ทำงานในโซนนี้';ls.textContent='';return;}
  const c=ovCounts(),app=st.applied||{mov:0,del:0,add:0};
  sv.innerHTML=`โซน ${(ZONES[G.zone]||{}).n||G.zone} · บันทึกล่าสุด: ${st.rev?('rev '+st.rev+` (ย้าย ${app.mov} · ลบ ${app.del} · เพิ่ม ${app.add}${st.skipped&&st.skipped.length?` · ข้าม ${st.skipped.length}`:''})`):'ยังไม่มี'}${st.code==='rejected'?' <span style="color:var(--rose,#ff6b8b)">· ไม่ถูกใช้ (ทำให้เส้นทางตัน)</span>':''}`;
  ct.innerHTML=`ที่แตกต่างจากสูตรตอนนี้: ย้าย <b>${c.mov}</b> · ลบ <b>${c.del}</b> · เพิ่ม <b>${c.add}</b> ${ED.dirty?'<span style="color:var(--gold,#e7c35c)">● ยังไม่บันทึก</span>':'<span style="color:var(--mint,#8dffc8)">ตรงกับที่บันทึกไว้</span>'}${OV.hiddenTypes?` · พาเลตหมวดนี้ซ่อน ${OV.hiddenTypes} ชนิดที่ไม่ผ่านกฎความปลอดภัย/นำเข้าเอง`:''}`;
  const lines=[];if(v&&v.errors)for(const e of v.errors.slice(0,8))lines.push('✗ '+e);if(st.skipped&&st.skipped.length)for(const s of st.skipped.slice(0,6))lines.push('ข้าม '+(s.id||'')+': '+s.why);
  ls.textContent=lines.join('\n');
  const m=document.getElementById('ovMsg');if(m&&OV.msg)m.textContent=OV.msg;}

/* ---------- enable / disable ---------- */
function ovRegen(zid){if(G.zone!==zid||G.state==='title')return;try{PROPS=loadPropsFor(zid);ED.sel=null;ED.dirty=false;buildSolids();if(typeof OBL!=='undefined'&&OBL)OBL.dirty=true;}catch(e){ovNote('regen error '+e);}}
addEventListener('resize',()=>{if(OV.mode)ovSyncCompact();});
window.COLED={
  build:OVR_BUILD,
  enable(z){if(ovC().allowedZones.indexOf(z)<0)return false;OV.zones.add(z);ovFlagsSave();ovInstall();if(G.zone===z)ovRegen(z);return true;},
  disable(z){const had=OV.zones.has(z);if(OV.mode&&G.zone===z&&ED.on){if(ovDirty())ovRevert(true);ovModeEnd();}OV.zones.delete(z);ovFlagsSave();if(OV.st[z])OV.st[z].active=false;if(!OV.zones.size){const zid=G.zone;ovUninstall();if(had&&zid===z&&G.state!=='title'){try{PROPS=loadPropsFor(zid);buildSolids();if(typeof OBL!=='undefined'&&OBL)OBL.dirty=true;}catch(e){}}}else if(had&&G.zone===z)ovRegen(z);const p=document.getElementById('ovBox');if(p)p.hidden=true;},
  enabled:()=>[...OV.zones],isOn:z=>OV.zones.has(z||G.zone),installed:()=>OV.inst,
  avail:z=>ovAvail(z||G.zone),status:()=>({build:OVR_BUILD,zones:[...OV.zones],mode:OV.mode,st:OV.st,log:OV.log.slice(-10),dirty:ovDirty(),rejected:OV.rejected||{}}),
  validate:ovValidate,save:ovSave,cancel:()=>ovRevert(),rollback:ovRollback,clear:ovClear,history:ovHistory,
  diff:()=>{const rd=ovReadDoc(),zd=rd.state==='ok'?rd.doc.zones[G.zone]:null;return ovDiff(zd&&ovZoneOk(zd)?zd:{next:1});},
  counts:ovCounts,read:ovReadDoc,readBak:ovReadBak,base:()=>OV.base,view:()=>OV.view,locked:ovLocked,typeOk:ovTypeOk,apply:ovApply,opCheck:ovOpCheck,write:ovWrite,keys:{data:()=>ovC().dataKey,bak:()=>ovC().bakKey},
  mode:()=>OV.mode,config:()=>ovC(),log:OV.log,
  enterMode:()=>{if(OV.inst&&ED.on)ovModeStart();}};
ovFlagsLoad();if(OV.zones.size)ovInstall();

/* ---------- GM panel entry (phone friendly: no P key needed; the ✎ button of the toolbar opens the same editor) ---------- */
function ovGmPanel(){const cp=document.getElementById('camPanel');if(!cp)return;let d=document.getElementById('ovGm');
  if(!d){d=document.createElement('details');d.id='ovGm';d.hidden=true;
    d.innerHTML=`<summary>🧩 แก้แมพด้วย Editor แบบ Overrides (ทดลอง · แอดมิน)</summary><div class="muted" style="font-size:11px;margin:6px 0">ค่าเริ่มต้น = ปิด · ใช้ได้เฉพาะโซนนำร่อง (Sylva) และต้องเปิด “ระบบตกแต่งแมพแบบสูตร” ของโซนนั้นก่อน · เพิ่ม/ย้าย/ลบของตกแต่งโดยไม่แก้โค้ด · กดบันทึกแล้วจึงเก็บถาวร (เก็บเป็นส่วนต่างจากสูตร มีสำรองและย้อนกลับได้) · build <b>${OVR_BUILD}</b></div>
<label class="rr"><input type="checkbox" id="ovGmOn"> <span id="ovGmOnT">เปิด Overrides ในโซนนี้</span></label>
<div class="rr"><button class="btn sm" id="ovGmOpen">✎ เปิด Map Editor (โหมด Overrides)</button><button class="btn sm" id="ovGmOff">ปิด Overrides ทุกโซน</button></div>
<div id="ovGmSay" class="muted" style="font-size:11px;margin-top:4px"></div>`;
    const st=document.createElement('style');st.textContent='#ovGm{margin-top:10px;border-top:1px solid var(--line);padding-top:8px}#ovGm summary{cursor:pointer;font-family:var(--display);letter-spacing:.06em;font-size:12px;color:#fff}#ovGm .rr{display:flex;align-items:center;gap:6px;font-size:12px;margin:3px 0;flex-wrap:wrap}';document.head.appendChild(st);cp.appendChild(d);
    const say=m=>{d.querySelector('#ovGmSay').textContent=m||'';};
    d.querySelector('#ovGmOn').onchange=e=>{if(e.target.checked){if(!COLED.enable(G.zone)){say('โซนนี้ไม่อยู่ในรายการนำร่อง');e.target.checked=false;return;}const a=COLED.avail(G.zone);say(a.ok?'เปิดแล้ว — กด “เปิด Map Editor” เพื่อเริ่มแก้':a.why);}else{COLED.disable(G.zone);say('ปิดแล้ว (ข้อมูลที่บันทึกไว้ยังอยู่)');}};
    d.querySelector('#ovGmOpen').onclick=()=>{if(G.state!=='play'){say('เข้าเกมก่อนแล้วค่อยเปิด Editor');return;}if(!OV.zones.has(G.zone)){if(!COLED.enable(G.zone)){say('โซนนี้ไม่อยู่ในรายการนำร่อง');return;}}
      try{cp.hidden=true;const b=document.getElementById('bCam');if(b)b.classList.remove('on');}catch(e){}try{if(G.win==='wGM')closeWin();}catch(e){}try{const dv=document.getElementById('dev');if(dv&&!dv.hidden)toggleDev();}catch(e){}
      if(!ED.on)toggleEditor(true);};
    d.querySelector('#ovGmOff').onclick=()=>{for(const z of COLED.enabled())COLED.disable(z);say('ปิด Overrides ทุกโซนแล้ว (ข้อมูลที่บันทึกไว้ยังอยู่)');};}
  d.hidden=!(typeof G!=='undefined'&&G.god);
  if(!d.hidden){const c=d.querySelector('#ovGmOn');if(c&&document.activeElement!==c)c.checked=OV.zones.has(G.zone);const allowed=ovC().allowedZones.indexOf(G.zone)>=0;d.querySelector('#ovGmOnT').textContent='เปิด Overrides ในโซนนี้ ('+((ZONES[G.zone]||{}).n||G.zone)+')'+(allowed?'':' — ไม่อยู่ในรายการนำร่อง');if(c)c.disabled=!allowed;}}
setInterval(()=>{try{ovGmPanel();}catch(e){}},1500);
