function slWindmillRotor(c,p,s,tm){const S=SYLVA_ART.windmill_rotor,im=imgOf(S.src);if(!im)return;const W=WINDMILL,R=W.rotor,k=R.sc*s;
  const ang=RTR.frozen!=null?RTR.frozen:(tm*6.2832/R.period);RTR.ang=ang;
  const hx=p.x+W.hub[0]*s,hy=p.y+W.hub[1]*s;let fade=1;
  try{if(P&&!ED.on&&depthKey(p)>depthKey(P)){const q=w2s(p.x,p.y),z=camZ()*slBBs(q[1]),a=[q[0]+W.hub[0]*s*z,q[1]+W.hub[1]*s*z],b=w2s(P.x,P.y-20),rx=R.R*s*R.m[0]*z,ry=R.R*s*z;if(((b[0]-a[0])/rx)**2+((b[1]-a[1])/ry)**2<1)fade=.42;}}catch(e){}   // same see-through rule as the building: the player standing behind the blades stays visible
  c.save();c.globalAlpha*=fade;c.translate(hx,hy);c.transform(R.m[0],R.m[1],R.m[2],R.m[3],0,0);c.rotate(ang);c.imageSmoothingEnabled=true;c.imageSmoothingQuality='high';c.drawImage(im,-S.w*k/2,-S.h*k/2,S.w*k,S.h*k);c.restore();}
