const LAMPS_BANNER=[['svLamp',690,690,1.0,1,0],['svLamp',1010,740,1.0,1,0],['svLamp',1030,445,1.0,1,0],['svLamp',470,862,1.0,1,0]];   // saved alternative: the original banner lamp posts (art 'lamp', ART.svLamp and these anchors are kept untouched)
