      const end=Math.min(1,Math.min(s0,1e9)/60),wl=PATHW/2+(9*Math.sin(s0*.019+ph[0])+6*Math.sin(s0*.047+ph[1])+3*Math.sin(s0*.11+ph[1]*2))*am[0],wr=PATHW/2+(9*Math.sin(s0*.017+ph[2])+6*Math.sin(s0*.053+ph[3])+3*Math.sin(s0*.13+ph[3]*2))*am[1];
