  // stone plaza: a one-off round decal (never tiled), soft contact shadow, and the end of the two paths slip under its rim
  {const [cx,cy,k]=PLAZA,R=156*k,S=SYLVA_ART.plaza,gr=GCON()?g.createRadialGradient(cx,cy,R*.9,cx,cy,R*1.07):g.createRadialGradient(cx,cy,R*.86,cx,cy,R*1.12);gr.addColorStop(0,GCON()?'rgba(10,26,10,.24)':'rgba(10,26,10,.34)');gr.addColorStop(1,'rgba(10,26,10,0)');g.fillStyle=gr;g.beginPath();g.arc(cx,cy,R*(GCON()?1.07:1.12),0,TAU);g.fill();
   g.imageSmoothingEnabled=true;g.imageSmoothingQuality='high';g.drawImage(GCON()?slPlazaIrregular(imgOf(S.src)):imgOf(S.src),cx-S.w*k/2,cy-S.h*k/2,S.w*k,S.h*k);}
