  {const id=g.getImageData(0,0,W,H),d=id.data;for(let i=0;i<d.length;i+=4){const r=d[i],gg=d[i+1],b=d[i+2],l=.3*r+.59*gg+.11*b;d[i]=Math.min(255,l+(r-l)*.93+1);d[i+1]=Math.min(255,l+(gg-l)*.93);d[i+2]=Math.min(255,l+(b-l)*.93-1);}g.putImageData(id,0,0);}
