function slDeactivate(){slAmbClear();if(SL.wv){SL.wv.on=false;SL.wv.fit=null;}if(SL.em){slEditEnd();if(ED.on)try{SL.orig.toggleEditor(false);}catch(_){}}SL.active=false;SL.back=null;if(SL.cam0){CAM.zt=SL.cam0.zt;CAM.tt=SL.cam0.tt;SL.cam0=null;}for(let i=enemies.length-1;i>=0;i--)if(enemies[i].lab)enemies.splice(i,1);slChip();}
