  const R=slRnd(t.length*977+t.charCodeAt(3)*131),rr=(a,b)=>a+(b-a)*R(),T=.866;
  const W=(x,y)=>[(x-A.ax)*A.sc,(y-A.ay)*A.sc/T];   // source px → world offsets from the anchor
