  const pad=140,bb=[1e9,1e9,-1e9,-1e9];const ext=(x,y,r)=>{bb[0]=Math.min(bb[0],x-r);bb[1]=Math.min(bb[1],y-r);bb[2]=Math.max(bb[2],x+r);bb[3]=Math.max(bb[3],y+r);};
  const fp=A.fp?A.fp.map(([x,y])=>W(x,y)):null,st=A.steps?W(A.steps[0],A.steps[1]):null;
  if(fp)fp.forEach(q=>ext(q[0],q[1],pad));if(st)ext(st[0]+150,st[1]+190,pad*.6);for(const q of sol)ext(q[0],q[1],q[2]+60);const cm=A.cs?slContact(A):null;if(cm){ext(-A.ax*A.sc,0,20);ext((cm.width-A.ax)*A.sc,0,20);ext(0,-A.ay*A.sc/T,20);ext(0,(cm.height-A.ay)*A.sc/T,20);}
  const ox=Math.floor(bb[0]),oy=Math.floor(bb[1]),w=Math.ceil(bb[2]-bb[0]),h=Math.ceil(bb[3]-bb[1]),c=document.createElement('canvas');c.width=w;c.height=h;let g=c.getContext('2d'),padc=null;g.translate(-ox,-oy);
  const earth=g.createPattern(em,'repeat');
  const blob=(pts,grow,wob)=>{const cx=pts.reduce((a,q)=>a+q[0],0)/pts.length,cy=pts.reduce((a,q)=>a+q[1],0)/pts.length,out=[];   // outline of a point set, grown and wobbled (smooth, uneven — never a string of round bumps)
    const ph=[rr(0,6.28),rr(0,6.28),rr(0,6.28)];const N=pts.length*10;for(let i=0;i<N;i++){const u=i/N*pts.length,k=Math.floor(u),f=u-k,p=pts[k%pts.length],q=pts[(k+1)%pts.length],x=p[0]+(q[0]-p[0])*f,y=p[1]+(q[1]-p[1])*f,dx=x-cx,dy=y-cy,l=Math.hypot(dx,dy)||1,a=i/N*6.28,
        o=grow+wob*(Math.sin(a*3+ph[0])*.6+Math.sin(a*5+ph[1])*.3+Math.sin(a*9+ph[2])*.15);out.push([x+dx/l*o,y+dy/l*o]);}return out;};
  const fill=(o,style)=>{g.fillStyle=style;g.beginPath();o.forEach((q,i)=>i?g.lineTo(q[0],q[1]):g.moveTo(q[0],q[1]));g.closePath();g.fill();};
