function slViewInsets(){const sa=(n)=>0,Wd=innerWidth,Hd=innerHeight;
  if(Hd>=Wd)return{l:10,r:10,t:68,b:196};            // portrait: top HP/menu cluster, bottom joystick/actions row
  return{l:172,r:204,t:68,b:30};}                     // landscape: side joystick/action clusters, top cluster
function slViewFit(){const I=slViewInsets(),Wd=W,Hd=H,uw=Wd-I.l-I.r-16,uh=Hd-I.t-I.b-16,U=WV_U,T=.866,A=WINDMILL;
  let z=1,s=1;for(let i=0;i<6;i++){z=Math.min(uw/((U.x1-U.x0)*s),uh/((U.y1-U.y0)*s),1.8);
    const ucx=I.l+(Wd-I.l-I.r)/2,ucy=I.t+(Hd-I.t-I.b)/2,ay=ucy-(U.y0+U.y1)/2*z*s;s=slBBs(ay);}
  z=clamp(z,.5,1.8);const ucx=I.l+(Wd-I.l-I.r)/2,ucy=I.t+(Hd-I.t-I.b)/2;
  const axs=ucx-(U.x0+U.x1)/2*z*s,ays=ucy-(U.y0+U.y1)/2*z*s;           // wanted screen position of the anchor
  let cx=A.ax-(axs-Wd/2)/z;const slack=Math.max(0,(uw-(U.x1-U.x0)*z*s)/2-4)/z,cE=ZONES[LAB].w-(Wd/z)/2;   // world slack left/right inside the usable rect
  if(cx>cE)cx=Math.max(cE,cx-slack);                                 // east edge: use the slack first, only the rest shows void
  return{z,cx,cy:A.ay-(ays-Hd/2)/(z*T)};}
function slViewCam(){const w=SL.wv,f=w.fit||(w.fit=slViewFit()),now=performance.now(),k=Math.min(1,Math.max(.05,1-Math.exp(-((now-(w.lt||now))/1000)*6)));w.lt=now;
  const VWt=W/f.z,VHt=H/(f.z*.866),tx=f.cx-VWt/2,ty=f.cy-VHt/2;
  if(w.px==null){w.px=cam.x;w.py=cam.y;}w.px+=(tx-w.px)*k;w.py+=(ty-w.py)*k;}   // own smoothed camera state: the map-edge clamp would otherwise pull the mill (near the N/E edge) out of the usable rect
