function w22RoadDist(zid,x,y){let md=1e9;for(const R of W22.roads[zid]||[]){const S=R.sp||(R.sp=w22Spline(R.pts));for(let i=0;i<S.length-1;i+=2){const a=S[i],b=S[Math.min(S.length-1,i+2)],dx=b[0]-a[0],dy=b[1]-a[1],L=dx*dx+dy*dy||1,t=Math.max(0,Math.min(1,((x-a[0])*dx+(y-a[1])*dy)/L)),d=Math.hypot(x-a[0]-t*dx,y-a[1]-t*dy)-R.w/2;if(d<md)md=d;}}return md;}   // distance to the nearest road EDGE (<0 = on the road)
