  const clear=(x,y,r)=>{for(let gx=-2;gx<=2;gx++)for(let gy=-2;gy<=2;gy++){const l=grid.get(key(x+gx*CS,y+gy*CS));if(l)for(const o of l)if(Math.hypot(o[0]-x,o[1]-y)<r+o[2])return false;}return true;};
  const reg=(x,y,r)=>{const k=key(x,y);(grid.get(k)||grid.set(k,[]).get(k)).push([x,y,r]);};
  for(const p of out){const d=PROP_DEFS[p.t];reg(p.x,p.y,d&&d.solid&&d.solid.length?Math.max(...d.solid.map(s=>Math.hypot(s.dx,s.dy)+s.r)):30);}
  // reserved ground: open combat clearings and the approach in front of every house door stay free of scatter
  for(const c of PL.open_clearings||[])for(let gx=-c.r;gx<=c.r;gx+=60)for(let gy=-c.r;gy<=c.r;gy+=60)if(Math.hypot(gx,gy)<=c.r)reg(c.x+gx,c.y+gy,60);
  for(const h of PL.houses||[]){const fp=(w22HouseFoot(h)||[[]])[0];if(fp.length){const cx=fp.reduce((a,q)=>a+q[0],0)/4,cy=fp.reduce((a,q)=>a+q[1],0)/4;for(let gx=-230;gx<=230;gx+=60)for(let gy=-110;gy<=170;gy+=60)reg(cx+gx,cy+gy,60);}}
