  const pk=L.park;scat(['svTree','svTreeS1','svTreeS2','svTreeB'],20,60,70,pk.c[0]-pk.r,pk.c[1]-pk.r,pk.c[0]+pk.r,pk.c[1]+pk.r,.85,1.05,[pk.c[0],pk.c[1],pk.r]);
  scat(['svFlowerPatch','svFlowerG','svFernA','svSeedgrassCream','svBushF'],40,16,34,pk.c[0]-pk.r,pk.c[1]-pk.r,pk.c[0]+pk.r,pk.c[1]+pk.r,.7,1,[pk.c[0],pk.c[1],pk.r]);
