const diagLog=[];const counters={capHits:0,invalid:0,zeroImmune:0,minHit:0,ccRejected:0};
function diag(kind,msg,extra){counters.invalid+= kind==='invalid'?1:0;if(diagLog.length>=300)diagLog.shift();diagLog.push({kind,msg,extra});}
const isNum=v=>typeof v==='number'&&isFinite(v);
