/* ---------------- elements ---------------- */
function elemKey(e){if(e==null)return 'Neutral';const k=CFG.legacyElement[e]||CFG.legacyElement[String(e).toLowerCase()];if(!k){diag('invalid','unknown element '+e);return 'Neutral';}return k;}
