    if(ev.levels){st.unspentPts=(st.unspentPts||0)+ev.pts;st.levelEarnedPts=(st.levelEarnedPts||0)+ev.pts;}
    if(st.lvl>=newCap){const rem=st.exp;st.exp=0;st.capOverflow=Math.min(rem,expNeed(newCap));st.capOverflowCap=newCap;st.capOverflowUsed=false;}
