  sums(now){this._purge(now);let ord=0,all=0;for(const e of this.entries){all+=e.amt;if(!e.elite)ord+=e.amt;}return {ord,all};}
  start(maxHp,now){if(this.refMax==null)this.refMax=maxHp;}
