  const st=e.rf;if(!st||st.st!=='on'){S.rfStats.offState++;return;}
  const lost=Math.max(0,hp0-Math.max(0,e.hp));if(lost<=0)return;
  const C=S.RF;let want=lost*C.rate;S.rfStats.calls++;S.rfStats.reflected+=want;
  // per-cast budget (skill casts carry a context object; everything else is bucketed per 0.5 s = one basic attack)
  const ctx=(o&&o.ctx)||S.cur;let cast;
  if(ctx){if(ctx.rfLeft==null){ctx.rfRef=P.maxHp;ctx.rfLeft=C.perCastPct*ctx.rfRef;}cast=ctx;}
  else{const k=Math.floor(time*2);if(S.rfBasic.key!==k){S.rfBasic={key:k,ref:P.maxHp,left:C.perCastPct*P.maxHp};}cast=S.rfBasic;if(cast.rfLeft==null)cast.rfLeft=cast.left;}
  const left1=ctx?cast.rfLeft:S.rfBasic.left;
