  hurtPlayer(amt,{type:'reflect:'+e.type,m:{},L:P.lvl,elem:'Neutral',atk:amt,reflectHit:1,dead:false});
  const got=Math.max(0,S.stats.hpIn+S.stats.shIn-h0);S.rfStats.delivered+=got;
  if(ctx)cast.rfLeft=Math.max(0,cast.rfLeft-got);else S.rfBasic.left=Math.max(0,S.rfBasic.left-got);
  w.list.push({t:time,v:got});
