    const sr=lv<10?0:lv<30?1:2;rar={low:0,standard:sr,high:Math.min(5,sr+2)}[tier];ref={low:0,standard:Math.floor(lv/12),high:Math.min(15,Math.floor(lv/6))}[tier];
