const ST_TH={stun:'สตัน',root:'ตรึง',silence:'ใบ้',fear:'หวาดกลัว',burn:'เผาไหม้',poison:'พิษ',slow:'ช้าลง',armorBreak:'เกราะแตก'};
const BF_TH={atk:'ATK',matk:'MATK',def:'ลดความเสียหาย',aspd:'ความเร็วโจมตี',speed:'ความเร็วเดิน',crit:'คริติคอล',critDmg:'แรงคริ',regen:'ฟื้น HP/วิ',shield:'โล่ดูดซับ',lifesteal:'ดูดเลือด',cdr:'ลดคูลดาวน์',aura:'ออร่าทำดาเมจรอบตัว',storm:'สายฟ้าผ่าอัตโนมัติ',reflect:'สะท้อนดาเมจ'};
function skDesc(s,lv){
  lv=Math.max(1,lv);const m=Math.round((s.m||0)*(1+.12*(lv-1))*100),dt=s.dt==='mag'?'MATK':'ATK',L=[];
  const bt=b=>Object.keys(b).map(k=>`${BF_TH[k]} ${k==='crit'?'+'+Math.round(b[k]):k==='storm'?'':(b[k]>0?'+':'')+Math.round(b[k]*100)+'%'}`).join(', ');
  if(s.desc)L.push(s.desc(lv));else switch(s.type){
    case 'slash':L.push(`ฟันวงพระจันทร์รัศมี ${s.r}${s.cross?' เป็นรูปกางเขน':''} · ${m}% ${dt}`);break;
    case 'execute':L.push(`เคียววิญญาณ ${m}% ${dt} · ประหารทันทีหาก HP ศัตรูต่ำกว่า ${s.exec*100}% (บอสรับ x3)`);break;
    case 'nova':L.push(`ระเบิดพลังรอบตัวรัศมี ${s.r}${m?` · ${m}% ${dt}`:''}`);break;
    case 'proj':L.push(`ยิง${s.n>1?` ${s.n} ลูก`:''}${s.homing?' ติดตามเป้า':''}${s.pierce?' เจาะทะลุเป็นแถว':''}${s.bounce?` ชิ่ง ${s.bounce} ครั้ง`:''}${s.aoe?` ระเบิดวง ${s.aoe}`:''}${s.multi?' ทำดาเมจต่อเนื่องขณะผ่าน':''} · ${m}% ${dt}`);break;
    case 'boomerang':L.push(`ขว้างออกไปแล้วบินกลับ โดน 2 จังหวะ · ${m}% ${dt}`);break;
    case 'line':L.push(`คลื่นเส้นตรงยาว ${s.len} เจาะทะลุทุกตัว · ${m}% ${dt}${s.true?' · True Damage ทะลุเกราะ 100%':''}`);break;
    case 'ground':L.push(`สร้างเขตพลังรัศมี ${s.r} นาน ${s.dur}s${m?` · ${m}% ${dt}/ครั้ง`:''}${s.heal?' · ฟื้นฟู HP ในเขต':''}${s.pull?' · ดูดศัตรูเข้าหาศูนย์กลาง':''}`);break;
    case 'burst':L.push(`ระเบิด ณ จุดเป้าหมาย รัศมี ${s.r} · ${m}% ${dt}`);break;
    case 'meteor':L.push(`เรียก${s.arrows?'ห่าลูกธนูแสง':s.pillar?'ลำแสงศักดิ์สิทธิ์':'อุกกาบาต'} ${s.n} ลูกลงพื้นที่เป้าหมาย · ${m}% ${dt}`);break;
    case 'chain':L.push(`สายฟ้ากระโดด ${s.n} เป้า · ${m}% ${dt}`);break;
    case 'dash':L.push(s.back?'กระโดดถอยหลังพร้อมอมตะชั่วขณะ':`พุ่งชาร์จ ${s.range} หน่วย ชนศัตรูตามทาง · ${m}% ${dt}`);break;
    case 'leap':L.push(`กระโดดกระแทกพื้น ณ จุดเป้าหมาย รัศมี ${s.r} · ${m}% ${dt}`);break;
    case 'blink':L.push(`วาร์ปไปยังเคอร์เซอร์ (ระยะ ${s.range})${s.buff?' · '+bt(s.buff):''}`);break;
    case 'buff':L.push(`เสริมพลัง ${bt(s.buff)} นาน ${s.dur}s`);break;
    case 'heal':L.push(`ฟื้นฟู HP ${Math.round(s.heal*100*(1+.05*(lv-1)))}%${s.cleanse?' · ล้างสถานะผิดปกติ':''}${s.dome?` · โดมคุ้มกัน ${s.dome}s`:''}${s.buff?' · '+bt(s.buff):''}`);break;
    case 'summon':L.push(`อัญเชิญ ${SUMMON[s.sum].n} x${s.n}${s.extra?` + ${SUMMON[s.extra].n}`:''} นาน ${s.dur}s ช่วยโจมตี`);break;
    case 'dome':L.push(`กางโดมป้องกันความเสียหาย 100% นาน ${s.dur}s และสะท้อนกระสุนศัตรู`);break;
    case 'revive':L.push(`เมื่อ HP หมด จะคืนชีพทันทีพร้อม HP ${Math.round(s.heal*100)}% (ออร่าอยู่ ${s.dur}s)`);break;
    case 'spin':L.push(`หมุนตัวฟันต่อเนื่อง ${s.dur}s · ${m}%/ครั้ง`);break;
    case 'passive':L.push(`Passive · เพิ่ม DEF +${lv*s.passive.def} และ Max HP +${lv*s.passive.hp} ถาวร (ไม่ต้องกดใช้)`);break;
    case 'trap':L.push(`วางกับดักรัศมี ${s.r} ทำงานเมื่อศัตรูเหยียบ · ${m}% ${dt}`);break;
  }
  if(s.st)L.push(Object.keys(s.st).map(k=>`${ST_TH[k]} ${s.st[k]}s`).join(', '));
  if(s.drain)L.push(`ดูดเลือด ${s.drain*100}%`);
  return L.join(' · ');
}

/* ---------- HUD ---------- */
const SLOT_KEYS=['1','2','3','4','5','6','q','e','r','f'];
function buildBar(){
  const bar=$('#bar');let h='';P.slots=P.slots.map(id=>id&&SK[id]&&SK[id].type!=='passive'?id:null);
  P.slots.forEach((id,i)=>{h+=`<div class="slot" data-i="${i}" ${id?`data-sk="${id}" draggable="true"`:''}>${id?`<img src="${skillIcon(id)}" alt="">`:''}<div class="cd"></div><div class="cdt"></div><kbd>${SLOT_KEYS[i].toUpperCase()}</kbd>${id?`<span class="lv">${P.skills[id]||0}</span>`:''}</div>`;if(i===5)h+='<div class="sep"></div>';});
  h+=`<div class="sep"></div><div class="slot pot" data-pot="hp"><img src="${itemIcon({id:'hpPot'})}" alt=""><kbd>Z</kbd><span class="q" id="qHp"></span></div><div class="slot pot" data-pot="mp"><img src="${itemIcon({id:'mpPot'})}" alt=""><kbd>X</kbd><span class="q" id="qMp"></span></div>`;
  bar.innerHTML=h;if(typeof buildTouchSkills==='function'&&TOUCH.on)buildTouchSkills();
}
let hudT=0;
function updHUD(dt){
  if(!P)return;
  const hp=P.hp/P.maxHp,mp=P.mp/P.maxMp;
  const q=v=>Math.round(v*1000)/10;   // v22: write to the DOM only when the rounded value changes (was every frame)
  hudSet('arcHp','a',q(hp));hudSet('arcMp','a',q(mp));hudSet('hpI','w',q(hp));hudSet('mpI','w',q(mp));
  hudSet('xpI','w',q(P.lvl>=C182cap()?1:P.exp/need(P.lvl)));hudSet('jxI','w',q(P.jobLv>=jobCap()?1:P.jobExp/needJob(P.jobLv)));
  hudT-=dt;
  if(hudT<=0){hudT=.15;
    $('#hpT').textContent=`${fmt(Math.ceil(P.hp))} / ${fmt(P.maxHp)}`;$('#mpT').textContent=`${fmt(Math.floor(P.mp))} / ${fmt(P.maxMp)}`;
    $('#hLv').textContent=P.lvl;$('#cJob').textContent=`Job ${P.jobLv}/${jobCap()}`;$('#hCls').textContent=CLASSES[P.cls].n+(G.god?' · GOD':'');$('#cGold').textContent=fmt(P.gold)+' G';$('#cSp').textContent='Spirit '+P.sp;
    const pts=[];if(P.skillPts)pts.push(P.skillPts+' SP');if(P.statPts)pts.push(P.statPts+' Stat');const cp=$('#cPts');cp.hidden=!pts.length;cp.textContent=pts.join(' · ');
    const qh=window.POTFLAT221&&POTFLAT221.on?POTFLAT221.cnt('hp'):countItem('hpPot')+countItem('hpPot2'),qm=window.POTFLAT221&&POTFLAT221.on?POTFLAT221.cnt('mp'):countItem('mpPot');const a=$('#qHp'),b=$('#qMp');if(a)a.textContent=qh;if(b)b.textContent=qm;
    const pr=$('#prompt');const it=G.interact;
    if(it&&G.state==='play'&&!G.win){let t='';if(it.k==='way')t=G.unlocked.has(G.zone)?'วาร์ปกลับ Capital City':'ผนึกพลังแท่นวาร์ป (Attune Waystone)';else if(it.k==='nexus')t='เปิด Grand Teleport Nexus';else t=npcPrompt(it.n);pr.innerHTML=`<kbd>F</kbd>${t}`;pr.hidden=false;}else if(G.state==='play'&&lootNear()){pr.innerHTML=`<kbd>F</kbd>เก็บของ (${lootNear()})`;pr.hidden=false;}else pr.hidden=true;
  }
  if(!HUDC.slots||HUDC.slotsV!==HUDC.barV){HUDC.slots=[...document.querySelectorAll('.slot[data-sk]')].map(el=>({el,cdE:el.querySelector('.cd'),tE:el.querySelector('.cdt'),k:{}}));HUDC.slotsV=HUDC.barV;}
  for(const o of HUDC.slots){const el=o.el;if(!el.isConnected){HUDC.slots=null;break;}
    const id=el.dataset.sk,s=SK[id];if(!s)continue;const cd=P.cds[id]||0,max=s.cd*(1-clamp(B('cdr'),0,.7))||1;
    const fr=cd>0?Math.round(cd/max*100)/100:0,tx=cd>0?(cd<10?cd.toFixed(1):String(Math.ceil(cd))):'',nm=P.mp<mpCost(s,P.skills[id]||1),rd=cd<=0,k=o.k;
    if(k.fr!==fr){k.fr=fr;o.cdE.style.setProperty('--cd',fr);}if(k.tx!==tx){k.tx=tx;o.tE.textContent=tx;}
    if(k.nm!==nm){k.nm=nm;el.classList.toggle('nomp',nm);}if(k.rd!==rd){k.rd=rd;el.classList.toggle('ready',rd);}}
}
const HUDC={el:{},v:{},slots:null,slotsV:0,barV:0};
function hudSet(id,kind,v){const key=id+kind;if(HUDC.v[key]===v)return;HUDC.v[key]=v;const el=HUDC.el[id]||(HUDC.el[id]=$('#'+id));if(!el)return;
  if(kind==='a')el.setAttribute('stroke-dasharray',`${v} 100`);else el.style.width=v+'%';}
function showBanner(t,s,dur=2.8){$('#bnT').textContent=t;$('#bnS').textContent=s||'';$('#banner').classList.add('show');G.banner=dur;}
function updZoneTag(){const Z=ZONES[G.zone];$('#zName').textContent=Z.n;$('#zSub').textContent=(Z.range&&!Z.safe?`Lv ${Z.range[0]}–${Z.range[1]}${G.zone==='dark'?'+':''}`:'Safe Zone')+(G.area?` · ${G.area}`:'');}

/* ---------- Windows ---------- */
function openWin_v3(id){
  if(G.win&&G.win!==id)$('#'+G.win).hidden=true;
  G.win=id;$('#'+id).hidden=false;
  if(id==='wSkill')renderSkillWin();else if(id==='wStat')renderStats();else if(id==='wInv')renderInv();else if(id==='wTele')renderTele();else if(id==='wShop')renderShop();else if(id==='wRefine')renderRefine();else if(id==='wMap')mapBase=null;
}
function closeWin(){if(G.win){$('#'+G.win).hidden=true;G.win=null;}G.assign=null;document.body.classList.remove('assign');document.querySelectorAll('.sk img.sel').forEach(e=>e.classList.remove('sel'));}
function toggleWin(id){if(G.win===id)closeWin();else openWin(id);}

function canAdvance_v3(c){const C=CLASSES[c];return C.parent===P.cls&&P.lvl>=TIER_LV[C.tier];}
function skillReq_v3(id){
  const s=SK[id],C=CLASSES[s.cls],lvReq=TIER_LV[C.tier]+s.idx*2;
  if(P.lvl<lvReq)return `ต้องการ Lv ${lvReq}`;
  if(s.idx>0){const prev=C.sk[s.idx-1];if(!P.skills[prev])return `ต้องเรียน ${SK[prev].name} ก่อน`;}
  return '';
}
function renderSkillWin(){
  const lin=lineage(P.cls);$('#skSub').textContent=`${CLASSES[P.cls].n} · Job Lv ${P.jobLv}/${jobCap()} · Skill Points ${P.skillPts}`;
  const node=c=>{const C=CLASSES[c],st=c===P.cls?'cur':lin.includes(c)?'done':canAdvance(c)?'avail':'lock';return `<button class="node ${st}" data-cls="${c}" ${st==='avail'?'':'tabindex="-1"'}>${C.n}<small>Job ${C.jobCap||JOB_CAP[C.tier]}</small></button>`;};
  let h=`<div class="row" style="justify-content:space-between;align-items:center;margin-bottom:10px"><span style="font-size:13px"><b style="color:var(--gold)">${advanceHint()}</b><br><span class="muted">ได้ 1 Skill Point ต่อ 1 Job Level · ลากไอคอนสกิลไปวางที่แถบด้านล่าง หรือคลิกไอคอนแล้วคลิกช่องสกิล</span></span></div>`;
  for(const c of lin.slice().reverse()){const C=CLASSES[c];h+=`<h3 class="sec">${C.n} Skills · Tier ${C.tier}</h3><div class="sklist">`;
    for(const id of C.sk){const s=SK[id],lv=P.skills[id]||0,req=skillReq(id);
      h+=`<div class="sk ${lv?'':'locked'}"><img src="${skillIcon(id)}" alt="${s.name}" data-sk="${id}" draggable="${lv&&s.type!=='passive'?'true':'false'}" class="${G.assign===id?'sel':''}"><div><b>${s.name}</b><span class="lv">Lv ${lv}/10</span><p>${skDesc(s,lv||1)}${s.type==='passive'?'':` · ${ctLabel(s)} · CD ${s.cd}s · MP ${mpCost(s,Math.max(1,lv))}`}</p>${req&&lv<10?`<p class="req">${req}</p>`:''}</div><button class="plus" data-learn="${id}" ${P.skillPts>0&&!req&&lv<10?'':'disabled'} title="ใช้ 1 Skill Point">+</button></div>`;}
    h+='</div>';}
  $('#skBody').innerHTML=h;
}
function learn_v3(id){if(P.skillPts<=0||skillReq(id)||(P.skills[id]||0)>=10)return;P.skills[id]=(P.skills[id]||0)+1;P.skillPts--;
  if(P.skills[id]===1){const i=P.slots.indexOf(null);if(i>=0&&!P.slots.includes(id))P.slots[i]=id;}
  buildBar();renderSkillWin();}
function setClassBase(c,silent){P.cls=c;recalc();if(!silent){const pl=pal(null);fx.push({k:'pillar',x:P.x,y:P.y,t:0,dur:1.6,col:pl.main,w:100,h:600});ring(P.x,P.y,10,260,.9,pl.main,10);emitThemed(P.x,P.y,pl,60,300);showBanner(CLASSES[c].n.toUpperCase(),'เปลี่ยนคลาสสำเร็จ',2.6);log(`เปลี่ยนคลาสเป็น ${CLASSES[c].n}`,'g');}
  for(const k in ICONS)if(k.includes('|'))delete ICONS[k];buildBar();if(G.win==='wSkill')renderSkillWin();saveGame();}

function renderStats_v2(){
  $('#stSub').textContent=`${CLASSES[P.cls].n} · Lv ${P.lvl}`;
  const S=P.stats,info={str:'พลังโจมตีระยะประชิด',agi:'ความเร็วโจมตี',vit:'HP และพลังป้องกัน',int:'MATK และ MP',dex:'พลังธนู / แม่นยำ',luk:'โอกาสคริติคอล'};
  let h=`<div class="row" style="justify-content:space-between;align-items:center;margin-bottom:10px"><b>Stat Points: <span style="color:var(--gold)">${P.statPts}</span></b><label style="font-size:12px;display:flex;gap:6px;align-items:center"><input type="checkbox" id="autoStat" ${P.autoStat?'checked':''}> Auto-assign ตามสายอาชีพ</label></div><div class="stgrid"><div>`;
  for(const k in S)h+=`<div class="strow"><b>${k.toUpperCase()}</b><span>${info[k]}</span><em>${S[k]}</em><button class="plus" data-stat="${k}" ${P.statPts>0?'':'disabled'} title="Shift+คลิก = +10">+</button></div>`;
  h+=`</div><div>`;
  const kv=[['Max HP',fmt(P.maxHp)],['Max MP',fmt(P.maxMp)],['ATK',fmt(Math.round(P.atk*(1+B('atk'))))],['MATK',fmt(Math.round(P.matk*(1+B('matk'))))],['DEF',P.def],['ASPD',(WEAPONS[P.weapon.t].aspd*P.aspdF*(1+B('aspd'))).toFixed(2)+'/s'],['ความเร็วเดิน',Math.round(P.speed*(1+B('speed')))],['Critical',ST6.cc(P.crit+B('crit')).toFixed(1)+'%'],['Spirit Power',`${P.sp} (+${(P.sp*.6).toFixed(1)}% dmg)`],['Weapon',`${P.weapon.name} · ${WEAPONS[P.weapon.t].n}`],['EXP',`${fmt(P.exp)} / ${fmt(need(P.lvl))}`]];
  for(const [a,b] of kv)h+=`<div class="kv"><span>${a}</span><b>${b}</b></div>`;
  h+='</div></div>';$('#stBody').innerHTML=h;
}
function renderInv_v2(){
  $('#invSub').textContent=`${P.inv.length} / ${P.invSize} ช่อง`;
  const cost=bagCost(),w=P.weapon;
  let h=`<div class="invtop"><div class="equip"><img src="${itemIcon(w)}" alt=""><div><b style="color:${RARITY[w.rar].c}">${w.name}</b><div class="muted" style="font-size:12px">${WEAPONS[w.t].n} · ${WEAPONS[w.t].th} · ATK ${w.atk}${w.matk?` · MATK ${w.matk}`:''}</div></div></div>
    <div class="row" style="align-items:center"><span class="chip">${fmt(P.gold)} G</span><button class="btn gold" id="bBag" ${P.gold>=cost&&P.invSize<192?'':'disabled'}>อัปเกรดกระเป๋า +16 ช่อง · ${fmt(cost)} G</button></div></div>
    <p class="muted" style="font-size:12px;margin:0 0 10px">คลิกเพื่อใช้/สวมใส่ · คลิกขวาที่ของเพื่อขาย · กระเป๋าเริ่มต้น 64 ช่อง ขยายได้สูงสุด 192 ช่อง</p><div class="grid">`;
  for(let i=0;i<P.invSize;i++){const it=P.inv[i];if(!it){h+='<div class="cell"></div>';continue;}
    const name=it.kind==='wpn'?it.name:ITEMS[it.id].n;h+=`<div class="cell ${it.kind==='wpn'?'r'+it.rar:''}" data-inv="${i}" data-tip="${i}"><img src="${itemIcon(it)}" alt="${name}">${it.q>1?`<span class="q">${it.q}</span>`:''}</div>`;}
  h+='</div>';$('#invBody').innerHTML=h;
}
function bagCost(){return 300*(P.bagUp+1);}
function tipFor_v2(it){if(it.kind==='wpn')return `<b style="color:${RARITY[it.rar].c}">${it.name}</b><br>${WEAPONS[it.t].n} (${WEAPONS[it.t].th})<br>ATK ${it.atk}${it.matk?` · MATK ${it.matk}`:''}<br><span class="muted">คลิกเพื่อสวมใส่ · ขายได้ ${sellPrice(it)} G</span>`;
  const d=ITEMS[it.id];return `<b>${d.n}</b> x${it.q}<br><span class="muted">${d.d}</span>`;}
function sellPrice_v2(it){return it.kind==='wpn'?Math.round(10+it.lvl*3*(1+it.rar)):(ITEMS[it.id].sell||Math.round((ITEMS[it.id].price||20)/3));}
function useInv_v2(i){const it=P.inv[i];if(!it)return;
  if(it.kind==='wpn'){P.inv[i]=P.weapon;P.weapon=it;recalc();log(`สวมใส่ ${it.name} — ท่าโจมตี ${WEAPONS[it.t].n}`,'g');syncDev();}
  else useItemId(it.id);renderInv();}
function sellInv(i){const it=P.inv[i];if(!it)return;const p=sellPrice(it);if(it.id){it.q--;if(it.q<=0)P.inv.splice(i,1);}else P.inv.splice(i,1);P.gold+=p;log(`ขายได้ ${p} G`);renderInv();}
function renderShop_v6(){
  const L=P.lvl,rows=[['hpPot',30],['hpPot2',120],['mpPot',30]];
  let h='<div class="tele">';
  for(const [id,p] of rows)h+=`<div class="tp on" style="cursor:default"><img src="${itemIcon({id})}" width="40" height="40" alt=""><div><b>${ITEMS[id].n}</b><small>${ITEMS[id].d}</small></div><button class="btn" data-buy="${id}" data-p="${p}" ${P.gold>=p?'':'disabled'}>${p} G</button></div>`;
  const bs=400*(P.bagUp+1);
  h+=`<div class="tp on" style="cursor:default"><img src="${itemIcon({id:'bagScroll'})}" width="40" height="40" alt=""><div><b>Bag Expansion Scroll</b><small>ขยายกระเป๋า +16 ช่อง</small></div><button class="btn" data-buy="bagScroll" data-p="${bs}" ${P.gold>=bs?'':'disabled'}>${bs} G</button></div>`;
  h+=`<h3 class="sec">อาวุธ Lv ${L}</h3>`;
  for(const t of GEAR_TYPES){const p=L*15+80;h+=`<div class="tp on" style="cursor:default"><img src="${itemIcon({kind:'eq',type:t,rar:1})}" width="40" height="40" alt=""><div><b>Fine ${GEAR[t].n}</b><small>${t==='acc'?'โบนัสสเตตัส':'DEF ~'+Math.round((3+L*.9)*GEAR[t].def*1.25)} · ช่องการ์ด [1]</small></div><button class="btn" data-buyg="${t}" data-p="${p}" ${P.gold>=p?'':'disabled'}>${fmt(p)} G</button></div>`;}
  for(const t of WTYPES){const p=L*20+100;h+=`<div class="tp on" style="cursor:default"><img src="${itemIcon({kind:'wpn',t,rar:1})}" width="40" height="40" alt=""><div><b>Fine ${WEAPONS[t].n}</b><small>${WEAPONS[t].th} · ATK ~${Math.round((8+L*2.6)*1.25*WEAPONS[t].f)}</small></div><button class="btn" data-buyw="${t}" data-p="${p}" ${P.gold>=p?'':'disabled'}>${fmt(p)} G</button></div>`;}
  const sh=countItem('shard');h+=`<div class="row" style="margin-top:10px"><button class="btn gold" id="bSellShard" ${sh?'':'disabled'}>ขาย Spirit Shard ทั้งหมด (${sh}) · ${sh*((window.GOLD262&&GOLD262.on)?5:25)} G</button></div></div>`;
  $('#shopBody').innerHTML=h;
}
function renderTele(){
  let h=`<button class="tp on" data-tp="capital"><span class="ic">✧</span><div><b>Capital City</b><small>เมืองหลวง · Safe Zone</small></div><em>—</em></button>`;
  for(const z of ZORDER){const Z=ZONES[z],on=G.unlocked.has(z);
    h+=`<button class="tp ${on?'on':'off'}" data-tp="${z}" ${on?'':'disabled'}><span class="ic">${on?'◆':'🔒'}</span><div><b>${Z.n}</b><small>${Z.th}${on?'':' · ยังไม่ได้ผนึกแท่นวาร์ป'}</small></div><em>Lv ${Z.range[0]}–${Z.range[1]}${z==='dark'?'+':''}</em></button>`;}
  $('#teleList').innerHTML=h;
}

/* ---------- World map ---------- */
const MAPPOS={capital:[480,320,95,75],jungle:[200,320,130,110],desert:[760,320,130,110],wasteland:[250,120,120,80],snow:[480,95,120,70],lava:[480,545,125,75],deepsea:[240,520,120,85],dark:[95,605,85,45]};
let mapBase=null;
function drawMap_v1(){
  const c=$('#mapCv'),g=c.getContext('2d'),Wm=960,Hm=640;
  if(!mapBase){mapBase=document.createElement('canvas');mapBase.width=Wm;mapBase.height=Hm;const b=mapBase.getContext('2d');srand(3);
    const sea=b.createRadialGradient(480,320,50,480,320,620);sea.addColorStop(0,'#0e2046');sea.addColorStop(1,'#040814');b.fillStyle=sea;b.fillRect(0,0,Wm,Hm);
    for(let i=0;i<500;i++){const x=srr(0,Wm),y=srr(0,Hm);b.strokeStyle=rgba(pick(['#1a3a6a','#0a1a3a','#2a4a7a']),srr(.1,.3));b.lineWidth=srr(1,4);b.beginPath();b.moveTo(x,y);b.quadraticCurveTo(x+10,y-srr(-6,6),x+srr(10,30),y);b.stroke();}
    const cols={capital:'#5f86c8',jungle:'#1f7a58',desert:'#b07a4a',wasteland:'#6a5a5a',snow:'#c8dcf4',lava:'#b83a1a',deepsea:'#1a5a8a',dark:'#5a1a8a'};
    b.lineCap='round';
    for(const z of ZORDER){if(z==='dark')continue;const [x,y]=MAPPOS[z],[cx,cy]=MAPPOS.capital;b.strokeStyle='rgba(255,190,92,.35)';b.setLineDash([2,8]);b.lineWidth=3;b.beginPath();b.moveTo(cx,cy);b.lineTo(x,y);b.stroke();}
    b.strokeStyle='rgba(176,76,255,.6)';b.beginPath();b.moveTo(MAPPOS.deepsea[0],MAPPOS.deepsea[1]);b.lineTo(MAPPOS.dark[0],MAPPOS.dark[1]);b.stroke();b.setLineDash([]);
    for(const z in MAPPOS){const [x,y,rx,ry]=MAPPOS[z];for(let i=0;i<40;i++){const a=srr(0,TAU),d=srr(0,.6);const gr=b.createRadialGradient(x+Math.cos(a)*rx*d,y+Math.sin(a)*ry*d,0,x+Math.cos(a)*rx*d,y+Math.sin(a)*ry*d,rx*.55);
        gr.addColorStop(0,rgba(cols[z],.35));gr.addColorStop(1,rgba(cols[z],0));b.fillStyle=gr;b.beginPath();b.arc(x+Math.cos(a)*rx*d,y+Math.sin(a)*ry*d,rx*.55,0,TAU);b.fill();}
      b.strokeStyle=rgba(cols[z],.6);b.lineWidth=1.5;b.setLineDash([4,5]);b.beginPath();b.ellipse(x,y,rx,ry,0,0,TAU);b.stroke();b.setLineDash([]);
      const Z=ZONES[z];b.textAlign='center';b.font='700 17px Cinzel, Georgia, serif';b.lineWidth=4;b.strokeStyle='rgba(2,4,12,.85)';b.strokeText(Z.n,x,y-ry+22);b.fillStyle='#ffffff';b.fillText(Z.n,x,y-ry+22);
      b.font='12px "Noto Sans Thai", system-ui, sans-serif';const sub=Z.range?`Lv ${Z.range[0]}–${Z.range[1]}${z==='dark'?'+':''}`:'Safe Zone';b.strokeText(sub,x,y-ry+40);b.fillStyle=z==='capital'?'#8dffc8':'#ffbe5c';b.fillText(sub,x,y-ry+40);}
    b.font='italic 13px Cinzel, Georgia, serif';b.fillStyle='rgba(185,140,255,.8)';b.fillText('Void Rift',160,570);
  }
  g.drawImage(mapBase,0,0);
  const t=time;
  const mp=(z,px,py)=>{const [x,y,rx,ry]=MAPPOS[z],Z=ZONES[z];return [x-rx*.7+px/Z.w*rx*1.4,y-ry*.55+py/Z.h*ry*1.3];};
  g.globalCompositeOperation='lighter';
  for(const z of ZORDER){const Z=ZONES[z],[x,y]=mp(z,Z.way[0],Z.way[1]),on=G.unlocked.has(z);
    if(on){g.drawImage(glowSprite('#5ef0e0'),x-18,y-18,36,36);g.fillStyle='#e0fffb';}else g.fillStyle='#56688f';
    g.beginPath();g.moveTo(x,y-8);g.lineTo(x+6,y);g.lineTo(x,y+8);g.lineTo(x-6,y);g.fill();}
  {const [x,y]=mp('capital',ZONES.capital.nexus[0],ZONES.capital.nexus[1]);g.drawImage(glowSprite('#8dffc8'),x-22,y-22,44,44);g.fillStyle='#ffffff';g.beginPath();g.arc(x,y,4,0,TAU);g.fill();}
  g.globalCompositeOperation='source-over';
  for(const z of ZORDER)if(!G.unlocked.has(z)){const Z=ZONES[z],[x,y]=mp(z,Z.way[0],Z.way[1]);g.font='11px system-ui';g.textAlign='center';g.fillText('🔒',x,y-10);}
  const _mz=ZONES[G.zone].base,[px,py]=_mz?mp(_mz,ZONES[_mz].subPos[0],ZONES[_mz].subPos[1]):mp(G.zone,P.x,P.y);g.globalCompositeOperation='lighter';g.drawImage(glowSprite('#ffbe5c'),px-22-Math.sin(t*4)*4,py-22-Math.sin(t*4)*4,44+Math.sin(t*4)*8,44+Math.sin(t*4)*8);g.globalCompositeOperation='source-over';
  g.fillStyle='#ffbe5c';g.strokeStyle='#1a0e00';g.lineWidth=2;g.beginPath();g.moveTo(px+Math.cos(P.face)*10,py+Math.sin(P.face)*10);g.lineTo(px+Math.cos(P.face+2.5)*7,py+Math.sin(P.face+2.5)*7);g.lineTo(px+Math.cos(P.face-2.5)*7,py+Math.sin(P.face-2.5)*7);g.closePath();g.fill();g.stroke();
  g.font='700 12px "Noto Sans Thai", system-ui';g.textAlign='left';g.fillStyle='#fff';g.fillText('คุณอยู่ที่นี่',px+12,py+4);
  g.textAlign='left';g.font='700 13px Cinzel, serif';g.fillStyle='rgba(228,241,255,.75)';g.fillText(`Waystones: ${G.unlocked.size} / ${ZORDER.length}`,18,26);
}

/* ---------- Dev console ---------- */
function buildDev(){
  $('#dWeapon').innerHTML=WTYPES.map(k=>`<option value="${k}">${WEAPONS[k].n} · ${WEAPONS[k].th}</option>`).join('');
  let o='<option value="novice">Novice</option>';
  for(const pk in PATHS){o+=`<optgroup label="${PATHS[pk].n}">`;for(const c in CLASSES)if(CLASSES[c].path===pk)o+=`<option value="${c}">${'— '.repeat(CLASSES[c].tier-1)}${CLASSES[c].n} (T${CLASSES[c].tier})</option>`;o+='</optgroup>';}
  $('#dClass').innerHTML=o;
  $('#dTheme').innerHTML=THEME_KEYS.map(([k,n])=>`<button class="btn thb" data-theme="${k}">${n}</button>`).join('');
  syncDev();
}
function syncAI(){$('#aiAtk').value=G.atkScale;$('#aiAggro').value=G.aggroR;$('#aiDen').value=G.density;
  $('#aiAtkV').textContent=`${G.atkScale}/10 · ${Math.round(G.aggroR*G.atkScale/10)} หน่วย`;$('#aiAggroV').textContent=`${G.aggroR} หน่วย`;$('#aiDenV').textContent=`x${(+G.density).toFixed(2)} · ${mobCap()} ตัว`;$('#aiRad').checked=G.showRadii;}
function syncDev(){if(!P)return;syncAI();$('#dWeapon').value=P.weapon.t;$('#dClass').value=P.cls;document.querySelectorAll('.thb').forEach(b=>b.classList.toggle('on',b.dataset.theme===G.theme));
  $('#dGod').textContent='God Mode: '+(G.god?'ON':'OFF');$('#dBloom').textContent='Bloom: '+(G.bloom?'ON':'OFF');}
function devClass_v2(c){
  const C=CLASSES[c];P.lvl=Math.max(P.lvl,TIER_LV[C.tier]);
  const lin=lineage(c);for(const cl of lin)for(const id of CLASSES[cl].sk)P.skills[id]=Math.max(P.skills[id]||0,5);
  const pool=[];for(const cl of lin.slice().reverse())for(const id of CLASSES[cl].sk)pool.push(id);
  P.slots=pool.slice(0,10);while(P.slots.length<10)P.slots.push(null);
  P.weapon=makeWeapon(C.wp,P.lvl,2);P.statPts+=0;setClass(c);if(P.autoStat){P.statPts+=Math.max(0,P.lvl*3-Object.values(P.stats).reduce((a,b)=>a+b,0)+30);autoAllocate();}
  recalc();P.hp=P.maxHp;P.mp=P.maxMp;for(const k in P.cds)P.cds[k]=0;syncDev();
}
function devAction(a){
  switch(a){
    case 'lv1':gainExp(need(P.lvl)-P.exp);break;
    case 'lv10':for(let i=0;i<10&&P.lvl<C182cap();i++){P.exp=0;levelUp();}break;
    case 'lv120':case 'lv250':{const tgt=a==='lv120'?120:250;while(P.lvl<tgt){P.exp=0;P.lvl++;P.statPts+=Math.floor(P.lvl/5)+3;}if(P.weapon.t!=='fist')P.weapon.atk=Math.max(P.weapon.atk,makeWeapon(P.weapon.t,P.lvl,2).atk);recalc();P.hp=P.maxHp;P.mp=P.maxMp;levelUpFx();break;}
    case 'sp':P.skillPts+=50;break;
    case 'stat':P.statPts+=50;recalc();break;
    case 'maxsk':for(const c of lineage(P.cls))for(const id of CLASSES[c].sk)P.skills[id]=10;buildBar();break;
    case 'ways':for(const z of ZORDER)G.unlocked.add(z);log('ปลดล็อก Waystone ทั้งหมดแล้ว','g');break;
    case 'gold':P.gold+=10000;break;
    case 'heal':P.hp=P.maxHp;P.mp=P.maxMp;for(const k in P.cds)P.cds[k]=0;break;
    case 'wave':if(ZONES[G.zone].safe){log('Capital City เป็นเขตปลอดภัย — ไปโซนอื่นเพื่อเรียกมอนสเตอร์','r');break;}for(let i=0;i<10;i++){const Z=ZONES[G.zone],[type,lv]=pick(Z.mobs),a=rand(0,TAU);const e=makeEnemy(type,lv,clamp(P.x+Math.cos(a)*380,60,Z.w-60),clamp(P.y+Math.sin(a)*300,60,Z.h-60));e.aggro=true;enemies.push(e);}break;
    case 'boss':{if(ZONES[G.zone].safe){log('ไม่สามารถเรียกบอสในเขตปลอดภัยได้','r');break;}const e=makeEnemy('darklord',250,P.x+Math.cos(P.face)*420,P.y+Math.sin(P.face)*420);const Z=ZONES[G.zone];e.x=clamp(e.x,80,Z.w-80);e.y=clamp(e.y,80,Z.h-80);e.aggro=true;enemies.push(e);showBanner('DARK LORD','Lv 250 · Boss',2.5);break;}
    case 'god':G.god=!G.god;break;
    case 'bloom':G.bloom=!G.bloom;break;
  }
  syncDev();if(G.win==='wSkill')renderSkillWin();if(G.win==='wInv')renderInv();if(G.win==='wTele')renderTele();
}
function levelUpFx_v1(){fx.push({k:'pillar',x:P.x,y:P.y,t:0,dur:1.4,col:'#ffbe5c',w:70,h:420});textAt(P.x,P.y-80,'LV '+P.lvl,'#ffbe5c',30,{life:1.6});}

/* ---------- Save / Load ---------- */
const SAVE_KEY=KEYP+'save_v1';
function saveGame(){try{if(!P||P.dead)return;localStorage.setItem(SAVE_KEY,JSON.stringify({v:SAVE_VER,P:{lvl:P.lvl,exp:P.exp,cls:P.cls,stats:P.stats,statPts:P.statPts,skillPts:P.skillPts,autoStat:P.autoStat,skills:P.skills,slots:P.slots,weapon:P.weapon,equip:P.equip,look:P.look,jobLv:P.jobLv,jobExp:P.jobExp,skLv:P.skLv||null,inv:P.inv,invSize:P.invSize,bagUp:P.bagUp,gold:P.gold,sp:P.sp},zone:G.zone,unlocked:[...G.unlocked],theme:G.theme,x:P.x,y:P.y,ai:{atk:G.atkScale,aggro:G.aggroR,den:G.density}}));}catch(e){try{window.__SV2&&window.__SV2.fail('stringify',SAVE_KEY,e,true);}catch(_){}}}
function loadSave(){try{const s=localStorage.getItem(SAVE_KEY);return s?saveMigrate(JSON.parse(s)):null;}catch(e){return null;}}
function clearSave(){try{localStorage.removeItem(SAVE_KEY);}catch(e){}}

/* ---------- Input ---------- */
addEventListener('keydown',e=>{
  const k=e.key.toLowerCase();
  if(e.target&&(e.target.tagName==='SELECT'||e.target.tagName==='INPUT'||e.target.tagName==='TEXTAREA'))return;
  if(k===' '||k==='`'||k.startsWith('arrow'))e.preventDefault();
  if(keys[k]&&!['1','2','3','4','5','6','q','e','r','f'].includes(k)){keys[k]=true;return;}
  keys[k]=true;G.lastInput='mouse';
  if(G.state!=='play'){if(k==='enter'&&G.state==='title')startGame(false);return;}
  if(k==='p'){toggleEditor();return;}
  if(ED.on){if(k==='delete'||k==='backspace'){e.preventDefault();edDelete();}else if(k==='escape'){if(ED.pick||ED.sel){ED.pick=null;ED.sel=null;ED.tool='select';renderEditor();}else toggleEditor(false);}return;}
  if(k==='escape'){closeWin();return;}
  if(k==='m')toggleWin('wMap');else if(k==='k')toggleWin('wSkill');else if(k==='c')toggleWin('wInv');else if(k==='i')toggleWin('wInv');
  else if(k==='t')toggleAuto();else if(k==='`'||k==='~')toggleDev();else if(k==='g'){interact()||pickupNear();}
  else if(k==='z')usePotion('hp');else if(k==='x')usePotion('mp');
  else{const i=SLOT_KEYS.indexOf(k);if(i>=0){if(k==='f'&&(interact()||pickupNear()))return;if(!e.repeat)castSkill(P.slots[i]);}}
});
addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false;});
addEventListener('blur',()=>{for(const k in keys)keys[k]=false;mouse.down=false;});
cv.addEventListener('pointermove',e=>{mouse.x=e.clientX;mouse.y=e.clientY;if(ED.on)edPointerMove(e);if(G.touch&&e.pointerType==='touch'){G.touch.x=e.clientX;G.touch.y=e.clientY;}});
cv.addEventListener('pointerdown',e=>{
  mouse.x=e.clientX;mouse.y=e.clientY;
  if(G.state!=='play')return;
  if(ED.on){if(e.button===0)edPointerDown(e);cv.setPointerCapture&&cv.setPointerCapture(e.pointerId);return;}
  if(G.assign){G.assign=null;document.body.classList.remove('assign');return;}
  const wx=mwx(e.clientX,e.clientY),wy=mwy(e.clientX,e.clientY);
  if(G.interact&&((WAY&&d2(wx,wy,WAY.x,WAY.y-80)<120)||(NEXUS&&d2(wx,wy,NEXUS.x,NEXUS.y-40)<140)||NPCS.some(n=>d2(wx,wy,n.x,n.y-20)<50))){interact();return;}
  if(e.pointerType==='touch'){G.lastInput='touch';G.touch={x:e.clientX,y:e.clientY,move:true};const n=nearestEnemy(wx,wy,90);if(n){G.touch.move=false;mouse.down=true;}}
  else{G.lastInput='mouse';if(e.button===0)mouse.down=true;}
  cv.setPointerCapture&&cv.setPointerCapture(e.pointerId);
});
addEventListener('pointerup',()=>{mouse.down=false;G.touch=null;if(ED.on)edPointerUp();});
cv.addEventListener('contextmenu',e=>e.preventDefault());

// bar
$('#bar').addEventListener('click',e=>{
  const s=e.target.closest('.slot');if(!s)return;
  if(s.dataset.pot){usePotion(s.dataset.pot);return;}
  const i=+s.dataset.i;
  if(G.assign){const old=P.slots.indexOf(G.assign);if(old>=0)P.slots[old]=P.slots[i];P.slots[i]=G.assign;G.assign=null;document.body.classList.remove('assign');buildBar();if(G.win==='wSkill')renderSkillWin();saveGame();return;}
  if(P.slots[i])castSkill(P.slots[i]);
});
$('#bar').addEventListener('contextmenu',e=>{e.preventDefault();const s=e.target.closest('.slot');if(!s||s.dataset.pot)return;P.slots[+s.dataset.i]=null;buildBar();});
$('#bar').addEventListener('dragstart',e=>{const s=e.target.closest('.slot');if(s&&s.dataset.sk){e.dataTransfer.setData('text/plain',JSON.stringify({sk:s.dataset.sk,from:+s.dataset.i}));}});
$('#bar').addEventListener('dragover',e=>{if(e.target.closest('.slot:not(.pot)'))e.preventDefault();});
$('#bar').addEventListener('drop',e=>{e.preventDefault();const s=e.target.closest('.slot');if(!s||s.dataset.pot)return;let d;try{d=JSON.parse(e.dataTransfer.getData('text/plain'));}catch(_){return;}
  const i=+s.dataset.i;if(d.from!==undefined&&d.from>=0){const t=P.slots[i];P.slots[i]=d.sk;P.slots[d.from]=t;}else{const old=P.slots.indexOf(d.sk);if(old>=0)P.slots[old]=P.slots[i];P.slots[i]=d.sk;}
  buildBar();if(G.win==='wSkill')renderSkillWin();saveGame();});
